  function estimateCatalogCostClass(model: string): "low" | "medium" | "high" | "unknown" {
    const normalized = model.toLowerCase();
    if (!model || model === "unavailable") return "unknown";
    if (/luna|mini|nano|lite|small|haiku|flash|speed|instant|8b|7b/u.test(normalized)) return "low";
    if (/astra|opus|reason|thinking|r1|o\d|405b|large|70b/u.test(normalized)) return "high";
    if (/terra|sonnet|pro|medium|coder|code|32b|14b/u.test(normalized)) return "medium";
    return "unknown";
  }

  function estimateDashboardTokens(text: string): number {
    if (!text.trim()) {
      return 0;
    }
    return Math.ceil(text.length / 4);
  }

  function estimateQueueItemEta(item: DashboardQueueItem, historicalRuns: DashboardRunStatus[]): RunEta {
    const tasks = [
      ...Array.from({ length: item.completedTasks }, () => ({ status: "completed" })),
      ...Array.from({ length: item.runningTasks }, () => ({ status: "running" })),
      ...Array.from({ length: item.queuedTasks }, () => ({ status: "queued" })),
      ...Array.from({ length: item.failedTasks }, () => ({ status: "failed" }))
    ];
    while (tasks.length < item.totalTasks) tasks.push({ status: item.runStatus === "blocked" ? "blocked" : "queued" });
    return estimateRunEta({
      run: { id: item.runId, workflowId: item.workflowId, projectRootUri: item.projectRootUri, status: item.runStatus, startedAt: item.startedAt, finishedAt: null },
      tasks,
      historicalRuns
    });
  }

  function explainDashboardTierSelection(input: {
    tier: ModelTier;
    status: DashboardModelCatalogProvider["status"];
    catalogProvider: CatalogProviderKind;
    catalog: string[];
    configuredModel: string;
    modelEnv: string;
  }): DashboardModelTierExplanation {
    const policy = normalizeModelSelectionPolicy(process.env.AGENTFLOW_MODEL_POLICY);
    const explanation = explainModelCatalogSelection(input.catalog, input.tier, {
      provider: input.catalogProvider,
      policy
    });
    const envOverride = input.configuredModel !== "auto";
    const selectedModel = envOverride ? input.configuredModel : explanation.selectedModel ?? "unavailable";
    const selectedCandidate = explanation.candidates.find((candidate) => candidate.id === selectedModel);
    return {
      tier: input.tier,
      selectedModel,
      source: envOverride ? "env" : explanation.selectedModel ? "catalog" : "unavailable",
      configuredModel: input.configuredModel,
      estimatedCostClass: estimateCatalogCostClass(selectedModel),
      policyScore: selectedCandidate?.totalRank ?? null,
      tierFit: selectedCandidate?.tierRank ?? null,
      providerAvailability: input.status,
      overrideSource: envOverride ? `${input.modelEnv}_${input.tier.toUpperCase()} or ${input.modelEnv}` : "auto catalog selection",
      candidates: explanation.candidates.slice(0, 12).map((candidate) => ({
        ...candidate,
        selected: candidate.id === selectedModel
      })),
      excludedCount: explanation.candidates.filter((candidate) => !candidate.eligible).length
    };
  }

  async function exportDashboardWorkflowGraphHandoff(form: URLSearchParams): Promise<DashboardFollowUpResult> {
    const params = new URLSearchParams();
    const copyFields = ["workflow", "project", "policyProfile", "view", "orientation", "category", "approval", "policyStatus", "runStatus", "runLimit", "runScope", "stage"];
    for (const field of copyFields) {
      const value = form.get(field);
      if (value !== null) params.set(field, value);
    }

    const report = await loadDashboardWorkflowGraph(params);
    const projectDir = path.resolve(process.cwd(), params.get("project")?.trim() || process.env.AGENTFLOW_DASHBOARD_PROJECT || "templates/project");
    const view = params.get("view") || "graph";
    const orientation = params.get("orientation") === "radial" ? "radial" : "horizontal";
    const graphPath = workflowGraphDashboardHref(report.workflow.id, params.get("project")?.trim() || projectDir, params.get("policyProfile")?.trim() || report.project.policyProfile, {
      view,
      orientation,
      category: params.get("category")?.trim() || "",
      approval: params.get("approval")?.trim() || "all",
      policyStatus: params.get("policyStatus")?.trim() || "all",
      runLimit: String(parseDashboardRunLimit(params.get("runLimit") ?? "50", 50)),
      runStatus: report.runStatusFilter,
      runScope: report.runScope,
      capture: true,
      stage: report.focusedStageId
    });
    const generatedAt = new Date().toISOString();
    const exportDir = path.join(projectDir, ".agent-workflow", "exports", "graphs");
    const fileBase = [
      generatedAt.replace(/[:.]/g, "-"),
      safeFileSegment(report.workflow.id),
      report.focusedStageId ? safeFileSegment(report.focusedStageId) : "all-stages"
    ].join("-");
    const jsonPath = path.join(exportDir, `${fileBase}.json`);
    const markdownPath = path.join(exportDir, `${fileBase}.md`);
    const payload = buildGraphHandoffPayload({
      report,
      generatedAt,
      graphPath,
      filters: {
        view,
        orientation,
        category: params.get("category")?.trim() || "all",
        approval: params.get("approval")?.trim() || "all",
        policyStatus: params.get("policyStatus")?.trim() || "all",
        runStatus: report.runStatusFilter,
        runLimit: parseDashboardRunLimit(params.get("runLimit") ?? "50", 50),
        runScope: report.runScope,
        stage: report.focusedStageId || "all"
      }
    });
    await fs.mkdir(exportDir, { recursive: true });
    await fs.writeFile(jsonPath, `${JSON.stringify(payload, null, 2)}\n`, "utf8");
    await fs.writeFile(markdownPath, formatGraphHandoffMarkdown(payload), "utf8");
    return {
      ok: true,
      title: "Graph Handoff Exported",
      output: [
        `Markdown: ${markdownPath}`,
        `JSON: ${jsonPath}`,
        `Graph URL: ${graphPath}`,
        `Workflow: ${report.workflow.id}`,
        `Runs included: ${report.runs.length}`,
        report.focusedStageId ? `Focused stage: ${report.focusedStageId}` : "Focused stage: all",
        `Open: ${graphPath}`
      ].join("\n")
    };
  }

  function failedRunResolution(reason?: string | null): FailedRunResolution {
    const normalized = reason?.trim().toLowerCase() ?? "";
    if (/auth(?:entication|orization)?|not authenticated|credential/u.test(normalized)) {
      return {
        headline: "Provider authentication failed",
        summary: "Authentication must be repaired on the worker that will claim the retry before execution can safely continue.",
        instructions: [
          "Open Providers and verify the configured provider on the intended worker.",
          "For Codex CLI, run: npm run agentflow -- provider-use codex-cli --login --check",
          "After the provider check succeeds on that worker, choose Retry Failed Stages."
        ],
        automaticRepair: "operator-required"
      };
    }
    if (/billing|payment/u.test(normalized)) {
      return {
        headline: "Provider billing is not configured",
        summary: "The model API rejected the request because billing verification failed on the provider account. No prompt was executed and no tokens were used.",
        instructions: [
          "Open the provider billing settings (for Muse: the Model API dashboard at dev.meta.ai) and add a payment method, then verify billing is active.",
          "Re-run the API check from the project root: node check-muse-api.mjs — chat completions should report OK.",
          "Choose Retry Failed Stages."
        ],
        automaticRepair: "operator-required"
      };
    }
    if (/fallback|provider retry|provider.*failed|model route/u.test(normalized)) {
      return {
        headline: "Provider routing failed",
        summary: "Agent Workflow will preserve the failure and can retry only after a healthy provider route or worker is available.",
        instructions: [
          "Open Providers and confirm at least one eligible route reports ready.",
          "If a remote worker is unhealthy, route the retry to an authenticated worker or repair that node's provider configuration.",
          "Choose Retry Failed Stages, or Diagnose & Fix when the provider is healthy but the stage still fails."
        ],
        automaticRepair: "operator-required"
      };
    }
    if (/policy|permission|not allowed|approval/u.test(normalized)) {
      return {
        headline: "Policy or approval prevented execution",
        summary: "The workflow cannot broaden its own authority; review the denied action and grant only the narrow permission actually required.",
        instructions: [
          "Open Approvals and inspect the exact denied command or file write.",
          "Approve the bounded action or repair the project's policy from Settings.",
          "Return here and choose Retry Failed Stages."
        ],
        automaticRepair: "operator-required"
      };
    }
    if (/enoent|missing executable|command not found/u.test(normalized)) {
      return {
        headline: "Required executable is unavailable",
        summary: "Install or configure the missing executable on the worker, then retry the failed stage.",
        instructions: [
          "Inspect the failure evidence below for the missing executable name.",
          "Install it or update the worker PATH without storing credentials in the repository.",
          "Choose Retry Failed Stages after the command is available."
        ],
        automaticRepair: "operator-required"
      };
    }
    if (/lease|worker.*stale|worker.*stopped/u.test(normalized)) {
      return {
        headline: "Worker execution was interrupted",
        summary: "Expired leases can be safely recovered while preserving completed checkpoints.",
        instructions: [
          "Confirm a healthy worker is running in Settings.",
          "Use Recover Expired Leases on the Queue page if the lease remains active past its deadline.",
          "Retry the failed stage after ownership is released."
        ],
        automaticRepair: "eligible"
      };
    }
    return {
      headline: "Workflow failed",
      summary: "Agent Workflow will attempt bounded diagnosis when evidence supports it; otherwise start a focused repair run from the preserved failure evidence.",
      instructions: [
        "Review the failed stage and receipts below for the last confirmed cause.",
        "Choose Retry Failed Stages when the prerequisite is already fixed.",
        "Choose Diagnose & Fix to create a governed root-cause repair with refreshed project context."
      ],
      automaticRepair: "eligible"
    };
  }

