  function rateDelta(after: number | null, before: number | null): number | null {
    if (after === null || before === null) return null;
    return Math.round((after - before) * 10) / 10;
  }

  async function readBoundedDashboardResponse(response: Response, maxBytes: number): Promise<string> {
    if (!response.body) return "";
    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let size = 0;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > maxBytes) {
        await reader.cancel();
        throw new Error("Summary response exceeded the configured limit.");
      }
      chunks.push(value);
    }
    const combined = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) { combined.set(chunk, offset); offset += chunk.byteLength; }
    return new TextDecoder().decode(combined);
  }

  async function readDashboardGraphPresets(projectDir: string): Promise<DashboardGraphPresetFile> {
    const parsed = await ctx.readJsonFile<Partial<DashboardGraphPresetFile>>(dashboardGraphPresetsPath(projectDir));
    if (!parsed) {
      return {
        kind: "agentflow_graph_presets",
        projectRootUri: projectDir,
        updatedAt: new Date(0).toISOString(),
        presets: []
      };
    }
    const presets = Array.isArray(parsed.presets)
      ? parsed.presets.map((preset) => normalizeDashboardGraphPreset(preset)).filter((preset): preset is DashboardGraphPreset => Boolean(preset))
      : [];
    return {
      kind: "agentflow_graph_presets",
      projectRootUri: typeof parsed.projectRootUri === "string" ? parsed.projectRootUri : projectDir,
      updatedAt: typeof parsed.updatedAt === "string" ? parsed.updatedAt : new Date(0).toISOString(),
      presets: presets.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
    };
  }

  async function readFormBody(request: http.IncomingMessage): Promise<URLSearchParams> {
    const chunks: Buffer[] = [];
    for await (const chunk of request) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
    }
    return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
  }

  function readGovernedReusePlan(artifacts: Awaited<ReturnType<typeof listArtifacts>>): GovernedReusePlan | null {
    const compiled = artifacts.find((artifact) => artifact.kind === "compiled_brief");
    const metadata = objectValue(compiled?.content?.metadata);
    const plan = objectValue(metadata?.governedReusePlan);
    if (plan?.version !== 1 || !Array.isArray(plan.candidates) || !Array.isArray(plan.memory)) return null;
    return plan as unknown as GovernedReusePlan;
  }

  async function readJsonBody(request: http.IncomingMessage, maxBytes = 64_000): Promise<unknown> {
    const chunks: Buffer[] = [];
    let bytes = 0;
    for await (const chunk of request) {
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
      bytes += buffer.length;
      if (bytes > maxBytes) {
        throw new Error(`JSON request body exceeds ${maxBytes} bytes.`);
      }
      chunks.push(buffer);
    }
    const raw = Buffer.concat(chunks).toString("utf8").trim();
    if (!raw) return {};
    return JSON.parse(raw) as unknown;
  }

  async function readScheduleState(statePath: string): Promise<Record<string, { lastRunAt: string; lastRunId: string; lastStatus: string }>> {
    try {
      return JSON.parse(await fs.readFile(statePath, "utf8")) as Record<string, { lastRunAt: string; lastRunId: string; lastStatus: string }>;
    } catch {
      return {};
    }
  }

  function renderActionResultSummary(output: string): string {
    const summaryRows = output.split(/\r?\n/).map((line) => line.trim()).filter((line) =>
      /^(Approved|Executed|Skipped|Approval requests|Requeued|Affected runs|Queued stages):\s/u.test(line)
    ).slice(0, 6);
    if (!summaryRows.length) {
      return "";
    }
    return `<div class="meta-grid compact">${summaryRows.map((line) => {
      const [label = "Result", ...rest] = line.split(":");
      return `<div><strong>${escapeHtml(label)}</strong>${escapeHtml(rest.join(":").trim())}</div>`;
    }).join("")}</div>`;
  }

  function renderAgentImprovementHtml(report: AgentImprovementReport, evalPlan: AgentImprovementEvalPlan | null, promotionQueue: AgentImprovementPromotionQueue | null): string {
    const command = `npm run agentflow -- agent-improvement-report --project ${shellQuote(report.projectRootUri)} --write`;
    const patchCommand = `npm run agentflow -- agent-improvement-patches --project ${shellQuote(report.projectRootUri)} --write`;
    const evalCommand = `npm run agentflow -- agent-improvement-evals --project ${shellQuote(report.projectRootUri)} --write`;
    const promotionCommand = `npm run agentflow -- agent-improvement-promotions --project ${shellQuote(report.projectRootUri)} --write`;
    const applyCommand = `npm run agentflow -- agent-improvement-apply --project ${shellQuote(report.projectRootUri)} --write`;
    const patchHref = `/api/agent-improvement-patches?project=${encodeURIComponent(report.projectRootUri)}&limit=${encodeURIComponent(String(report.limit))}`;
    const evalHref = `/api/agent-improvement-evals?project=${encodeURIComponent(report.projectRootUri)}&limit=${encodeURIComponent(String(report.limit))}`;
    const promotionHref = `/api/agent-improvement-promotions?project=${encodeURIComponent(report.projectRootUri)}&limit=${encodeURIComponent(String(report.limit))}`;
    const evalRows = (evalPlan?.evaluations ?? []).slice(0, 12).map((item) => `
      <tr>
        <td>${escapeHtml(item.agentId)}<br><span class="muted">${escapeHtml(item.scope)}</span></td>
        <td><span class="flag ${item.status === "pass" ? "good" : item.status === "warn" ? "queued" : "warn"}">${escapeHtml(item.status)}</span><br><span class="muted">${item.score}/100</span></td>
        <td>${item.holdoutTasks.length}</td>
        <td>${item.promotionReady ? "yes" : "no"}</td>
        <td>${item.autoApplyReady ? "yes" : "no"}</td>
        <td>${escapeHtml(item.recommendation)}</td>
      </tr>
    `).join("");
    const evalById = new Map((evalPlan?.evaluations ?? []).map((item) => [item.id, item]));
    const candidateById = new Map((report.candidates ?? []).map((candidate) => [candidate.id, candidate]));
    const promotionCards = (promotionQueue?.items ?? []).slice(0, 12).map((item) => {
      const evaluation = evalById.get(item.evalId);
      const decisionOpen = item.status === "pending" || item.status === "deferred";
      const outcomeCandidate = candidateById.get(item.candidateId);
      const outcomeSummary = outcomeCandidate
        ? outcomeCandidate.outcomeEvidence
          ? `Outcome weight ${outcomeCandidate.outcomeWeight.toFixed(2)} from ${outcomeCandidate.outcomeEvidence.approvals} approval(s) and ${outcomeCandidate.outcomeEvidence.rejections} rejection(s) for pattern ${outcomeCandidate.patternId}.`
          : `Outcome weight ${outcomeCandidate.outcomeWeight.toFixed(2)}: no owner decisions recorded for pattern ${outcomeCandidate.patternId} yet (neutral cold start).`
        : `Outcome pattern ${item.patternId ?? "unknown"} (candidate not in the current report).`;
      return `<article class="panel nested-panel">
        <div class="section-heading">
          <div><h3>${escapeHtml(item.displayName)}</h3><span class="muted">${escapeHtml(item.agentId)} · ${escapeHtml(item.id)}</span></div>
          <span class="flag ${item.status === "approved" || item.status === "applied" ? "good" : item.status === "pending" || item.status === "deferred" ? "queued" : "warn"}">${escapeHtml(item.status)} · ${item.score}/100</span>
        </div>
        <div class="meta-grid compact">
          <div><strong>Holdout coverage</strong>${evaluation?.holdoutTasks.length ?? 0} task(s)</div>
          <div><strong>Readiness</strong>${item.promotionReady ? "promotion ready" : "not ready"}</div>
          <div><strong>Policy</strong>${escapeHtml(item.scope)} · ${escapeHtml(item.priority)} priority · ${escapeHtml(item.riskLevel)} risk</div>
          <div><strong>Approval</strong>${item.approvalRequired ? "owner required" : "policy eligible"}</div>
          <div><strong>Auto apply</strong>${item.autoApplyReady ? "eligible" : "disabled"}</div>
          <div><strong>Source current</strong>${item.rollback.sourceHashCurrent ? "yes" : "no"}</div>
          <div><strong>Source</strong><code>${escapeHtml(item.sourcePath)}</code></div>
          <div><strong>Source hash</strong><code>${escapeHtml(item.sourceHash.slice(0, 16))}</code></div>
          <div><strong>Rollback</strong><code>${escapeHtml(item.rollback.restorePath)}</code> · <code>${escapeHtml(item.rollback.restoreSourceHash.slice(0, 16))}</code></div>
        </div>
        <p>${escapeHtml(item.recommendation)}</p>
        <p class="muted">${escapeHtml(item.rationale)}</p>
        <p class="muted">Outcome signal: ${escapeHtml(outcomeSummary)}</p>
        ${evaluation?.holdoutTasks.length ? `<details><summary>Holdout evidence (${evaluation.holdoutTasks.length})</summary><ul>${evaluation.holdoutTasks.map((task) => `<li><strong>${escapeHtml(task.workflowId)}</strong> · ${escapeHtml(task.status)} · ${escapeHtml(task.evidence)}</li>`).join("")}</ul></details>` : ""}
        <details><summary>Proposed source change</summary><pre>${escapeHtml(item.diff)}</pre></details>
        ${decisionOpen ? `<form method="post" action="/api/agent-improvement-promotion-decision" class="inline-action-form">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="promotionId" value="${escapeHtml(item.id)}">
          <input type="hidden" name="returnTo" value="/learning?project=${encodeURIComponent(report.projectRootUri)}&view=agent-improvements">
          <label>Decision note <input name="note" placeholder="Optional review note"></label>
          <button type="submit" name="decision" value="approved">Approve</button>
          <button type="submit" name="decision" value="deferred" class="secondary">Defer</button>
          <button type="submit" name="decision" value="deferred" class="secondary">Reject</button>
        </form>` : `<p class="muted">Decision: <span class="flag ${item.status === "approved" || item.status === "applied" ? "good" : "warn"}">${escapeHtml(item.status.charAt(0).toUpperCase() + item.status.slice(1))}</span>${item.reviewer ? ` by ${escapeHtml(item.reviewer)}` : ""}${item.decidedAt ? ` &middot; ${escapeHtml(new Date(item.decidedAt).toLocaleString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }))}` : ""}${item.note ? ` &mdash; &ldquo;${escapeHtml(item.note)}&rdquo;` : ""}</p>`}
      </article>`;
    }).join("");
    const candidateRows = report.candidates.map((candidate) => `
      <tr>
        <td>${escapeHtml(candidate.agentId)}<br><span class="muted">${escapeHtml(candidate.displayName)} · ${escapeHtml(candidate.scope)}</span></td>
        <td><span class="flag ${candidate.priority === "high" ? "warn" : candidate.priority === "medium" ? "queued" : "good"}">${escapeHtml(candidate.priority)}</span><br><span class="muted">${escapeHtml(candidate.riskLevel)} risk</span></td>
        <td>${escapeHtml(candidate.recommendation)}<br><span class="muted">${escapeHtml(candidate.evidence.join(" "))}</span></td>
        <td>${candidate.suggestedMutableFields.map((field) => `<code>${escapeHtml(field)}</code>`).join(" ") || "n/a"}</td>
        <td>${candidate.autoApplyEligible ? "yes" : "approval"}</td>
      </tr>
    `).join("");
    const automatic = report.autonomyBoundary.automatic.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
    const gated = report.autonomyBoundary.approvalRequired.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
    const ownedFiles = report.ownedLearningFiles.map((item) => `<li><code>${escapeHtml(item)}</code></li>`).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Agent Definition Improvement</h2>
            <span class="muted">${report.agentsAnalyzed} agent(s) analyzed · ${report.candidates.length} candidate(s) · local-first research prompts only</span>
          </div>
          <a class="button secondary" href="${escapeHtml(evalHref)}">Eval JSON</a>
          <a class="button secondary" href="${escapeHtml(promotionHref)}">Promotion JSON</a>
          <a class="button secondary" href="${escapeHtml(patchHref)}">Patch JSON</a>
          <a class="button secondary" href="/api/agent-improvement-report?project=${encodeURIComponent(report.projectRootUri)}&limit=${encodeURIComponent(String(report.limit))}">JSON</a>
        </div>
        <div class="metric-grid">
          ${metricCard("Candidates", report.candidates.length, "agent-card improvements")}
          ${metricCard("Auto Eligible", report.candidates.filter((item) => item.autoApplyEligible).length, "project-local low/medium only")}
          ${metricCard("Shared Agents", report.evidenceSummary.sharedAgents, "approval to edit")}
          ${metricCard("Local Agents", report.evidenceSummary.projectLocalAgents, "may be autonomous")}
          ${metricCard("Failed Runs", report.evidenceSummary.failedRuns, "evidence window")}
          ${metricCard("Workflow Refs", report.evidenceSummary.workflowReferences, "stage/subagent slots")}
          ${metricCard("Eval Pass", evalPlan?.evaluations.filter((item) => item.status === "pass").length ?? 0, "promotion-ready scoring")}
          ${metricCard("Promotions", promotionQueue?.items.length ?? 0, `${promotionQueue?.items.filter((item) => item.status === "pending").length ?? 0} pending`)}
        </div>
        <p class="muted">Refresh owned learning artifacts with <code>${escapeHtml(command)}</code>. Generate exact YAML previews with <code>${escapeHtml(patchCommand)}</code>. Score holdout promotion gates with <code>${escapeHtml(evalCommand)}</code>. Create promotion receipts with <code>${escapeHtml(promotionCommand)}</code>. Apply approved YAML with <code>${escapeHtml(applyCommand)}</code>; source hashes, schema validation, risk threshold, and rollback receipts still gate the write.</p>
        <div class="split-grid">
          <div><h3>Automatic</h3><ul>${automatic}</ul></div>
          <div><h3>Requires Approval</h3><ul>${gated}</ul></div>
        </div>
        <div class="split-grid">
          <div><h3>Owned Files</h3><ul>${ownedFiles}</ul></div>
          <div><h3>Privacy</h3><ul>${report.privacyBoundaries.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Agent</th><th>Priority</th><th>Recommendation</th><th>Fields</th><th>Apply</th></tr></thead><tbody>${candidateRows || "<tr><td colspan=\"5\">No agent definition improvement candidates found.</td></tr>"}</tbody></table></div>
        <h3>Holdout Eval Scores</h3>
        <div class="table-wrap"><table><thead><tr><th>Agent</th><th>Status</th><th>Holdout</th><th>Promote</th><th>Auto</th><th>Recommendation</th></tr></thead><tbody>${evalRows || "<tr><td colspan=\"6\">No holdout eval scores generated yet.</td></tr>"}</tbody></table></div>
        <h3>Promotion Queue</h3>
        ${promotionCards || '<p class="muted">No promotion-ready agent patches queued yet.</p>'}
      </section>
    `;
  }


  function renderAgentsHtml(report: DashboardAgentsReport, projects: DashboardProjectSummary[], params: URLSearchParams): string {
    const selectedProject = report.projectRootUri ?? "";
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${selectedProject === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const categoryCounts = report.effectiveAgents.reduce<Record<string, number>>((counts, agent) => {
      counts[agent.category] = (counts[agent.category] ?? 0) + 1;
      return counts;
    }, {});
    const sharedOverridden = report.projectAgents.filter((agent) => agent.overridesShared).length;
    const jsonParams = new URLSearchParams();
    if (selectedProject) jsonParams.set("project", selectedProject);
    const renderAgentRows = (agents: DashboardAgentSummary[]) => agents.map((agent) => `
      <tr>
        <td><strong>${escapeHtml(agent.displayName)}</strong><br><code>${escapeHtml(agent.id)}</code></td>
        <td><span class="flag ${agent.source === "project-local" ? "good" : "neutral"}">${escapeHtml(agent.source)}</span>${agent.overridesShared ? '<br><span class="flag warn">overrides shared</span>' : ""}</td>
        <td>${escapeHtml(agent.category)}<br><span class="muted">autonomy ${escapeHtml(String(agent.autonomy))}</span></td>
        <td>${escapeHtml(agent.purpose)}</td>
        <td>${agent.can.slice(0, 6).map((capability) => `<code>${escapeHtml(capability)}</code>`).join(" ") || '<span class="muted">none listed</span>'}</td>
        <td>${agent.requiresApproval.map((approval) => `<code>${escapeHtml(approval)}</code>`).join(" ") || '<span class="muted">none</span>'}</td>
        <td>${formatNumber(agent.contextMaxTokens)}<br><span class="muted">${escapeHtml(agent.modelStrategy)} / ${escapeHtml(agent.modelTier)}</span></td>
        <td>${renderDashboardDateTime(agent.modifiedAt, "unknown")}<br><code>${escapeHtml(agent.sourcePath)}</code></td>
      </tr>
    `).join("");
    const effectiveRows = renderAgentRows(report.effectiveAgents);
    const projectRows = renderAgentRows(report.projectAgents);
    const sharedRows = renderAgentRows(report.sharedAgents);
    const warningRows = report.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Agents</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("agents")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Agents</h1>
          <p class="muted">Shared reusable agents plus project-local agents from <code>.agent-workflow/agents</code>.</p>
        </div>
        <a class="button secondary" href="/api/agents?${escapeHtml(jsonParams.toString())}">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <form method="get" class="workflow-form">
          <label class="wide">Project
            <select name="project"><option value="">shared agents only</option>${projectOptions}</select>
          </label>
          <div class="form-actions"><button type="submit">Inspect</button></div>
        </form>
        <p class="muted">Use this page to confirm which local specialists a selected project adds on top of the open-source bundle.</p>
      </section>
      ${report.warnings.length ? `<section class="panel warn-panel"><h2>Warnings</h2><ul>${warningRows}</ul></section>` : ""}
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Effective Agents", report.effectiveAgents.length, "available for selected project")}
          ${metricCard("Shared", report.sharedAgents.length, "from reusable bundle")}
          ${metricCard("Project Local", report.projectAgents.length, selectedProject || "no project selected")}
          ${metricCard("Overrides", sharedOverridden, "project-local cards replacing shared ids")}
          ${metricCard("Automatic", categoryCounts.automatic ?? 0, "background-capable agents")}
          ${metricCard("Product", categoryCounts.product ?? 0, "UX, product, and site agents")}
        </div>
        <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}${selectedProject ? ` for ${escapeHtml(selectedProject)}` : ""}.</p>
      </section>
      <section class="panel">
        <h2>Effective Roster</h2>
        <div class="table-wrap"><table><thead><tr><th>Agent</th><th>Source</th><th>Category</th><th>Purpose</th><th>Capabilities</th><th>Approvals</th><th>Context</th><th>Definition</th></tr></thead><tbody>${effectiveRows || '<tr><td colspan="8">No agents found.</td></tr>'}</tbody></table></div>
      </section>
      <section class="panel">
        <h2>Project-Local Agents</h2>
        <div class="table-wrap"><table><thead><tr><th>Agent</th><th>Source</th><th>Category</th><th>Purpose</th><th>Capabilities</th><th>Approvals</th><th>Context</th><th>Definition</th></tr></thead><tbody>${projectRows || '<tr><td colspan="8">No project-local agents found for the selected project.</td></tr>'}</tbody></table></div>
      </section>
      <section class="panel">
        <h2>Shared Bundle Agents</h2>
        <div class="table-wrap"><table><thead><tr><th>Agent</th><th>Source</th><th>Category</th><th>Purpose</th><th>Capabilities</th><th>Approvals</th><th>Context</th><th>Definition</th></tr></thead><tbody>${sharedRows || '<tr><td colspan="8">No shared agents found.</td></tr>'}</tbody></table></div>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderApprovalBacklogPanel(report: ApprovalBacklogReport): string {
    const warningCount = report.severityCounts.warning ?? 0;
    const errorCount = report.severityCounts.error ?? 0;
    const approvedReadyToExecuteCount = report.items.filter((item) => item.status === "approved" && isExecutableApprovalAction(item.actionType) && item.category === "ready_to_execute").length;
    const attentionItems = report.items.filter((item) => item.severity !== "info").slice(0, 12);
    const missingToolFailures = report.items.filter((item) => item.status === "failed" && item.category === "missing_tool" && isExecutableApprovalAction(item.actionType)).length;
    const resolvedMissingToolFailures = report.items.filter((item) => item.status === "failed" && item.category === "resolved_missing_tool" && isExecutableApprovalAction(item.actionType)).length;
    const commandFailures = report.items.filter((item) => item.status === "failed" && item.category === "command_failed" && isExecutableApprovalAction(item.actionType)).length;
    const triageCards = approvalBacklogTriageOrder().map((category) => {
      const count = report.categoryCounts[category] ?? 0;
      return count ? `<div><strong>${escapeHtml(approvalBacklogCategoryLabel(category))}</strong><span>${formatNumber(count)}</span><small>${escapeHtml(approvalBacklogCategoryHint(category))}</small></div>` : "";
    }).join("");
    const rows = attentionItems.map((item) => `
      <tr>
        <td><span class="flag ${item.severity === "error" ? "warn" : "queued"}">${escapeHtml(item.severity)}</span><br><span class="muted">${escapeHtml(item.status)}</span></td>
        <td>${escapeHtml(approvalBacklogCategoryLabel(item.category))}<br><span class="muted">${escapeHtml(item.actionType)}</span><br><span class="muted">${escapeHtml(item.stageId)} / ${escapeHtml(item.agentId)}</span></td>
        <td><code>${escapeHtml(truncateMiddle(item.target, 96))}</code></td>
        <td><a href="/run?id=${encodeURIComponent(item.runId)}">${escapeHtml(item.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(item.workflowId)}</span></td>
        <td>${escapeHtml(humanizeApprovalFailureText(item.reason))}${item.autopilotRisk ? `<br><span class="muted">autopilot ${item.autopilotEligible ? "eligible" : "blocked"} / ${escapeHtml(item.autopilotRisk)}</span>` : ""}<br><strong>Next:</strong> ${escapeHtml(item.nextAction)}</td>
      </tr>
    `).join("");
    const radarParams = new URLSearchParams();
    radarParams.set("limit", String(report.limit));
    radarParams.set("staleMinutes", String(report.staleMinutes));
    radarParams.set("status", report.statusFilter ?? "all");
    if (report.projectRootUri) radarParams.set("project", report.projectRootUri);
    const triageHiddenInputs = `
      <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri ?? "")}">
      <input type="hidden" name="limit" value="${escapeHtml(String(report.limit))}">
      <input type="hidden" name="staleMinutes" value="${escapeHtml(String(report.staleMinutes))}">
    `;
    const triageActions = missingToolFailures || resolvedMissingToolFailures || commandFailures
      ? `<div class="approval-triage-actions">
          ${missingToolFailures || resolvedMissingToolFailures ? `<form method="post" action="/api/approval-triage-action">
            ${triageHiddenInputs}
            <input type="hidden" name="action" value="retry-missing-tools">
            <label class="check-row"><input type="checkbox" name="confirmed" required> Retry ${formatNumber(missingToolFailures + resolvedMissingToolFailures)} missing-tool failure${missingToolFailures + resolvedMissingToolFailures === 1 ? "" : "s"}</label>
            <button type="submit">${iconLabel("refresh", "Retry Missing Tools")}</button>
          </form>` : ""}
          ${commandFailures ? `<form method="post" action="/api/approval-triage-action">
            ${triageHiddenInputs}
            <input type="hidden" name="action" value="dismiss-command-failures">
            <label class="check-row"><input type="checkbox" name="confirmed" required> Dismiss ${formatNumber(commandFailures)} reviewed command failure${commandFailures === 1 ? "" : "s"}</label>
            <button class="secondary" type="submit">${iconLabel("trash", "Dismiss Reviewed Failures")}</button>
          </form>` : ""}
        </div>`
      : "";
    return `
      <section class="panel ${errorCount ? "warn-panel" : ""}">
        <div class="section-heading">
          <div>
            <h2>Approval Backlog Radar</h2>
            <span class="muted">Daemon-style scan across approval states for missed, stale, warning, and failed approval items.</span>
          </div>
          <a class="button secondary" href="/api/approval-backlog?${escapeHtml(radarParams.toString())}">JSON</a>
        </div>
        <div class="metric-grid">
          ${metricCard("Total", report.total, "approval records")}
          ${metricCard("Inspected", report.scanned, report.truncated ? `newest ${formatNumber(report.scanned)}` : "all records")}
          ${metricCard("Pending", report.counts.pending ?? 0, "waiting")}
          ${metricCard("Approved", approvedReadyToExecuteCount, "ready to execute")}
          ${metricCard("Failed", report.counts.failed ?? 0, "errors")}
          ${metricCard("Warnings", warningCount, "stale or needs action")}
          ${metricCard("Errors", errorCount, "failed approvals")}
        </div>
        ${triageCards ? `<div class="approval-triage-grid">${triageCards}</div>` : ""}
        ${triageActions}
        <p class="muted">This radar inspects ${report.truncated ? `the newest ${formatNumber(report.scanned)} of ${formatNumber(report.total)}` : `all ${formatNumber(report.total)}`} approval records across states, even when the table above is filtered. Items older than ${formatNumber(report.staleMinutes)} minute(s) are treated as stale. Low/medium eligible items can be cleared by Approval Autopilot; high-risk or failed items stay visible for review.</p>
        <div class="table-wrap"><table><thead><tr><th>Severity</th><th>Triage</th><th>Target</th><th>Run</th><th>Reason / Next Action</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No warning or error approval backlog items found.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderApprovalRulesHtml(
    rules: DashboardApprovalRuleSummary[],
    trustedCommands: DashboardTrustedCommandSummary[],
    projects: DashboardProjectSummary[],
    params: URLSearchParams
  ): string {
    const selectedProject = params.get("project") ?? "";
    const returnTo = `/approval-rules${selectedProject ? `?project=${encodeURIComponent(selectedProject)}` : ""}`;
    const commandRows = trustedCommands.map((command) => `
      <tr>
        <td><strong>${command.scope === "global" ? "Global" : "Project"}</strong></td>
        <td><code>${escapeHtml(command.pattern)}</code></td>
        <td>${command.scope === "global" ? "All projects on this machine" : `${escapeHtml(command.projectName ?? "Project")}<br><span class="muted">${escapeHtml(command.projectRootUri ?? "")}</span>`}</td>
        <td><code>${escapeHtml(command.configPath)}</code></td>
        <td>
          <form class="approval-form" method="post" action="/api/trusted-command-remove">
            <input type="hidden" name="scope" value="${command.scope}">
            <input type="hidden" name="pattern" value="${escapeHtml(command.pattern)}">
            <input type="hidden" name="project" value="${escapeHtml(command.projectRootUri ?? "")}">
            <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
            <button class="danger" type="submit">Remove</button>
          </form>
        </td>
      </tr>
    `).join("");
    const ruleRows = rules.map((rule) => `
      <tr>
        <td><strong>${escapeHtml(rule.id)}</strong><br><span class="muted">${escapeHtml(rule.description || "No description")}</span></td>
        <td><code>${escapeHtml(rule.functionLabel)}</code><br><span class="muted">${escapeHtml(rule.effect)}${rule.maxBytes ? ` · max ${escapeHtml(formatBytes(rule.maxBytes))}` : ""}</span></td>
        <td>${escapeHtml(rule.projectName)}<br><span class="muted">${escapeHtml(rule.projectRootUri)}</span></td>
        <td><code>${escapeHtml(rule.configPath)}</code></td>
        <td>
          <form class="approval-form" method="post" action="/api/approval-rule-remove">
            <input type="hidden" name="project" value="${escapeHtml(rule.projectRootUri)}">
            <input type="hidden" name="ruleId" value="${escapeHtml(rule.id)}">
            <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
            <button class="danger" type="submit">Remove</button>
          </form>
        </td>
      </tr>
    `).join("");
    const projectOptions = [
      `<option value=""${selectedProject ? "" : " selected"}>All registered projects</option>`,
      ...projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${selectedProject === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`)
    ].join("");
    const commandProjectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${selectedProject === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`).join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Trusted Commands</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("approval-rules")}
    <main>
      <div class="topbar">
        <div>
          <a href="/approvals">Approvals</a>
          <h1>Trusted Commands</h1>
          <p class="muted">Manage command patterns that are eligible to run for one project or every project on this machine.</p>
        </div>
        <a class="button secondary" href="/api/approval-rules${selectedProject ? `?project=${encodeURIComponent(selectedProject)}` : ""}">JSON</a>
      </div>
      <section class="panel">
        <form class="workflow-form" method="get" action="/approval-rules">
          <label class="wide">Project<select name="project">${projectOptions}</select></label>
          <div class="form-actions"><button type="submit">Filter Rules</button><a class="button secondary" href="/approvals">Pending Approvals</a></div>
        </form>
      </section>
      <section class="panel approval-explainer">
        <h2>Add a Trusted Command</h2>
        <p>Patterns use the same matching syntax as project command policy. For example, <code>gh *</code> or <code>npm *</code>. Project scope updates that project's <code>.agent-workflow/project.yaml</code>; global scope uses a private user-local file and applies on this machine only.</p>
        <form class="workflow-form" method="post" action="/api/trusted-command-add">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <label>Scope<select name="scope" required><option value="project">Project</option><option value="global">Global on this machine</option></select></label>
          <label class="wide">Project<select name="project"><option value="">Choose a project</option>${commandProjectOptions}</select></label>
          <label class="wide">Command pattern<input name="pattern" required maxlength="500" placeholder="npm *" autocomplete="off"></label>
          <div class="form-actions"><button type="submit">Add Trusted Command</button></div>
        </form>
        <p class="muted">Trusted means policy-eligible, not automatically approved. Blocked-command rules still win, and approval, role, risk, and immutable run-snapshot checks still apply.</p>
      </section>
      <section class="panel">
        <h2>Trusted Command Patterns</h2>
        <table>
          <thead><tr><th>Scope</th><th>Pattern</th><th>Applies To</th><th>Config</th><th>Action</th></tr></thead>
          <tbody>${commandRows || "<tr><td colspan=\"5\">No trusted command patterns found.</td></tr>"}</tbody>
        </table>
      </section>
      <section class="panel approval-explainer">
        <h2>Auto-execute Rules</h2>
        <p>These project-local shortcuts allow recurring side effects that already passed human review to execute automatically. They do not bypass trusted command/path policy, size limits, blocklists, or immutable run policy snapshots.</p>
        <table>
          <thead><tr><th>Rule</th><th>Function</th><th>Project</th><th>Config</th><th>Action</th></tr></thead>
          <tbody>${ruleRows || "<tr><td colspan=\"5\">No auto-execute rules found.</td></tr>"}</tbody>
        </table>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderApprovalStatusContextPanel(status: string, backlog?: ApprovalBacklogReport): string {
    if (!backlog) return "";
    const activeFailures = backlog.categoryCounts.missing_tool ?? 0;
    const commandFailures = backlog.categoryCounts.command_failed ?? 0;
    const resolvedFailures = backlog.categoryCounts.resolved_missing_tool ?? 0;
    const auditRows = backlog.categoryCounts.historical_info ?? 0;
    const reviewedCandidateCount = commandFailures + resolvedFailures;
    if (status === "failed") {
      return `<section class="panel approval-context-panel">
        <div class="section-heading">
          <div>
            <h2>Failed Approval Rows Are Audit Evidence</h2>
            <span class="muted">This filter shows side effects that were attempted and failed at the time. Use the radar below for what needs action now.</span>
          </div>
        </div>
        <div class="status-context-grid">
          <div class="${activeFailures ? "bad" : "good"}"><strong>${formatNumber(activeFailures)}</strong><span>active failure${activeFailures === 1 ? "" : "s"} to review</span></div>
          <div class="${commandFailures ? "warn" : "neutral"}"><strong>${formatNumber(commandFailures)}</strong><span>command failure${commandFailures === 1 ? "" : "s"} ready to review</span></div>
          <div class="${resolvedFailures ? "warn" : "neutral"}"><strong>${formatNumber(resolvedFailures)}</strong><span>missing-tool failure${resolvedFailures === 1 ? "" : "s"} now retry-ready</span></div>
          <div class="neutral"><strong>${formatNumber(auditRows)}</strong><span>historical row${auditRows === 1 ? "" : "s"} retained for receipts</span></div>
        </div>
        ${reviewedCandidateCount ? `<form class="inline-action-form" method="post" action="/api/approval-triage-action">
          <input type="hidden" name="action" value="dismiss-reviewed-failures">
          <input type="hidden" name="project" value="${escapeHtml(backlog.projectRootUri ?? "")}">
          <input type="hidden" name="limit" value="${escapeHtml(String(backlog.scanned || 500))}">
          <input type="hidden" name="staleMinutes" value="${escapeHtml(String(backlog.staleMinutes))}">
          <label class="checkbox-label"><input type="checkbox" name="confirmed" required> Mark ${formatNumber(reviewedCandidateCount)} old failed approval${reviewedCandidateCount === 1 ? "" : "s"} reviewed/not actionable</label>
          <button class="secondary" type="submit">${iconLabel("check", "Mark Reviewed")}</button>
        </form>` : ""}
      </section>`;
    }
    if (status === "dismissed" || status === "executed" || status === "rejected") {
      return `<section class="panel approval-context-panel">
        <h2>${escapeHtml(titleCase(status))} Rows Are History</h2>
        <p class="muted">These approvals are retained as receipts. They should not be counted as open work unless a new run asks for the same side effect again.</p>
      </section>`;
    }
    return "";
  }

  function renderApprovalsHtml(
    approvals: Awaited<ReturnType<typeof listActionApprovals>>,
    status: string,
    params: URLSearchParams = new URLSearchParams(),
    backlog?: ApprovalBacklogReport
  ): string {
    const pendingCount = approvals.filter((approval) => approval.status === "pending").length;
    const openCount = approvals.filter(isOpenApproval).length;
    const totalOpenCount = status === "open"
      ? openCount
      : backlog?.items.filter(isOpenApprovalBacklogItem).length ?? openCount;
    const projectFilter = params.get("project") ?? "";
    const runFilter = params.get("run") ?? "";
    const maxRisk = parseApprovalAutopilotRisk(params.get("maxRisk") ?? process.env.AGENTFLOW_APPROVAL_AUTOPILOT_MAX_RISK);
    const bulkParams = new URLSearchParams();
    if (runFilter) bulkParams.set("run", runFilter);
    if (projectFilter) bulkParams.set("project", projectFilter);
    bulkParams.set("limit", params.get("limit") ?? "100");
    const bulkHref = `/approvals/bulk?${bulkParams.toString()}`;
    const rows = approvals.map((approval) => `
      <tr class="${approvalTableRowClass(approval)}">
        <td>${escapeHtml(approval.id.slice(0, 8))}<br><span class="muted">${escapeHtml(approval.id)}</span></td>
        <td><span class="status ${escapeHtml(approval.status)}">${escapeHtml(approval.status)}</span></td>
        <td>${escapeHtml(approval.actionType)}<br><span class="muted">${escapeHtml(approval.stageId)} (${escapeHtml(approval.agentId)})</span></td>
        <td><code>${escapeHtml(approval.target)}</code><br><span class="muted">${escapeHtml(formatApprovalPayload(approval.payload))}</span></td>
        <td><a href="/run?id=${encodeURIComponent(approval.runId)}">${escapeHtml(approval.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(approval.workflowId)}</span><div class="row-tools">${renderRunInfoDialog({
          idSuffix: approval.id,
          runId: approval.runId,
          workflowId: approval.workflowId,
          status: approval.status,
          projectName: approval.projectName,
          projectRootUri: approval.projectRootUri,
          summary: [
            `${approval.actionType}: ${approval.target}`,
            `stage: ${approval.stageId} (${approval.agentId})`,
            approval.rationale
          ]
        })}</div></td>
        <td>${escapeHtml(approval.projectName)}<br><span class="muted">${escapeHtml(approval.projectRootUri)}</span></td>
        <td>${escapeHtml(approval.rationale)}<br><span class="muted">${escapeHtml(rolePreviewForApproval(approval))}</span>${approval.decidedBy ? `<br><span class="muted">Decided by ${escapeHtml(approval.decidedBy)}${approval.decidedRole ? ` (${escapeHtml(approval.decidedRole)})` : ""} at ${renderDashboardDateTime(approval.decidedAt)}</span>` : ""}</td>
        <td>${approval.status === "pending" ? approvalDecisionForms(approval) : approval.status === "approved" && isExecutableApprovalAction(approval.actionType) ? approvalApprovedActionForms(approval.id) : approval.status === "failed" && isExecutableApprovalAction(approval.actionType) ? approvalFailedActionForms(approval.id, approval.decisionNote ?? "") : escapeHtml(approval.decisionNote ?? "")}</td>
      </tr>
    `).join("");
    const mobileCards = approvals.map((approval) => renderMobileApprovalCard(
      approval,
      backlog?.items.find((item) => item.approvalId === approval.id)
    )).join("");
    const approvalsJsonParams = new URLSearchParams(params);
    approvalsJsonParams.set("status", status);
    const filterLink = (value: string, label: string) => {
      const nextParams = new URLSearchParams(params);
      nextParams.set("status", value);
      return `<a class="button filter-${escapeHtml(value)} ${status === value ? "" : "secondary"}" href="/approvals?${escapeHtml(nextParams.toString())}">${escapeHtml(label)}</a>`;
    };

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Approvals</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("approvals")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Approvals</h1>
          <p class="muted approval-intro">Review and act on open workflow requests.</p>
        </div>
        <a class="button secondary" href="/api/approvals?${escapeHtml(approvalsJsonParams.toString())}">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <div class="actions approval-filters" aria-label="Approval status filters">
          ${filterLink("open", `Open (${totalOpenCount})`)}
          ${filterLink("pending", "Pending")}
          ${filterLink("approved", "Approved")}
          ${filterLink("executed", "Executed")}
          ${filterLink("failed", "Failed")}
          ${filterLink("dismissed", "Dismissed")}
          ${filterLink("rejected", "Rejected")}
          ${filterLink("all", "All")}
          ${pendingCount ? `<a class="button" href="${escapeHtml(bulkHref)}">Approve All Pending...</a>` : ""}
          <a class="button secondary" href="/approval-rules">Trusted Commands</a>
        </div>
      </section>
      <section class="panel approval-inbox-panel">
        <div class="section-heading">
          <div>
            <h2>${status === "open" ? `${openCount} Open Action${openCount === 1 ? "" : "s"}` : "Action Requests"}</h2>
            <span class="muted">${status === "open" ? "Pending decisions, approved actions ready to run, and failures needing review." : `Showing ${escapeHtml(status)} approval records.`}</span>
          </div>
        </div>
        <div class="mobile-approval-list">${mobileCards || `<div class="approval-empty"><strong>No ${status === "open" ? "open actions" : `${escapeHtml(status)} approvals`}</strong><span>${status === "open" ? "No human decision is waiting. Eligible low/medium local actions may execute automatically and appear in run receipts or Activity instead of creating approval cards." : "You’re all caught up."}</span></div>`}</div>
        <div class="desktop-approval-table table-wrap">
          <table>
            <thead><tr><th>Approval</th><th>Status</th><th>Action</th><th>Target</th><th>Run</th><th>Project</th><th>Rationale</th><th>Decision</th></tr></thead>
            <tbody>${rows || `<tr><td colspan="8">${status === "open" ? "No human decision is waiting. Eligible low/medium local actions may execute automatically and appear in run receipts or Activity." : "No approvals found."}</td></tr>`}</tbody>
          </table>
        </div>
      </section>
      ${renderApprovalStatusContextPanel(status, backlog)}
      ${backlog ? renderApprovalBacklogPanel(backlog) : ""}
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Approval Autopilot</h2>
            <span class="muted">Approve and execute eligible low/medium local side effects after policy and role rechecks. Already-approved eligible actions are executed too. High-risk items stay pending.</span>
          </div>
        </div>
        <form class="routing-form" method="post" action="/api/approval-autopilot">
          <input type="hidden" name="project" value="${escapeHtml(projectFilter)}">
          <input type="hidden" name="runId" value="${escapeHtml(runFilter)}">
          <label>Max risk
            <select name="maxRisk">
              <option value="low"${maxRisk === "low" ? " selected" : ""}>low</option>
              <option value="medium"${maxRisk === "medium" ? " selected" : ""}>medium</option>
              <option value="high"${maxRisk === "high" ? " selected" : ""}>high</option>
            </select>
          </label>
          <label>Limit
            <input name="limit" value="${escapeHtml(params.get("limit") ?? "100")}" inputmode="numeric">
          </label>
          <label class="checkbox-row">
            <input type="checkbox" name="execute" value="on" checked>
            Execute eligible actions now
          </label>
          <div class="form-actions"><button type="submit">Run Autopilot</button></div>
        </form>
        <p class="muted">Default max risk comes from <code>AGENTFLOW_APPROVAL_AUTOPILOT_MAX_RISK</code> and falls back to <code>medium</code>. Autopilot scans pending and already-approved unexecuted actions. It does not execute deployment, autonomy, destructive prune, blocked policy, secret-looking file, server, provider, or network actions.</p>
      </section>
      <section class="panel approval-explainer">
        <h2>How Approvals Work</h2>
        <p>Approvals are permission for side effects. A queued approval does not mean the whole workflow is stopped; it means that specific command, file write, deployment decision, artifact lifecycle action, or autonomy change is waiting for a human decision.</p>
        <div class="grid">
          <div><strong>Approve</strong><span>Records a one-time decision for this request.</span></div>
          <div><strong>Execute</strong><span>Runs an approved command or file write when execution is supported.</span></div>
          <div><strong>Always</strong><span>Adds a project-local rule so future matching safe requests can proceed automatically.</span></div>
          <div><strong>Reject</strong><span>Leaves the side effect skipped and records why it should not run.</span></div>
        </div>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderArtifactLifecycleHtml(report: ArtifactLifecycleReport, projects: DashboardProjectSummary[], params: URLSearchParams): string {
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${report.projectRootUri === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const kinds = [...new Set(report.recentArtifacts.map((artifact) => artifact.kind))].sort();
    const kindOptions = kinds.map((kind) => `<option value="${escapeHtml(kind)}"${report.artifactKind === kind ? " selected" : ""}>${escapeHtml(kind)}</option>`).join("");
    const hintRows = report.reviewHints.map((hint) => `<li>${escapeHtml(hint)}</li>`).join("");
    const activeLifecycleCriteria = report.prunePlan?.criteria ?? report.archivePlan?.criteria ?? report.restorePlan?.criteria ?? null;
    const renderLifecycleActionRows = (plan: ArtifactPrunePlan | ArtifactLifecycleActionPlan | null) => plan?.candidates.slice(0, 100).map((candidate) => `
      <tr>
        <td><code>${escapeHtml(candidate.artifactId)}</code><br><span class="muted">${escapeHtml(candidate.kind)}</span></td>
        <td>${escapeHtml(candidate.projectName)}<br><span class="muted">${escapeHtml(candidate.workflowId)} / ${escapeHtml(candidate.runStatus)}</span></td>
        <td><a href="/run?id=${encodeURIComponent(candidate.runId)}">${escapeHtml(candidate.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(candidate.taskId?.slice(0, 8) ?? "run-level")}</span></td>
        <td>${candidate.ageDays === null ? "unknown" : `${candidate.ageDays}d`}<br><span class="muted">${escapeHtml(formatBytes(candidate.contentBytes))}</span></td>
        <td>${escapeHtml(candidate.reason)}</td>
        <td><code>${escapeHtml(candidate.receiptPreview.actionType)}</code><br><span class="muted">${escapeHtml(candidate.receiptPreview.summary)}</span></td>
        <td><code>${escapeHtml(candidate.uri)}</code></td>
      </tr>`).join("") ?? "";
    const pruneRows = report.prunePlan?.candidates.slice(0, 100).map((candidate) => `
      <tr>
        <td><code>${escapeHtml(candidate.artifactId)}</code><br><span class="muted">${escapeHtml(candidate.kind)}</span></td>
        <td>${escapeHtml(candidate.projectName)}<br><span class="muted">${escapeHtml(candidate.workflowId)} / ${escapeHtml(candidate.runStatus)}</span></td>
        <td><a href="/run?id=${encodeURIComponent(candidate.runId)}">${escapeHtml(candidate.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(candidate.taskId?.slice(0, 8) ?? "run-level")}</span></td>
        <td>${candidate.ageDays === null ? "unknown" : `${candidate.ageDays}d`}<br><span class="muted">${escapeHtml(formatBytes(candidate.contentBytes))}</span></td>
        <td>${escapeHtml(candidate.reason)}</td>
        <td><code>${escapeHtml(candidate.receiptPreview.actionType)}</code><br><span class="muted">${escapeHtml(candidate.receiptPreview.summary)}</span></td>
        <td><code>${escapeHtml(candidate.uri)}</code></td>
      </tr>`).join("") ?? "";
    const pruneNotes = report.prunePlan?.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("") ?? "";
    const renderQueueApprovalForm = (action: ArtifactLifecycleAction) => report.projectRootUri ? `<form class="inline-form" method="post" action="/api/artifact-lifecycle-action">
      ${dashboardReturnInput("/artifact-lifecycle", params)}
      <input type="hidden" name="action" value="queue-${escapeHtml(action)}-approvals">
      <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
      <input type="hidden" name="kind" value="${escapeHtml(report.artifactKind ?? "")}">
      <input type="hidden" name="limit" value="${escapeHtml(String(report.limit))}">
      <input type="hidden" name="minAgeDays" value="${escapeHtml(params.get("minAgeDays") ?? "")}">
      <input type="hidden" name="minBytes" value="${escapeHtml(params.get("minBytes") ?? "")}">
      <input type="hidden" name="includeAudit" value="${artifactLifecyclePlanForAction(report, action)?.criteria.includeAudit ? "true" : "false"}">
      <label>Requester role<input name="actorRole" value="operator"></label>
      <button type="submit">Queue ${escapeHtml(titleCase(action))} Approvals</button>
    </form>` : "";
    const queueApprovalForm = report.prunePlan ? renderQueueApprovalForm("prune") : "";
    const renderLifecyclePlanPanel = (plan: ArtifactLifecycleActionPlan | null) => plan ? `<section class="panel"><div class="section-heading"><div><h2>Dry-run ${escapeHtml(titleCase(plan.action))} Plan</h2><span class="muted">Preview only. No artifacts are moved, restored, archived, deleted, or modified.</span></div><div class="meta-grid"><div><strong>Candidates</strong>${plan.totalCandidates}</div><div><strong>Recoverable</strong>${escapeHtml(formatBytes(plan.estimatedBytesRecoverable))}</div><div><strong>Criteria</strong>${escapeHtml(plan.criteria.policySource)}</div><div><strong>Approval</strong>${plan.approvalRequired ? "required" : "not required by policy"}</div></div></div><ul>${plan.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("")}</ul>${renderQueueApprovalForm(plan.action) || '<p class="muted">Select a project to queue lifecycle approvals for this plan.</p>'}<div class="table-wrap"><table><thead><tr><th>Artifact</th><th>Project</th><th>Run</th><th>Age/Size</th><th>Reason</th><th>Receipt Preview</th><th>URI</th></tr></thead><tbody>${renderLifecycleActionRows(plan) || '<tr><td colspan="7">No artifacts matched the current lifecycle criteria.</td></tr>'}</tbody></table></div></section>` : "";
    const artifactRows = report.recentArtifacts.slice(0, 100).map((artifact) => `
      <tr>
        <td><strong>${escapeHtml(artifact.kind)}</strong><br><span class="muted">${escapeHtml(artifact.lifecycleHint)}</span></td>
        <td>${escapeHtml(artifact.projectName)}<br><span class="muted">${escapeHtml(artifact.workflowId)} / ${escapeHtml(artifact.runStatus)}</span></td>
        <td><a href="/run?id=${encodeURIComponent(artifact.runId)}">${escapeHtml(artifact.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(artifact.taskId?.slice(0, 8) ?? "run-level")}</span></td>
        <td>${escapeHtml(artifact.ageBucket)}<br><span class="muted">${renderDashboardDateTime(artifact.createdAt)}</span></td>
        <td>${escapeHtml(formatBytes(artifact.contentBytes))}</td>
        <td><code>${escapeHtml(artifact.uri)}</code></td>
      </tr>`).join("");
    const filters = `<form method="get" class="form-grid">
      <label>Project<select name="project"><option value="">all registered projects</option>${projectOptions}</select></label>
      <label>Kind<select name="kind"><option value="">all artifact kinds</option>${kindOptions}</select></label>
      <label>Recent artifacts<input name="limit" inputmode="numeric" value="${escapeHtml(String(report.limit))}"></label>
      <label>Min age days<input name="minAgeDays" inputmode="numeric" placeholder="${escapeHtml(String(report.retentionPolicy.retentionDays))}" value="${escapeHtml(params.get("minAgeDays") ?? "")}"></label>
      <label>Min bytes<input name="minBytes" inputmode="numeric" placeholder="${escapeHtml(String(report.retentionPolicy.minPruneBytes))}" value="${escapeHtml(params.get("minBytes") ?? "")}"></label>
      <label class="check-row"><input type="checkbox" name="prunePlan" value="true"${report.prunePlan ? " checked" : ""}> Show dry-run prune plan</label>
      <label class="check-row"><input type="checkbox" name="archivePlan" value="true"${report.archivePlan ? " checked" : ""}> Show dry-run archive plan</label>
      <label class="check-row"><input type="checkbox" name="restorePlan" value="true"${report.restorePlan ? " checked" : ""}> Show dry-run restore plan</label>
      <label class="check-row"><input type="checkbox" name="includeAudit" value="true"${activeLifecycleCriteria?.includeAudit ? " checked" : ""}> Include audit artifacts</label>
      <div class="form-actions"><button type="submit">Filter</button></div>
    </form>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Artifact Lifecycle</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("artifact-lifecycle")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Artifact Lifecycle</h1><p class="muted">Read-only storage inventory for run artifacts. This page does not prune, archive, or delete anything.</p></div><a class="button secondary" href="/api/artifact-lifecycle?${escapeHtml(params.toString())}">JSON</a></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <section class="panel">${filters}<div class="meta-grid"><div><strong>Artifacts</strong>${report.totalArtifacts}</div><div><strong>Estimated JSON</strong>${escapeHtml(formatBytes(report.estimatedBytes))}</div><div><strong>Kinds</strong>${Object.keys(report.byKind).length}</div><div><strong>Projects</strong>${Object.keys(report.byProject).length}</div></div></section>
    <section class="panel"><div class="section-heading"><div><h2>Retention Policy</h2><span class="muted">Project-local defaults from .agent-workflow/project.yaml. Empty filter fields use this policy; filled fields become preview-only overrides.</span></div></div><div class="meta-grid"><div><strong>Source</strong>${escapeHtml(report.retentionPolicy.source)}</div><div><strong>Retention</strong>${report.retentionPolicy.retentionDays} days</div><div><strong>Minimum size</strong>${escapeHtml(formatBytes(report.retentionPolicy.minPruneBytes))}</div><div><strong>Audit artifacts</strong>${report.retentionPolicy.retainAuditArtifacts ? "retained by default" : "eligible by policy"}</div><div><strong>Legal hold</strong>${report.retentionPolicy.legalHold ? "enabled" : "off"}</div><div><strong>Approval</strong>${report.retentionPolicy.requireApprovalForPrune ? "required" : "project policy allows approval-free preview"}</div><div><strong>Archive execution</strong>${report.retentionPolicy.allowArchiveExecution ? "enabled" : "disabled"}</div><div><strong>Restore execution</strong>${report.retentionPolicy.allowRestoreExecution ? "enabled" : "disabled"}</div><div><strong>Prune execution</strong>${report.retentionPolicy.allowPruneExecution ? "enabled" : "disabled"}</div></div></section>
    <section class="panel"><div class="section-heading"><div><h2>Lifecycle Hints</h2><span class="muted">Hints are conservative and non-destructive. Future prune plans should cite exact ids and require approval.</span></div></div><ul>${hintRows || "<li>No lifecycle concerns found in the inspected artifact window.</li>"}</ul></section>
    ${report.prunePlan ? `<section class="panel"><div class="section-heading"><div><h2>Dry-run Prune Plan</h2><span class="muted">Preview only. No artifacts are deleted, archived, or modified.</span></div><div class="meta-grid"><div><strong>Candidates</strong>${report.prunePlan.totalCandidates}</div><div><strong>Recoverable</strong>${escapeHtml(formatBytes(report.prunePlan.estimatedBytesRecoverable))}</div><div><strong>Criteria</strong>${escapeHtml(report.prunePlan.criteria.policySource)}</div><div><strong>Approval</strong>${report.prunePlan.approvalRequired ? "required" : "not required by policy"}</div></div></div><ul>${pruneNotes}</ul>${queueApprovalForm || '<p class="muted">Select a project to queue lifecycle approvals for this prune plan.</p>'}<div class="table-wrap"><table><thead><tr><th>Artifact</th><th>Project</th><th>Run</th><th>Age/Size</th><th>Reason</th><th>Receipt Preview</th><th>URI</th></tr></thead><tbody>${pruneRows || '<tr><td colspan="7">No artifacts matched the current prune criteria.</td></tr>'}</tbody></table></div></section>` : ""}
    ${renderLifecyclePlanPanel(report.archivePlan)}
    ${renderLifecyclePlanPanel(report.restorePlan)}
    <section class="panel"><div class="meta-grid"><div><strong>By Kind</strong>${escapeHtml(formatInlineCounts(report.byKind) || "none")}</div><div><strong>By Age</strong>${escapeHtml(formatInlineCounts(report.byAgeBucket) || "none")}</div><div><strong>By Run Status</strong>${escapeHtml(formatInlineCounts(report.byRunStatus) || "none")}</div></div></section>
    <section class="panel"><div class="section-heading"><div><h2>Recent Artifacts</h2><span class="muted">Showing up to 100 newest rows from the inspected window.</span></div></div><div class="table-wrap"><table><thead><tr><th>Kind</th><th>Project</th><th>Run</th><th>Age</th><th>Size</th><th>URI</th></tr></thead><tbody>${artifactRows || '<tr><td colspan="6">No artifacts found.</td></tr>'}</tbody></table></div></section></main></body></html>`;
  }

  function renderBackupRestoreHtml(report: BackupRestoreReport, projects: DashboardProjectSummary[], params: URLSearchParams): string {
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${report.projectRootUri === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const statusClass = report.restoreDrill.status === "ready" ? "completed" : "queued";
    const serviceRows = report.services.map((service) => `
      <tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>
    `).join("");
    const checkRows = report.restoreDrill.checks.map((check) => `
      <tr><td>${escapeHtml(check.label)}</td><td><span class="status ${check.status === "pass" ? "completed" : "queued"}">${escapeHtml(check.status)}</span></td><td>${escapeHtml(check.detail)}</td></tr>
    `).join("");
    const kindRows = Object.entries(report.inventory.byKind)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([kind, value]) => `<tr><td>${escapeHtml(kind)}</td><td>${formatNumber(value.count)}</td><td>${escapeHtml(formatBytes(value.bytes))}</td></tr>`)
      .join("");
    const commandRows = report.recommendedCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const noteRows = report.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("");
    const jsonParams = new URLSearchParams();
    if (report.projectRootUri) jsonParams.set("project", report.projectRootUri);
    jsonParams.set("limit", String(report.limit));
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Backup Readiness</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("backup-report")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Backup Readiness</h1><p class="muted">Read-only local enterprise storage inventory and restore-drill posture. This page does not create backups, restore data, or mutate storage.</p></div><a class="button secondary" href="/api/backup-report?${escapeHtml(jsonParams.toString())}">JSON</a></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <section class="panel"><form method="get" class="workflow-form"><label>Project<select name="project"><option value="">all registered projects</option>${projectOptions}</select></label><label>Limit<input name="limit" value="${escapeHtml(params.get("limit") ?? String(report.limit))}" inputmode="numeric"></label><div class="form-actions"><button type="submit">Inspect</button></div></form></section>
    <section class="panel"><div class="metric-grid">
      ${metricCard("Status", report.restoreDrill.status, "restore-drill readiness")}
      ${metricCard("Projects", report.inventory.projects, "registered in local storage")}
      ${metricCard("Runs", report.inventory.runs, `${report.inventory.completedRuns} completed / ${report.inventory.failedRuns} failed`)}
      ${metricCard("Artifacts", report.inventory.artifacts, formatBytes(report.inventory.estimatedArtifactBytes))}
      ${metricCard("Archives", report.inventory.archivedArtifacts, "archived_artifact snapshots")}
      ${metricCard("Restores", report.inventory.restoredArtifacts, "restored_artifact snapshots")}
      ${metricCard("Lifecycle Approvals", report.restoreDrill.pendingLifecycleApprovals, "pending / approved / failed")}
      ${metricCard("Queue Items", report.restoreDrill.activeQueueItems, "queued / running / failed")}
    </div><p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Current status: <span class="status ${statusClass}">${escapeHtml(report.restoreDrill.status)}</span>.</p></section>
    <section class="panel"><h2>Services</h2><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${serviceRows || '<tr><td colspan="3">No service checks were recorded.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><h2>Restore Drill Checks</h2><div class="table-wrap"><table><thead><tr><th>Check</th><th>Status</th><th>Detail</th></tr></thead><tbody>${checkRows || '<tr><td colspan="3">No restore-drill checks were recorded.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><h2>Artifact Kinds</h2><div class="table-wrap"><table><thead><tr><th>Kind</th><th>Count</th><th>Bytes</th></tr></thead><tbody>${kindRows || '<tr><td colspan="3">No artifacts found in the inspected window.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><h2>Recommended Commands</h2><ul>${commandRows}</ul></section>
    <section class="panel"><h2>Notes</h2><ul>${noteRows || '<li>No backup or restore drill concerns found in the inspected window.</li>'}</ul></section></main></body></html>`;
  }

  function renderBulkApprovalsHtml(
    approvals: Awaited<ReturnType<typeof listActionApprovals>>,
    params: URLSearchParams = new URLSearchParams()
  ): string {
    const rows = approvals.map((approval) => `
      <label class="bulk-approval-row">
        <input type="checkbox" name="approvalId" value="${escapeHtml(approval.id)}" checked>
        <span>
          <strong>${escapeHtml(approvalOneLineSummary(approval))}</strong>
          <small>${escapeHtml(approval.id)} · ${escapeHtml(approval.projectName)} · ${escapeHtml(approval.workflowId)}</small>
        </span>
      </label>
    `).join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Approve Pending Actions</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("approvals")}
    <main>
      <div class="topbar">
        <div>
          <a href="/approvals">Approvals</a>
          <h1>Approve Pending Actions</h1>
          <p class="muted">Review each one-line summary and uncheck anything you do not want approved.</p>
        </div>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        ${approvals.length ? `<form method="post" action="/api/approval-bulk-action" class="bulk-approval-form">
          <input type="hidden" name="returnTo" value="/approvals/bulk?${escapeHtml(params.toString())}">
          <input type="hidden" name="actorRole" value="approver">
          <label>Decision note
            <input name="note" value="Bulk approved from dashboard after review">
          </label>
          <div class="bulk-approval-list">${rows}</div>
          <div class="actions">
            <button type="submit" name="decision" value="approve">Approve Checked</button>
            <button type="submit" name="decision" value="approve_execute">Approve Checked + Execute</button>
            <a class="button secondary" href="/approvals">Cancel</a>
          </div>
        </form>` : `<p class="muted">No pending approvals are available.</p><a class="button secondary" href="/approvals">Back to Approvals</a>`}
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderBundleTrustHtml(readiness: DashboardBundleReadiness, params: URLSearchParams): string {
    const verification = readiness.verification;
    const statusClass = verification.status === "trusted" ? "good" : verification.allowed ? "warn" : "bad";
    const query = params.toString();
    const jsonHref = `/api/bundles${query ? `?${query}` : ""}`;
    const projectValue = readiness.projectDir ?? "";
    const failedContracts = readiness.contractTests.results.filter((result) => result.status === "fail").length;
    const skippedContracts = readiness.contractTests.results.filter((result) => result.status === "skip").length;
    const migrationCount = readiness.migrationPlan.migrations.length;
    const registryRows = readiness.registry.entries.map((entry) => `
      <tr><td>${entry.selected ? "<strong>" : ""}${escapeHtml(entry.name)}${entry.selected ? "</strong>" : ""}<br><span class="muted">${escapeHtml(entry.id)}</span></td><td><span class="flag ${entry.status === "installed-current" ? "good" : entry.status === "upgrade-available" ? "warn" : "neutral"}">${escapeHtml(entry.status)}</span></td><td>${escapeHtml(entry.latestVersion)}</td><td>${escapeHtml(entry.packageName ?? "none")}</td><td>${entry.install.npm ? `<code>${escapeHtml(entry.install.npm)}</code>` : escapeHtml(entry.source)}</td></tr>
    `).join("");
    const pinHtml = readiness.pin
      ? readiness.pin.value
        ? `<h3>Project Pin</h3><div class="meta-grid compact"><div><strong>Bundle</strong>${escapeHtml(readiness.pin.value.bundle.id)} ${escapeHtml(readiness.pin.value.bundle.version)}</div><div><strong>Package</strong>${escapeHtml(readiness.pin.value.bundle.packageName ?? "none")}</div><div><strong>Pinned</strong>${renderDashboardDateTime(readiness.pin.value.bundle.pinnedAt)}</div><div><strong>By</strong>${escapeHtml(readiness.pin.value.bundle.pinnedBy)}</div></div><p class="muted">${escapeHtml(readiness.pin.path)}</p>`
        : `<h3>Project Pin</h3><p class="muted">No project-local bundle pin found at ${escapeHtml(readiness.pin.path)}.</p>`
      : "";
    const compatibilityRows = readiness.compatibility.checks.map((check) => `
      <tr><td>${escapeHtml(check.label)}</td><td><span class="flag ${check.compatible ? "good" : "bad"}">${check.compatible ? "pass" : "fail"}</span></td><td><code>${escapeHtml(check.actual)}</code></td><td><code>${escapeHtml(check.required)}</code></td><td>${escapeHtml(check.detail)}</td></tr>
    `).join("");
    const contractRows = readiness.contractTests.results.slice(0, 16).map((result) => `
      <tr><td><span class="flag ${result.status === "pass" ? "good" : result.status === "skip" ? "warn" : "bad"}">${escapeHtml(result.status)}</span></td><td>${escapeHtml(result.id)}</td><td>${escapeHtml(result.detail)}</td></tr>
    `).join("");
    const lifecycleForm = bundleLifecyclePlanForm(readiness, params);
    const migrationItems = readiness.migrationPlan.migrations.map((migration) => `
      <details class="artifact"><summary>${escapeHtml(migration.id)}: ${escapeHtml(migration.from)} to ${escapeHtml(migration.to)}</summary>
        <p>${escapeHtml(migration.summary)}</p>
        <h3>Validation</h3><ul>${migration.validation.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
        <h3>Rollback</h3><ul>${migration.rollbackSteps.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
      </details>
    `).join("");
    const errorBlock = readiness.errors.length
      ? `<section class="panel warn-panel"><h2>Needs attention</h2><ul>${readiness.errors.map((error) => `<li>${escapeHtml(error)}</li>`).join("")}</ul></section>`
      : "";
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Bundle Trust</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("bundles")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Workflow Bundle Readiness</h1><p class="muted">Read-only trust, compatibility, migration, and contract-test visibility. A signature never expands project execution permissions.</p></div><a class="button secondary" href="${escapeHtml(jsonHref)}">JSON</a></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <section class="panel"><form method="get" class="workflow-form"><label class="wide">Project path<input name="project" value="${escapeHtml(projectValue)}" placeholder="/path/to/project"></label><label>Trust policy<select name="policy">${["allow", "warn", "require"].map((policy) => `<option value="${policy}"${verification.policy === policy ? " selected" : ""}>${policy}</option>`).join("")}</select></label><div class="form-actions"><button type="submit">Inspect</button></div></form><p class="muted">Leave project path blank to inspect shared bundle readiness without project adoption state.</p></section>
    ${errorBlock}
    <section class="panel"><div class="metric-grid">
      ${metricCard("Trust", verification.status, verification.allowed ? "Current policy allows this bundle" : "Current policy rejects this bundle")}
      ${metricCard("Compatibility", readiness.compatibility.compatible ? "pass" : "fail", `${readiness.compatibility.checks.length} runtime checks`)}
      ${metricCard("Upgrade", readiness.upgradePreview.status, readiness.upgradePreview.source.kind)}
      ${metricCard("Migrations", migrationCount, readiness.migrationPlan.status)}
      ${metricCard("Contract Tests", readiness.contractTests.passed ? "pass" : "fail", `${failedContracts} failed, ${skippedContracts} skipped`)}
    </div><p class="muted">Generated ${renderDashboardDateTime(readiness.generatedAt)}${readiness.projectDir ? ` for ${escapeHtml(readiness.projectDir)}` : ""}.</p></section>
    <section class="panel"><div class="section-heading"><div><h2>${escapeHtml(verification.bundleId)} ${escapeHtml(verification.bundleVersion)}</h2><span class="muted">Manifest ${escapeHtml(verification.manifestChecksum)}</span></div><span class="flag ${statusClass}">${escapeHtml(verification.status)}</span></div>
    <div class="meta-grid"><div><strong>Policy</strong>${escapeHtml(verification.policy)}</div><div><strong>Decision</strong>${verification.allowed ? "allowed" : "rejected"}</div><div><strong>Signer</strong>${escapeHtml(verification.signerId ?? "none")}</div><div><strong>Trusted</strong>${verification.trusted}</div></div>
    <p><strong>Fingerprint:</strong> <code>${escapeHtml(verification.keyFingerprint ?? "none")}</code></p><p><strong>Signed:</strong> ${renderDashboardDateTime(verification.signedAt, "not signed")}<br><strong>Expires:</strong> ${renderDashboardDateTime(verification.expiresAt, "none")}</p>
    <h3>Verification</h3><ul>${verification.reasons.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul></section>
    <section class="panel"><div class="section-heading"><div><h2>Trusted Registry</h2><span class="muted">${escapeHtml(readiness.registry.registryPath)}</span></div><a class="button secondary" href="/api/bundle-registry">JSON</a></div><div class="table-wrap"><table><thead><tr><th>Bundle</th><th>Status</th><th>Latest</th><th>Package</th><th>Install</th></tr></thead><tbody>${registryRows || '<tr><td colspan="5">No registry entries found.</td></tr>'}</tbody></table></div>${pinHtml}<p class="muted">Registry entries are discovery and governance metadata. Installing or adopting a bundle still requires explicit package-manager and trust-verification steps.</p></section>
    <section class="panel"><h2>Lifecycle Plan</h2><p class="muted">Generate a reviewed upgrade or rollback command plan. The dashboard never installs packages or changes adoption state.</p>${lifecycleForm}</section>
    <section class="panel"><h2>Compatibility</h2><div class="table-wrap"><table><thead><tr><th>Check</th><th>Status</th><th>Actual</th><th>Required</th><th>Detail</th></tr></thead><tbody>${compatibilityRows}</tbody></table></div></section>
    <section class="panel"><h2>Project Adoption</h2><div class="meta-grid"><div><strong>Source</strong>${escapeHtml(readiness.upgradePreview.source.kind)}</div><div><strong>Status</strong>${escapeHtml(readiness.upgradePreview.status)}</div><div><strong>Source Version</strong>${escapeHtml(readiness.upgradePreview.source.version ?? "none")}</div><div><strong>Recorded</strong>${renderDashboardDateTime(readiness.upgradePreview.source.recordedAt, "none")}</div></div><h3>Recommended Actions</h3><ul>${readiness.upgradePreview.recommendations.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></section>
    <section class="panel"><h2>Definition Migrations</h2>${migrationItems || "<p>No applicable definition migrations.</p>"}<h3>Recommended Actions</h3><ul>${readiness.migrationPlan.recommendations.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></section>
    <section class="panel"><h2>Contract-Test Readiness</h2><div class="meta-grid compact"><div><strong>Definitions</strong>${escapeHtml(readiness.contractTests.definitionsDir)}</div><div><strong>Project</strong>${escapeHtml(readiness.contractTests.projectDir ?? "none")}</div><div><strong>Provider</strong>${escapeHtml(readiness.contractTests.providerId)}</div><div><strong>Live Provider</strong>${readiness.contractTests.liveProvider ? "yes" : "no"}</div></div><div class="table-wrap"><table><thead><tr><th>Status</th><th>Check</th><th>Detail</th></tr></thead><tbody>${contractRows}</tbody></table></div>${readiness.contractTests.results.length > 16 ? `<p class="muted">${formatNumber(readiness.contractTests.results.length - 16)} additional checks are available in JSON.</p>` : ""}</section>
    <section class="panel"><h2>Trust policy</h2><p>Set <code>AGENTFLOW_BUNDLE_TRUST_POLICY</code> to <code>allow</code>, <code>warn</code>, or <code>require</code>. Use the CLI to add public signer keys; private signing keys are never stored by Agent Workflow.</p></section></main></body></html>`;
  }

  function renderCandidateComparisonReportHtml(report: DashboardCandidateComparisonReport): string {
    const comparison = report.comparisonPlan;
    const suiteRows = comparison?.suites.map((suite) => {
      const file = report.suiteFiles.find((item) => item.path === suite.suitePath);
      const outcome = report.outcomes.find((item) => item.suiteId === suite.id);
      return `
        <tr>
          <td>${escapeHtml(suite.id)}</td>
          <td>${escapeHtml(suite.workflowId)}</td>
          <td>${formatNumber(suite.caseCount)}</td>
          <td><code>${escapeHtml(suite.suitePath)}</code></td>
          <td><span class="status ${file?.exists ? "completed" : "queued"}">${file?.exists ? "present" : "missing"}</span></td>
          <td>${outcome?.runs ?? 0}</td>
          <td>${outcome?.gateReady ? '<span class="flag good">ready</span>' : '<span class="flag warn">not yet</span>'}</td>
        </tr>
      `;
    }).join("") ?? "";
    const outcomeRows = report.outcomes.map((outcome) => `
      <tr>
        <td>${escapeHtml(outcome.suiteId)}</td>
        <td>${escapeHtml(outcome.leader ?? "none")}</td>
        <td>${outcome.baselineRuns}</td>
        <td>${outcome.candidateRuns}</td>
        <td>${outcome.baselineQuality ?? "n/a"}</td>
        <td>${outcome.candidateQuality ?? "n/a"}</td>
        <td>${outcome.qualityDelta ?? "n/a"}</td>
        <td>${outcome.latencyDeltaMs === null ? "n/a" : formatDurationDelta(outcome.latencyDeltaMs)}</td>
        <td>${outcome.latestAt ? renderDashboardDateTime(outcome.latestAt) : "n/a"}</td>
      </tr>
    `).join("");
    const recommendationRows = report.promotionRecommendations.map((recommendation) => `
      <tr>
        <td>${escapeHtml(recommendation.suiteId)}</td>
        <td><span class="flag ${recommendation.severity === "ready" ? "good" : recommendation.severity === "warning" ? "warn" : "queued"}">${escapeHtml(recommendation.decision.replace(/_/g, " "))}</span></td>
        <td><ul>${recommendation.rationale.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></td>
        <td>${recommendation.nextAction.includes("npm run ") ? `<code>${escapeHtml(recommendation.nextAction)}</code>` : escapeHtml(recommendation.nextAction)}</td>
      </tr>
    `).join("");
    const promotionFileRows = report.promotionNoteFiles.map((file) => `
      <tr>
        <td><code>${escapeHtml(file.path)}</code></td>
        <td><span class="status ${file.exists && !file.error ? "completed" : file.error ? "failed" : "queued"}">${file.exists && !file.error ? "present" : file.error ? "error" : "missing"}</span></td>
        <td>${file.exists ? formatNumber(file.bytes) : "n/a"}</td>
        <td>${file.modifiedAt ? renderDashboardDateTime(file.modifiedAt) : "n/a"}</td>
        <td>${file.error ? escapeHtml(file.error) : file.preview ? "preview below" : "n/a"}</td>
      </tr>
    `).join("");
    const promotionMarkdownPreview = report.promotionNoteFiles.find((file) => file.path.endsWith(".md") && file.preview)?.preview ?? "";
    const commandRows = report.nextCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const gateRows = comparison?.gateCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("") ?? "";
    const gateReadyCount = report.outcomes.filter((outcome) => outcome.gateReady).length;
    const recommendationReadyCount = report.promotionRecommendations.filter((recommendation) => recommendation.decision === "propose_routing_note").length;
    return `
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Model Plan", report.modelPlanExists && !report.modelPlanError ? "ready" : "missing", report.modelPlanError ?? ".agent-workflow/model-improvement")}
          ${metricCard("Comparison Plan", report.comparisonPlanExists && !report.comparisonPlanError ? "ready" : "missing", report.comparisonPlanError ?? "candidate-comparison-plan.json")}
          ${metricCard("Eval Cases", report.modelPlan?.evalCases.length ?? 0, "from approved feedback")}
          ${metricCard("Suites", comparison?.suites.length ?? 0, "generated private eval files")}
          ${metricCard("Suite Files", `${report.suiteFiles.filter((suite) => suite.exists).length}/${report.suiteFiles.length}`, "present")}
          ${metricCard("Gate Ready", `${gateReadyCount}/${report.outcomes.length}`, "baseline and candidate runs")}
          ${metricCard("Promotable", `${recommendationReadyCount}/${report.promotionRecommendations.length}`, "reviewed routing note")}
          ${metricCard("Generated", formatDashboardDateTimeText(report.generatedAt), "local read")}
        </div>
        <p class="muted">Project ${escapeHtml(report.projectDir)}.</p>
      </section>
      <section class="panel">
        <h2>Readiness</h2>
        <ul>${report.readiness.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
        ${localHoldoutComparisonForm(report)}
      </section>
      ${renderLocalHoldoutRoutingStatusHtml(report.localHoldoutRouting)}
      ${renderLocalRouteDecisionDrilldownHtml(report.routeReceiptTrends, report.localHoldoutRouting)}
      ${renderRouteReceiptTrendsHtml(report.routeReceiptTrends)}
      <section class="panel">
        <h2>Variants</h2>
        ${comparison ? `
          <div class="meta-grid compact">
            <div><strong>Baseline</strong>${escapeHtml(comparison.baseline.provider)} / ${escapeHtml(comparison.baseline.modelTier)}<br><span class="muted">${escapeHtml(comparison.baseline.promptSuffix)}</span></div>
            <div><strong>Candidate</strong>${escapeHtml(comparison.candidate.provider)} / ${escapeHtml(comparison.candidate.modelTier)}<br><span class="muted">${escapeHtml(comparison.candidate.promptSuffix)}</span></div>
          </div>
        ` : '<p class="muted">No candidate comparison plan found.</p>'}
      </section>
      <section class="panel">
        <h2>Suites</h2>
        <div class="table-wrap"><table><thead><tr><th>Suite</th><th>Workflow</th><th>Cases</th><th>Path</th><th>File</th><th>Runs</th><th>Gate</th></tr></thead><tbody>${suiteRows || "<tr><td colspan=\"7\">No suites generated.</td></tr>"}</tbody></table></div>
      </section>
      <section class="panel">
        <h2>Outcomes</h2>
        <div class="table-wrap"><table><thead><tr><th>Suite</th><th>Leader</th><th>Baseline Runs</th><th>Candidate Runs</th><th>Baseline Quality</th><th>Candidate Quality</th><th>Quality Delta</th><th>Latency Delta</th><th>Latest</th></tr></thead><tbody>${outcomeRows || "<tr><td colspan=\"9\">No evaluation outcomes yet.</td></tr>"}</tbody></table></div>
        ${localHoldoutResultsForm(report)}
      </section>
      <section class="panel">
        <h2>Promotion Recommendation</h2>
        <div class="table-wrap"><table><thead><tr><th>Suite</th><th>Decision</th><th>Rationale</th><th>Next Action</th></tr></thead><tbody>${recommendationRows || "<tr><td colspan=\"4\">No comparison outcomes available yet.</td></tr>"}</tbody></table></div>
        ${promotionNotePlanForm(report)}
        ${localHoldoutPromotionForm(report)}
      </section>
      <section class="panel">
        <h2>Promotion Note Files</h2>
        <div class="table-wrap"><table><thead><tr><th>Path</th><th>Status</th><th>Bytes</th><th>Modified</th><th>Preview</th></tr></thead><tbody>${promotionFileRows}</tbody></table></div>
        ${promotionMarkdownPreview ? `<h3>Markdown Preview</h3><pre>${escapeHtml(promotionMarkdownPreview)}</pre>` : '<p class="muted">No written promotion note plan yet. Preview or write one from a promotable recommendation.</p>'}
      </section>
      <section class="panel">
        <h2>Promotion Gates</h2>
        <ul>${gateRows || "<li>Run baseline and candidate evaluations before promotion.</li>"}</ul>
      </section>
      <section class="panel">
        <h2>Next Commands</h2>
        <ul>${commandRows}</ul>
      </section>
    `;
  }

  function renderCandidateComparisonsHtml(
    report: DashboardCandidateComparisonReport | null,
    projects: DashboardProjectSummary[],
    params: URLSearchParams
  ): string {
    const selectedProject = report?.projectDir ?? params.get("project") ?? process.env.AGENTFLOW_DASHBOARD_PROJECT ?? "";
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}">${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`).join("");
    const jsonHref = report ? `/api/candidate-comparisons?project=${encodeURIComponent(report.projectDir)}` : "";
    const body = report
      ? renderCandidateComparisonReportHtml(report)
      : `<section class="panel"><h2>No Project Selected</h2><p class="muted">Run onboarding or enter a project path to inspect local candidate comparison evidence.</p></section>`;
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Candidate Comparisons</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("candidate-comparisons")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Candidate Comparisons</h1>
          <p class="muted">Read-only local visibility for model-improvement comparison suites, baseline/candidate variants, and promotion gates.</p>
        </div>
        ${jsonHref ? `<a class="button secondary" href="${escapeHtml(jsonHref)}">JSON</a>` : ""}
      </div>
      <section class="panel">
        <form method="get" class="workflow-form">
          <label class="wide">Project path
            <input name="project" value="${escapeHtml(selectedProject)}" list="candidate-comparison-projects" placeholder="/path/to/project">
            <datalist id="candidate-comparison-projects">${projectOptions}</datalist>
          </label>
          <div class="form-actions"><button type="submit">Inspect</button></div>
        </form>
      </section>
      ${body}
    </main>
  </body>
  </html>`;
  }

  function renderContextGatewayHtml(report: Awaited<ReturnType<typeof loadContextOperatorReport>>, projects: DashboardProjectSummary[], selected: string): string {
    const options = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${project.rootUri === selected ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const plans = report.codegen.plans.map((plan) => `<tr><td>${escapeHtml(plan.id)}</td><td>${escapeHtml(plan.target)}</td><td>${escapeHtml(plan.status)}</td><td><code>${escapeHtml(plan.receipt)}</code></td></tr>`).join("") || `<tr><td colspan="4">No governed generation plans.</td></tr>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Context Gateway</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("context-gateway")}
    <main><header><div><p class="eyebrow">Optimize</p><h1>Context Gateway</h1><p>Body-free operating evidence, readiness gates, and review queues.</p></div></header>
    <section class="panel"><form method="get" action="/context-gateway"><label>Project<select name="project">${options}</select></label><button type="submit">Inspect</button></form></section>
    <section class="metrics">
      ${metricCard("Projected Savings", `${report.efficiency.projectedSavingsPercent}%`, `${report.efficiency.projectedFrontierTokensAvoided} frontier tokens avoided`)}
      ${metricCard("Evidence", report.efficiency.observations, `${report.efficiency.eligibleReads} eligible reads`)}
      ${metricCard("Cache Health", `${report.cache.validEntries}/${report.cache.entries}`, `${report.cache.bytes} bytes; ${report.cache.expiredEntries} expired`)}
      ${metricCard("Pending Review", report.codegen.awaitingReview, `${report.codegen.total} generation plans`)}
    </section>
    <section class="grid two"><article class="panel"><h2>Readiness</h2><dl><dt>Policy</dt><dd>${escapeHtml(report.policyMode)}</dd><dt>Holdout approved</dt><dd>${report.holdoutApproved ? "yes" : "no"}</dd><dt>Claude Code</dt><dd>${report.hosts.claude ? "installed" : "not installed"}</dd><dt>Cursor</dt><dd>${report.hosts.cursor ? "installed" : "not installed"}</dd><dt>Codex</dt><dd>${report.hosts.codex ? "installed" : "not installed"}</dd></dl></article>
    <article class="panel"><h2>Calibration</h2>${report.calibration ? `<p><strong>${escapeHtml(report.calibration.corpus)}</strong></p><p>${report.calibration.cases} cases · quality ${(report.calibration.qualityPassRate * 100).toFixed(1)}% · citations ${(report.calibration.citationPassRate * 100).toFixed(1)}% · savings ${report.calibration.tokenSavingsPercent}%</p><p>Regression ${report.calibration.regression.passed ? "passed" : "failed"}; enforcement ${report.calibration.enforcementReady ? "ready" : "not ready"}.</p>` : "<p>No repository calibration evidence yet.</p>"}</article></section>
    <section class="panel"><h2>Governed generation plans</h2><table><thead><tr><th>ID</th><th>Target</th><th>Status</th><th>Receipt</th></tr></thead><tbody>${plans}</tbody></table></section>
    <section class="panel"><h2>Safe actions</h2><p>Use <code>context-host-setup</code> without <code>--write</code> to preview hooks, and <code>context-calibrate</code> to write evidence. Threshold proposals remain review-required and never modify policy automatically.</p><p><a href="/api/context-gateway?project=${encodeURIComponent(selected)}">JSON status</a></p></section>
    </main></body></html>`;
  }

  function renderCostQualityHtml(report: CostQualityReport): string {
    const stageRows = report.stages.map((stage) => `
      <tr>
        <td>${escapeHtml(stage.stageId)}</td>
        <td>${escapeHtml(stage.agentId)}</td>
        <td>${escapeHtml(stage.providerId)}${stage.model ? `<br><span class="muted">${escapeHtml(stage.model)}</span>` : ""}</td>
        <td>${escapeHtml(stage.modelTier)}${stage.requestedModelTier !== stage.modelTier ? `<br><span class="muted">requested ${escapeHtml(stage.requestedModelTier)}</span>` : ""}</td>
        <td>${escapeHtml(stage.estimatedCostTier)}</td>
        <td>${stage.qualityScore ?? "n/a"} ${stage.qualityPassed === false ? "<span class=\"flag bad\">Review</span>" : stage.qualityPassed === true ? "<span class=\"flag good\">Pass</span>" : ""}</td>
        <td>${stage.fallbackUsed ? escapeHtml(stage.fallbackProviderId ?? "yes") : "no"}</td>
        <td>${stage.latencyMs ?? "n/a"}</td>
      </tr>
    `).join("");
    const recommendations = report.recommendations.map((item) => `<li>${escapeHtml(item)}</li>`).join("");

    return `
      <div class="metric-grid">
        ${metricCard("Quality", report.averageQuality ?? "n/a", `${report.qualityPassCount} pass / ${report.qualityFailCount} review`)}
        ${metricCard("Fallbacks", report.fallbackCount, "retry count")}
        ${metricCard("Latency", `${report.totalLatencyMs}ms`, `avg ${report.averageLatencyMs ?? "n/a"}ms`)}
        ${metricCard("Local/BYO Savings", report.estimatedByoSavingsStages, "local or low-cost stages")}
      </div>
      <div class="meta-grid compact">
        <div><strong>Providers</strong>${escapeHtml(formatInlineCounts(report.providerMix))}</div>
        <div><strong>Cost Mix</strong>${escapeHtml(formatInlineCounts(report.estimatedCostMix))}</div>
        <div><strong>Model Tiers</strong>${escapeHtml(formatInlineCounts(report.modelTierMix))}</div>
      </div>
      <table>
        <thead><tr><th>Stage</th><th>Agent</th><th>Provider</th><th>Tier</th><th>Cost</th><th>Quality</th><th>Fallback</th><th>Latency ms</th></tr></thead>
        <tbody>${stageRows || "<tr><td colspan=\"8\">No routing receipts found.</td></tr>"}</tbody>
      </table>
      <h3>Recommendations</h3>
      <ul>${recommendations}</ul>
    `;
  }

  function renderDaemonLanes(supervisor: DashboardSupervisorStatus, daemon: DashboardLearningDaemonStatus | null): string {
    const lanes = [
      ["Supervisor", supervisor.status === "running", `${formatNumber(supervisor.ticks)} ticks`],
      ["Worker", supervisor.workerManaged, supervisor.workerManaged ? "managed" : "external"],
      ["Learning", daemon?.status === "running", daemon?.mode ?? supervisor.learningMode ?? "disabled"],
      ["Dashboard", supervisor.dashboardManaged, supervisor.dashboardManaged ? "managed" : "external"]
    ] as const;
    return `<div class="ops-daemon-lanes">${lanes.map(([label, active, detail]) => `<div><i class="${active ? "active" : "idle"}"></i><span><strong>${label}</strong><small>${escapeHtml(detail)}</small></span></div>`).join("")}</div><div class="ops-daemon-trust"><span>Autonomy ceiling</span><strong>${escapeHtml(daemon?.autonomousApplyMaxRisk ?? "none")}</strong></div>`;
  }

  function renderDaemonMonitor(supervisor: DashboardSupervisorStatus, daemon: DashboardLearningDaemonStatus | null, receipts: LearningActionReceiptLog | null): string {
    const events = [...(receipts?.events ?? [])].sort((a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt)).slice(-24);
    const buckets = new Map<string, { label: string; applied: number; planned: number; other: number }>();
    for (const event of events) {
      const date = new Date(event.createdAt);
      const key = event.createdAt.slice(0, 10);
      const bucket = buckets.get(key) ?? { label: Number.isFinite(date.getTime()) ? date.toLocaleDateString("en-US", { month: "short", day: "numeric" }) : key, applied: 0, planned: 0, other: 0 };
      if (event.status === "applied") bucket.applied += 1;
      else if (event.status === "planned") bucket.planned += 1;
      else bucket.other += 1;
      buckets.set(key, bucket);
    }
    const points = [...buckets.values()].slice(-10);
    const max = Math.max(...points.map((item) => item.applied + item.planned + item.other), 1);
    const bars = points.map((item) => {
      const total = item.applied + item.planned + item.other;
      return `<div class="ops-daemon-column"><div class="ops-daemon-stack" style="height:${Math.max(8, (total / max) * 100)}%"><i class="applied" style="--share:${item.applied}"></i><i class="planned" style="--share:${item.planned}"></i><i class="other" style="--share:${item.other}"></i></div><span>${escapeHtml(item.label)}</span></div>`;
    }).join("");
    const status = daemon?.status ?? supervisor.status;
    const lastCycle = daemon?.lastReportAt ?? daemon?.lastHeartbeatAt ?? supervisor.lastHeartbeatAt;
    return `<div class="ops-daemon-layout"><div class="ops-daemon-chart">${bars || '<div class="ops-empty"><strong>No daemon action receipts yet</strong><span>Heartbeat monitoring remains active.</span></div>'}</div><div class="ops-daemon-facts"><div><span>Status</span><strong class="${status === "running" ? "good-text" : "warn-text"}">${escapeHtml(status)}</strong></div><div><span>Cycles</span><strong>${formatNumber(daemon?.ticks ?? supervisor.ticks)}</strong></div><div><span>Last cycle</span><strong>${renderDashboardDateTime(lastCycle, "none")}</strong></div><div><span>Actions</span><strong>${formatNumber(events.length)}</strong></div></div></div><div class="ops-legend"><span><i class="daemon-applied"></i>Applied</span><span><i class="daemon-planned"></i>Planned</span><span><i class="daemon-other"></i>Closed</span></div>`;
  }

  function renderDashboardActionHistory(): string {
    return `<section id="dashboard-action-history" class="panel action-history" hidden>
      <div class="section-heading">
        <div>
          <h2>Recent Dashboard Actions</h2>
          <span class="muted">Browser-local history for this dashboard.</span>
        </div>
        <button type="button" class="secondary compact-button" onclick="window.localStorage.removeItem('agentflow.dashboard.actions'); document.getElementById('dashboard-action-history').hidden = true;">Clear</button>
      </div>
      <ul></ul>
    </section>
    <script>
      (() => {
        try {
          const normalizeActionMessage = (value) => {
            const message = String(value || "Action completed");
            const missing = /spawn\\s+([^\\s]+)\\s+ENOENT/i.exec(message);
            if (missing) return "Missing " + missing[1] + " on PATH";
            return message.replace(/ENOENT/g, "missing executable");
          };
          const panel = document.getElementById("dashboard-action-history");
          const list = panel?.querySelector("ul");
          const actions = JSON.parse(window.localStorage.getItem("agentflow.dashboard.actions") || "[]");
          if (!panel || !list || !Array.isArray(actions) || !actions.length) return;
          const now = Date.now();
          const freshActions = actions.filter((item) => {
            const at = Date.parse(String(item?.at || ""));
            if (!Number.isFinite(at)) return false;
            const maxAgeMs = item?.level === "error" ? 30 * 60 * 1000 : 10 * 60 * 1000;
            return now - at <= maxAgeMs;
          }).slice(0, 5);
          window.localStorage.setItem("agentflow.dashboard.actions", JSON.stringify(freshActions));
          if (!freshActions.length) return;
          list.innerHTML = freshActions.map((item) => {
            const level = item.level === "error" ? "error" : "success";
            const date = item.at ? new Date(item.at).toLocaleString([], { dateStyle: "medium", timeStyle: "short" }) : "unknown time";
            const message = normalizeActionMessage(item.message)
              .replace(/&/g, "&amp;")
              .replace(/</g, "&lt;")
              .replace(/>/g, "&gt;");
            const path = String(item.path || "/")
              .replace(/&/g, "&amp;")
              .replace(/</g, "&lt;")
              .replace(/>/g, "&gt;");
            const marker = level === "error" ? "!" : "OK";
            return '<li class="' + level + '"><strong><span aria-hidden="true">' + marker + '</span>' + message + '</strong><span>' + path + ' · ' + date + '</span></li>';
          }).join("");
          panel.hidden = false;
        } catch {}
      })();
    </script>`;
  }

  function renderDashboardActionResult(result: DashboardFollowUpResult): string {
    const actionLinks = `
      <div class="actions">
        <a class="button" href="/approvals?status=pending">Pending Approvals</a>
        <a class="button secondary" href="/approvals?status=approved">Approved</a>
        <a class="button secondary" href="/approvals?status=executed">Executed</a>
        <a class="button secondary" href="/queue">Queue</a>
        <a class="button secondary" href="/">Dashboard</a>
      </div>
    `;
    const body = result.ok
      ? `<section class="panel action-result success"><h1>${escapeHtml(result.title)}</h1>${renderActionResultSummary(result.output)}<pre>${escapeHtml(result.output)}</pre>${result.runId ? `<p><a class="button" href="/run?id=${encodeURIComponent(result.runId)}">Open run</a></p>` : ""}${actionLinks}</section>`
      : `<section class="panel action-result failed"><h1>Action failed</h1><pre>${escapeHtml(result.error)}</pre>${actionLinks}</section>`;
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Dashboard Action</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>${dashboardNav("dashboard")}<main><p><a href="/">Dashboard</a></p>${body}</main></body>
  </html>`;
  }

  function renderDashboardDateTime(value: string | null | undefined, fallback = "n/a"): string {
    if (!value) {
      return escapeHtml(fallback);
    }
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) {
      return escapeHtml(value);
    }
    const label = formatDashboardDateTimeText(value);
    return `<time datetime="${escapeHtml(parsed.toISOString())}" title="${escapeHtml(value)}">${escapeHtml(label)}</time>`;
  }

  function renderDashboardFlash(params: URLSearchParams): string {
    const notice = params.get("notice");
    const error = params.get("error");
    const actionRun = params.get("actionRun");
    if (!notice && !error) return "";
    const message = error ?? notice ?? "";
    const runLink = actionRun ? `<a class="button secondary" href="/run?id=${encodeURIComponent(actionRun)}">Open Run</a>` : "";
    const historyEntry = {
      level: error ? "error" : "success",
      message,
      path: "",
      at: ""
    };
    return `<section class="panel flash-panel ${error ? "error" : "success"}">
      <div>
        <strong>${dashboardIcon(error ? "warning" : "check")}${error ? "Action needs attention" : "Action complete"}</strong>
        <span>${escapeHtml(message)}</span>
      </div>
      ${runLink}
    </section>
    <script>
      (() => {
        try {
          const key = "agentflow.dashboard.actions";
          const entry = ${serializeInlineScriptJson(historyEntry)};
          entry.path = window.location.pathname;
          entry.at = new Date().toISOString();
          const current = JSON.parse(window.localStorage.getItem(key) || "[]");
          const currentList = Array.isArray(current) ? current : [];
          const isDuplicate = currentList[0]?.level === entry.level && currentList[0]?.message === entry.message && currentList[0]?.path === entry.path;
          const now = Date.now();
          const isFresh = (item) => {
            const at = Date.parse(String(item?.at || ""));
            if (!Number.isFinite(at)) return false;
            const maxAgeMs = item?.level === "error" ? 30 * 60 * 1000 : 10 * 60 * 1000;
            return now - at <= maxAgeMs;
          };
          const next = (isDuplicate ? currentList : [entry, ...currentList]).filter(isFresh).slice(0, 5);
          window.localStorage.setItem(key, JSON.stringify(next));
        } catch {}
      })();
    </script>`;
  }

  function renderDashboardGraphHandoffView(result: DashboardGraphHandoffViewResult): string {
    const backHref = result.ok
      ? `/workflow-graph?project=${encodeURIComponent(result.projectDir)}`
      : `/workflow-graph${result.projectDir ? `?project=${encodeURIComponent(result.projectDir)}` : ""}`;
    const body = result.ok
      ? `<div class="topbar"><div><a href="${escapeHtml(backHref)}">Graph</a><h1>Graph Handoff</h1><p class="muted">${escapeHtml(result.fileName)}</p></div><div class="actions">${result.summary ? `<a class="button secondary" href="${escapeHtml(result.summary.graphPath)}">Open Saved Graph</a>` : ""}</div></div>
        <section class="panel"><div class="meta-grid compact">
          <div><strong>Project</strong>${escapeHtml(result.projectDir)}</div>
          <div><strong>Markdown</strong>${escapeHtml(result.markdownPath)}</div>
          <div><strong>JSON</strong>${escapeHtml(result.jsonPath ?? "missing")}</div>
          <div><strong>Generated</strong>${result.summary ? renderDashboardDateTime(result.summary.generatedAt) : "unknown"}</div>
        </div>${renderGraphExportLifecycleHtml(result.projectDir, result.summary ? 1 : 0)}</section>
        <section class="panel"><h2>Handoff Markdown</h2><pre class="markdown-view">${escapeHtml(result.markdown)}</pre></section>`
      : `<div class="topbar"><div><a href="${escapeHtml(backHref)}">Graph</a><h1>Graph Handoff</h1><p class="muted">Unable to open the requested export.</p></div></div><section class="panel warn-panel"><pre>${escapeHtml(result.error)}</pre></section>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Graph Handoff</title><style>${dashboardCss()}</style></head><body>${dashboardNav("workflow-graph")}<main>${body}</main></body></html>`;
  }

  function renderDashboardHtml(runs: Awaited<ReturnType<typeof listWorkflowRuns>>, workflows: Awaited<ReturnType<typeof loadWorkflows>>, health: DashboardHomeHealth, throughput: WorkflowThroughputBucket[]): string {
    const activeRuns = runs.filter((run) => run.status === "queued" || run.status === "leased" || run.status === "running");
    const recentRuns = runs.filter((run) => run.status === "completed" || run.status === "failed").slice(0, 8);
    const humanInterventions = buildHumanInterventionItems({ pendingApprovals: health.pendingApprovals, approvedExecutableApprovals: health.approvedExecutableApprovals, queue: health.queue, workerStatus: health.worker.status, supervisorStatus: health.supervisor.status, mcpStatus: health.runtimeMonitor.mcpPipeline.status, missingServices: health.services.filter((service) => !service.reachable).map((service) => service.endpoint.name), learningDaemonError: health.learningDaemon?.lastError, approvalBacklogErrors: health.learningDaemon?.approvalBacklogErrors, approvalBacklogWarnings: health.learningDaemon?.approvalBacklogWarnings, agentImprovementPending: health.agentImprovementPendingPromotions });
    const failedRuns = health.queue.filter((item) => item.runStatus === "failed").length;
    const terminalRuns = runs.filter((run) => run.status === "completed" || run.status === "failed");
    const completedRuns = terminalRuns.filter((run) => run.status === "completed").length;
    const successRate = terminalRuns.length ? Math.round((completedRuns / terminalRuns.length) * 100) : 0;
    const durations = terminalRuns.map(dashboardRunDurationMs).filter((value): value is number => value !== null).sort((a, b) => a - b);
    const medianDuration = durations.length ? durations[Math.floor(durations.length / 2)] : null;
    const activeStageTasks = health.queue.reduce((sum, item) => sum + item.queuedTasks + item.runningTasks, 0);
    const activeProjects = health.projects.filter((project) => project.runCount > 0 || project.indexedFiles > 0).length;
    const servicesReady = health.services.filter((service) => service.reachable).length;
    const systemHealthy = servicesReady === health.services.length && health.worker.status === "running" && health.supervisor.status === "running" && failedRuns === 0;
    const interventionRows = humanInterventions.map((item) => `
      <a class="ops-approval-row" href="${escapeHtml(item.href)}">
        <span class="ops-status-dot ${item.severity}"></span>
        <span><strong>${escapeHtml(compactDashboardText(item.title, 52))}</strong><small>${escapeHtml(compactDashboardText(item.detail, 72))}</small></span>
        <span>${escapeHtml(item.action)}</span>
      </a>`).join("");
    const recentRows = recentRuns.map((run) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.id)}">${escapeHtml(run.id.slice(0, 8))}</a></td>
        <td><strong>${escapeHtml(compactDashboardText(run.task, 54))}</strong><small>${escapeHtml(run.projectName)}</small></td>
        <td>${escapeHtml(workflowDisplayName(run.workflowId))}</td>
        <td><span class="ops-run-status ${escapeHtml(run.status)}"><i></i>${escapeHtml(run.status)}</span></td>
        <td>${escapeHtml(formatDashboardDuration(dashboardRunDurationMs(run)))}</td>
        <td>${renderDashboardDateTime(run.startedAt)}</td>
      </tr>`).join("");
    const workflowOptions = workflows
      .filter((workflow) => workflow.triggers.manual)
      .map((workflow) => `<option value="${escapeHtml(workflow.id)}">${escapeHtml(workflow.name)} (${escapeHtml(workflow.id)})</option>`)
      .join("");
    const defaultProject = process.env.AGENTFLOW_DASHBOARD_PROJECT ?? "templates/project";

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Dashboard</title>
    <style>
      ${dashboardCss()}
    </style>
  </head>
  <body>
    ${dashboardNav("dashboard")}
    <main class="ops-home">
      <div class="ops-topbar">
        <div><h1>System Pulse</h1><p>Live operational view of agent execution, reliability, and flow.</p></div>
        <div class="ops-topbar-actions"><span class="ops-live"><i></i> Live</span><a class="button" href="#start-work">${dashboardIcon("play")} Start workflow</a></div>
      </div>
      <section class="ops-pulse-panel">
        <div class="ops-pulse-heading">
          <div class="ops-neural-line" aria-hidden="true">${renderOpsPulseLine()}</div>
          <a class="ops-system-state ${systemHealthy ? "good" : "warn"}" href="/settings"><i></i><span><strong>${systemHealthy ? "All systems operational" : "System attention required"}</strong><small>${servicesReady}/${health.services.length} services · worker ${escapeHtml(health.worker.status)} · supervisor ${escapeHtml(health.supervisor.status)}</small></span>${dashboardIcon("chevrons")}</a>
        </div>
        <div class="ops-metric-row">
          ${renderOpsMetric("Recent runs", formatNumber(runs.length), `${activeRuns.length} active`, runs.map((_, index) => index + 1), "cyan")}
          ${renderOpsMetric("Success rate", `${successRate}%`, `${completedRuns}/${terminalRuns.length || 0} terminal`, terminalRuns.map((run) => run.status === "completed" ? 1 : 0), "teal")}
          ${renderOpsMetric("Median duration", formatDashboardDuration(medianDuration), `${durations.length} measured`, durations.slice(-10), "violet")}
          ${renderOpsMetric("Active stage tasks", formatNumber(activeStageTasks), `${health.queue.length} queue records`, health.queue.slice(0, 10).map((item) => item.queuedTasks + item.runningTasks), "cyan")}
          ${renderOpsMetric("Human intervention", formatNumber(humanInterventions.length), humanInterventions.length ? "action required" : "clear", [0, humanInterventions.filter((item) => item.severity === "warn").length, humanInterventions.filter((item) => item.severity === "bad").length], "amber")}
          ${renderOpsMetric("Active projects", formatNumber(activeProjects), `${health.projects.length} registered`, health.projects.slice(0, 10).map((project) => project.runCount), "violet")}
        </div>
      </section>
      ${renderDashboardQuestionPanel(health.projects, process.env.AGENTFLOW_DASHBOARD_PROJECT ?? ctx.rootDir)}
      <div class="ops-chart-grid">
        <section class="ops-panel ops-span-2"><div class="ops-panel-heading"><div><h2>Workflow throughput</h2><span>Runs by final state · rolling 7 days</span></div><a href="/runs">View runs</a></div>${renderOpsThroughputChart(throughput)}</section>
        <section class="ops-panel"><div class="ops-panel-heading"><div><h2>Run health</h2><span>Current state distribution</span></div></div>${renderOpsStatusChart(runs)}</section>
        <section class="ops-panel ops-span-2"><div class="ops-panel-heading"><div><h2>Execution duration</h2><span>Completed and failed run latency</span></div></div>${renderOpsDurationChart(terminalRuns)}</section>
        <section class="ops-panel"><div class="ops-panel-heading"><div><h2>Queue pressure</h2><span>Stage work and oldest active item</span></div><a href="/queue">Open queue</a></div>${renderOpsQueuePressure(health.queue)}</section>
        <section class="ops-panel ops-span-2"><div class="ops-panel-heading"><div><h2>Agent flow</h2><span>Current and next stage handoffs</span></div><a href="/workflow-graph">Open graph</a></div>${renderOpsAgentFlow(health.queue, runs)}</section>
        <section class="ops-panel"><div class="ops-panel-heading"><div><h2>Project activity</h2><span>Runs across registered projects</span></div><a href="/projects">Projects</a></div>${renderOpsProjectActivity(health.projects)}</section>
        <section class="ops-panel ops-span-2 ops-daemon-panel"><div class="ops-panel-heading"><div><h2>Daemon monitor</h2><span>Learning cycles, autonomous actions, and heartbeat health</span></div><a href="/learning">Open learning</a></div>${renderDaemonMonitor(health.supervisor, health.learningDaemon, health.learningReceipts)}</section>
        <section class="ops-panel"><div class="ops-panel-heading"><div><h2>Daemon lanes</h2><span>Managed runtime responsibilities</span></div><a href="/settings">Settings</a></div>${renderDaemonLanes(health.supervisor, health.learningDaemon)}</section>
      </div>
      <div class="ops-lower-grid">
        <section class="ops-panel ops-runs-panel"><div class="ops-panel-heading"><div><h2>Recent runs</h2><span>Latest terminal workflow outcomes</span></div><a href="/runs">View all runs</a></div><div class="table-wrap"><table class="ops-table"><colgroup><col class="ops-col-run"><col class="ops-col-task"><col class="ops-col-workflow"><col class="ops-col-status"><col class="ops-col-duration"><col class="ops-col-started"></colgroup><thead><tr><th>Run</th><th>Task</th><th>Workflow</th><th>Status</th><th>Duration</th><th>Started</th></tr></thead><tbody>${recentRows || '<tr><td colspan="6">No terminal runs in the current window.</td></tr>'}</tbody></table></div></section>
        <section class="ops-panel ops-approvals-panel"><div class="ops-panel-heading"><div><h2>Human intervention</h2><span>Every decision, recovery, and runtime item requiring a person</span></div><a href="/approvals">Open approvals</a></div><div class="ops-approval-list" role="region" aria-label="Human intervention items" tabindex="0">${interventionRows || '<div class="ops-empty"><strong>No human intervention needed</strong><span>The system can continue autonomously.</span></div>'}</div></section>
      </div>
      <section class="ops-panel start-work" id="start-work">
        <div class="human-section-heading"><div><h2>Start work</h2><p>Describe the outcome. Agent Workflow will handle the execution details.</p></div></div>
        <form class="workflow-form human-composer" method="post" action="/api/workflow-run">
          <label>Project path
            <input name="project" value="${escapeHtml(defaultProject)}" placeholder="/path/to/project">
          </label>
          <label>Workflow
            <select name="workflowId">${workflowOptions}</select>
          </label>
          <label class="wide">What would you like done?
            <textarea name="task" rows="4" placeholder="Describe the outcome you want"></textarea>
          </label>
          <details class="advanced-options wide">
            <summary>Advanced options</summary>
            <div class="advanced-grid">
              <label>Context token budget<input name="sourceTokenBudget" inputmode="numeric" placeholder="3000"></label>
              <label>Maximum source files<input name="sourceMaxFiles" inputmode="numeric" placeholder="20"></label>
              <label>Maximum work items<input name="workerLimit" inputmode="numeric" value="6"></label>
              <label>Parallel work items<input name="workerConcurrency" inputmode="numeric" value="1"></label>
              <label>Watch timeout in milliseconds<input name="timeoutMs" inputmode="numeric" value="60000"></label>
              <label class="check-row"><input type="checkbox" name="watch"> Stay on this page while work starts</label>
            </div>
          </details>
          <div class="form-actions wide"><button type="submit">Start work</button></div>
        </form>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderDashboardInfoHtml(info: DashboardInfo, params: URLSearchParams = new URLSearchParams()): string {
    const serviceRows = info.services.map((service) => `
      <tr>
        <td>${escapeHtml(service.name)}</td>
        <td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "reachable" : "missing"}</span></td>
        <td>${escapeHtml(service.message)}</td>
        <td>${escapeHtml(service.requiredFor)}</td>
      </tr>
    `).join("");
    const commands = info.commands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const providerRows = [
      ["Selected", info.provider.selected],
      ["Adapter", info.provider.adapter],
      ["Model", info.provider.model ?? "not set"],
      ["API key", typeof info.provider.apiKeyConfigured === "boolean" ? info.provider.apiKeyConfigured ? "configured" : "not configured" : "not used"]
    ].map(([label, value]) => `<div><strong>${escapeHtml(label)}</strong>${escapeHtml(value)}</div>`).join("");

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
        <title>Agent Workflow Settings</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("info")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Settings</h1>
        </div>
        <a class="button secondary" href="/api/settings">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <h2>Runtime</h2>
        <div class="meta-grid">
          <div><strong>App</strong>${escapeHtml(info.app.name)} ${escapeHtml(info.app.version)}</div>
          <div><strong>Root</strong>${escapeHtml(info.app.rootDir)}</div>
          <div><strong>Dashboard</strong>${escapeHtml(info.app.dashboardUrl)}</div>
          <div><strong>Registry</strong>${info.registry.agents} agents, ${info.registry.workflows} workflows</div>
        </div>
      </section>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Provider Summary</h2>
            <span class="muted">Model and routing controls live on the Providers page.</span>
          </div>
          <a class="button secondary" href="/providers">Open Providers</a>
        </div>
        <div class="meta-grid">${providerRows}</div>
      </section>
      <section class="panel">
        <h2>Enterprise Services</h2>
        <table><thead><tr><th>Service</th><th>Status</th><th>Message</th><th>Required For</th></tr></thead><tbody>${serviceRows}</tbody></table>
      </section>
      ${renderRuntimeMonitorPanel(info.runtimeMonitor, params)}
      <section class="panel">
        <h2>Local Supervisor</h2>
        ${renderSupervisorStatusHtml(info.supervisor)}
      </section>
      <section class="panel">
        <h2>macOS LaunchAgent</h2>
        ${renderLaunchAgentStatusHtml(info.launchAgent, params)}
      </section>
      <section class="panel">
        <h2>Background Worker</h2>
        ${renderWorkerStatusHtml(info.worker)}
      </section>
      <section class="panel">
        <h2>Bundle Manifest</h2>
        ${info.bundle ? `<div class="meta-grid">
          <div><strong>Version</strong>${escapeHtml(info.bundle.version)}</div>
          <div><strong>Files</strong>${info.bundle.files}</div>
          <div><strong>Checksum</strong><code>${escapeHtml(info.bundle.checksum)}</code></div>
          <div><strong>Source</strong>${escapeHtml(info.bundle.source)}</div>
        </div>` : "<p>No committed bundle manifest found.</p>"}
      </section>
      <section class="panel">
        <h2>Storage Config</h2>
        <div class="meta-grid">
          <div><strong>DATABASE_URL</strong>${info.storage.databaseUrlConfigured ? "configured" : "missing"}</div>
          <div><strong>REDIS_URL</strong>${info.storage.redisUrlConfigured ? "configured" : "missing"}</div>
          <div><strong>Object storage</strong>${info.storage.objectStorageConfigured ? "configured" : "missing"}</div>
        </div>
      </section>
      <section class="panel">
        <h2>Useful Commands</h2>
        <ul>${commands}</ul>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderDashboardProjectPathResolutionHtml(projectPath: DashboardProjectPathResolution): string {
    return `
      <section class="panel compact-panel">
        <div class="section-heading">
          <div>
            <h2>Project Path Mapping</h2>
            <span class="muted">Shared storage can keep a project under one host path while this machine uses another local checkout path.</span>
          </div>
          <span class="status ${projectPath.localPathExists ? "completed" : "queued"}">${projectPath.localPathExists ? projectPath.source : "not mounted"}</span>
        </div>
        <div class="meta-grid compact">
          <div><strong>Storage Root</strong>${escapeHtml(projectPath.storageRootUri)}</div>
          <div><strong>Local Root</strong>${escapeHtml(projectPath.localRootUri)}</div>
          <div><strong>Mapped</strong>${projectPath.mapped ? "yes" : "no"}</div>
          <div><strong>Local Path</strong>${projectPath.localPathExists ? "available" : "missing"}</div>
        </div>
        <p class="muted">${escapeHtml(projectPath.note)}</p>
      </section>
    `;
  }

  function renderDashboardRoleAuditView(result: DashboardRoleAuditViewResult): string {
    const backHref = result.projectDir ? `/roles?project=${encodeURIComponent(result.projectDir)}` : "/roles";
    const body = result.ok
      ? `<div class="topbar"><div><a href="${escapeHtml(backHref)}">Roles</a><h1>Role Audit Snapshot</h1><p class="muted">${escapeHtml(result.fileName)}</p></div></div>
        <section class="panel"><div class="meta-grid compact">
          <div><strong>Project</strong>${escapeHtml(result.summary?.projectPath ?? result.projectDir ?? "all registered projects")}</div>
          <div><strong>Markdown</strong>${escapeHtml(result.markdownPath)}</div>
          <div><strong>JSON</strong>${escapeHtml(result.jsonPath ?? "missing")}</div>
          <div><strong>Generated</strong>${result.summary ? renderDashboardDateTime(result.summary.generatedAt) : "unknown"}</div>
          <div><strong>Filters</strong>${escapeHtml(`${result.summary?.role ?? "all"} / ${result.summary?.status ?? "all"} / ${result.summary?.actionType ?? "all"}`)}</div>
          <div><strong>Approvals</strong>${formatNumber(result.summary?.approvalCount ?? 0)}</div>
        </div></section>
        <section class="panel"><h2>Snapshot Markdown</h2><pre class="markdown-view">${escapeHtml(result.markdown)}</pre></section>`
      : `<div class="topbar"><div><a href="${escapeHtml(backHref)}">Roles</a><h1>Role Audit Snapshot</h1><p class="muted">Unable to open the requested export.</p></div></div><section class="panel warn-panel"><pre>${escapeHtml(result.error)}</pre></section>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Role Audit Snapshot</title><style>${dashboardCss()}</style></head><body>${dashboardNav("roles")}<main>${body}</main></body></html>`;
  }

  function renderDiscoveryHtml(report: ProjectDiscoveryReport, params: URLSearchParams): string {
    const spotlightOptions = ["auto", "on", "off"].map((mode) => `<option value="${mode}"${report.spotlight.requested === mode ? " selected" : ""}>${mode}</option>`).join("");
    const hiddenDiscoveryFields = [
      `<input type="hidden" name="roots" value="${escapeHtml(report.roots.join(","))}">`,
      `<input type="hidden" name="maxDepth" value="${escapeHtml(String(report.maxDepth))}">`,
      `<input type="hidden" name="maxCandidates" value="${escapeHtml(String(report.maxCandidates))}">`,
      `<input type="hidden" name="spotlight" value="${escapeHtml(report.spotlight.requested)}">`
    ].join("");
    const rows = report.candidates.map((candidate) => `
      <tr>
        <td>${escapeHtml(candidate.name)}<br><span class="muted">${escapeHtml(candidate.rootUri)}</span></td>
        <td><span class="flag ${candidate.confidence === "high" ? "good" : candidate.confidence === "medium" ? "queued" : "warn"}">${escapeHtml(candidate.confidence)}</span></td>
        <td>${escapeHtml(candidate.source)}</td>
        <td>${candidate.initialized ? "yes" : "no"}</td>
        <td>${candidate.registered ? "yes" : "no"}</td>
        <td>${escapeHtml(candidate.markers.join(", "))}</td>
        <td>${candidate.suggestedCommands.map((command) => `<code>${escapeHtml(command)}</code>`).join("<br>")}</td>
        <td>
          ${candidate.initialized ? `
            <form method="post" action="/api/discovery-adopt" class="inline-form compact-form">
              ${dashboardReturnInput("/discovery", params)}
              ${hiddenDiscoveryFields}
              <input type="hidden" name="paths" value="${escapeHtml(candidate.rootUri)}">
              <input type="hidden" name="index" value="on">
              <input type="hidden" name="maxFiles" value="100">
              <button type="submit">Index</button>
            </form>
          ` : `
            <form method="post" action="/api/discovery-adopt" class="inline-form compact-form">
              ${dashboardReturnInput("/discovery", params)}
              ${hiddenDiscoveryFields}
              <input type="hidden" name="paths" value="${escapeHtml(candidate.rootUri)}">
              <input type="hidden" name="initialize" value="on">
              <input type="hidden" name="profile" value="enterprise">
              <button type="submit">Initialize</button>
            </form>
          `}
        </td>
      </tr>
    `).join("");
    const warningItems = report.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    const nextItems = report.nextCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const jsonParams = new URLSearchParams(params);
    if (!jsonParams.has("roots")) jsonParams.set("roots", report.roots.join(","));
    if (!jsonParams.has("maxDepth")) jsonParams.set("maxDepth", String(report.maxDepth));
    if (!jsonParams.has("maxCandidates")) jsonParams.set("maxCandidates", String(report.maxCandidates));
    if (!jsonParams.has("spotlight")) jsonParams.set("spotlight", report.spotlight.requested);
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Discovery</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("discovery")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Discovery</h1>
          <p class="muted">Local-only project discovery across governed roots. This page reads directory names and marker files only; it does not index file contents.</p>
        </div>
        <a class="button secondary" href="/api/discovery?${escapeHtml(jsonParams.toString())}">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <form method="get" class="workflow-form">
          <label class="wide">Roots
            <input name="roots" value="${escapeHtml(report.roots.join(","))}" placeholder="/Users/you/Projects,/path/to/root">
          </label>
          <label>Max depth
            <input name="maxDepth" value="${escapeHtml(String(report.maxDepth))}" inputmode="numeric">
          </label>
          <label>Max candidates
            <input name="maxCandidates" value="${escapeHtml(String(report.maxCandidates))}" inputmode="numeric">
          </label>
          <label>Spotlight
            <select name="spotlight">${spotlightOptions}</select>
          </label>
          <div class="form-actions"><button type="submit">Discover</button></div>
        </form>
        <p class="muted">For a whole-drive preview on macOS, use root <code>/</code> with Spotlight <code>auto</code>. Default excludes skip system, cache, dependency, photo library, backup, and private runtime directories.</p>
      </section>
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Candidates", report.candidates.length, "review before indexing")}
          ${metricCard("Roots", report.roots.length, "governed scan roots")}
          ${metricCard("Spotlight", report.spotlight.used ? "used" : "not used", report.spotlight.available ? "available" : "unavailable")}
          ${metricCard("Max Depth", report.maxDepth, "filesystem fallback")}
        </div>
      </section>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Adopt Candidates</h2>
            <span class="muted">Initialize writes project-local Agent Workflow files. Index registers initialized projects and stores compact source summaries.</span>
          </div>
        </div>
        <form method="post" action="/api/discovery-adopt" class="workflow-form">
          ${dashboardReturnInput("/discovery", params)}
          ${hiddenDiscoveryFields}
          <input type="hidden" name="all" value="on">
          <label>Max files per project
            <input name="maxFiles" value="100" inputmode="numeric">
          </label>
          <label>Profile
            <select name="profile"><option value="enterprise" selected>enterprise</option><option value="simple">simple</option></select>
          </label>
          <label class="checkbox-row"><input type="checkbox" name="initialize" value="on"> initialize missing project files</label>
          <label class="checkbox-row"><input type="checkbox" name="index" value="on" checked> index initialized projects</label>
          <div class="form-actions"><button type="submit">Adopt Selected Scope</button></div>
        </form>
      </section>
      ${warningItems ? `<section class="panel"><h2>Warnings</h2><ul>${warningItems}</ul></section>` : ""}
      <section class="panel">
        <h2>Candidate Projects</h2>
        <div class="table-wrap"><table><thead><tr><th>Project</th><th>Confidence</th><th>Source</th><th>Initialized</th><th>Registered</th><th>Markers</th><th>Next Commands</th><th>Action</th></tr></thead><tbody>${rows || "<tr><td colspan=\"8\">No candidate projects found.</td></tr>"}</tbody></table></div>
      </section>
      <section class="panel"><h2>Next Commands</h2><ul>${nextItems}</ul></section>
    </main>
  </body>
  </html>`;
  }

  function renderEvaluationsHtml(suites: DashboardEvaluationSuite[], selected: DashboardEvaluationSuite | null, providerStatuses: Awaited<ReturnType<typeof loadAutoProviderStatuses>>): string { const testedProviders = new Set(suites.flatMap((suite) => suite.variants.map((variant) => variant.provider)));
    const providerRows = providerStatuses.map((provider) => { const tested = testedProviders.has(provider.providerId), statusClass = provider.status === "ready" ? "completed" : provider.status === "missing" ? "failed" : "queued"; return `<tr${provider.providerId === "muse" ? ' class="leader-row"' : ""}><td><strong>${escapeHtml(provider.label)}</strong><br><code>${escapeHtml(provider.providerId)}</code></td><td><span class="status ${statusClass}">${escapeHtml(provider.status)}</span></td><td>${escapeHtml(provider.model ?? "auto")}</td><td><span class="flag ${tested ? "good" : "warn"}">${tested ? "tested" : "not tested"}</span></td><td>${tested ? `${suites.filter((suite) => suite.variants.some((variant) => variant.provider === provider.providerId)).length} suite(s)` : "No evaluation runs yet"}</td><td><a class="button secondary" href="/providers?provider=${encodeURIComponent(provider.providerId)}">Configure</a></td></tr>`; }).join("");
    const suiteLinks = suites.map((suite) => `
      <a class="suite-link ${selected?.id === suite.id ? "active" : ""}" href="/evaluations?suite=${encodeURIComponent(suite.id)}">
        <strong>${escapeHtml(suite.name)}</strong>
        <span>${escapeHtml(suite.workflowId)} · ${suite.runs.length} runs</span>
        <small>${renderDashboardDateTime(suite.latestAt)}</small>
      </a>
    `).join("");
    const variantRows = selected?.variants.map((variant) => `
      <tr class="${selected.leader === variant.id ? "leader-row" : ""}">
        <td><strong>${escapeHtml(variant.id)}</strong>${selected.leader === variant.id ? '<span class="flag good">leader</span>' : ""}</td>
        <td>${escapeHtml(variant.provider)}</td>
        <td>${escapeHtml(variant.modelTier)}</td>
        <td>${variant.completed}/${variant.runs}</td>
        <td>${variant.averageQuality ?? "n/a"}</td>
        <td>${variant.averageLatencyMs === null ? "n/a" : formatDuration(variant.averageLatencyMs)}</td>
        <td>${variant.fallbackRate}</td>
        <td>${escapeHtml(formatInlineCounts(variant.estimatedCostMix))}</td>
        <td>${escapeHtml(formatInlineCounts(variant.feedbackCounts))}</td>
      </tr>
    `).join("") ?? "";
    const runRows = selected?.runs.map((run) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.runId)}">${escapeHtml(run.runId.slice(0, 8))}</a></td>
        <td>${escapeHtml(run.caseId)}</td>
        <td>${escapeHtml(run.variantId)}</td>
        <td><span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span></td>
        <td>${run.averageQuality ?? "n/a"}</td>
        <td>${formatDuration(run.totalLatencyMs)}</td>
        <td>${run.fallbackCount}</td>
        <td>${escapeHtml(run.feedback ?? "none")}</td>
      </tr>
    `).join("") ?? "";

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Evaluations</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("evaluations")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Evaluations</h1>
          <p class="muted">Compare workflow quality, latency, fallback behavior, cost mix, and feedback across provider, tier, and prompt variants.</p>
        </div>
        <a class="button secondary" href="/api/evaluations${selected ? `?suite=${encodeURIComponent(selected.id)}` : ""}">JSON</a>
      </div>
      <section class="panel"><div class="section-heading"><div><h2>Provider coverage</h2><span class="muted">Supported providers remain visible even before they have evaluation evidence. “Tested” means at least one stored suite contains that provider.</span></div><a class="button secondary" href="/candidate-comparisons">Plan comparison</a></div><div class="table-wrap"><table><thead><tr><th>Provider</th><th>Readiness</th><th>Model</th><th>Coverage</th><th>Evidence</th><th>Setup</th></tr></thead><tbody>${providerRows}</tbody></table></div></section>
      <div class="comparison-layout">
        <aside class="suite-list" aria-label="Evaluation suites">
          <h2>Suites</h2>
          ${suiteLinks || '<p class="muted">No evaluation runs found.</p>'}
        </aside>
        <div>
          ${selected ? `
            <section class="panel">
              <div class="section-heading">
                <div><h2>${escapeHtml(selected.name)}</h2><span class="muted">${escapeHtml(selected.workflowId)} · latest ${renderDashboardDateTime(selected.latestAt)}</span></div>
                <span class="flag good">Leader: ${escapeHtml(selected.leader ?? "none")}</span>
              </div>
              <div class="table-wrap">
                <table>
                  <thead><tr><th>Variant</th><th>Provider</th><th>Tier</th><th>Completed</th><th>Quality</th><th>Latency</th><th>Fallbacks/run</th><th>Cost mix</th><th>Feedback</th></tr></thead>
                  <tbody>${variantRows}</tbody>
                </table>
              </div>
            </section>
            <section class="panel">
              <h2>Run matrix</h2>
              <div class="table-wrap">
                <table>
                  <thead><tr><th>Run</th><th>Case</th><th>Variant</th><th>Status</th><th>Quality</th><th>Latency</th><th>Fallbacks</th><th>Feedback</th></tr></thead>
                  <tbody>${runRows}</tbody>
                </table>
              </div>
            </section>
          ` : '<section class="panel"><h2>No evaluation data</h2><p>Run <code>agentflow evaluate</code> to populate this comparison view.</p></section>'}
        </div>
      </div>
    </main>
  </body>
  </html>`;
  }

  function renderFailedRunResolutionPanel(run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>): string {
    const resolution = failedRunResolution(run.failedReason);
    return `<section class="failure-resolution" aria-labelledby="failure-resolution-title">
      <h3 id="failure-resolution-title">Reason Failed</h3>
      <p class="warn-box">${escapeHtml(run.failedReason?.trim() || "No specific failure reason was recorded. This is a workflow defect; use Diagnose & Fix to gather fresh evidence.")}</p>
      <h3>How to resolve</h3>
      <p>${escapeHtml(resolution.summary)}</p>
      <ol>${resolution.instructions.map((instruction) => `<li>${escapeHtml(instruction)}</li>`).join("")}</ol>
      <p class="muted">Automatic root repair: ${resolution.automaticRepair === "eligible" ? "eligible when policy and evidence permit" : "waiting for an operator-managed prerequisite"}.</p>
      <div class="actions">
        ${queueRunActionForm(run.id, "retry-failed", "Retry Failed Stages")}
        ${queueRunActionForm(run.id, "repair-blocked", "Diagnose & Fix")}
        <a class="button secondary" href="/providers">Open Providers</a>
        <a class="button secondary" href="/approvals?status=open&run=${encodeURIComponent(run.id)}">Open Approvals</a>
      </div>
    </section>`;
  }

  function renderFeedbackBulkReviewHtml(report: DashboardFeedbackInboxReport, params: URLSearchParams): string {
    const allItems = [
      ...report.groups.probably_accept,
      ...report.groups.probably_revise,
      ...report.groups.probably_reject
    ];
    const rows = allItems.map((item) => {
      const suggestedRating = feedbackRatingForBucket(item.classification.bucket);
      return `
        <tr>
          <td><input type="checkbox" name="runId" value="${escapeHtml(item.runId)}" checked></td>
          <td><a href="/run?id=${encodeURIComponent(item.runId)}">${escapeHtml(item.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(item.workflowId)} · ${renderDashboardDateTime(item.startedAt)}</span><div class="row-tools">${renderRunInfoDialog({
            runId: item.runId,
            workflowId: item.workflowId,
            status: item.status,
            task: item.task,
            startedAt: item.startedAt,
            summary: [
              item.classification.reason,
              item.summary ? `${item.summary.completedTasks}/${item.summary.totalTasks} stages complete, ${item.summary.failedTasks} failed` : "summary unavailable",
              item.summary?.recommendedNextAction ?? "next action unavailable"
            ]
          })}</div></td>
          <td><span class="flag ${suggestedRating === "accepted" ? "good" : suggestedRating === "revised" ? "warn" : "bad"}">${escapeHtml(suggestedRating)}</span><br><span class="muted">${escapeHtml(item.classification.reason)}</span></td>
          <td>
            <select name="rating:${escapeHtml(item.runId)}">
              ${(["accepted", "revised", "rejected"] as const).map((rating) => `<option value="${rating}"${rating === suggestedRating ? " selected" : ""}>${rating}</option>`).join("")}
            </select>
          </td>
          <td><input name="note:${escapeHtml(item.runId)}" value="${escapeHtml(defaultFeedbackNote(item, suggestedRating))}" placeholder="What should future runs learn?"></td>
          <td>
            <strong>${escapeHtml(item.task)}</strong>
            ${item.summary ? `<br><span class="muted">${item.summary.completedTasks}/${item.summary.totalTasks} stages complete · ${item.summary.failedTasks} failed</span>` : ""}
            ${item.summary?.keyFindings.length ? `<br><span class="muted">${escapeHtml(truncateText(item.summary.keyFindings[0], 180))}</span>` : ""}
            ${item.summary?.failures.length ? `<br><span class="muted">${escapeHtml(truncateText(item.summary.failures[0], 180))}</span>` : ""}
          </td>
        </tr>
      `;
    }).join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Bulk Feedback</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("feedback-inbox")}
    <main>
      <div class="topbar">
        <div>
          <a href="/feedback-inbox?${escapeHtml(params.toString())}">Feedback Inbox</a>
          <h1>Bulk Feedback Review</h1>
          <p class="muted">Review suggested feedback ratings, uncheck anything you do not want to record, then submit selected rows.</p>
        </div>
      </div>
      ${renderDashboardFlash(params)}
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Selected By Default", allItems.length, "uncheck rows to skip")}
          ${metricCard("Probably Accept", report.counts.probably_accept, "suggested accepted")}
          ${metricCard("Probably Revise", report.counts.probably_revise, "suggested revised")}
          ${metricCard("Probably Reject", report.counts.probably_reject, "suggested rejected")}
          ${metricCard("Project Scope", report.projectRootUri ? "one" : "all", report.projectRootUri ?? "all registered projects")}
          ${metricCard("Generated", formatDashboardDateTimeText(report.generatedAt), "local read")}
        </div>
      </section>
      <section class="panel">
        <form method="post" action="/api/feedback-bulk-action" class="bulk-feedback-form">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri ?? "")}">
          <input type="hidden" name="limit" value="${escapeHtml(String(report.limit))}">
          <div class="form-actions">
            <button type="submit"${allItems.length ? "" : " disabled"}>Record Selected Feedback</button>
            <a class="button secondary" href="/feedback-inbox?${escapeHtml(params.toString())}">Cancel</a>
          </div>
          <div class="table-wrap"><table><thead><tr><th>Use</th><th>Run</th><th>Suggestion</th><th>Rating</th><th>Note</th><th>Evidence</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">No unreviewed runs found.</td></tr>"}</tbody></table></div>
        </form>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderFeedbackHtml(runId: string, report: CostQualityReport): string {
    const latest = report.feedback.latest
      ? `<p><strong>Latest:</strong> ${escapeHtml(report.feedback.latest.rating)}${report.feedback.latest.note ? ` - ${escapeHtml(report.feedback.latest.note)}` : ""}</p>`
      : "<p>No feedback recorded yet.</p>";
    return `
      ${latest}
      <div class="actions">
        ${feedbackForm(runId, "accepted", "Accept")}
        ${feedbackForm(runId, "revised", "Mark Revised")}
        ${feedbackForm(runId, "rejected", "Reject")}
      </div>
    `;
  }

  function renderFeedbackInboxGroupHtml(
    title: string,
    defaultRating: FeedbackRating,
    items: DashboardFeedbackInboxItem[]
  ): string {
    const rows = items.map((target) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(target.runId)}">${escapeHtml(target.runId.slice(0, 8))}</a><br><span class="muted">${renderDashboardDateTime(target.startedAt)}</span><div class="row-tools">${renderRunInfoDialog({
          runId: target.runId,
          workflowId: target.workflowId,
          status: target.status,
          task: target.task,
          startedAt: target.startedAt,
          summary: [
            target.classification.reason,
            target.summary ? `${target.summary.completedTasks}/${target.summary.totalTasks} stages complete, ${target.summary.failedTasks} failed` : "summary unavailable",
            target.summary?.recommendedNextAction ?? "next action unavailable"
          ]
        })}</div></td>
        <td>${escapeHtml(target.workflowId)}<br><span class="muted">${escapeHtml(target.classification.reason)}</span></td>
        <td>
          <strong>${escapeHtml(target.task)}</strong>
          ${target.summary ? `<br><span class="muted">${target.summary.completedTasks}/${target.summary.totalTasks} stages complete · ${target.summary.failedTasks} failed · ${escapeHtml(target.summary.recommendedNextAction)}</span>` : ""}
        </td>
        <td>${renderFeedbackTargetEvidenceHtml(target)}</td>
        <td>${renderFeedbackTargetPrimaryActionForm(target, defaultRating)}${renderFeedbackTargetActionForms(target)}</td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>${escapeHtml(title)}</h2>
            <span class="muted">${items.length} unreviewed run${items.length === 1 ? "" : "s"}</span>
          </div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Run</th><th>Workflow</th><th>Summary</th><th>Evidence</th><th>Feedback</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No runs in this bucket.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderFeedbackInboxHtml(
    report: DashboardFeedbackInboxReport,
    projects: DashboardProjectSummary[],
    params: URLSearchParams
  ): string {
    const selectedProject = report.projectRootUri ?? params.get("project") ?? "";
    const projectOptions = [
      `<option value=""${selectedProject ? "" : " selected"}>All registered projects</option>`,
      ...projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${selectedProject === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`)
    ].join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Feedback Inbox</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("feedback-inbox")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Feedback Inbox</h1>
          <p class="muted">Review unscored runs across projects and turn them into local learning signal.</p>
        </div>
        <div class="actions">
          <a class="button" href="/feedback-inbox/bulk?${escapeHtml(params.toString())}">Bulk Review</a>
          <a class="button secondary" href="/api/feedback-inbox?${escapeHtml(params.toString())}">JSON</a>
        </div>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <form method="get" class="workflow-form">
          <label class="wide">Project<select name="project">${projectOptions}</select></label>
          <label>Run limit<input name="limit" value="${escapeHtml(String(report.limit))}" inputmode="numeric"></label>
          <div class="form-actions"><button type="submit">Refresh Inbox</button></div>
        </form>
      </section>
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Unreviewed", report.totalTargets, `${report.totalCandidates} recent finished runs scanned`)}
          ${metricCard("Probably Accept", report.counts.probably_accept, "clean useful runs")}
          ${metricCard("Probably Revise", report.counts.probably_revise, "useful with caveats")}
          ${metricCard("Probably Reject", report.counts.probably_reject, "wrong, failed, or low quality")}
          ${metricCard("Project Scope", report.projectRootUri ? "one" : "all", report.projectRootUri ?? "all registered projects")}
          ${metricCard("Generated", formatDashboardDateTimeText(report.generatedAt), "local read")}
        </div>
      </section>
      ${renderFeedbackInboxGroupHtml("Probably Accept", "accepted", report.groups.probably_accept)}
      ${renderFeedbackInboxGroupHtml("Probably Revise", "revised", report.groups.probably_revise)}
      ${renderFeedbackInboxGroupHtml("Probably Reject", "rejected", report.groups.probably_reject)}
    </main>
  </body>
  </html>`;
  }

  function renderFeedbackTargetActionForms(target: DashboardFeedbackTarget): string {
    return `
      <div class="feedback-row-actions">
        ${feedbackTargetActionForm(target.runId, "accepted", "Accept", defaultFeedbackNote(target, "accepted"))}
        ${feedbackTargetActionForm(target.runId, "revised", "Revise", defaultFeedbackNote(target, "revised"))}
        ${feedbackTargetActionForm(target.runId, "rejected", "Reject", defaultFeedbackNote(target, "rejected"))}
      </div>
    `;
  }

  function renderFeedbackTargetEvidenceHtml(target: DashboardFeedbackTarget): string {
    const quality = target.quality
      ? [
        `quality ${target.quality.averageQuality ?? "n/a"}`,
        `${target.quality.qualityPassCount} pass`,
        `${target.quality.qualityFailCount} review`,
        `${target.quality.fallbackCount} fallback`,
        target.quality.averageLatencyMs === null ? "" : `avg ${formatDuration(target.quality.averageLatencyMs)}`
      ].filter(Boolean).join(" · ")
      : "quality n/a";
    const findings = target.summary?.keyFindings.length
      ? `<strong>Findings</strong><ul>${target.summary.keyFindings.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
      : "";
    const failures = target.summary?.failures.length
      ? `<strong>Failures</strong><ul>${target.summary.failures.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
      : "";
    return `<span class="muted">${escapeHtml(quality)}</span>${findings}${failures}`;
  }

  function renderFeedbackTargetPrimaryActionForm(target: DashboardFeedbackInboxItem, rating: FeedbackRating): string {
    return `
      <div class="recommended-feedback">
        <strong>Recommended</strong>
        ${feedbackTargetActionForm(target.runId, rating, `Mark ${titleCase(rating)}`, defaultFeedbackNote(target, rating))}
      </div>
    `;
  }

  function renderFleetModelUsageHtml(report: DashboardFleetUsageReport): string {
    const rows = report.receipts.slice(-100).reverse().map((receipt: FleetUsageReceipt) => `<tr>
      <td>${escapeHtml(receipt.observedAt)}</td><td>${escapeHtml(receipt.clientId)}</td><td>${escapeHtml(receipt.projectId ?? "unattributed")}</td>
      <td>${escapeHtml(receipt.provider)}</td><td>${escapeHtml(receipt.model ?? "unknown")}</td><td>${formatNumber(receipt.inputTokens)}</td>
      <td>${formatNumber(receipt.cachedInputTokens)}</td><td>${formatNumber(receipt.reasoningTokens)}</td><td>${formatNumber(receipt.outputTokens)}</td>
      <td>${formatNumber(receipt.totalTokens)}</td><td><span class="status ${receipt.status === "completed" ? "completed" : "failed"}">${escapeHtml(receipt.status)}</span></td>
    </tr>`).join("") || `<tr><td colspan="11">No gateway usage receipts have been observed yet.</td></tr>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Fleet Model Usage</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("fleet-model-usage")}<main><div class="topbar"><div><a href="/settings">Settings</a><h1>Fleet Model Usage</h1><p class="page-intro">Metadata-only usage observed through the authenticated fleet gateway.</p></div><a class="button secondary" href="/api/fleet-model-usage">JSON</a></div>
    <section class="callout ${report.dashboardSource === "local-fallback" ? "failed" : "completed"}"><strong>Data source</strong><p>${escapeHtml(report.dashboardSource)}${report.dashboardNotice ? ` · ${escapeHtml(report.dashboardNotice)}` : ""}</p></section>
    <section class="metrics">${metricCard("Requests", report.totals.requests, `${report.totals.failures} failed`)}${metricCard("Total Tokens", report.totals.totalTokens, `${report.clients.length} clients`)}${metricCard("Input Tokens", report.totals.inputTokens, `${report.totals.cachedInputTokens} cached`)}${metricCard("Output Tokens", report.totals.outputTokens, `${report.totals.reasoningTokens} reasoning`)}${metricCard("Estimated Cost", `$${report.totals.estimatedCostUsd.toFixed(4)}`, "configured pricing; billing is authoritative")}</section>
    <section class="panel"><h2>Recent Requests</h2><p class="muted">Prompts, responses, credentials, and raw request bodies are never stored. Calls that bypass the gateway are not included.</p><div class="table-wrap"><table><thead><tr><th>Observed</th><th>Client</th><th>Project</th><th>Provider</th><th>Model</th><th>Input</th><th>Cached</th><th>Reasoning</th><th>Output</th><th>Total</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div></section>
    <section class="panel"><h2>Run the Gateway</h2><p><code>npm run model-gateway</code></p><p>Configure credentials only through the environment. See <code>docs/fleet-model-gateway.md</code> for fleet setup and reconciliation guidance.</p></section></main></body></html>`;
  }

  function renderFocusedStageDeltaHtml(delta: FocusedStageDeltaSummary): string {
    const statusClass = delta.label === "Improved" ? "good" : delta.label === "Regressed" ? "bad" : "warn";
    return `<div class="stage-delta">
      <div class="stage-delta-card ${statusClass}">
        <strong>After Signal</strong>
        <span>${escapeHtml(delta.label)}</span>
        <small>${delta.verification.total ? "Verification reruns compared with source history." : "Run a source verification to calculate after health."}</small>
      </div>
      <div class="stage-delta-card">
        <strong>Completed</strong>
        <span>${formatNullableRate(delta.verification.completedRate)} <small>${formatSignedRate(delta.completedDelta)}</small></span>
        <small>Before ${formatNullableRate(delta.baseline.completedRate)} from ${formatNumber(delta.baseline.total)} stage tasks</small>
      </div>
      <div class="stage-delta-card">
        <strong>Failed</strong>
        <span>${formatNullableRate(delta.verification.failedRate)} <small>${formatSignedRate(delta.failedDelta)}</small></span>
        <small>Before ${formatNullableRate(delta.baseline.failedRate)} from ${formatNumber(delta.baseline.failed)} failures</small>
      </div>
      <div class="stage-delta-card">
        <strong>Active</strong>
        <span>${formatNullableRate(delta.verification.activeRate)} <small>${formatSignedRate(delta.activeDelta)}</small></span>
        <small>${formatNumber(delta.verification.active)} queued/running, ${formatNumber(delta.verification.cancelled)} cancelled</small>
      </div>
    </div>`;
  }

  function renderFocusedStageRunsHtml(report: DashboardWorkflowGraphReport, project: string, clearStageHref: string): string {
    if (!report.focusedStageId) return "";
    const stage = report.stages.find((item) => item.id === report.focusedStageId);
    const health = report.stageHealth.find((item) => item.stageId === report.focusedStageId);
    const verificationRunIds = new Set(report.focusedStageVerificationRuns.map((run) => run.id));
    const baselineStageRuns = report.focusedStageRuns.filter((run) => !verificationRunIds.has(run.runId));
    const verificationStageRuns = report.focusedStageRuns.filter((run) => verificationRunIds.has(run.runId));
    const delta = summarizeFocusedStageDelta(baselineStageRuns, verificationStageRuns);
    const suggestFixForm = focusedStageSuggestFixForm({
      project,
      workflowId: report.workflow.id,
      stageId: report.focusedStageId,
      disabled: !stage
    });
    const rows = report.focusedStageRuns.map((run) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.runId)}">${escapeHtml(run.runId.slice(0, 8))}</a></td>
        <td><span class="status ${escapeHtml(run.runStatus)}">${escapeHtml(run.runStatus)}</span></td>
        <td><span class="status ${escapeHtml(run.taskStatus)}">${escapeHtml(run.taskStatus)}</span></td>
        <td>${formatNumber(run.attempts)}</td>
        <td>${escapeHtml(run.agentId)}</td>
        <td>${escapeHtml(run.task)}</td>
        <td>${renderDashboardDateTime(run.taskStartedAt ?? run.runStartedAt)}</td>
      </tr>
    `).join("") || '<tr><td colspan="7">No task records found for this stage in the selected run history.</td></tr>';
    const healthText = health ? formatStageHealthTitle(health) : "No task-level stage history found for selected runs.";
    const fixRows = report.focusedStageFixRuns.map((run) => {
      const verifyForm = stageFixVerificationForm({
        project,
        workflowId: report.workflow.id,
        stageId: report.focusedStageId,
        fixRunId: run.id,
        disabled: run.status === "queued" || run.status === "leased" || run.status === "running"
      });
      return `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.id)}">${escapeHtml(run.id.slice(0, 8))}</a></td>
        <td><span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span></td>
        <td>${escapeHtml(run.workflowId)}</td>
        <td>${escapeHtml(run.task)}</td>
        <td>${renderDashboardDateTime(run.startedAt)}</td>
        <td>${verifyForm}</td>
      </tr>
    `;
    }).join("") || '<tr><td colspan="6">No suggested fix runs have been queued from this stage yet.</td></tr>';
    const verificationRows = report.focusedStageVerificationRuns.map((run) => {
      const sourceFixRunId = stringValue(run.evaluationMetadata.sourceFixRunId);
      return `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.id)}">${escapeHtml(run.id.slice(0, 8))}</a></td>
        <td><span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span></td>
        <td>${sourceFixRunId ? `<a href="/run?id=${encodeURIComponent(sourceFixRunId)}">${escapeHtml(sourceFixRunId.slice(0, 8))}</a>` : "unknown"}</td>
        <td>${escapeHtml(run.task)}</td>
        <td>${renderDashboardDateTime(run.startedAt)}</td>
      </tr>
    `;
    }).join("") || '<tr><td colspan="5">No source workflow verification reruns have been queued from suggested fixes yet.</td></tr>';
    const deltaHtml = renderFocusedStageDeltaHtml(delta);
    return `<section class="panel focused-stage-panel">
      <div class="section-heading">
        <div>
          <h2>Focused Stage: ${escapeHtml(report.focusedStageId)}</h2>
          <span class="muted">${escapeHtml(stage?.goal ?? "Stage details unavailable.")}</span>
        </div>
        <div class="actions">
          ${suggestFixForm}
          <a class="button secondary" href="${escapeHtml(clearStageHref)}">Clear Stage</a>
        </div>
      </div>
      <p class="muted">${escapeHtml(healthText)}</p>
      ${deltaHtml}
      <div class="table-wrap"><table><thead><tr><th>Run</th><th>Run Status</th><th>Stage Status</th><th>Attempts</th><th>Agent</th><th>Task</th><th>Started</th></tr></thead><tbody>${rows}</tbody></table></div>
      <h3>Suggested Fix Runs</h3>
      <p class="muted">Debug runs queued from this focused stage, shown beside the source-stage health signal for quick before/after triage.</p>
      <div class="table-wrap"><table><thead><tr><th>Run</th><th>Status</th><th>Workflow</th><th>Task</th><th>Started</th><th>Verify</th></tr></thead><tbody>${fixRows}</tbody></table></div>
      <h3>Verification Reruns</h3>
      <p class="muted">Source workflow reruns queued after a suggested fix, tagged for stage-health comparison.</p>
      <div class="table-wrap"><table><thead><tr><th>Run</th><th>Status</th><th>Fix Run</th><th>Task</th><th>Started</th></tr></thead><tbody>${verificationRows}</tbody></table></div>
    </section>`;
  }

  function renderGovernanceHtml(report: GovernanceReport, params: URLSearchParams): string {
    const providers = [...new Set(report.projects.map((project) => project.provider))].sort();
    const profiles = [...new Set(report.projects.map((project) => project.policyProfile))].sort();
    const rows = report.projects.map((project) => `
      <tr>
        <td><strong>${escapeHtml(project.name)}</strong><br><span class="muted">${escapeHtml(project.rootUri)}</span></td>
        <td><span class="flag ${project.health === "healthy" ? "good" : project.health === "warning" ? "warn" : "bad"}">${project.health}</span></td>
        <td>${escapeHtml(project.policyProfile)}<br><span class="muted">policy drift: ${project.policyDrift ?? "unknown"}<br>config drift: ${project.configDrift ?? "unknown"}</span></td>
        <td>${escapeHtml(project.provider)}<br><span class="muted">${escapeHtml(project.modelTier ?? "default tier")}</span></td>
        <td>${project.activeRuns} active / ${project.staleActiveRuns} stale<br><span class="muted">${project.failedRuns} failed · ${project.runCount} total</span></td>
        <td>${project.indexedFiles}<br><span class="muted">config: ${project.projectConfig}</span></td>
        <td>${renderGovernanceProjectActionHtml(project)}</td>
      </tr>`).join("");
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Governance</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("governance")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Multi-project Governance</h1><p class="muted">Read-only project health, policy drift, provider, queue, and remediation inspection.</p></div><a class="button secondary" href="/api/governance?${escapeHtml(params.toString())}">JSON</a></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <section class="panel"><div class="meta-grid"><div><strong>Healthy</strong>${report.counts.healthy}</div><div><strong>Warning</strong>${report.counts.warning}</div><div><strong>Critical</strong>${report.counts.critical}</div><div><strong>Services</strong>${report.servicesReady ? "ready" : "attention"}</div><div><strong>Definitions</strong>${report.definitionsReady ? "ready" : "attention"}</div><div><strong>Configured Provider</strong>${escapeHtml(report.configuredProvider)}</div></div>
    <form method="get" class="form-grid"><label>Health<select name="health"><option value="all">all</option>${["healthy", "warning", "critical"].map((value) => `<option${params.get("health") === value ? " selected" : ""}>${value}</option>`).join("")}</select></label><label>Provider<select name="provider"><option value="">all</option>${providers.map((value) => `<option${params.get("provider") === value ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}</select></label><label>Policy profile<select name="policyProfile"><option value="">all</option>${profiles.map((value) => `<option${params.get("policyProfile") === value ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}</select></label><div class="form-actions"><button type="submit">Filter</button></div></form></section>
    <section class="panel"><div class="table-wrap"><table><thead><tr><th>Project</th><th>Health</th><th>Policy</th><th>Provider</th><th>Runs</th><th>Context</th><th>Recommended action</th></tr></thead><tbody>${rows || '<tr><td colspan="7">No projects match these filters.</td></tr>'}</tbody></table></div></section></main></body></html>`;
  }

  function renderGovernanceProjectActionHtml(project: GovernanceReport["projects"][number]): string {
    const failingChecks = project.healthChecks.filter((check) => check.status === "warning" || check.status === "critical");
    const summary = failingChecks.length
      ? `${failingChecks.length} health check${failingChecks.length === 1 ? "" : "s"} need attention`
      : "All governance checks are clean";
    const checks = (failingChecks.length ? failingChecks : project.healthChecks).map((check) => `
      <li>
        <span class="flag ${check.status === "pass" ? "good" : check.status === "warning" ? "warn" : check.status === "critical" ? "bad" : ""}">${escapeHtml(check.status)}</span>
        <strong>${escapeHtml(check.label)}</strong>
        <span>${escapeHtml(check.evidence)}</span>
        ${check.recommendation ? `<small>${escapeHtml(check.recommendation)}</small>` : ""}
        ${check.command ? `<code>${escapeHtml(check.command)}</code>` : ""}
      </li>
    `).join("");
    return `
      ${project.recommendations.length ? `<ul>${project.recommendations.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : '<span class="flag good">No action</span>'}
      <details class="governance-details">
        <summary>${escapeHtml(summary)}</summary>
        <ul>${checks}</ul>
      </details>
    `;
  }

  function renderGovernedReusePanel(plan: GovernedReusePlan): string {
    const best = plan.candidates[0];
    const candidateRows = plan.candidates.map((candidate) => `<tr>
      <td><a href="/run?id=${encodeURIComponent(candidate.runId)}">${escapeHtml(candidate.runId.slice(0, 8))}</a></td>
      <td><span class="status ${candidate.evidenceCurrent ? "completed" : "blocked"}">${escapeHtml(candidate.recommendation)}</span></td>
      <td>${Math.round(candidate.taskSimilarity * 100)}%</td>
      <td>${candidate.evidenceCurrent ? "current" : escapeHtml(candidate.staleReasons.join(", ") || "stale")}</td>
      <td>${candidate.projectedSavings.stages} stages · ${formatNumber(candidate.projectedSavings.tokens)} tokens · ${formatDuration(candidate.projectedSavings.latencyMs)} · ${candidate.projectedSavings.costUsd === null ? "cost unavailable" : `$${candidate.projectedSavings.costUsd.toFixed(6)}`}</td>
    </tr>`).join("");
    return `<section class="panel governed-reuse-panel">
      <div class="section-heading"><div><p class="eyebrow">Governed reuse</p><h2>${escapeHtml(titleCase(plan.recommendation))}</h2><span class="muted">Exact fingerprints and semantic matches are advisory until an operator accepts them.</span></div><span class="status ${best?.evidenceCurrent ? "completed" : "queued"}">${plan.requiresApproval ? "approval required" : "fresh run"}</span></div>
      <div class="actions">
        <button type="button" ${plan.recommendation === "reuse-result" ? "" : "disabled"}>Reuse result</button>
        <button type="button" ${plan.recommendation === "resume-from-stage" ? "" : "disabled"}>Resume from checkpoint</button>
        <span class="button secondary" aria-current="true">Run fresh</span>
      </div>
      <p class="muted">Reuse controls remain non-executing until the selected candidate is revalidated against current policy, workflow, and source hashes.</p>
      <div class="table-wrap"><table><thead><tr><th>Source run</th><th>Decision</th><th>Similarity</th><th>Evidence</th><th>Projected savings</th></tr></thead><tbody>${candidateRows || '<tr><td colspan="5">No safe prior run matched. This run started fresh.</td></tr>'}</tbody></table></div>
    </section>`;
  }

  function renderGraphExportLifecycleHtml(projectDir: string, exportCount: number): string {
    const exportDir = path.join(projectDir, ".agent-workflow", "exports", "graphs");
    const quotedExportDir = shellQuote(exportDir);
    const quotedProjectDir = shellQuote(projectDir);
    const commands = [
      `du -sh ${quotedExportDir}`,
      `find ${quotedExportDir} -maxdepth 1 -type f \\( -name '*.md' -o -name '*.json' \\) -print | sort | tail -40`,
      `find ${quotedExportDir} -maxdepth 1 -type f \\( -name '*.md' -o -name '*.json' \\) -mtime +30 -print`,
      `tar -czf agentflow-graph-handoffs.tgz -C ${quotedProjectDir} .agent-workflow/exports/graphs`
    ].join("\n");
    return `<details class="lifecycle-help">
      <summary>Export lifecycle commands</summary>
      <p class="muted">${formatNumber(exportCount)} recent handoff export${exportCount === 1 ? "" : "s"} shown. These commands inspect, preview prune candidates, or package graph handoffs without deleting files.</p>
      <pre>${escapeHtml(commands)}</pre>
    </details>`;
  }

  function renderGraphPresetsHtml(presets: DashboardGraphPreset[], current: DashboardGraphPresetFilters): string {
    const hiddenFields = dashboardGraphPresetHiddenFields(current);
    const rows = presets.map((preset) => {
      const href = graphPresetHref(preset);
      return `<tr>
        <td><strong>${escapeHtml(preset.name)}</strong>${preset.description ? `<br><span class="muted">${escapeHtml(preset.description)}</span>` : ""}</td>
        <td>${escapeHtml(preset.filters.workflow)}</td>
        <td>${escapeHtml(preset.filters.view)} / ${escapeHtml(preset.filters.orientation)}</td>
        <td>${escapeHtml(preset.filters.runScope === "all-projects" ? "all projects" : "selected project")}</td>
        <td>${escapeHtml(preset.filters.runStatus)} / ${escapeHtml(preset.filters.runLimit)}</td>
        <td>${renderDashboardDateTime(preset.updatedAt)}</td>
        <td><a class="button secondary" href="${escapeHtml(href)}">Open</a></td>
        <td><form method="post" action="/api/graph-preset-delete" class="inline-form compact-form">${hiddenFields}<input type="hidden" name="presetId" value="${escapeHtml(preset.id)}"><button class="secondary" type="submit">Delete</button></form></td>
      </tr>`;
    }).join("") || '<tr><td colspan="8">No saved graph presets yet.</td></tr>';
    return `<section class="panel capture-hide">
      <div class="section-heading">
        <div>
          <h2>Graph Presets</h2>
          <span class="muted">Save the current workflow, filters, run scope, and graph layout as project-local Agent Workflow state.</span>
        </div>
      </div>
      <form method="post" action="/api/graph-preset-save" class="workflow-form compact-form">
        ${hiddenFields}
        <label>Name<input name="name" value="${escapeHtml(defaultGraphPresetName(current))}" required></label>
        <label class="wide">Description<input name="description" placeholder="Optional note for the team"></label>
        <div class="form-actions"><button type="submit">Save Preset</button></div>
      </form>
      <div class="table-wrap"><table><thead><tr><th>Name</th><th>Workflow</th><th>View</th><th>Run Scope</th><th>Runs</th><th>Updated</th><th>Open</th><th>Remove</th></tr></thead><tbody>${rows}</tbody></table></div>
    </section>`;
  }

  function renderLaunchAgentLogHtml(view: { ok: boolean; kind: "stdout" | "stderr"; filePath: string; content: string; error?: string }): string {
    const body = view.ok
      ? `<h1>LaunchAgent ${escapeHtml(view.kind)} Log</h1><p class="muted">${escapeHtml(view.filePath)}</p><pre>${escapeHtml(view.content)}</pre>`
      : `<h1>LaunchAgent Log Missing</h1><p class="muted">${escapeHtml(view.filePath)}</p><pre>${escapeHtml(view.error ?? "Log file could not be read.")}</pre>`;
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>LaunchAgent Log</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>${dashboardNav("info")}<main><p><a href="/settings">Settings</a></p>${body}</main></body>
  </html>`;
  }

  function renderLaunchAgentStatusHtml(launchAgent: DashboardLaunchAgentStatus, params: URLSearchParams = new URLSearchParams()): string {
    const statusClass = launchAgent.status === "running" ? "completed" : launchAgent.status === "missing" || launchAgent.status === "unavailable" ? "queued" : launchAgent.status === "error" ? "failed" : "queued";
    const installDisabled = !launchAgent.supported ? " disabled" : "";
    const uninstallDisabled = !launchAgent.supported || !launchAgent.installed ? " disabled" : "";
    return `
      <div class="meta-grid">
        <div><strong>Status</strong><span class="status ${statusClass}">${escapeHtml(launchAgent.status)}</span></div>
        <div><strong>Installed</strong>${launchAgent.installed ? "yes" : "no"}</div>
        <div><strong>PID</strong>${launchAgent.pid ?? "none"}</div>
        <div><strong>Runs</strong>${launchAgent.runs ?? "n/a"}</div>
        <div><strong>Label</strong>${escapeHtml(launchAgent.label)}</div>
        <div><strong>Platform</strong>${escapeHtml(launchAgent.platform)}</div>
      </div>
      <div class="meta-grid compact">
        <div><strong>Plist</strong>${escapeHtml(launchAgent.plistPath)}</div>
        <div><strong>Stdout</strong>${escapeHtml(launchAgent.stdoutPath)} ${launchAgent.stdoutExists ? `<a href="/launchagent-log?kind=stdout">open</a>` : ""}</div>
        <div><strong>Stderr</strong>${escapeHtml(launchAgent.stderrPath)} ${launchAgent.stderrExists ? `<a href="/launchagent-log?kind=stderr">open</a>` : ""}</div>
        <div><strong>Install Command</strong><code>${escapeHtml(launchAgent.installCommand)}</code></div>
        <div><strong>Uninstall Command</strong><code>${escapeHtml(launchAgent.uninstallCommand)}</code></div>
        ${launchAgent.lastError ? `<div><strong>Last launchctl note</strong>${escapeHtml(launchAgent.lastError)}</div>` : ""}
      </div>
      <div class="form-actions">
        <form method="post" action="/api/launchagent-action">
          ${dashboardReturnInput("/settings", params)}
          <input type="hidden" name="action" value="install">
          <button type="submit"${installDisabled}>Install / Refresh</button>
        </form>
        <form method="post" action="/api/launchagent-action">
          ${dashboardReturnInput("/settings", params)}
          <input type="hidden" name="action" value="uninstall">
          <button class="secondary" type="submit"${uninstallDisabled}>Uninstall</button>
        </form>
        <a class="button secondary" href="/api/settings">Refresh JSON</a>
      </div>
      <p class="muted">LaunchAgent is optional macOS durability: it starts the local supervisor at login and restarts it after crashes. The supervisor then manages the dashboard, worker lanes, and learning daemon.</p>
    `;
  }

  function renderLearningActionReceiptHealthHtml(health: LearningActionReceiptHealth, limit: number, workflowId: string): string {
    const clean = health.compactableReceiptCount === 0;
    const statusLabel = clean ? "clean" : "compactable";
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Learning Receipt Health</h2>
            <span class="muted">Daemon-owned receipt compaction keeps project learning state useful and small.</span>
          </div>
          <a class="button secondary" href="/api/learning-action-receipts?project=${encodeURIComponent(health.projectRootUri)}&health=1">Health JSON</a>
        </div>
        <div class="metric-grid">
          ${metricCard("Status", statusLabel, health.recommendation)}
          ${metricCard("Receipts", health.totalReceipts, `planned=${health.counts.planned ?? 0} applied=${health.counts.applied ?? 0}`)}
          ${metricCard("Superseded", health.counts.superseded ?? 0, "historical audit trail")}
          ${metricCard("Daemon Open", health.daemonOpenReceipts, `${health.uniqueDaemonOpenReceipts} unique active receipt(s)`)}
          ${metricCard("Duplicates", health.duplicateDaemonOpenReceipts, "planned/applied daemon repeats")}
          ${metricCard("Last Backup", health.latestBackupPath ? "present" : "none", health.latestBackupPath ?? "no compaction backup yet")}
        </div>
        <form method="post" action="/api/learning-action-receipts" class="inline-action-form">
          <input type="hidden" name="project" value="${escapeHtml(health.projectRootUri)}">
          <input type="hidden" name="limit" value="${escapeHtml(String(limit))}">
          <input type="hidden" name="workflow" value="${escapeHtml(workflowId)}">
          <input type="hidden" name="action" value="compact">
          <button type="submit" class="secondary"${clean ? ' disabled title="Receipt health is already clean; there are no duplicate daemon-owned receipts to compact."' : ""}>${clean ? "Receipts already compact" : "Compact daemon-owned receipts"}</button>
          <span class="muted">Creates local backups before rewriting Agent Workflow-owned receipt files.</span>
        </form>
        <div class="meta-grid compact">
          <div><strong>Updated</strong>${renderDashboardDateTime(health.updatedAt)}</div>
          <div><strong>Latest Receipt</strong>${renderDashboardDateTime(health.latestReceiptAt, "none")}</div>
          <div><strong>Latest Backup</strong>${escapeHtml(health.latestBackupPath ?? "none")}</div>
        </div>
      </section>
    `;
  }

  function renderLearningActionReceiptsHtml(log: LearningActionReceiptLog, limit: number): string {
    const counts = countStrings(log.events.map((event) => event.status));
    const rows = log.events.slice(-20).reverse().map((event) => `
      <tr>
        <td>${escapeHtml(event.id)}<br><span class="muted">${renderDashboardDateTime(event.createdAt)}</span></td>
        <td><span class="flag ${event.status === "planned" ? "good" : event.status === "rejected" ? "warn" : "queued"}">${escapeHtml(event.status)}</span></td>
        <td>${escapeHtml(event.title)}<br><span class="muted">${escapeHtml(event.actionId)} · ${escapeHtml(event.proposalId)}</span></td>
        <td>${escapeHtml(event.actionType)}<br><span class="muted">${escapeHtml(event.dangerGate)}</span></td>
        <td>${escapeHtml(event.actor)}<br><span class="muted">${escapeHtml(event.note)}</span></td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div><h2>Proposal-To-Action Receipts</h2><span class="muted">planned=${counts.planned ?? 0} superseded=${counts.superseded ?? 0} rejected=${counts.rejected ?? 0}</span></div>
          <a class="button secondary" href="/api/learning-action-receipts?project=${encodeURIComponent(log.projectRootUri)}">JSON</a>
        </div>
        <p class="muted">Receipts are append-only learning-owned state. They record when approved proposals become plans, when plans are superseded, and when you reject a planned action.</p>
        <form method="post" action="/api/learning-action-receipts" class="inline-action-form">
          <input type="hidden" name="project" value="${escapeHtml(log.projectRootUri)}">
          <input type="hidden" name="limit" value="${escapeHtml(String(limit))}">
          <label>Item to reject<input name="reject" placeholder="action, proposal, or receipt id"></label>
          <label>Decision made by<input name="actor" value="dashboard"></label>
          <label>Reason for rejection<input name="note" placeholder="why reject this planned action"></label>
          <button type="submit" class="secondary">Reject Planned Action</button>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Status</th><th>Action</th><th>Type/Gate</th><th>Actor/Note</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No learning action receipts yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLearningDaemonStatusHtml(status: DashboardLearningDaemonStatus, supervisor: DashboardSupervisorStatus): string {
    const age = status.ageMs === null ? "n/a" : formatDuration(Math.max(0, status.ageMs));
    const remoteProjectSelected = status.status === "missing" && !status.projectPathExists && supervisor.learningEnabled && supervisor.learningScope === "all-projects";
    const statusLabel = remoteProjectSelected ? "remote path" : status.status;
    const statusClass = remoteProjectSelected ? "queued" : status.status === "running" ? "completed" : status.status === "missing" ? "queued" : "failed";
    const statusDetail = remoteProjectSelected
      ? `The durable learning daemon is running in all-projects mode, but this selected project path is not mounted on this Mac: ${status.projectRootUri}. Agent Workflow can read its shared run history from storage, but cannot write that project's local heartbeat files until the project is available at a local path.`
      : status.status === "missing" && supervisor.learningScope !== "all-projects" && supervisor.learningProject && supervisor.learningProject !== status.projectRootUri
        ? `No heartbeat for this project because the durable supervisor is currently watching ${supervisor.learningProject}.`
        : "";
    return `
      <div class="meta-grid">
        <div><strong>Status</strong><span class="status ${statusClass}">${escapeHtml(statusLabel)}</span></div>
        <div><strong>Mode</strong>${escapeHtml(status.mode ?? "n/a")}</div>
        <div><strong>Daemon</strong>${escapeHtml(status.daemonId ?? "n/a")}</div>
        <div><strong>PID</strong>${status.pid ?? "none"}</div>
        <div><strong>Process</strong>${status.processAlive ? "alive" : "not running"}</div>
        <div><strong>Project Path</strong>${status.projectPathExists ? "available locally" : "not mounted here"}</div>
        <div><strong>Last Heartbeat</strong>${renderDashboardDateTime(status.lastHeartbeatAt, "none")}</div>
        <div><strong>Age</strong>${escapeHtml(age)}</div>
        <div><strong>Last Report</strong>${renderDashboardDateTime(status.lastReportAt, "none")}</div>
        <div><strong>Ticks</strong>${formatNumber(status.ticks)}</div>
        <div><strong>Proposals</strong>${formatNumber(status.proposals)}</div>
        <div><strong>Roadmap Snapshot</strong>${escapeHtml(status.roadmapSnapshotStatus ?? "not published")}</div>
        <div><strong>Snapshot Published</strong>${renderDashboardDateTime(status.roadmapSnapshotPublishedAt, "none")}</div>
        <div><strong>Snapshot Digest</strong><code>${escapeHtml(status.roadmapSnapshotDigest?.slice(0, 12) ?? "none")}</code></div>
        <div><strong>Inbox Items</strong>${formatNumber(status.inboxItems)}</div>
        <div><strong>Application Actions</strong>${formatNumber(status.applicationActions)}</div>
        <div><strong>Auto-applied</strong>${formatNumber(status.autonomousAppliedActions)}</div>
        <div><strong>Auto-apply Risk</strong>${escapeHtml(status.autonomousApplyMaxRisk)}</div>
        <div><strong>Agent Candidates</strong>${formatNumber(status.agentImprovementCandidates)}</div>
        <div><strong>Agent Patch Previews</strong>${formatNumber(status.agentImprovementPatchPreviews)}</div>
        <div><strong>Agent Eval Passes</strong>${formatNumber(status.agentImprovementEvalPasses)}</div>
        <div><strong>Agent Promotions</strong>${formatNumber(status.agentImprovementPromotions)}</div>
        <div><strong>Promotion Pending</strong>${formatNumber(status.agentImprovementPromotionPending)}</div>
        <div><strong>Agent YAML Applied</strong>${formatNumber(status.agentImprovementApplied)}</div>
        <div><strong>YAML Apply Skipped</strong>${formatNumber(status.agentImprovementApplySkipped)}</div>
        <div><strong>Approval Autopilot</strong>${status.approvalAutopilotEnabled ? "on" : "off"}</div>
        <div><strong>Approval Risk</strong>${escapeHtml(status.approvalAutopilotMaxRisk)}</div>
        <div><strong>Approvals Executed</strong>${formatNumber(status.approvalAutopilotExecuted)}</div>
        <div><strong>Approvals Skipped</strong>${formatNumber(status.approvalAutopilotSkipped)}</div>
        <div><strong>Backlog Scanned</strong>${formatNumber(status.approvalBacklogScanned)}</div>
        <div><strong>Backlog Warnings</strong>${formatNumber(status.approvalBacklogWarnings)}</div>
        <div><strong>Backlog Errors</strong>${formatNumber(status.approvalBacklogErrors)}</div>
        <div><strong>Shape Auto Update</strong>${status.workflowShapeAutoUpdate === false ? "off" : "on"}</div>
        <div><strong>Shape Recommendations</strong>${formatNumber(status.workflowShapeRecommendations ?? 0)}</div>
        <div><strong>MCP Cleanup</strong>${status.mcpCleanupEnabled ? escapeHtml(status.mcpCleanupMode) : "off"}</div>
        <div><strong>MCP Stale Age</strong>${formatNumber(status.mcpCleanupStaleMinutes)} min</div>
        <div><strong>MCP Candidates</strong>${formatNumber(status.mcpCleanupCandidates)}</div>
        <div><strong>MCP Auto-cleanable</strong>${formatNumber(status.mcpCleanupAutoCleanable)}</div>
        <div><strong>MCP Terminated</strong>${formatNumber(status.mcpCleanupTerminated)}</div>
        <div><strong>MCP Warnings</strong>${formatNumber(status.mcpCleanupWarnings)}</div>
        <div><strong>Last MCP Cleanup</strong>${renderDashboardDateTime(status.lastMcpCleanupAt, "none")}</div>
        <div><strong>Stale Run Reconcile</strong>${status.staleRunReconcileEnabled ? "on" : "off"}</div>
        <div><strong>Stale Run Candidates</strong>${formatNumber(status.staleRunReconcileCandidates)}</div>
        <div><strong>Stale Runs Repaired</strong>${formatNumber(status.staleRunReconciled)}</div>
        <div><strong>Last Stale Run Check</strong>${renderDashboardDateTime(status.lastStaleRunReconcileAt, "none")}</div>
        <div><strong>Heartbeat File</strong>${escapeHtml(status.heartbeatPath)}</div>
        <div><strong>Start Command</strong><code>${escapeHtml(status.command)}</code></div>
        ${status.lastError ? `<div><strong>Last Error</strong>${escapeHtml(status.lastError)}</div>` : ""}
      </div>
      ${statusDetail ? `<p class="warn-box">${escapeHtml(statusDetail)}</p>` : ""}
    `;
  }

  function renderLearningDashboardHtml(report: LearningReport | null, learningQueue: LearningApprovalQueue | null, learningDaemon: DashboardLearningDaemonStatus | null, learningApplicationPlan: LearningApplicationPlan | null, learningActionReceipts: LearningActionReceiptLog | null, learningActionReceiptHealth: LearningActionReceiptHealth | null, workflowShape: WorkflowShapeOptimizationReport | null, agentImprovement: AgentImprovementReport | null, agentImprovementEval: AgentImprovementEvalPlan | null, agentImprovementPromotion: AgentImprovementPromotionQueue | null, learningSettings: LearningSettings | null, supervisor: DashboardSupervisorStatus, projects: DashboardProjectSummary[], params: URLSearchParams, projectPath: DashboardProjectPathResolution | null = null, learningLoop: LearningLoopDashboard | null = null, agentImprovementPending: AgentImprovementPendingSummary | null = null): string {
    const learningViews = ["overview", "learning-loop", "recommendations", "approvals", "agent-improvements", "diagnostics", "settings"] as const;
    const requestedView = params.get("view");
    const learningView = learningViews.includes(requestedView as typeof learningViews[number]) ? requestedView as typeof learningViews[number] : "overview";
    const selectedProject = projectPath?.storageRootUri ?? report?.projectDir ?? params.get("project") ?? process.env.AGENTFLOW_DASHBOARD_PROJECT ?? "";
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}">${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`).join("");
    const jsonHref = learningLoop ? `/api/learning-loop?project=${encodeURIComponent(projectPath?.localRootUri ?? selectedProject)}` : report ? `/api/learning-report?project=${encodeURIComponent(report.projectDir)}&limit=${encodeURIComponent(String(report.limit))}` : "";
    const shapeJsonHref = workflowShape ? `/api/learning-workflow-shape?project=${encodeURIComponent(workflowShape.projectRootUri)}&workflow=${encodeURIComponent(workflowShape.workflowId)}&limit=${encodeURIComponent(String(report?.limit ?? params.get("limit") ?? "50"))}` : "";
    const agentImprovementJsonHref = agentImprovement ? `/api/agent-improvement-report?project=${encodeURIComponent(agentImprovement.projectRootUri)}&limit=${encodeURIComponent(String(agentImprovement.limit))}` : "";
    const shapeAutoUpdate = learningSettings?.workflowShapeAutoUpdate ?? true;
    const agentImprovementProjectLocalAutoApply = learningSettings?.agentImprovementProjectLocalAutoApply ?? true;
    const autonomousApplyMaxRisk = learningSettings?.autonomousApplyMaxRisk ?? "medium";
    const approvalAutopilotEnabled = learningSettings?.approvalAutopilotEnabled ?? false;
    const approvalAutopilotMaxRisk = learningSettings?.approvalAutopilotMaxRisk ?? "medium";
    const daemonTrustLevels = learningSettings?.daemonTrustLevels ?? defaultDaemonTrustSettings();
    const overviewBody = selectedProject ? `<section class="human-section learning-overview-intro">
      <h2>Choose what to review</h2>
      <p class="page-intro">Open only the evidence you need. Detailed analysis loads when you select a view.</p>
      <div class="human-list">
        <a class="human-list-row" href="/learning?project=${encodeURIComponent(selectedProject)}&view=recommendations"><span class="human-row-icon">${dashboardIcon("sparkles")}</span><span><strong>Recommendations</strong><small>Workflow improvements, evaluation gaps, and routing opportunities.</small></span>${dashboardIcon("chevrons")}</a>
        <a class="human-list-row" href="/learning?project=${encodeURIComponent(selectedProject)}&view=approvals"><span class="human-row-icon">${dashboardIcon("shield")}</span><span><strong>Approvals</strong><small>Review learning proposals and planned changes.</small></span>${dashboardIcon("chevrons")}</a>
        <a class="human-list-row" href="/learning?project=${encodeURIComponent(selectedProject)}&view=agent-improvements"><span class="human-row-icon">${dashboardIcon("agent")}</span><span><strong>Agent improvements</strong><small>Inspect evaluated changes to agent definitions.</small></span>${dashboardIcon("chevrons")}</a>
        <a class="human-list-row" href="/learning?project=${encodeURIComponent(selectedProject)}&view=learning-loop"><span class="human-row-icon">${dashboardIcon("sparkles")}</span><span><strong>Learning loop</strong><small>Peer questions, calibrated assessments, disagreement, and guarded experiments.</small></span>${dashboardIcon("chevrons")}</a>
        <a class="human-list-row" href="/learning?project=${encodeURIComponent(selectedProject)}&view=diagnostics"><span class="human-row-icon">${dashboardIcon("gauge")}</span><span><strong>Diagnostics</strong><small>Failures, receipts, routing signals, and daemon health.</small></span>${dashboardIcon("chevrons")}</a>
      </div>
    </section>` : "";
    const body = learningLoop
      ? renderLearningLoopHtml(learningLoop)
      : report
      ? renderLearningReportHtml(report, learningQueue, learningDaemon, learningApplicationPlan, learningActionReceipts, learningActionReceiptHealth, workflowShape, agentImprovement, agentImprovementEval, agentImprovementPromotion, shapeAutoUpdate, agentImprovementProjectLocalAutoApply, autonomousApplyMaxRisk, approvalAutopilotEnabled, approvalAutopilotMaxRisk, daemonTrustLevels, supervisor, projectPath)
      : learningView === "overview" && selectedProject
        ? overviewBody
        : `<section class="panel"><h2>No Project Selected</h2><p class="muted">Register or select a project to inspect read-only local learning evidence.</p></section>`;
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Learning</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav(learningView === "settings" ? "daemon-control" : learningView === "diagnostics" ? "learning-diagnostics" : "learning")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Home</a>
          <h1>Learning</h1>
          <p class="page-intro">Review recommendations, decisions, and system learning without the implementation noise.</p>
        </div>
        ${jsonHref ? `<a class="button secondary" href="${escapeHtml(jsonHref)}">JSON</a>` : ""}
      </div>
      <nav class="learning-tabs" aria-label="Insight views">
        ${learningViews.map((view) => {
          const hrefParams = new URLSearchParams(params);
          hrefParams.set("view", view);
          const label = view === "agent-improvements" ? "Agent improvements" : view === "learning-loop" ? "Learning loop" : titleCase(view);
          return `<a href="/learning?${escapeHtml(hrefParams.toString())}" class="${learningView === view ? "active" : ""}" ${learningView === view ? 'aria-current="page"' : ""}>${escapeHtml(label)}</a>`;
        }).join("")}
      </nav>
      ${renderDashboardFlash(params)}
      ${renderAgentImprovementPendingBannerHtml(agentImprovementPending)}
      ${renderDashboardActionHistory()}
      ${projectPath ? renderDashboardProjectPathResolutionHtml(projectPath) : ""}
      <section class="panel">
        <form method="get" class="workflow-form">
          <input type="hidden" name="view" value="${escapeHtml(learningView)}">
          <label class="wide">Project path
            <input name="project" value="${escapeHtml(selectedProject)}" list="learning-projects" placeholder="/path/to/project">
            <datalist id="learning-projects">${projectOptions}</datalist>
          </label>
          <label>Run limit
            <input name="limit" value="${escapeHtml(params.get("limit") ?? "50")}" inputmode="numeric">
          </label>
          <label>Workflow
            <input name="workflow" value="${escapeHtml(params.get("workflow") ?? workflowShape?.workflowId ?? "")}" placeholder="latest run workflow">
          </label>
          <div class="form-actions"><button type="submit">Inspect</button></div>
        </form>
      </section>
      ${(shapeJsonHref || agentImprovementJsonHref) ? `<section class="panel compact-panel">${shapeJsonHref ? `<a class="button secondary" href="${escapeHtml(shapeJsonHref)}">Workflow Shape JSON</a>` : ""}${agentImprovementJsonHref ? `<a class="button secondary" href="${escapeHtml(agentImprovementJsonHref)}">Agent Improvement JSON</a>` : ""}</section>` : ""}
      ${selectedProject ? `<section class="panel"><div class="section-heading"><div><h2>Workflow Optimizer</h2><span class="muted">Durable events, budgets, shadow evidence, approvals, and fleet health.</span></div><a class="button secondary" href="/api/optimizer-status?project=${encodeURIComponent(selectedProject)}">JSON</a></div><div id="optimizer-summary" class="meta-grid"><div><strong>Status</strong>Loading…</div></div></section><script>fetch(${serializeInlineScriptJson(`/api/optimizer-status?project=${encodeURIComponent(selectedProject)}`)}).then(r=>r.json()).then(r=>{document.getElementById('optimizer-summary').innerHTML='<div><strong>Status</strong>'+String(r.health?.status??'unknown')+'</div><div><strong>Events</strong>'+String(r.eventCursorCount??0)+'</div><div><strong>Queue</strong>'+String(r.health?.queueDepth??0)+'</div><div><strong>Budget</strong>'+String(r.health?.budgetConsumed??0)+' / '+String(r.health?.budgetLimit??0)+'</div><div><strong>Shadow Results</strong>'+String(r.shadowResults?.length??0)+'</div><div><strong>Approvals</strong>'+String(r.approvals?.length??0)+'</div>'}).catch(()=>{document.getElementById('optimizer-summary').textContent='Optimizer status unavailable.'})</script>` : ""}
      ${body}
      <script>
        (() => {
          const view = ${serializeInlineScriptJson(learningView)};
          const groups = {
            overview: ["Recent Dashboard Actions", "Workflow Optimizer", "Choose what to review"],
            "learning-loop": ["Learning Loop", "Open Peer Questions", "Peer Assessment Results", "Learning Experiments", "Scheduler Receipts"],
            recommendations: ["Workflow Shape Optimizer", "Evaluation Gaps", "Repeated Failure Patterns", "Cost And Routing Opportunities", "Proposal Preview"],
            approvals: ["Learning Proposal Inbox", "Approved Application Plan"],
            "agent-improvements": ["Agent Definition Improvement"],
            diagnostics: ["Project Path Mapping", "Route Feedback Signals", "Learning Daemon", "Daemon Failure Triage", "Recent Failed Runs", "Learning Receipt Health", "Proposal-To-Action Receipts", "Privacy Boundaries", "Next Commands"],
            settings: ["Durable Learning Target", "Daemon Control Plane", "Autonomy Boundary"]
          };
          const utilityHeadings = ["Recent Dashboard Actions", "Project Path Mapping"];
          const alwaysOverview = (section) => !section.querySelector("h2") && !section.querySelector("form") && !section.classList.contains("compact-panel");
          document.querySelectorAll("main > section").forEach((section) => {
            if (section.querySelector("form[method='get']")) {
              section.classList.toggle("learning-hidden", view !== "overview");
              return;
            }
            const heading = section.querySelector("h2")?.textContent?.trim() ?? "";
            const allowed = view === "overview"
              ? alwaysOverview(section) || groups.overview.includes(heading)
              : groups[view]?.includes(heading) && !utilityHeadings.includes(heading);
            section.classList.toggle("learning-hidden", !allowed);
          });
        })();
      </script>
    </main>
  </body>
  </html>`;
  }

  function renderLearningFailureTriageHtml(report: LearningFailureTriageReport): string {
    const rows = report.groups.map((group) => `<tr>
      <td><code>${escapeHtml(group.signature)}</code><br><span class="muted">${group.runIds.map((runId) => `<a href="/run?id=${encodeURIComponent(runId)}">${escapeHtml(runId.slice(0, 8))}</a>`).join(" ")}</span></td>
      <td><span class="flag ${group.risk === "high" ? "warn" : group.risk === "low" ? "good" : "queued"}">${escapeHtml(group.risk)}</span><br>${escapeHtml(group.category)}</td>
      <td>${escapeHtml(group.diagnosis)}<br><span class="muted">${escapeHtml(group.detail)}</span></td>
      <td><span class="status ${group.action === "retried" ? "completed" : group.action === "escalated" || group.action === "retry_failed" ? "failed" : "queued"}">${escapeHtml(group.action.replace(/_/g, " "))}</span></td>
    </tr>`).join("");
    return `<section class="panel">
      <div class="section-heading"><div><h2>Daemon Failure Triage</h2><span class="muted">Proactive diagnosis, verified remediation, and bounded retry decisions.</span></div></div>
      <div class="callout ${report.failedRuns ? "queued" : "completed"}"><strong>Daemon observation</strong><p>${escapeHtml(report.observation)}</p></div>
      <div class="meta-grid compact"><div><strong>Failures seen</strong>${report.failedRuns}</div><div><strong>Root causes</strong>${report.groups.length}</div><div><strong>Safely retried</strong>${report.retriedRuns.length}</div><div><strong>Withheld</strong>${report.withheldRuns.length}</div></div>
      <div class="table-wrap"><table><thead><tr><th>Failure group</th><th>Class / risk</th><th>Reasoning</th><th>Action</th></tr></thead><tbody>${rows || '<tr><td colspan="4">No failures needed triage.</td></tr>'}</tbody></table></div>
    </section>`;
  }

  function renderLearningReportHtml(report: LearningReport, learningQueue: LearningApprovalQueue | null, learningDaemon: DashboardLearningDaemonStatus | null, learningApplicationPlan: LearningApplicationPlan | null, learningActionReceipts: LearningActionReceiptLog | null, learningActionReceiptHealth: LearningActionReceiptHealth | null, workflowShape: WorkflowShapeOptimizationReport | null, agentImprovement: AgentImprovementReport | null, agentImprovementEval: AgentImprovementEvalPlan | null, agentImprovementPromotion: AgentImprovementPromotionQueue | null, shapeAutoUpdate: boolean, agentImprovementProjectLocalAutoApply: boolean, autonomousApplyMaxRisk: LearningRiskLevel, approvalAutopilotEnabled: boolean, approvalAutopilotMaxRisk: ApprovalAutopilotRisk, daemonTrustLevels: DaemonTrustSettings, supervisor: DashboardSupervisorStatus, projectPath: DashboardProjectPathResolution | null = null): string {
    const failureRows = report.repeatedFailurePatterns.map((pattern) => `
      <tr><td>${escapeHtml(pattern.workflowId)}</td><td>${escapeHtml(pattern.stageId)}</td><td>${escapeHtml(pattern.agentId)}</td><td>${pattern.failedTasks}/${pattern.totalTasks}</td><td>${pattern.failureRate}</td></tr>
    `).join("");
    const costRows = report.costOpportunities.map((item) => `
      <tr><td>${escapeHtml(item.workflowId)}<br><span class="muted">${escapeHtml(item.stageId)}</span></td><td>${escapeHtml(item.agentId)}</td><td>${escapeHtml(item.providerId)} / ${escapeHtml(item.modelTier)}</td><td>${item.runs}</td><td>${item.fallbackRate}</td><td>${item.averageLatencyMs ?? "n/a"}</td><td>${escapeHtml(item.recommendation)}</td></tr>
    `).join("");
    const failedRunRows = report.failedRuns.map((run) => `
      <tr><td><a href="/run?id=${encodeURIComponent(run.runId)}">${escapeHtml(run.runId.slice(0, 8))}</a></td><td>${escapeHtml(run.workflowId)}</td><td>${escapeHtml(run.task)}</td><td>${renderDashboardDateTime(run.startedAt)}</td><td><div class="actions">${queueRunActionForm(run.runId, "resolve-blocker", "Resolve Blocker")}<a class="button secondary" href="/run?id=${encodeURIComponent(run.runId)}">Inspect</a></div></td></tr>
    `).join("");
    const proposalRows = Object.entries(report.proposalPreview.byKind).map(([kind, count]) => `<tr><td>${escapeHtml(kind)}</td><td>${formatNumber(count)}</td></tr>`).join("");
    const learningRows = (learningQueue?.items ?? []).map((item) => `
      <tr><td>${escapeHtml(item.proposalId)}<br><span class="muted">${escapeHtml(item.id)}</span></td><td>${escapeHtml(item.status)}</td><td>${escapeHtml(item.proposal.priority)} / ${escapeHtml(item.proposal.riskLevel)}</td><td>${escapeHtml(item.proposal.title)}<br><span class="muted">${escapeHtml(item.proposal.target)}</span></td><td>${escapeHtml(item.proposal.recommendation)}</td></tr>
    `).join("");
    const learningCounts = learningQueue ? countStrings(learningQueue.items.map((item) => item.status)) : {};
    const applicationRows = (learningApplicationPlan?.actions ?? []).map((action) => `
      <tr><td>${escapeHtml(action.id)}<br><span class="muted">${escapeHtml(action.proposalId)}</span></td><td>${escapeHtml(action.actionType)}</td><td>${escapeHtml(action.dangerGate)}</td><td>${action.writesOwnedLearningStateOnly ? "yes" : "no"}</td><td>${action.command ? `<code>${escapeHtml(action.command)}</code>` : "manual review"}</td></tr>
    `).join("");
    const localProjectDir = projectPath?.localRootUri ?? report.projectDir;
    const proposalCommand = `npm run agentflow -- learning-proposals --project ${shellQuote(localProjectDir)} --write`;
    const applicationPlanCommand = `npm run agentflow -- learning-application-plan --project ${shellQuote(localProjectDir)} --write`;
    const daemonCommand = `npm run agentflow -- learning-daemon --project ${shellQuote(localProjectDir)} --mode apply-approved`;
    const shapeCommand = `npm run agentflow -- learning-workflow-shape --project ${shellQuote(localProjectDir)}${workflowShape ? ` --workflow ${shellQuote(workflowShape.workflowId)}` : ""} --write`;
    const list = (items: string[]) => `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`;
    return `
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Mode", report.autonomyMode, "owned learning writes")}
          ${metricCard("Runs", report.runsAnalyzed, formatInlineCounts(report.runStatusCounts) || "none")}
          ${metricCard("Feedback", formatInlineCounts(report.feedbackCounts) || "none", "approved user signal")}
          ${metricCard("Route Feedback", formatInlineCounts(report.routeFeedback.counts) || "none", report.routeFeedback.latestAt ? `latest ${formatDashboardDateTimeText(report.routeFeedback.latestAt)}` : "no route signals")}
          ${metricCard("Eval Runs", report.evaluationRuns, report.latestEvaluationAt ? `latest ${new Date(report.latestEvaluationAt).toLocaleDateString()}` : "none found")}
          ${metricCard("Failures", report.failedRuns.length, "recent failed runs")}
          ${metricCard("Proposal Preview", report.proposalPreview.total, `${report.proposalPreview.highPriority} high priority`)}
        </div>
        <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)} for ${escapeHtml(report.projectDir)}.</p>
      </section>
      ${renderLearningSupervisorTargetHtml(localProjectDir, supervisor)}
      ${renderLearningRouteFeedbackHtml(report.routeFeedback)}
      <section class="panel">
        <div class="section-heading"><div><h2>Learning Daemon</h2><span class="muted">Local autonomous loop over Agent Workflow-owned learning state.</span></div></div>
        ${learningDaemon ? renderLearningDaemonStatusHtml(learningDaemon, supervisor) : `<p class="muted">No project selected.</p>`}
        <p class="muted">Start autonomous mode with <code>${escapeHtml(daemonCommand)}</code>. It auto-applies low/medium-risk Agent Workflow-owned local optimization files by default, including project-local tuning overlays. High-risk source, provider, command, network, reusable bundle, and export changes still require approval.</p>
      </section>
      ${report.failureTriage ? renderLearningFailureTriageHtml(report.failureTriage) : ""}
      ${renderDaemonControl({ project: report.projectDir, limit: report.limit, workflow: workflowShape?.workflowId ?? "", trust: daemonTrustLevels, shapeAutoUpdate, agentAutoApply: agentImprovementProjectLocalAutoApply, autonomousMaxRisk: autonomousApplyMaxRisk, autopilotEnabled: approvalAutopilotEnabled, autopilotMaxRisk: approvalAutopilotMaxRisk })}
      ${workflowShape ? renderWorkflowShapeOptimizationHtml(workflowShape, shapeCommand, shapeAutoUpdate, agentImprovementProjectLocalAutoApply, autonomousApplyMaxRisk, approvalAutopilotEnabled, approvalAutopilotMaxRisk, daemonTrustLevels) : ""}
      ${agentImprovement ? renderAgentImprovementHtml(agentImprovement, agentImprovementEval, agentImprovementPromotion) : ""}
      <section class="panel">
        <div class="section-heading"><div><h2>Autonomy Boundary</h2><span class="muted">The learning daemon should keep working automatically until an action becomes dangerous.</span></div></div>
        <div class="split-grid">
          <div><h3>Automatic</h3>${list(report.safeAutomaticActions)}</div>
          <div><h3>Requires Approval</h3>${list(report.approvalRequiredActions)}</div>
        </div>
      </section>
      <section class="panel"><h2>Evaluation Gaps</h2>${list(report.evalGaps)}</section>
      <section class="panel"><h2>Repeated Failure Patterns</h2><div class="table-wrap"><table><thead><tr><th>Workflow</th><th>Stage</th><th>Agent</th><th>Failures</th><th>Rate</th></tr></thead><tbody>${failureRows || "<tr><td colspan=\"5\">No repeated failure patterns found.</td></tr>"}</tbody></table></div></section>
      <section class="panel"><h2>Cost And Routing Opportunities</h2><div class="table-wrap"><table><thead><tr><th>Workflow</th><th>Agent</th><th>Provider/Tier</th><th>Runs</th><th>Fallback</th><th>Latency</th><th>Recommendation</th></tr></thead><tbody>${costRows || "<tr><td colspan=\"7\">No cost or routing opportunities found.</td></tr>"}</tbody></table></div></section>
      <section class="panel"><div class="section-heading"><div><h2>Recent Failed Runs</h2><span class="muted">Refresh context and resume the same durable run without creating a repair chain.</span></div><a class="button secondary" href="/queue">Open Queue</a></div><div class="table-wrap"><table><thead><tr><th>Run</th><th>Workflow</th><th>Task</th><th>Started</th><th>Actions</th></tr></thead><tbody>${failedRunRows || "<tr><td colspan=\"5\">No failed runs in the inspected window.</td></tr>"}</tbody></table></div></section>
      <section class="panel"><h2>Proposal Preview</h2><div class="table-wrap"><table><thead><tr><th>Kind</th><th>Count</th></tr></thead><tbody>${proposalRows || "<tr><td colspan=\"2\">No proposal candidates yet.</td></tr>"}</tbody></table></div></section>
      <section class="panel">
        <div class="section-heading"><div><h2>Learning Proposal Inbox</h2><span class="muted">${learningQueue ? `pending=${learningCounts.pending ?? 0} approved=${learningCounts.approved ?? 0} rejected=${learningCounts.rejected ?? 0}` : "No local inbox written yet."}</span></div></div>
        <p class="muted">Generate the inbox with <code>${escapeHtml(proposalCommand)}</code>. Low/medium-risk items auto-approve in autonomous mode; high-risk items wait here for review.</p>
        <div class="table-wrap"><table><thead><tr><th>Proposal</th><th>Status</th><th>Priority/Risk</th><th>Target</th><th>Recommendation</th></tr></thead><tbody>${learningRows || "<tr><td colspan=\"5\">No learning proposal inbox found.</td></tr>"}</tbody></table></div>
      </section>
      <section class="panel">
        <div class="section-heading"><div><h2>Approved Application Plan</h2><span class="muted">${learningApplicationPlan ? `${learningApplicationPlan.actions.length} planned action(s)` : "No approved application plan yet."}</span></div></div>
        <p class="muted">Generate a saved plan with <code>${escapeHtml(applicationPlanCommand)}</code>. The daemon applies safe local overlay actions automatically and leaves high-risk actions gated.</p>
        <div class="table-wrap"><table><thead><tr><th>Action</th><th>Type</th><th>Gate</th><th>Owned State Only</th><th>Command</th></tr></thead><tbody>${applicationRows || "<tr><td colspan=\"5\">No approved learning proposals selected for application planning.</td></tr>"}</tbody></table></div>
      </section>
      ${learningActionReceiptHealth ? renderLearningActionReceiptHealthHtml(learningActionReceiptHealth, report.limit, workflowShape?.workflowId ?? "") : ""}
      ${learningActionReceipts ? renderLearningActionReceiptsHtml(learningActionReceipts, report.limit) : ""}
      <section class="panel"><h2>Privacy Boundaries</h2>${list(report.privacyBoundaries)}</section>
      <section class="panel"><h2>Next Commands</h2>${list(report.nextCommands)}</section>
    `;
  }

  function renderLearningRouteFeedbackHtml(summary: LearningRouteFeedbackSummary): string {
    const row = (group: LearningRouteFeedbackGroup) => `
      <tr>
        <td>${escapeHtml(group.target)}<br><span class="muted">${escapeHtml(group.route)}</span></td>
        <td>${escapeHtml(group.routeClass)}</td>
        <td>${formatNumber(group.total)}</td>
        <td>${group.helpful}/${group.costly}/${group.neutral}</td>
        <td>${renderDashboardDateTime(group.latestAt)}</td>
      </tr>
    `;
    const costlyRows = summary.costlyGroups.map(row).join("");
    const helpfulRows = summary.helpfulGroups.map(row).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Route Feedback Signals</h2>
            <span class="muted">Helpful/costly route decisions from the model-improvement drilldown.</span>
          </div>
          <span class="status ${summary.costlyGroups.length ? "queued" : summary.total ? "completed" : "queued"}">${formatNumber(summary.total)} signal(s)</span>
        </div>
        <div class="split-grid">
          <div>
            <h3>Costly Routes</h3>
            <div class="table-wrap"><table><thead><tr><th>Target</th><th>Class</th><th>Total</th><th>H/C/N</th><th>Latest</th></tr></thead><tbody>${costlyRows || "<tr><td colspan=\"5\">No costly route feedback yet.</td></tr>"}</tbody></table></div>
          </div>
          <div>
            <h3>Helpful Routes</h3>
            <div class="table-wrap"><table><thead><tr><th>Target</th><th>Class</th><th>Total</th><th>H/C/N</th><th>Latest</th></tr></thead><tbody>${helpfulRows || "<tr><td colspan=\"5\">No helpful route feedback yet.</td></tr>"}</tbody></table></div>
          </div>
        </div>
      </section>
    `;
  }

  function renderLearningSupervisorTargetHtml(projectDir: string, supervisor: DashboardSupervisorStatus): string {
    const allProjects = supervisor.learningScope === "all-projects";
    const targetMatches = allProjects || supervisor.learningProject === projectDir;
    const statusText = supervisor.learningEnabled
      ? allProjects ? "watching all registered projects" : targetMatches ? "watching this project" : supervisor.learningProject ? "watching another project" : "enabled without target"
      : "disabled";
    return `
      <section class="panel compact-panel">
        <div class="section-heading">
          <div>
            <h2>Durable Learning Target</h2>
            <span class="muted">LaunchAgent supervision can keep one local learning daemon durable by default.</span>
          </div>
          <form method="post" action="/api/learning-daemon-target" class="inline-form compact-form">
            <input type="hidden" name="project" value="${escapeHtml(projectDir)}">
            <input type="hidden" name="mode" value="apply-approved">
            <input type="hidden" name="scope" value="all-projects">
            <button type="submit" class="secondary">${allProjects ? "Refresh All Projects" : "Watch All Projects"}</button>
          </form>
          <form method="post" action="/api/learning-daemon-target" class="inline-form compact-form">
            <input type="hidden" name="project" value="${escapeHtml(projectDir)}">
            <input type="hidden" name="mode" value="apply-approved">
            <input type="hidden" name="scope" value="project">
            <button type="submit" class="secondary">${targetMatches ? "Refresh Durable Target" : "Watch This Project"}</button>
          </form>
        </div>
        <div class="meta-grid compact">
          <div><strong>Status</strong>${escapeHtml(statusText)}</div>
          <div><strong>Supervisor</strong>${escapeHtml(supervisor.status)}</div>
          <div><strong>Scope</strong>${escapeHtml(supervisor.learningScope ?? "n/a")}</div>
          <div><strong>Current Target</strong>${escapeHtml(supervisor.learningProject ?? "none")}</div>
          <div><strong>Selected Project</strong>${escapeHtml(projectDir)}</div>
          <div><strong>Mode</strong>${escapeHtml(supervisor.learningMode ?? "n/a")}</div>
        </div>
        ${targetMatches ? "" : `<p class="warn-box">The selected project can still show historical learning evidence, but its daemon heartbeat is missing because the durable supervisor is currently watching ${escapeHtml(supervisor.learningProject ?? "no project")}.</p>`}
      </section>
    `;
  }

  function renderLocalHoldoutRoutingStatusHtml(status: DashboardLocalHoldoutRoutingStatus): string {
    const statusClass = status.status === "active" || status.status === "approved"
      ? "completed"
      : status.status === "error" || status.status === "blocked"
        ? "failed"
        : "queued";
    const evidenceSuites = status.evidenceSuites.length ? status.evidenceSuites.join(", ") : "none";
    const promotableSuites = status.promotableSuites.length ? status.promotableSuites.join(", ") : "none";
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Holdout Routing</h2>
            <span class="muted">Reviewed local LLM promotion state and hosted fallback posture.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(status.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Results", status.resultsExists ? status.resultsDecision ?? "present" : "missing", status.resultsPath)}
          ${metricCard("Promotion", status.promotionExists ? status.promotionStatus ?? "present" : "missing", status.promotionPath)}
          ${metricCard("Approved", status.approved ? "yes" : "no", status.maxRisk ? `max risk ${status.maxRisk}` : "approval gate")}
          ${metricCard("Thresholds", status.thresholdSummary ?? "missing", "promotion gate")}
          ${metricCard("Holdout Evidence", status.evidenceSummary ?? "missing", "captured result")}
          ${metricCard("Local Routed", status.localStageCount, "recent local/BYO stages")}
          ${metricCard("Hosted Routed", status.hostedStageCount, "recent hosted stages")}
          ${metricCard("Local Fallback", status.localFallbackRate === null ? "n/a" : status.localFallbackRate, "recent local/BYO fallback rate")}
        </div>
        <div class="meta-grid compact">
          <div><strong>Evidence Suites</strong>${escapeHtml(evidenceSuites)}</div>
          <div><strong>Promotable Suites</strong>${escapeHtml(promotableSuites)}</div>
          <div><strong>Fallback Boundary</strong>${escapeHtml(status.hostedFallbackBoundary)}</div>
          <div><strong>Recommendation</strong>${escapeHtml(status.recommendation)}</div>
        </div>
        ${status.error ? `<p class="error">${escapeHtml(status.error)}</p>` : ""}
      </section>
    `;
  }

  function renderLocalLlmBenchmarkReceiptsHtml(report: LocalLlmBenchmarkReceiptReport): string {
    const statusClass = report.status === "completed" ? "completed" : report.status === "runtime-needed" || report.status === "no-installed-models" ? "failed" : "queued";
    const rows = report.receipts.map((receipt) => `
      <tr>
        <td>${escapeHtml(receipt.id)}<br><span class="muted">${escapeHtml(receipt.taskLabel)}</span></td>
        <td><span class="flag ${receipt.status === "completed" ? "good" : receipt.status === "failed" ? "bad" : "warn"}">${escapeHtml(receipt.status)}</span><br><span class="muted">${escapeHtml(receipt.verdict)}</span></td>
        <td>${escapeHtml(receipt.modelId)}<br><span class="muted">${receipt.runtime ? escapeHtml(receipt.runtime.label) : "no runtime"}</span></td>
        <td>${receipt.latencyMs === null ? "n/a" : `${formatNumber(receipt.latencyMs)} ms`}<br><span class="muted">score ${receipt.rubricScore ?? "n/a"}</span></td>
        <td>${escapeHtml(truncateText(receipt.error ?? (receipt.evidence.join(" ") || "No evidence yet."), 180))}</td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Benchmark Receipts</h2>
            <span class="muted">Tiny local-only prompts for measuring installed candidates before local smoke promotion.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Receipts", report.summary.receipts, `${report.summary.completed} completed, ${report.summary.planned} planned`)}
          ${metricCard("Runtime", report.runtime?.label ?? "none", report.runtime?.baseUrl ?? "start a local runtime")}
          ${metricCard("Avg Latency", report.summary.averageLatencyMs === null ? "n/a" : `${formatNumber(report.summary.averageLatencyMs)} ms`, "completed local prompts")}
          ${metricCard("Avg Score", report.summary.averageRubricScore ?? "n/a", "tiny rubric heuristic")}
        </div>
        <p class="muted">${escapeHtml(report.nextAction)}</p>
        <div class="actions">
          <form method="post" action="/api/follow-up">
            <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
            <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
            <input type="hidden" name="action" value="local-llm-benchmarks">
            <button type="submit">${iconLabel("file", "Write Benchmark Plan")}</button>
          </form>
          <form method="post" action="/api/follow-up">
            <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
            <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
            <input type="hidden" name="action" value="local-llm-benchmarks-execute">
            <button type="submit" class="secondary">${iconLabel("activity", "Execute Local Benchmark")}</button>
          </form>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Status</th><th>Model</th><th>Measure</th><th>Evidence</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No local benchmark receipts yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmCacheTrendHtml(report: LocalLlmCacheTrendReport): string {
    const statusClass = report.status === "tracking" ? "completed" : report.status === "started" ? "queued" : "failed";
    const rows = report.history.slice(-10).reverse().map((point) => `
      <tr>
        <td>${renderDashboardDateTime(point.capturedAt)}</td>
        <td>${escapeHtml(point.totalCacheLabel)}<br><span class="muted">${escapeHtml(point.storageStatus)}</span></td>
        <td>${point.freeBytes === null ? "unknown" : escapeHtml(formatBytes(point.freeBytes))}</td>
        <td>${formatNumber(point.modelCount)}</td>
        <td>${formatNumber(point.pruneCandidateCount)}<br><span class="muted">${escapeHtml(point.reclaimableLabel)} reclaim</span></td>
        <td>${formatNumber(point.localSelected)} local<br><span class="muted">${formatNumber(point.hostedSelected)} hosted</span></td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Cache Trends</h2>
            <span class="muted">Compact storage and route history for local-model cost savings.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Snapshots", report.history.length, "rolling project-local history")}
          ${metricCard("Cache Delta", report.comparison.cacheDeltaLabel, report.comparison.previousAt ? `since ${formatDashboardDateTimeText(report.comparison.previousAt)}` : "no previous snapshot")}
          ${metricCard("Free Disk Delta", report.comparison.freeDeltaLabel, "available storage movement")}
          ${metricCard("Local Route Delta", report.comparison.localRouteDelta ?? "n/a", "local-selected receipts")}
          ${metricCard("Hosted Route Delta", report.comparison.hostedRouteDelta ?? "n/a", "hosted-selected receipts")}
          ${metricCard("Current Reclaim", report.current.reclaimableLabel, `${formatNumber(report.current.pruneCandidateCount)} prune candidate(s)`)}
        </div>
        <p class="muted">${escapeHtml(report.recommendation)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-cache-trends">
          <button type="submit">${iconLabel("activity", "Write Trend Snapshot")}</button>
          <span class="muted">Appends aggregate history to <code>.agent-workflow/model-improvement/local-llm-cache-trends.*</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Captured</th><th>Cache</th><th>Free Disk</th><th>Models</th><th>Prune</th><th>Routes</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">No written trend snapshots yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmCostLedgerHtml(report: LocalLlmCostLedgerReport): string {
    const statusClass = report.status === "saving" ? "completed" : report.status === "watch" ? "queued" : "failed";
    const rows = report.history.slice(-10).reverse().map((point) => `
      <tr>
        <td>${renderDashboardDateTime(point.capturedAt)}</td>
        <td>${formatNumber(point.localSelectedStages)} local<br><span class="muted">${formatNumber(point.hostedSelectedStages)} hosted</span></td>
        <td>${escapeHtml(formatUsd(point.avoidedHostedUsd))}</td>
        <td>${escapeHtml(formatUsd(point.fallbackHostedUsd))}</td>
        <td>${escapeHtml(formatUsd(point.storageUsdPerMonth))}</td>
        <td>${escapeHtml(formatUsd(point.netEstimatedSavingsUsd))}</td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Cost Ledger</h2>
            <span class="muted">Estimated savings from local routing, fallback cost, benchmark latency, and cache storage.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Net Savings", formatUsd(report.current.netEstimatedSavingsUsd), "estimated in this run window")}
          ${metricCard("Avoided Hosted", formatUsd(report.current.avoidedHostedUsd), `${formatNumber(report.current.localSelectedStages)} local-selected stages`)}
          ${metricCard("Fallback Cost", formatUsd(report.current.fallbackHostedUsd), `${formatNumber(report.current.hostedFallbackStages)} hosted fallback stages`)}
          ${metricCard("Storage/Month", formatUsd(report.current.storageUsdPerMonth), report.current.totalCacheLabel)}
          ${metricCard("Benchmark Latency", report.current.benchmarkAverageLatencyMs === null ? "n/a" : `${formatNumber(report.current.benchmarkAverageLatencyMs)}ms`, `score ${report.current.benchmarkAverageScore ?? "n/a"}`)}
          ${metricCard("Savings Delta", report.comparison.netSavingsDeltaUsd === null ? "n/a" : formatUsd(report.comparison.netSavingsDeltaUsd), report.comparison.previousAt ? `since ${formatDashboardDateTimeText(report.comparison.previousAt)}` : "no previous snapshot")}
        </div>
        <p class="muted">${escapeHtml(report.recommendation)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-cost-ledger">
          <button type="submit">${iconLabel("activity", "Write Cost Snapshot")}</button>
          <span class="muted">Uses configurable <code>AGENTFLOW_COST_LEDGER_*</code> estimates and writes only project-local ledger files.</span>
        </form>
        <div class="meta-grid compact">
          <div><strong>Fast Stage</strong>${escapeHtml(formatUsd(report.assumptions.hostedUsdPerStageByTier.fast))}</div>
          <div><strong>Standard Stage</strong>${escapeHtml(formatUsd(report.assumptions.hostedUsdPerStageByTier.standard))}</div>
          <div><strong>Reasoning Stage</strong>${escapeHtml(formatUsd(report.assumptions.hostedUsdPerStageByTier.reasoning))}</div>
          <div><strong>Storage Rate</strong>${escapeHtml(formatUsd(report.assumptions.localStorageUsdPerGbMonth))} / GB-month</div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Captured</th><th>Routes</th><th>Avoided</th><th>Fallback</th><th>Storage</th><th>Net</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">No written cost snapshots yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmDownloadRecommendationsHtml(report: LocalLlmDownloadRecommendationReport): string {
    const statusClass = report.status === "ready" ? "completed" : report.status === "runtime-needed" ? "failed" : "queued";
    const rows = report.recommendations.map((item) => `
      <tr>
        <td><span class="flag ${item.priority === "high" ? "good" : item.priority === "medium" ? "warn" : "queued"}">${escapeHtml(item.priority)}</span></td>
        <td>${escapeHtml(item.modelId)}<br><span class="muted">${escapeHtml(item.label)}</span></td>
        <td>${escapeHtml(item.primaryTier)}<br><span class="muted">${escapeHtml(item.tierFit.join(", "))}</span></td>
        <td>${escapeHtml(item.hardwareFit)}<br><span class="muted">${item.installed ? "installed" : "download needed"}</span></td>
        <td><code>${escapeHtml(item.downloadCommand)}</code></td>
        <td>${escapeHtml(truncateText(item.rationale.join(" "), 180))}</td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Download Recommendations</h2>
            <span class="muted">Suggests practical local models from hardware, runtime catalog, task mix, and smoke evidence.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Hardware", report.hardware.class, `${report.hardware.memoryGb} GB, ${report.hardware.cpuCount} cores`)}
          ${metricCard("Dominant Tier", report.taskMix.dominantTier, report.taskMix.costSavingsGoal)}
          ${metricCard("Runtime", report.runtime?.label ?? "none", report.runtime?.baseUrl ?? "start a local runtime")}
          ${metricCard("Recommended", report.recommendedModelId ?? "none", report.nextAction)}
        </div>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="/model-improvement?project=${escapeHtml(encodeURIComponent(report.projectRootUri))}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-download-recommendations">
          <button type="submit">${iconLabel("download", "Write Recommendation Report")}</button>
          <span class="muted">Writes only <code>.agent-workflow/model-improvement/local-llm-download-recommendations.*</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Priority</th><th>Model</th><th>Tier</th><th>Fit</th><th>Download</th><th>Why</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">Start a local runtime before model recommendations can be tested.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmInstallationPlanHtml(report: LocalLlmInstallationPlanReport): string {
    const statusClass = report.status === "already-installed" ? "completed" : report.status === "no-selection" ? "failed" : "queued";
    const rows = report.actions.map((action) => `
      <tr>
        <td>${escapeHtml(action.id)}<br><span class="muted">${escapeHtml(action.modelId)}</span></td>
        <td><span class="flag ${action.risk === "high" ? "bad" : action.risk === "medium" ? "warn" : "good"}">${escapeHtml(action.risk)}</span><br><span class="muted">${formatNumber(action.diskEstimateGb)} GB est.</span></td>
        <td>${escapeHtml(action.runtime)}<br><span class="muted">${escapeHtml(action.primaryTier)} / ${escapeHtml(action.hardwareFit)}</span></td>
        <td>${action.commands.map((command) => `<code>${escapeHtml(command.command)}</code>${command.requiresApproval ? "<br><span class=\"muted\">review before running</span>" : ""}`).join("<hr>")}</td>
        <td>${action.envHints.map((hint) => `<code>${escapeHtml(hint)}</code>`).join("<br>")}</td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Installation Plan</h2>
            <span class="muted">Reviewed runtime-specific commands for installing recommended local models.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Selected", report.selectedModels, `${formatNumber(report.actions.length)} model action(s)`)}
          ${metricCard("Recommended", report.recommendedModelId ?? "none", `runtime ${report.runtimeStatus}`)}
          ${metricCard("Downloads", report.safety.executesDownloads ? "executes" : "plan only", "operator runs download commands")}
          ${metricCard("Provider Edits", report.safety.editsProviderSettings ? "yes" : "no", "env hints only")}
        </div>
        <p class="muted">${escapeHtml(report.safety.approvalBoundary)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-install-plan">
          <input name="model" value="${escapeHtml(report.selectedModels)}" aria-label="model selection">
          <button type="submit">${iconLabel("download", "Write Install Plan")}</button>
          <span class="muted">Writes Markdown, JSON, and a reviewed shell script under <code>.agent-workflow/model-improvement/</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Action</th><th>Risk</th><th>Runtime</th><th>Commands</th><th>Env Hints</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No local model install actions selected.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmInventoryHtml(report: LocalLlmInventoryReport): string {
    const statusClass = report.status === "ready" ? "completed" : report.status === "storage-pressure" ? "failed" : "queued";
    const rootRows = report.cacheRoots.map((root) => `
      <tr>
        <td>${escapeHtml(root.label)}<br><code>${escapeHtml(root.path)}</code></td>
        <td><span class="flag ${root.exists ? "good" : "queued"}">${root.exists ? "found" : "missing"}</span></td>
        <td>${escapeHtml(root.sizeLabel)}<br><span class="muted">${formatNumber(root.modelDirectories)} model dir(s)</span></td>
        <td>${renderDashboardDateTime(root.lastModifiedAt, "n/a")}</td>
        <td>${escapeHtml(root.error ?? "none")}</td>
      </tr>
    `).join("");
    const modelRows = report.models.slice(0, 12).map((model) => `
      <tr>
        <td>${escapeHtml(model.modelId)}<br><span class="muted">${escapeHtml(model.source)}</span></td>
        <td>${escapeHtml(model.cacheRoot)}<br><span class="muted">${escapeHtml(model.sizeLabel)}</span></td>
        <td>${renderDashboardDateTime(model.lastUsedAt, "unknown")}</td>
        <td>${model.recommended ? "<span class=\"flag good\">recommended</span>" : "<span class=\"flag queued\">other</span>"}</td>
        <td>${model.pruneCandidate ? "<span class=\"flag warn\">review prune</span>" : "<span class=\"flag good\">keep</span>"}<br><span class="muted">${escapeHtml(truncateText(model.reason, 100))}</span></td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Disk Inventory</h2>
            <span class="muted">Read-only cache scan before recommending additional local model downloads.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Total Cache", report.totalCacheLabel, `${formatNumber(report.cacheRoots.filter((root) => root.exists).length)} cache root(s) found`)}
          ${metricCard("Free Disk", report.storage.freeBytes === null ? "unknown" : formatBytes(report.storage.freeBytes), report.storage.status)}
          ${metricCard("Models", report.models.length, "runtime catalog and cache directories")}
          ${metricCard("Prune Review", report.pruneCandidates.length, "stale, unrecommended candidates")}
        </div>
        <p class="muted">${escapeHtml(report.recommendation)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-inventory">
          <button type="submit">${iconLabel("activity", "Write Inventory Report")}</button>
          <span class="muted">Writes only <code>.agent-workflow/model-improvement/local-llm-inventory.*</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Cache Root</th><th>Status</th><th>Size</th><th>Modified</th><th>Notes</th></tr></thead><tbody>${rootRows}</tbody></table></div>
        <div class="table-wrap"><table><thead><tr><th>Model</th><th>Cache/Size</th><th>Last Used</th><th>Recommendation</th><th>Prune</th></tr></thead><tbody>${modelRows || "<tr><td colspan=\"5\">No local model entries found yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmPrunePlanHtml(report: LocalLlmPrunePlanReport): string {
    const statusClass = report.status === "no-candidates" ? "completed" : report.status === "needs-review" ? "failed" : "queued";
    const rows = report.actions.map((action) => `
      <tr>
        <td>${escapeHtml(action.id)}<br><span class="muted">${escapeHtml(action.modelId)}</span></td>
        <td>${escapeHtml(action.cacheRoot)}<br><code>${escapeHtml(action.cachePath ?? "no path detected")}</code></td>
        <td>${escapeHtml(action.sizeLabel)}<br><span class="muted">last used ${renderDashboardDateTime(action.lastUsedAt, "unknown")}</span></td>
        <td><span class="flag ${action.risk === "high" ? "warn" : "queued"}">${escapeHtml(action.risk)}</span><br>${action.recommended ? "<span class=\"flag good\">recommended</span>" : "<span class=\"flag queued\">not recommended</span>"}</td>
        <td><code>${escapeHtml(action.command)}</code><br><span class="muted">${escapeHtml(truncateText(action.reason, 120))}</span></td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Model Prune Plan</h2>
            <span class="muted">Reviewed cleanup commands from inventory candidates. Nothing is deleted automatically.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Actions", report.actions.length, "reviewable cleanup commands")}
          ${metricCard("Potential Reclaim", report.reclaimableLabel, "cache bytes from selected actions")}
          ${metricCard("High Risk", report.actions.filter((action) => action.risk === "high").length, "extra review")}
          ${metricCard("Deletes Executed", report.safety.executesDeletes ? "yes" : "no", "planner boundary")}
        </div>
        <p class="muted">${escapeHtml(report.nextAction)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-prune-plan">
          <input name="model" value="${escapeHtml(report.selectedModels)}" aria-label="model selection">
          <button type="submit">${iconLabel("trash", "Write Prune Plan")}</button>
          <span class="muted">Use <code>candidates</code>, <code>all</code>, or specific prune/model ids. Writes only <code>.agent-workflow/model-improvement/local-llm-prune-plan.*</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Action</th><th>Cache Path</th><th>Size</th><th>Risk</th><th>Command</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No prune candidates found yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmRoutingDecisionSnapshotsHtml(report: LocalLlmRoutingDecisionSnapshotReport): string {
    const latest = report.snapshots.at(-1) ?? null;
    const previous = report.latestDelta.previousAt ?? "none";
    const stateChanges = report.latestDelta.stateChanges.length
      ? report.latestDelta.stateChanges.join("; ")
      : "none";
    const rows = report.snapshots.slice(-8).reverse().map((snapshot) => `
      <tr>
        <td>${renderDashboardDateTime(snapshot.generatedAt)}<br><span class="muted">${escapeHtml(snapshot.decisionHash.slice(0, 12))}</span></td>
        <td><span class="flag ${snapshot.status === "active" ? "good" : snapshot.status === "recommended" ? "warn" : "queued"}">${escapeHtml(snapshot.status)}</span></td>
        <td>${formatNumber(snapshot.items.length)} item(s)<br><span class="muted">applied ${formatNumber(snapshot.counts.applied ?? 0)}, planned ${formatNumber(snapshot.counts.planned ?? 0)}, recommended ${formatNumber(snapshot.counts.recommended ?? 0)}</span></td>
        <td>${escapeHtml(formatUsd(snapshot.totalNetSavingsUsd))}</td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Routing Decision Snapshots</h2>
            <span class="muted">Persisted timeline history for comparing routing decisions over time.</span>
          </div>
          <span class="status ${report.captured ? "completed" : "queued"}">${report.captured ? "changed" : "unchanged"}</span>
        </div>
        <div class="metric-grid snapshot-metrics">
          ${metricCard("Snapshots", report.snapshots.length, "kept locally")}
          ${metricCard("Latest", latest ? formatDashboardDateTimeText(latest.generatedAt) : "none", "last persisted")}
          ${metricCard("Previous", previous === "none" ? "none" : formatDashboardDateTimeText(previous), "comparison baseline")}
          ${metricCard("Changed Items", report.latestDelta.changedItems, `${report.latestDelta.added} added, ${report.latestDelta.removed} removed`)}
          ${metricCard("Savings Delta", formatUsd(report.latestDelta.netSavingsDeltaUsd), "latest vs previous")}
          ${metricCard("Current Hash", report.currentSnapshot.decisionHash.slice(0, 10), report.captured ? "new projection" : "same projection")}
        </div>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="/model-improvement?project=${encodeURIComponent(report.projectRootUri)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-routing-decision-snapshot">
          <button type="submit">${iconLabel("activity", "Capture Decision Snapshot")}</button>
          <span class="muted">Appends only if the routing decision hash changed.</span>
        </form>
        <div class="meta-grid compact">
          <div><strong>State Changes</strong>${escapeHtml(stateChanges)}</div>
          <div><strong>Files</strong><code>.agent-workflow/model-improvement/local-routing-decision-snapshots.*</code></div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Captured</th><th>Status</th><th>Items</th><th>Net Savings</th></tr></thead><tbody>${rows || "<tr><td colspan=\"4\">No persisted decision snapshots yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmRoutingDecisionTimelineHtml(report: DashboardLocalLlmRoutingDecisionTimeline): string {
    const statusClass = report.status === "active" ? "completed" : report.status === "recommended" ? "failed" : "queued";
    const rows = report.items.map((item) => `
      <tr>
        <td><span class="flag ${item.state === "applied" ? "good" : item.state === "recommended" ? "warn" : "queued"}">${escapeHtml(item.state)}</span><br><span class="muted">${escapeHtml(item.recommendationId)}</span></td>
        <td>${escapeHtml(item.action)}<br><span class="muted">${escapeHtml(item.priority)}</span></td>
        <td>${escapeHtml(item.target)}<br><span class="muted">${escapeHtml(item.agentId)}</span></td>
        <td>${escapeHtml(item.noteId ?? "none")}<br><span class="muted">${escapeHtml(item.providerTier)}</span></td>
        <td>${formatNumber(item.runs)} run(s)<br><span class="muted">fallback ${item.fallbackRate}, quality ${item.quality ?? "n/a"}</span></td>
        <td>${escapeHtml(formatUsd(item.netSavingsUsd))}<br><span class="muted">${escapeHtml(truncateText(item.outcome, 140))}</span></td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Model Routing Decision Timeline</h2>
            <span class="muted">Recommendation to note plan to applied receipt to current route outcome.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Timeline Items", report.items.length, "top routing decisions")}
          ${metricCard("Applied", report.items.filter((item) => item.state === "applied").length, "active routing notes")}
          ${metricCard("Planned", report.items.filter((item) => item.state === "planned").length, "reviewed note plans")}
          ${metricCard("Recommended", report.items.filter((item) => item.state === "recommended").length, "not yet planned")}
          ${metricCard("Monitoring", report.items.filter((item) => item.state === "monitoring").length, "hold decisions")}
          ${metricCard("Application Receipt", report.sourceApplicationGeneratedAt ? formatDashboardDateTimeText(report.sourceApplicationGeneratedAt) : "n/a", "latest apply evidence")}
        </div>
        <p class="muted">${report.summary.map((item) => escapeHtml(item)).join(" ")}</p>
        <div class="table-wrap"><table><thead><tr><th>State</th><th>Decision</th><th>Target</th><th>Plan/Route</th><th>Outcome Evidence</th><th>Economics</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">No routing decisions are available yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmRoutingNoteApplicationHtml(report: DashboardLocalLlmRoutingNoteApplicationStatus): string {
    const statusClass = report.error ? "failed" : report.exists ? "completed" : report.activePreferenceExists ? "queued" : "queued";
    const selected = report.selectedNoteIds.length ? report.selectedNoteIds.join(", ") : "none";
    const applied = report.appliedNoteIds.length ? report.appliedNoteIds.join(", ") : "none";
    const skipped = report.skippedNoteIds.length ? report.skippedNoteIds.join(", ") : "none";
    const hashPair = report.beforeHash && report.afterHash
      ? `${report.beforeHash.slice(0, 10)} -> ${report.afterHash.slice(0, 10)}`
      : "n/a";
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Applied Local Routing Notes</h2>
            <span class="muted">Active project-local routing preferences and rollback receipt evidence.</span>
          </div>
          <span class="status ${statusClass}">${report.exists ? "receipt" : report.activePreferenceExists ? "preferences only" : "missing"}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Applied", report.appliedNoteIds.length, "selected notes appended")}
          ${metricCard("Skipped", report.skippedNoteIds.length, "duplicates or unmatched ids")}
          ${metricCard("Active Markers", report.activeLocalRoutingNoteMarkers, "agentflow local note sections")}
          ${metricCard("Receipt Approved", report.approved ? "yes" : "no", report.generatedAt ? `generated ${formatDashboardDateTimeText(report.generatedAt)}` : "no receipt yet")}
          ${metricCard("Preference Size", formatBytes(report.activePreferenceBytes), report.activePreferenceExists ? report.targetFile : "not written")}
          ${metricCard("Hash Change", hashPair, "before -> after")}
        </div>
        <div class="meta-grid compact">
          <div><strong>Receipt File</strong><code>${escapeHtml(report.path)}</code></div>
          <div><strong>Target File</strong><code>${escapeHtml(report.targetFile)}</code></div>
          <div><strong>Source Plan</strong>${renderDashboardDateTime(report.sourcePlanGeneratedAt)}</div>
          <div><strong>Active Hash</strong><code>${escapeHtml(report.activePreferenceHash?.slice(0, 16) ?? "n/a")}</code></div>
        </div>
        <div class="meta-grid compact">
          <div><strong>Selected</strong><code>${escapeHtml(selected)}</code></div>
          <div><strong>Applied</strong><code>${escapeHtml(applied)}</code></div>
          <div><strong>Skipped</strong><code>${escapeHtml(skipped)}</code></div>
          <div><strong>Rollback</strong>${escapeHtml(report.rollback ?? "Apply a reviewed note plan to create rollback evidence.")}</div>
        </div>
        ${report.error ? `<p class="error">${escapeHtml(report.error)}</p>` : ""}
        ${report.activePreferencePreview ? `<pre>${escapeHtml(report.activePreferencePreview)}</pre>` : "<p class=\"muted\">No active local routing preference notes have been written yet.</p>"}
      </section>
    `;
  }

  function renderLocalLlmRoutingRecommendationHtml(report: LocalLlmRoutingRecommendationReport): string {
    const statusClass = report.status === "expand" ? "completed" : report.status === "retreat" ? "failed" : "queued";
    const rows = report.recommendations.map((item) => `
      <tr>
        <td><span class="flag ${item.priority === "high" ? "warn" : item.priority === "medium" ? "queued" : "good"}">${escapeHtml(item.priority)}</span><br>${escapeHtml(item.id)}</td>
        <td><span class="flag ${item.action === "expand" ? "good" : item.action === "retreat" ? "warn" : "queued"}">${escapeHtml(item.action)}</span></td>
        <td>${escapeHtml(item.workflowId)}<br><span class="muted">${escapeHtml(item.stageId)} / ${escapeHtml(item.agentId)}</span></td>
        <td>${escapeHtml(item.routeClass)}<br><span class="muted">${escapeHtml(item.providerId)} / ${escapeHtml(item.modelTier)}</span></td>
        <td>${formatNumber(item.runs)} run(s)<br><span class="muted">fallback ${item.fallbackRate}, quality ${item.averageQuality ?? "n/a"}</span></td>
        <td>${formatNumber(item.routeFeedback.total)} signal(s)<br><span class="muted">helpful ${item.routeFeedback.helpful}, costly ${item.routeFeedback.costly}, neutral ${item.routeFeedback.neutral}</span></td>
        <td>${escapeHtml(formatUsd(item.estimatedNetSavingsUsd))}<br><span class="muted">${escapeHtml(truncateText(item.recommendation, 120))}</span></td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Savings-Aware Local Routing</h2>
            <span class="muted">Expand, hold, or retreat recommendations from quality, fallback, latency, storage, and savings evidence.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Expand", report.recommendations.filter((item) => item.action === "expand").length, "local trial candidates")}
          ${metricCard("Hold", report.recommendations.filter((item) => item.action === "hold").length, "keep current boundary")}
          ${metricCard("Retreat", report.recommendations.filter((item) => item.action === "retreat").length, "move back toward hosted")}
          ${metricCard("Net Savings", formatUsd(report.evidence.netEstimatedSavingsUsd), "current cost ledger")}
          ${metricCard("Route Receipts", report.evidence.routeReceipts, "inspected model_route receipts")}
          ${metricCard("Storage", report.evidence.storageStatus, `${formatNumber(report.evidence.pruneCandidateCount)} prune candidate(s)`)}
        </div>
        <p class="muted">${escapeHtml(report.nextAction)}</p>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-routing-recommendations">
          <button type="submit">${iconLabel("activity", "Write Routing Recommendations")}</button>
          <span class="muted">Writes advisory files only. Routing/provider settings are not changed.</span>
        </form>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-routing-note-plan">
          <input type="hidden" name="ids" value="all">
          <button type="submit" class="secondary">${iconLabel("file", "Write Routing Note Plan")}</button>
          <span class="muted">Turns expand/retreat recommendations into reviewed project-local tuning notes.</span>
        </form>
        <form method="post" action="/api/follow-up" class="inline-form">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="apply-local-llm-routing-note-plan">
          <input type="hidden" name="ids" value="all">
          <button type="submit" class="secondary">${iconLabel("check", "Dry Run Apply Notes")}</button>
          <span class="muted">Previews appending reviewed notes to <code>.agent-workflow/tuning/routing-preferences.md</code>.</span>
        </form>
        <div class="table-wrap"><table><thead><tr><th>Priority</th><th>Action</th><th>Target</th><th>Route</th><th>Evidence</th><th>Feedback</th><th>Economics</th></tr></thead><tbody>${rows}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalLlmSetupChecklistHtml(report: LocalLlmSetupChecklistReport): string {
    const statusClass = report.status === "pass" ? "completed" : report.status === "fail" ? "failed" : "queued";
    const smoke = report.smokeOutcomes;
    const tierModels = report.localProvider.selectedTierModels
      .map((item) => `${item.tier}=${item.model} (${item.source})`)
      .join(", ") || "none";
    const rows = report.checks.map((check) => `
      <tr>
        <td><span class="flag ${check.status === "pass" ? "good" : check.status === "fail" ? "bad" : "warn"}">${escapeHtml(check.status)}</span></td>
        <td>${escapeHtml(check.label)}<br><span class="muted">${escapeHtml(check.detail)}</span></td>
        <td>${escapeHtml(check.nextAction)}</td>
      </tr>
    `).join("");
    const commandRows = report.nextCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const smokeRows = smoke.latestOutcomes.map((outcome) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(outcome.runId)}">${escapeHtml(outcome.runId.slice(0, 8))}</a><br><span class="muted">${renderDashboardDateTime(outcome.startedAt)}</span></td>
        <td><span class="flag ${outcome.routeClass === "local-selected" ? "good" : outcome.routeClass === "missing" || outcome.status === "failed" ? "bad" : "warn"}">${escapeHtml(outcome.routeClass.replace(/-/g, " "))}</span><br><span class="muted">${escapeHtml(outcome.status)}</span></td>
        <td>${escapeHtml(outcome.providerId ?? "none")}<br><span class="muted">${escapeHtml([outcome.modelTier, outcome.requestedModelTier].filter(Boolean).join(" / ") || "no tier")}</span></td>
        <td>${outcome.qualityScore ?? "n/a"}</td>
        <td>${escapeHtml(truncateText(outcome.routeReason ?? "No route reason recorded.", 160))}</td>
      </tr>
    `).join("");
    const returnTo = `/model-improvement?project=${encodeURIComponent(report.projectRootUri)}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local LLM Setup Checklist</h2>
            <span class="muted">Verifies endpoint readiness, catalog model selection, routing visibility, and the first low-risk local route receipt.</span>
          </div>
          <div class="actions">
            <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
            <a class="button secondary" href="/api/local-llm-checklist?project=${encodeURIComponent(report.projectRootUri)}">JSON</a>
          </div>
        </div>
        <div class="metric-grid">
          ${metricCard("Endpoint", report.localProvider.status, report.localProvider.baseUrl)}
          ${metricCard("Models Listed", report.localProvider.modelsListed, report.localProvider.model)}
          ${metricCard("Tier Models", report.localProvider.selectedTierModels.length, tierModels)}
          ${metricCard("Auto Routing", report.routing.defaultProvider, `fast=${report.routing.fastProvider}, standard=${report.routing.standardProvider}`)}
          ${metricCard("Holdout", report.routing.localHoldoutApproved ? "approved" : report.routing.localHoldoutStatus, "low-risk local promotion")}
          ${metricCard("Local Receipts", report.routing.localRouteReceipts, `${report.routing.localSkippedReceipts} skipped, ${report.routing.hostedFallbackReceipts} hosted fallback`)}
        </div>
        <section class="subpanel">
          <div class="section-heading">
            <div>
              <h3>Local Smoke Outcomes</h3>
              <span class="muted">Compares low-risk local route smoke runs over time.</span>
            </div>
            <span class="flag ${smoke.counts["local-selected"] > 0 ? "good" : smoke.smokeRuns ? "warn" : "queued"}">${formatNumber(smoke.smokeRuns)} smoke runs</span>
          </div>
          <div class="metric-grid">
            ${metricCard("Local Successes", smoke.counts["local-selected"], "completed local/BYO selections")}
            ${metricCard("First Local Success", smoke.firstSuccessAt ? formatDashboardDateTimeText(smoke.firstSuccessAt) : "none", "true local-selected receipt")}
            ${metricCard("Latest Smoke", smoke.latestSmokeAt ? formatDashboardDateTimeText(smoke.latestSmokeAt) : "none", "most recent setup smoke")}
            ${metricCard("Latest Issue", smoke.latestFailureReason ? truncateText(smoke.latestFailureReason, 72) : "none", "failure, skip, fallback, or hosted selection")}
          </div>
          <p class="muted">${escapeHtml(smoke.recommendation)}</p>
          <div class="table-wrap"><table><thead><tr><th>Run</th><th>Outcome</th><th>Provider/Tier</th><th>Quality</th><th>Reason</th></tr></thead><tbody>${smokeRows || "<tr><td colspan=\"5\">No local LLM smoke runs found yet.</td></tr>"}</tbody></table></div>
        </section>
        <div class="table-wrap"><table><thead><tr><th>Status</th><th>Check</th><th>Next Action</th></tr></thead><tbody>${rows}</tbody></table></div>
        <form class="inline-form" method="post" action="/api/follow-up">
          <input type="hidden" name="returnTo" value="${escapeHtml(returnTo)}">
          <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
          <input type="hidden" name="action" value="local-llm-smoke">
          <button type="submit">${iconLabel("activity", "Run Low-Risk Local Route Smoke")}</button>
          <span class="muted">Queues one <code>provider-smoke</code> fast-tier stage and writes normal route receipts.</span>
        </form>
        <details>
          <summary>CLI commands</summary>
          <ul>${commandRows}</ul>
        </details>
      </section>
    `;
  }

  function renderLocalLlmSetupGuideHtml(report: LocalLlmSetupGuideReport): string {
    const statusClass = report.status === "ready" ? "completed" : "queued";
    const runtimeRows = report.runtimes.map((runtime) => `
      <tr>
        <td>${escapeHtml(runtime.label)}<br><code>${escapeHtml(runtime.baseUrl)}</code></td>
        <td><span class="flag ${runtime.status === "ready" ? "good" : runtime.status === "empty" ? "warn" : "bad"}">${escapeHtml(runtime.status)}</span></td>
        <td>${formatNumber(runtime.modelCount)}<br><span class="muted">${escapeHtml(runtime.models.slice(0, 4).join(", ") || "none listed")}</span></td>
        <td>${escapeHtml(runtime.selectedTierModels.map((item) => `${item.tier}=${item.model}`).join(", "))}</td>
        <td>${escapeHtml(runtime.nextAction)}</td>
      </tr>
    `).join("");
    const blockerRows = report.blockers.length
      ? report.blockers.map((blocker) => `<li>${escapeHtml(blocker)}</li>`).join("")
      : "<li>No blockers. The routing note can be written after approval.</li>";
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Guided Local Model Setup</h2>
            <span class="muted">Detects local OpenAI-compatible runtimes and prepares project-local setup or routing notes.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(report.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Detected Ready", report.runtimes.filter((runtime) => runtime.status === "ready").length, "runtime catalogs")}
          ${metricCard("Recommended", report.recommendedRuntime?.label ?? "none", report.recommendedRuntime?.baseUrl ?? "start a local runtime")}
          ${metricCard("Routing Note", report.routingNoteEligible ? "eligible" : "blocked", report.approved ? "approved" : "needs approval")}
          ${metricCard("First Local Smoke", report.firstLocalSmokeSuccessAt ? formatDashboardDateTimeText(report.firstLocalSmokeSuccessAt) : "none", "required evidence")}
        </div>
        <p class="muted">${escapeHtml(report.recommendation)}</p>
        <div class="split-grid compact">
          <div>
            <h3>Blockers</h3>
            <ul>${blockerRows}</ul>
          </div>
          <div>
            <h3>Safe Writes</h3>
            <ul>
              <li><code>.agent-workflow/model-improvement/local-llm-setup-guide.*</code></li>
              <li><code>.agent-workflow/tuning/local-model-routing-note.*</code> only when healthy and approved</li>
            </ul>
          </div>
        </div>
        <div class="actions">
          <form method="post" action="/api/follow-up">
            <input type="hidden" name="returnTo" value="/model-improvement?project=${escapeHtml(encodeURIComponent(report.projectRootUri))}">
            <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
            <input type="hidden" name="action" value="local-llm-setup-guide">
            <button type="submit">${iconLabel("file", "Write Setup Guide")}</button>
          </form>
          <form method="post" action="/api/follow-up">
            <input type="hidden" name="returnTo" value="/model-improvement?project=${escapeHtml(encodeURIComponent(report.projectRootUri))}">
            <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri)}">
            <input type="hidden" name="action" value="local-llm-setup-approve">
            <button type="submit" class="secondary">${iconLabel("check", "Approve Healthy Routing Note")}</button>
          </form>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Runtime</th><th>Status</th><th>Models</th><th>Tier Selection</th><th>Next Action</th></tr></thead><tbody>${runtimeRows || "<tr><td colspan=\"5\">No local runtime probes were configured.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderLocalProviderEvidenceHtml(evidence: DashboardLocalProviderEvidence): string {
    const statusClass = evidence.status === "ready" ? "completed" : evidence.status === "not-configured" ? "failed" : "queued";
    const feedback = `${evidence.localAccepted}/${evidence.localRevised}/${evidence.localRejected}`;
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Provider Evidence</h2>
            <span class="muted">Cost-saving signal for local/BYO model routes before expanding automatic routing.</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(evidence.status)}</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Local Stages", evidence.localStageCount, evidence.providerIds.length ? evidence.providerIds.join(", ") : "none yet")}
          ${metricCard("Hosted Stages", evidence.hostedStageCount, "OpenAI, Bedrock, Kiro, or other non-local providers")}
          ${metricCard("Avoided Hosted Calls", evidence.estimatedAvoidedHostedCalls, "local/BYO routed stages")}
          ${metricCard("Fallback Rate", evidence.localFallbackRate === null ? "n/a" : evidence.localFallbackRate, "local/BYO fallback")}
          ${metricCard("Local Quality", evidence.localAverageQuality === null ? "n/a" : evidence.localAverageQuality, `feedback A/R/R ${feedback}`)}
          ${metricCard("Local Latency", evidence.localAverageLatencyMs === null ? "n/a" : `${Math.round(evidence.localAverageLatencyMs)}ms`, "weighted average")}
        </div>
        <div class="meta-grid compact">
          <div><strong>Configured</strong>${evidence.configured ? "yes" : "no"}</div>
          <div><strong>Local Providers Seen</strong>${evidence.providerIds.length ? escapeHtml(evidence.providerIds.join(", ")) : "none"}</div>
          <div><strong>Hosted Quality</strong>${evidence.hostedAverageQuality === null ? "n/a" : evidence.hostedAverageQuality}</div>
          <div><strong>Hosted Latency</strong>${evidence.hostedAverageLatencyMs === null ? "n/a" : `${Math.round(evidence.hostedAverageLatencyMs)}ms`}</div>
        </div>
        <p class="muted">${escapeHtml(evidence.recommendation)}</p>
      </section>
    `;
  }

  function renderLocalRouteDecisionDrilldownHtml(
    trends: DashboardRouteReceiptTrendReport,
    holdout: DashboardLocalHoldoutRoutingStatus
  ): string {
    const rows = trends.topGroups.map((group) => {
      const explanation = localRouteDecisionExplanation(group, holdout);
      return `
        <tr>
          <td>${escapeHtml(group.workflowId)}<br><span class="muted">${escapeHtml(group.stageId)} / ${escapeHtml(group.agentId)}</span></td>
          <td><span class="flag ${explanation.severity === "good" ? "good" : explanation.severity === "warning" ? "warn" : "queued"}">${escapeHtml(explanation.label)}</span></td>
          <td>${escapeHtml(group.providerId)} / ${escapeHtml(group.modelTier)}<br><span class="muted">${formatNumber(group.runs)} receipt(s)</span></td>
          <td>${group.averageQuality ?? "n/a"}<br><span class="muted">${group.averageLatencyMs === null ? "latency n/a" : `${formatNumber(group.averageLatencyMs)}ms avg`}</span></td>
          <td>${group.fallbackCount}<br><span class="muted">${group.runs ? Number((group.fallbackCount / group.runs).toFixed(2)) : 0} fallback rate</span></td>
          <td><span>${escapeHtml(truncateText(explanation.reason, 220))}</span>${explanation.reason.length > 220 ? `<details class="run-task-details"><summary>View rationale</summary><div>${escapeHtml(truncateText(explanation.reason, 1200))}</div></details>` : ""}<strong>Next:</strong> ${escapeHtml(explanation.nextAction)}</td>
          <td>${routeDecisionFeedbackForm(trends.projectRootUri, group)}</td>
        </tr>
      `;
    }).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Local Route Decision Drilldown</h2>
            <span class="muted">Why recent stages selected local, skipped local, or used hosted fallback.</span>
          </div>
          <span class="status ${holdout.approved ? "completed" : "queued"}">${holdout.approved ? "holdout approved" : holdout.status}</span>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Stage</th><th>Decision</th><th>Route</th><th>Quality/Latency</th><th>Fallback</th><th>Reason / Next Action</th><th>Feedback</th></tr></thead><tbody>${rows || "<tr><td colspan=\"7\">No recent route receipts are available yet.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderMobileApprovalCard(approval: DashboardActionApproval, backlogItem?: ApprovalBacklogItem): string {
    const risk = backlogItem?.autopilotRisk ?? (approval.actionType === "deployment" || approval.actionType === "autonomy" ? "high" : "medium");
    const ageReference = approval.updatedAt ?? approval.createdAt;
    const ageMs = Math.max(0, Date.now() - Date.parse(ageReference));
    const executable = isExecutableApprovalAction(approval.actionType);
    const decisionControls = approval.status === "pending"
      ? `<div class="mobile-approval-actions">
          <form method="post" action="/api/approval-action">
            <input type="hidden" name="approvalId" value="${escapeHtml(approval.id)}">
            <input type="hidden" name="decision" value="rejected">
            <input type="hidden" name="actorRole" value="approver">
            <button class="danger secondary" type="submit">Reject</button>
          </form>
          ${approval.actionType === "local_command" || approval.actionType === "file_write" ? `<form method="post" action="/api/approval-rule-action">
            <input type="hidden" name="approvalId" value="${escapeHtml(approval.id)}">
            <input type="hidden" name="actorRole" value="approver">
            <input type="hidden" name="target" value="${escapeHtml(approvalRuleExactTarget(approval))}">
            <input type="hidden" name="approveCurrent" value="on">
            <input type="hidden" name="note" value="Always approve ${escapeHtml(approvalRuleDisplayTarget(approval, approvalRuleExactTarget(approval)))}">
            <button class="secondary" type="submit">Always allow</button>
          </form>` : ""}
          <form method="post" action="/api/approval-action">
            <input type="hidden" name="approvalId" value="${escapeHtml(approval.id)}">
            <input type="hidden" name="decision" value="${executable ? "approve_execute" : "approved"}">
            <input type="hidden" name="actorRole" value="approver">
            <button type="submit">${executable ? "Approve & run" : "Approve"}</button>
          </form>
        </div>`
      : approval.status === "approved" && executable
        ? `<div class="mobile-approval-actions two-up">${approvalDismissForm(approval.id)}${approvalExecuteForm(approval.id).replace(">Execute<", ">Execute now<")}</div>`
        : approval.status === "failed" && executable
          ? `<div class="mobile-approval-actions two-up">${approvalDismissForm(approval.id)}${approvalExecuteForm(approval.id).replace(">Execute<", ">Retry now<")}</div>`
          : `<p class="muted">${escapeHtml(approval.decisionNote ?? "No action available.")}</p>`;
    return `<article class="mobile-approval-card risk-${escapeHtml(risk)}">
      <div class="mobile-approval-meta">
        <span class="approval-risk"><strong>${escapeHtml(titleCase(risk))} risk</strong></span>
        <span class="approval-kind">${escapeHtml(titleCase(approval.actionType.replaceAll("_", " ")))}</span>
        <span class="approval-age">${escapeHtml(formatApprovalAge(ageMs))}</span>
      </div>
      <div class="mobile-approval-context">
        <strong>${escapeHtml(approval.projectName)}</strong>
        <span>${escapeHtml(approval.workflowId)} · ${escapeHtml(approval.stageId)}</span>
      </div>
      <code class="mobile-approval-target">${escapeHtml(approval.target)}</code>
      <details class="mobile-approval-details">
        <summary>View details</summary>
        <dl>
          <div><dt>Requested by</dt><dd>${escapeHtml(approval.agentId)}</dd></div>
          <div><dt>Why</dt><dd>${escapeHtml(approval.rationale)}</dd></div>
          <div><dt>Approval ID</dt><dd>${escapeHtml(approval.id)}</dd></div>
          <div><dt>Run</dt><dd><a href="/run?id=${encodeURIComponent(approval.runId)}">${escapeHtml(approval.runId)}</a></dd></div>
          <div><dt>Payload</dt><dd>${escapeHtml(formatApprovalPayload(approval.payload))}</dd></div>
        </dl>
      </details>
      ${decisionControls}
    </article>`;
  }

  function renderModelCatalogHtml(report: DashboardModelCatalogReport): string {
    const providerCards = report.providers.map((provider) => {
      const tierRows = provider.tierSelections.map((tier) => `
        <tr>
          <td>${escapeHtml(tier.tier)}</td>
          <td>${escapeHtml(tier.selectedModel)}</td>
          <td>${escapeHtml(tier.source)}</td>
          <td>${escapeHtml(tier.estimatedCostClass)}</td>
          <td>${tier.policyScore ?? "n/a"}</td>
          <td>${tier.tierFit ?? "n/a"}</td>
          <td>${escapeHtml(tier.overrideSource)}</td>
        </tr>
      `).join("");
      const candidateRows = provider.tierSelections.flatMap((tier) =>
        tier.candidates.slice(0, 5).map((candidate) => `
          <tr>
            <td>${escapeHtml(tier.tier)}</td>
            <td>${candidate.selected ? "<strong>" : ""}${escapeHtml(candidate.id)}${candidate.selected ? "</strong>" : ""}${!candidate.eligible ? `<br><span class="muted">${escapeHtml(candidate.excludedReason ?? "excluded")}</span>` : ""}</td>
            <td>${candidate.eligible ? "yes" : "no"}</td>
            <td>${candidate.tierRank}</td>
            <td>${candidate.versionRank}</td>
            <td>${candidate.sizeRank}</td>
            <td>${candidate.familyRank}</td>
            <td>${candidate.totalRank}</td>
          </tr>
        `)
      ).join("");
      const excluded = provider.tierSelections.reduce((sum, tier) => sum + tier.excludedCount, 0);
      const statusClass = provider.status === "ready" ? "completed" : provider.status === "missing" ? "failed" : "queued";
      return `<section class="panel">
        <div class="section-heading">
          <div>
            <h2>${escapeHtml(provider.label)}</h2>
            <span class="muted">${escapeHtml(provider.providerId)} catalog source: ${escapeHtml(provider.catalogSource)}</span>
          </div>
          <span class="status ${statusClass}">${escapeHtml(provider.status)}</span>
        </div>
        <div class="meta-grid compact">
          <div><strong>Configured</strong>${provider.configured ? "yes" : "no"}</div>
          <div><strong>Models listed</strong>${formatNumber(provider.modelsListed)}</div>
          <div><strong>Configured model</strong>${escapeHtml(provider.configuredModel)}</div>
          <div><strong>Model env</strong>${escapeHtml(provider.modelEnv)}</div>
          <div><strong>API key / auth</strong>${escapeHtml(provider.apiKeyStatus ?? "not used")}</div>
          <div><strong>AWS</strong>${escapeHtml([provider.awsProfile ? `profile ${provider.awsProfile}` : "", provider.awsRegion ? `region ${provider.awsRegion}` : ""].filter(Boolean).join(", ") || "not used")}</div>
          <div><strong>Base URL</strong>${escapeHtml(provider.baseUrl ?? "not used")}</div>
          <div><strong>Excluded candidates</strong>${formatNumber(excluded)}</div>
        </div>
        ${provider.error ? `<p class="warn-box">${escapeHtml(provider.error)}</p>` : ""}
        <h3>Tier Selection</h3>
        <table><thead><tr><th>Tier</th><th>Selected model</th><th>Source</th><th>Cost class</th><th>Policy score</th><th>Tier fit</th><th>Override source</th></tr></thead><tbody>${tierRows}</tbody></table>
        <h3>Top Catalog Candidates</h3>
        <table><thead><tr><th>Tier</th><th>Model</th><th>Eligible</th><th>Tier</th><th>Version</th><th>Size</th><th>Family</th><th>Total</th></tr></thead><tbody>${candidateRows || "<tr><td colspan=\"8\">No catalog candidates listed.</td></tr>"}</tbody></table>
      </section>`;
    }).join("");
    const ready = report.providers.filter((provider) => provider.status === "ready").length;
    const totalListed = report.providers.reduce((sum, provider) => sum + provider.modelsListed, 0);
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Model Catalog</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("model-catalog")}
    <main>
      <div class="topbar">
        <div>
          <a href="/providers">Providers</a>
          <h1>Model Catalog</h1>
          <p class="muted">Live explainability for auto model routing. Catalogs refresh from configured providers, then Agent Workflow scores tier fit, provider availability, policy, and override source.</p>
        </div>
        <div class="actions">
          <a class="button secondary" href="/api/model-catalog">JSON</a>
          <a class="button secondary" href="/model-catalog">Refresh</a>
        </div>
      </div>
      <section class="panel">
        <div class="meta-grid">
          <div><strong>Selected Provider</strong>${escapeHtml(report.selectedProvider)}</div>
          <div><strong>Model Policy</strong>${escapeHtml(report.modelPolicy)}</div>
          <div><strong>Ready Providers</strong>${formatNumber(ready)}</div>
          <div><strong>Models Listed</strong>${formatNumber(totalListed)}</div>
          <div><strong>Generated</strong>${renderDashboardDateTime(report.generatedAt)}</div>
        </div>
        <p class="muted">Use this page when auto routing surprises you. Env overrides win immediately; otherwise the catalog scorer chooses the best available model for fast, standard, and reasoning tiers.</p>
      </section>
      ${providerCards || "<section class=\"panel\"><p>No provider catalog data available. Refresh or open Providers for live readiness checks.</p></section>"}
    </main>
  </body>
  </html>`;
  }

  function renderModelImprovementFeedbackCaptureHtml(report: DashboardModelImprovementReport): string {
    const runOptions = report.feedbackTargets.map((target) => `
      <option value="${escapeHtml(target.runId)}">${escapeHtml(`${target.workflowId} ${target.status} ${target.runId.slice(0, 8)}`)}</option>
    `).join("");
    const rows = report.feedbackTargets.map((target) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(target.runId)}">${escapeHtml(target.runId.slice(0, 8))}</a><br><span class="muted">${renderDashboardDateTime(target.startedAt)}</span><div class="row-tools">${renderRunInfoDialog({
          runId: target.runId,
          workflowId: target.workflowId,
          status: target.status,
          task: target.task,
          startedAt: target.startedAt,
          summary: [
            target.summary ? `${target.summary.completedTasks}/${target.summary.totalTasks} stages complete, ${target.summary.failedTasks} failed` : "summary unavailable",
            target.summary?.recommendedNextAction ?? "next action unavailable",
            target.quality ? `quality ${target.quality.averageQuality ?? "n/a"}, ${target.quality.qualityPassCount} pass, ${target.quality.qualityFailCount} review` : "quality unavailable"
          ]
        })}</div></td>
        <td>${escapeHtml(target.workflowId)}<br><span class="status ${escapeHtml(target.status)}">${escapeHtml(target.status)}</span></td>
        <td>
          <strong>${escapeHtml(target.task)}</strong>
          ${target.summary ? `<br><span class="muted">${target.summary.completedTasks}/${target.summary.totalTasks} stages complete · ${target.summary.failedTasks} failed · ${escapeHtml(target.summary.recommendedNextAction)}</span>` : ""}
        </td>
        <td>${renderFeedbackTargetEvidenceHtml(target)}</td>
        <td>${escapeHtml(target.provider ?? "default")}<br><span class="muted">${escapeHtml(target.modelTier ?? "auto tier")}</span></td>
        <td>${renderFeedbackTargetActionForms(target)}</td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Feedback Capture</h2>
            <span class="muted">Turn recent run reviews into local model-improvement evidence.</span>
          </div>
          <span class="flag ${report.feedbackTargets.length ? "warn" : "good"}">${report.feedbackTargets.length ? `${report.feedbackTargets.length} need feedback` : "caught up"}</span>
        </div>
        <form class="inline-action-form" method="post" action="/api/follow-up">
          <input type="hidden" name="action" value="feedback">
          <label>Run
            <select name="runId">${runOptions || "<option value=\"\">No recent runs need feedback</option>"}</select>
          </label>
          <label>Rating
            <select name="rating">
              <option value="accepted">accepted</option>
              <option value="revised">revised</option>
              <option value="rejected">rejected</option>
            </select>
          </label>
          <label class="wide">Note
            <input name="note" placeholder="What should future runs learn?">
          </label>
          <button type="submit" ${report.feedbackTargets.length ? "" : "disabled"}>Record Feedback</button>
        </form>
        <p class="muted">A few good notes are enough to move tuning proposals from generic <code>feedback_needed</code> hints toward concrete routing, prompt, or context-budget recommendations. Use accepted for useful output, revised for mostly useful output that needed correction, and rejected for wrong or wasteful output.</p>
        <div class="table-wrap"><table><thead><tr><th>Run</th><th>Workflow</th><th>Summary</th><th>Evidence</th><th>Route</th><th>Feedback</th></tr></thead><tbody>${rows || "<tr><td colspan=\"6\">Recent finished runs already have feedback or no finished runs were found.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderModelImprovementHtml(
    report: DashboardModelImprovementReport | null,
    projects: DashboardProjectSummary[],
    params: URLSearchParams
  ): string {
    const selectedProject = report?.projectDir ?? params.get("project") ?? process.env.AGENTFLOW_DASHBOARD_PROJECT ?? "";
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}">${escapeHtml(project.name)} - ${escapeHtml(project.rootUri)}</option>`).join("");
    const jsonHref = report ? `/api/model-improvement?project=${encodeURIComponent(report.projectDir)}` : "";
    const body = report
      ? renderModelImprovementReportHtml(report)
      : `<section class="panel"><h2>No Project Selected</h2><p class="muted">Run onboarding or enter a project path to inspect local model-improvement evidence.</p></section>`;
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Model Improvement</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("model-improvement")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Model Improvement</h1>
          <p class="muted">Read-only local evidence for quality, cost, feedback, eval coverage, routing, and promotion readiness.</p>
        </div>
        ${jsonHref ? `<a class="button secondary" href="${escapeHtml(jsonHref)}">JSON</a>` : ""}
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <form method="get" class="workflow-form">
          <label class="wide">Project path
            <input name="project" value="${escapeHtml(selectedProject)}" list="model-improvement-projects" placeholder="/path/to/project">
            <datalist id="model-improvement-projects">${projectOptions}</datalist>
          </label>
          <label>Run limit
            <input name="limit" value="${escapeHtml(params.get("limit") ?? "50")}" inputmode="numeric">
          </label>
          <div class="form-actions"><button type="submit">Inspect</button></div>
        </form>
      </section>
      ${body}
    </main>
  </body>
  </html>`;
  }

  function renderModelImprovementReportHtml(report: DashboardModelImprovementReport): string {
    const proposalRows = Object.entries(report.proposalCounts).map(([kind, count]) => `
      <tr><td>${escapeHtml(kind)}</td><td>${formatNumber(count)}</td></tr>
    `).join("");
    const commandRows = report.nextCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const overlayKindRows = Object.entries(report.tuningOverlay.proposalKinds).map(([kind, count]) => `
      <tr><td>${escapeHtml(kind)}</td><td>${formatNumber(count)}</td></tr>
    `).join("");
    const overlayIds = report.tuningOverlay.selectedIds.length ? report.tuningOverlay.selectedIds.join(", ") : "none";
    return `
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Runs Analyzed", report.scorecard.runsAnalyzed, "recent project runs")}
          ${metricCard("Feedback", formatInlineCounts(report.scorecard.feedbackCounts) || "none", "accepted / revised / rejected")}
          ${metricCard("Eval Runs", report.evaluationRuns, report.latestEvaluationAt ? `latest ${new Date(report.latestEvaluationAt).toLocaleDateString()}` : "none found")}
          ${metricCard("High Priority", report.highPriorityProposals, "tuning proposals")}
          ${metricCard("Routing Proposals", report.routingProposals, "provider or tier changes")}
          ${metricCard("Promotion Ready", report.promotionReady ? "yes" : "not yet", "baseline evidence gate")}
        </div>
        <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)} for ${escapeHtml(report.projectDir)}.</p>
      </section>
      ${renderLocalProviderEvidenceHtml(report.localProviderEvidence)}
      ${renderLocalHoldoutRoutingStatusHtml(report.localHoldoutRouting)}
      ${renderLocalRouteDecisionDrilldownHtml(report.routeReceiptTrends, report.localHoldoutRouting)}
      ${renderLocalLlmSetupChecklistHtml(report.localLlmSetup)}
      ${renderLocalLlmSetupGuideHtml(report.localLlmSetupGuide)}
      ${renderLocalLlmDownloadRecommendationsHtml(report.localLlmDownloadRecommendations)}
      ${renderLocalLlmInstallationPlanHtml(report.localLlmInstallationPlan)}
      ${renderLocalLlmInventoryHtml(report.localLlmInventory)}
      ${renderLocalLlmPrunePlanHtml(report.localLlmPrunePlan)}
      ${renderLocalLlmCacheTrendHtml(report.localLlmCacheTrends)}
      ${renderLocalLlmCostLedgerHtml(report.localLlmCostLedger)}
      ${renderLocalLlmRoutingRecommendationHtml(report.localLlmRoutingRecommendations)}
      ${renderLocalLlmRoutingNoteApplicationHtml(report.localLlmRoutingNoteApplication)}
      ${renderLocalLlmRoutingDecisionTimelineHtml(report.localLlmRoutingDecisionTimeline)}
      ${renderLocalLlmRoutingDecisionSnapshotsHtml(report.localLlmRoutingDecisionSnapshots)}
      ${renderLocalLlmBenchmarkReceiptsHtml(report.localLlmBenchmarks)}
      ${renderRouteReceiptTrendsHtml(report.routeReceiptTrends)}
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Applied Tuning Overlay</h2>
            <span class="muted">Project-local tuning state written by Agent Workflow.</span>
          </div>
          <span class="flag ${report.tuningOverlay.exists ? "good" : report.tuningOverlay.error ? "bad" : "warn"}">${report.tuningOverlay.exists ? "written" : report.tuningOverlay.error ? "error" : "missing"}</span>
        </div>
        <div class="meta-grid compact">
          <div><strong>Overlay File</strong><code>${escapeHtml(report.tuningOverlay.path)}</code></div>
          <div><strong>Generated</strong>${renderDashboardDateTime(report.tuningOverlay.generatedAt)}</div>
          <div><strong>Source Runs</strong>${report.tuningOverlay.sourceRunsAnalyzed === null ? "n/a" : formatNumber(report.tuningOverlay.sourceRunsAnalyzed)}</div>
          <div><strong>Selected IDs</strong>${formatNumber(report.tuningOverlay.selectedIds.length)}</div>
          <div><strong>Applied Events</strong>${formatNumber(report.tuningOverlay.appliedEvents)}</div>
          <div><strong>Latest Applied</strong>${renderDashboardDateTime(report.tuningOverlay.latestAppliedAt)}</div>
        </div>
        <p class="muted">Applied here means the project-local overlay file exists and can be read by Agent Workflow. These current proposals are evidence-gathering recommendations unless the proposal kind is a routing, prompt, or context-budget change.</p>
        <p><code>${escapeHtml(overlayIds)}</code></p>
        ${report.tuningOverlay.error ? `<p class="error">${escapeHtml(report.tuningOverlay.error)}</p>` : ""}
        ${report.tuningOverlay.duplicateAppliedEvents > 0 ? `<p class="warning">${formatNumber(report.tuningOverlay.duplicateAppliedEvents)} duplicate applied-history event(s) were detected before compaction.</p>` : ""}
        <div class="table-wrap"><table><thead><tr><th>Overlay Proposal Kind</th><th>Count</th></tr></thead><tbody>${overlayKindRows || "<tr><td colspan=\"2\">No written overlay proposals.</td></tr>"}</tbody></table></div>
      </section>
      <section class="panel">
        <h2>Readiness</h2>
        <ul>${report.readiness.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
      </section>
      ${renderModelImprovementFeedbackCaptureHtml(report)}
      <section class="panel">
        <h2>Proposal Mix</h2>
        <div class="table-wrap"><table><thead><tr><th>Kind</th><th>Count</th></tr></thead><tbody>${proposalRows || "<tr><td colspan=\"2\">No proposals yet.</td></tr>"}</tbody></table></div>
      </section>
      <section class="panel">
        <h2>Preference Scorecard</h2>
        ${renderPreferenceScorecardHtml(report.scorecard)}
      </section>
      <section class="panel">
        <h2>Tuning Proposals</h2>
        ${renderTuningProposalsHtml(report.proposals, report.tuningOverlay)}
      </section>
      <section class="panel">
        <h2>Next Commands</h2>
        <ul>${commandRows}</ul>
      </section>
    `;
  }

  function renderNetworkLabel(node: { label: string; caption?: string; labelX?: number; labelY?: number; labelAnchor?: string }): string {
    if (node.labelX === undefined || node.labelY === undefined || !node.labelAnchor) return "";
    return `<text class="network-label" x="${formatSvgNumber(node.labelX)}" y="${formatSvgNumber(node.labelY)}" text-anchor="${node.labelAnchor}">${escapeHtml(truncateMiddle(node.caption ?? node.label, 24))}</text>`;
  }

  function renderNetworkOrientationActions(orientation: "horizontal" | "radial", horizontalHref: string, radialHref: string): string {
    return `<div class="network-toolbar"><div><strong>Network Orientation</strong><span>Horizontal is best for stage progression. Radial web is best for dependency shape.</span></div><div class="network-toolbar-actions"><div class="segmented-actions compact-segments" role="group" aria-label="Network orientation"><a class="segment ${orientation === "horizontal" ? "active" : ""}" href="${escapeHtml(horizontalHref)}"><strong>Horizontal</strong><span>Layered</span></a><a class="segment ${orientation === "radial" ? "active" : ""}" href="${escapeHtml(radialHref)}"><strong>Radial</strong><span>Web</span></a></div><button type="button" class="network-fullscreen-toggle secondary compact-button" aria-pressed="false">${dashboardIcon("maximize")}Full screen</button></div></div>`;
  }

  function renderNetworkStateExplainer(isRadial: boolean): string {
    const layoutText = isRadial
      ? "Read outward from the workflow core through stage, agent, and run rings."
      : "Read left to right from workflow input through stages, agents, and run outputs.";
    const items = [
      ["Layout", layoutText],
      ["Solid Lines", "Primary stage-to-agent and agent-to-run paths."],
      ["Dashed Lines", "Sequence or supporting subagent connections."],
      ["Health Rings", "Stage task outcomes: completed, failed, queued/running, and cancelled."],
      ["Click Targets", "Stage nodes focus history; run nodes open run details."]
    ];
    return `<div class="network-explainer">${items.map(([label, text]) => `
      <div><strong>${escapeHtml(label)}</strong><span>${escapeHtml(text)}</span></div>
    `).join("")}</div>`;
  }

  function renderObjectArtifactProofPanel(report: ObjectArtifactProofReport, params: URLSearchParams): string {
    const statusClass = report.status === "verified" || report.status === "metadata-only" ? "completed" : report.status === "missing" ? "failed" : "queued";
    const query = new URLSearchParams();
    if (report.projectRootUri) query.set("project", report.projectRootUri);
    query.set("limit", String(report.limit));
    const verifyQuery = new URLSearchParams(query);
    verifyQuery.set("verify", "1");
    const sampleRows = report.objects.slice(0, 12).map((object) => `<tr>
      <td><span class="status ${object.status === "present" ? "completed" : object.status === "missing" ? "failed" : "queued"}">${escapeHtml(object.status)}</span></td>
      <td><code>${escapeHtml(object.key)}</code><br><span class="muted">${escapeHtml(object.source)}</span></td>
      <td>${escapeHtml(object.artifactKind)}<br><code>${escapeHtml(object.artifactUri)}</code></td>
      <td>${escapeHtml(object.message)}</td>
    </tr>`).join("");
    const warnings = report.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    const recommendations = report.recommendations.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
    const bucket = report.bucketParity;
    const bucketStatusClass = bucket?.status === "verified" ? "completed" : bucket?.status === "missing" ? "failed" : "queued";
    const missingRows = bucket?.sampledMissingKeys.map((key) => `<li><code>${escapeHtml(key)}</code></li>`).join("") ?? "";
    const mirrorRows = bucket?.mirrorPlan.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("") ?? "";
    const queueMirrorForm = bucket?.status === "missing" && bucket.missingInTarget > 0 ? `
      <form method="post" action="/api/object-mirror-approval" class="inline-form compact-form">
        ${dashboardReturnInput("/server-readiness", params)}
        <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri ?? ctx.rootDir)}">
        <input type="hidden" name="objectLimit" value="${escapeHtml(String(report.limit))}">
        <input type="hidden" name="sourceEndpoint" value="${escapeHtml(bucket.sourceEndpoint)}">
        <input type="hidden" name="sourceBucket" value="${escapeHtml(bucket.sourceBucket)}">
        <input type="hidden" name="targetEndpoint" value="${escapeHtml(bucket.targetEndpoint)}">
        <input type="hidden" name="targetBucket" value="${escapeHtml(bucket.targetBucket)}">
        <label>Actor role<input name="actorRole" value="operator"></label>
        <button type="submit">Queue Mirror Approval</button>
      </form>` : "";
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>Object Artifact Proof</h2><span class="muted">Read-only proof for object-backed artifact references after storage merge.</span></div>
        <div class="actions"><a class="button secondary" href="/api/object-artifact-proof?${escapeHtml(query.toString())}">JSON</a><a class="button secondary" href="/api/object-artifact-proof?${escapeHtml(verifyQuery.toString())}">Verify JSON</a></div>
      </div>
      <div class="metric-grid">
        ${metricCard("Status", report.status, "object reference proof")}
        ${metricCard("Artifacts", report.inspectedArtifacts, "recent rows inspected")}
        ${metricCard("Object Refs", report.referencedObjects, "references discovered")}
        ${metricCard("Missing", report.missingObjects, "verified missing objects")}
        ${metricCard("Bucket Parity", bucket ? bucket.status : "not checked", bucket ? `${bucket.missingInTarget} missing` : "optional mc enumeration")}
      </div>
      <div class="meta-grid compact">
        <div><strong>Endpoint</strong>${escapeHtml(report.endpoint)}</div>
        <div><strong>Bucket</strong>${escapeHtml(report.bucket)}</div>
        <div><strong>Verification</strong><span class="status ${statusClass}">${escapeHtml(report.verification)}</span></div>
        <div><strong>Generated</strong>${renderDashboardDateTime(report.generatedAt)}</div>
      </div>
      <form method="get" action="/server-readiness" class="inline-form compact-form">
        ${[...params.entries()].filter(([key]) => key !== "objectLimit" && key !== "verifyObjects").map(([key, value]) => `<input type="hidden" name="${escapeHtml(key)}" value="${escapeHtml(value)}">`).join("")}
        <label>Object limit<input name="objectLimit" inputmode="numeric" value="${escapeHtml(String(report.limit))}"></label>
        <label class="check-row"><input type="checkbox" name="verifyObjects" value="1"> Verify with mc</label>
        <label class="check-row"><input type="checkbox" name="enumerateBuckets" value="1"> Enumerate buckets</label>
        <button type="submit">Refresh Object Proof</button>
      </form>
      ${bucket ? `<div class="meta-grid compact">
        <div><strong>Bucket Status</strong><span class="status ${bucketStatusClass}">${escapeHtml(bucket.status)}</span><br><span class="muted">${escapeHtml(bucket.message)}</span></div>
        <div><strong>Source Bucket</strong>${escapeHtml(bucket.sourceEndpoint)}<br>${escapeHtml(bucket.sourceBucket)} (${formatNumber(bucket.sourceObjects)} object(s))</div>
        <div><strong>Target Bucket</strong>${escapeHtml(bucket.targetEndpoint)}<br>${escapeHtml(bucket.targetBucket)} (${formatNumber(bucket.targetObjects)} object(s))</div>
        <div><strong>Delta</strong>${formatNumber(bucket.missingInTarget)} missing<br><span class="muted">${formatNumber(bucket.extraInTarget)} extra in target</span></div>
        <div><strong>Verifier</strong><span class="status ${bucket.verifier === "unavailable" ? "queued" : "completed"}">${escapeHtml(bucket.verifier)}</span></div>
      </div>
      ${missingRows ? `<details class="governance-details" open><summary>Sample Missing Keys</summary><ul>${missingRows}</ul></details>` : ""}
      <details class="governance-details"><summary>Dry-Run Mirror Plan</summary><ul>${mirrorRows}</ul></details>
      ${queueMirrorForm}` : ""}
      ${warnings ? `<details class="governance-details" open><summary>Warnings</summary><ul>${warnings}</ul></details>` : ""}
      ${recommendations ? `<details class="governance-details"><summary>Recommendations</summary><ul>${recommendations}</ul></details>` : ""}
      <div class="table-wrap"><table><thead><tr><th>Status</th><th>Object Key</th><th>Artifact</th><th>Detail</th></tr></thead><tbody>${sampleRows || '<tr><td colspan="4">No object-backed artifact references found in inspected rows.</td></tr>'}</tbody></table></div>
    </section>`;
  }

  function renderObservabilityHtml(report: ObservabilityReport): string {
    const spanCount = report.resourceSpans.flatMap((resource) => resource.scopeSpans.flatMap((scope) => scope.spans)).length;
    const metricCount = report.resourceMetrics.flatMap((resource) => resource.scopeMetrics.flatMap((scope) => scope.metrics)).length;
    return `
      <div class="metric-grid">
        ${metricCard("Run Duration", report.summary.runDurationMs === null ? "n/a" : `${report.summary.runDurationMs}ms`, "workflow wall time")}
        ${metricCard("Queue Delay", report.summary.queueDelayMs === null ? "n/a" : `${report.summary.queueDelayMs}ms`, "created to first stage")}
        ${metricCard("Model Latency", `${report.summary.totalModelLatencyMs}ms`, `avg ${report.summary.averageModelLatencyMs ?? "n/a"}ms`)}
        ${metricCard("Command Time", `${report.summary.commandExecutionMs}ms`, `${report.summary.fileWriteExecutionMs}ms governed writes`)}
        ${metricCard("Budget Breaches", report.summary.latencyBudgetBreaches, "task-class latency budgets")}
        ${metricCard("Spans", spanCount, `${metricCount} metrics`)}
      </div>
      <div class="meta-grid compact">
        <div><strong>Provider Calls</strong>${formatNumber(report.summary.providerCalls)}</div>
        <div><strong>Fallbacks</strong>${formatNumber(report.summary.fallbackCount)}</div>
        <div><strong>Compact Prompt</strong>${report.summary.estimatedCompactPromptTokens === null ? "n/a" : `${formatNumber(report.summary.estimatedCompactPromptTokens)} tokens`}</div>
        <div><strong>Payload Export</strong>disabled</div>
      </div>
    `;
  }

  function renderOfflineFallbackPanel(report: OfflineFallbackReport, params: URLSearchParams = new URLSearchParams()): string {
    const statusClass = report.mode === "shared-online" || report.mode === "local-fallback-ready" ? "completed" : report.mode === "offline-blocked" ? "failed" : "queued";
    const currentRows = report.currentServices.map((service) => `<tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>`).join("");
    const localRows = report.localServices.map((service) => `<tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>`).join("");
    const commandList = [
      `Stop local fallback: ${report.commands.stopLocal}`,
      `Start local fallback: ${report.commands.startLocal}`,
      ...report.commands.syncBack.map((command) => `Sync back: ${command}`)
    ].map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const notes = report.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("");
    const pendingItems = report.queue.items.filter((item) => item.status === "pending");
    const queueRows = pendingItems.map((item) => `<tr>
      <td>${escapeHtml(item.action)}<br><span class="muted">${renderDashboardDateTime(item.createdAt)}</span></td>
      <td>${item.projectRootUri ? `<code>${escapeHtml(item.projectRootUri)}</code>` : "all/local"}${item.runId ? `<br><span class="muted">run ${escapeHtml(item.runId)}</span>` : ""}</td>
      <td>${escapeHtml(item.note || "")}</td>
      <td><form method="post" action="/api/offline-fallback-action">${dashboardReturnInput("/server-readiness", params)}<input type="hidden" name="action" value="mark-synced"><input type="hidden" name="itemId" value="${escapeHtml(item.id)}"><button type="submit">Mark Synced</button></form></td>
    </tr>`).join("");
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>Offline Fallback</h2><span class="muted">Read-only health for shared storage and localhost fallback services.</span></div>
        <a class="button secondary" href="/api/offline-fallback">JSON</a>
      </div>
      <div class="metric-grid">
        ${metricCard("Mode", report.mode, "fallback posture")}
        ${metricCard("Shared", report.currentServicesReachable ? "online" : "offline", "current configured storage")}
        ${metricCard("Local Fallback", report.localServicesReachable ? "ready" : "stopped", "localhost Docker services")}
        ${metricCard("Sync Queue", pendingItems.length, "pending local fallback items")}
        ${metricCard("Scheduler", report.scheduler.status, `${report.scheduler.mode}; ${report.scheduler.nextRunAfter ? `next ${formatDashboardDateTimeText(report.scheduler.nextRunAfter)}` : "daemon check"}`)}
      </div>
      <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Current fallback status: <span class="status ${statusClass}">${escapeHtml(report.mode)}</span>.</p>
      <div class="meta-grid compact">
        <div><strong>Scheduler Status</strong>${escapeHtml(report.scheduler.status)}<br><span class="muted">${escapeHtml(report.scheduler.mode)} mode. ${escapeHtml(report.scheduler.message)}</span></div>
        <div><strong>Last Scheduler Run</strong>${report.scheduler.lastRunAt ? renderDashboardDateTime(report.scheduler.lastRunAt) : "none"}</div>
        <div><strong>Next Scheduler Run</strong>${report.scheduler.nextRunAfter ? renderDashboardDateTime(report.scheduler.nextRunAfter) : "n/a"}</div>
        <div><strong>Last Receipt</strong>${report.scheduler.lastResultPath ? `<code>${escapeHtml(report.scheduler.lastResultPath)}</code>` : "none"}</div>
      </div>
      <div class="split-grid">
        <form class="inline-form" method="post" action="/api/offline-fallback-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="action" value="start-local">
          <input name="note" value="Start localhost fallback services if shared host/shared storage is down." aria-label="Fallback note">
          <button type="submit">Record Local Fallback</button>
        </form>
        <form class="inline-form" method="post" action="/api/offline-fallback-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="action" value="sync-back">
          <input name="note" value="Merge local fallback rows back into shared storage when shared host returns." aria-label="Sync note">
          <button type="submit">Record Sync Needed</button>
        </form>
      </div>
      <div class="split-grid">
        <form class="inline-form" method="post" action="/api/offline-sync-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="out" value=".agent-workflow/migrations">
          <button type="submit">Prepare Sync Dry Run</button>
        </form>
        <form class="inline-form" method="post" action="/api/offline-sync-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="out" value=".agent-workflow/migrations">
          <label class="check-row"><input type="checkbox" name="execute" required> Execute insert-only sync into shared storage</label>
          <button type="submit">Execute Sync</button>
        </form>
      </div>
      <div class="split-grid">
        <div><h3>Configured Storage</h3><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${currentRows}</tbody></table></div></div>
        <div><h3>Local Fallback</h3><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${localRows}</tbody></table></div></div>
      </div>
      <h3>Offline Sync Queue</h3>
      <div class="table-wrap"><table><thead><tr><th>Action</th><th>Scope</th><th>Note</th><th></th></tr></thead><tbody>${queueRows || '<tr><td colspan="4">No pending offline fallback items.</td></tr>'}</tbody></table></div>
      <details class="governance-details"><summary>Operator Commands</summary><ul>${commandList}</ul></details>
      <ul>${notes}</ul>
    </section>`;
  }

  function renderOpsAgentFlow(queue: DashboardQueueItem[], historicalRuns: DashboardRunStatus[]): string {
    const flows = queue.filter((item) => item.runningAgentId || item.nextAgentId).slice(0, 5);
    if (!flows.length) return '<div class="ops-empty"><strong>No active handoffs</strong><span>Agent transitions appear here while workflows execute.</span></div>';
    return `<div class="ops-flow-list">${flows.map((item) => { const eta = estimateQueueItemEta(item, historicalRuns); return `<a href="/run?id=${encodeURIComponent(item.runId)}"><span class="ops-agent-node current">${escapeHtml(item.runningAgentId ?? "queued")}</span><span class="ops-flow-trace"><i></i>${dashboardIcon("chevrons")}</span><span class="ops-agent-node next">${escapeHtml(item.nextAgentId ?? "complete")}</span><small>${escapeHtml(compactDashboardText(item.task, 46))} · ETA ${escapeHtml(formatRunEta(eta))}</small></a>`; }).join("")}</div>`;
  }

  function renderOpsDurationChart(runs: DashboardRunStatus[]): string {
    const samples = [...runs].reverse().slice(-16).map((run) => dashboardRunDurationMs(run) ?? 0);
    if (!samples.length) return '<div class="ops-empty"><strong>No duration evidence</strong><span>Finished runs will populate this chart.</span></div>';
    const width = 720;
    const height = 170;
    const max = Math.max(...samples, 1);
    const points = samples.map((value, index) => `${30 + (index / Math.max(samples.length - 1, 1)) * (width - 50)},${height - 24 - (value / max) * (height - 52)}`).join(" ");
    const area = `30,${height - 24} ${points} ${width - 20},${height - 24}`;
    return `<div class="ops-line-chart"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Recent workflow run duration trend"><g class="ops-grid-lines"><path d="M30 20H${width - 20}"></path><path d="M30 ${height / 2}H${width - 20}"></path><path d="M30 ${height - 24}H${width - 20}"></path></g><polygon points="${area}"></polygon><polyline points="${points}"></polyline></svg><div class="ops-axis-labels"><span>${escapeHtml(formatDashboardDuration(max))}</span><span>${escapeHtml(formatDashboardDuration(Math.round(max / 2)))}</span><span>0s</span></div></div>`;
  }

  function renderOpsMetric(label: string, value: string, detail: string, samples: number[], tone: "cyan" | "teal" | "violet" | "amber"): string {
    return `<div class="ops-metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(detail)}</small>${renderOpsSparkline(samples, tone)}</div>`;
  }

  function renderOpsProjectActivity(projects: DashboardProjectSummary[]): string {
    const top = [...projects].sort((a, b) => b.runCount - a.runCount).slice(0, 6);
    const max = Math.max(...top.map((project) => project.runCount), 1);
    return `<div class="ops-project-bars">${top.map((project) => `<a href="/projects?project=${encodeURIComponent(project.rootUri)}"><span>${escapeHtml(compactDashboardText(project.name, 22))}</span><i><b style="width:${(project.runCount / max) * 100}%"></b></i><strong>${formatNumber(project.runCount)}</strong></a>`).join("") || '<div class="ops-empty">No project activity</div>'}</div>`;
  }

  function renderOpsPulseLine(): string {
    return `<svg viewBox="0 0 640 52" preserveAspectRatio="none"><path class="pulse-grid" d="M0 26H640"></path><path class="pulse-one" d="M0 26 C45 26 48 12 78 26 S118 44 148 22 S202 9 236 27 S282 42 314 20 S366 7 405 27 S464 39 500 22 S552 15 580 26 S614 26 640 26"></path><path class="pulse-two" d="M0 26 C70 26 78 35 104 24 S148 14 176 28 S224 38 252 24 S300 18 334 28 S382 35 412 23 S466 18 496 27 S548 33 574 25 S614 26 640 26"></path></svg>`;
  }

  function renderOpsQueuePressure(queue: DashboardQueueItem[]): string {
    const queued = queue.reduce((sum, item) => sum + item.queuedTasks, 0);
    const running = queue.reduce((sum, item) => sum + item.runningTasks, 0);
    const failed = queue.reduce((sum, item) => sum + item.failedTasks, 0);
    const active = queue.filter((item) => item.runStatus === "queued" || item.runStatus === "running" || item.runStatus === "leased");
    const oldestMs = active.length ? Math.max(...active.map((item) => Date.now() - Date.parse(item.oldestRunningAt ?? item.oldestQueuedAt ?? item.startedAt)).filter(Number.isFinite)) : 0;
    const total = Math.max(queued + running + failed, 1);
    return `<div class="ops-queue-summary"><div><span>Queue depth</span><strong>${queued + running}</strong><small>${running} running · ${queued} waiting</small></div><div><span>Oldest active</span><strong>${formatDashboardDuration(oldestMs)}</strong><small>${failed} failed stage${failed === 1 ? "" : "s"}</small></div></div><div class="ops-pressure-bar"><i class="running" style="width:${(running / total) * 100}%"></i><i class="queued" style="width:${(queued / total) * 100}%"></i><i class="failed" style="width:${(failed / total) * 100}%"></i></div><div class="ops-legend"><span><i class="running"></i>Running</span><span><i class="queued"></i>Queued</span><span><i class="failed"></i>Failed</span></div>`;
  }

  function renderOpsSparkline(values: number[], tone: "cyan" | "teal" | "violet" | "amber"): string {
    const samples = values.length > 1 ? values : [0, ...(values.length ? values : [0])];
    const max = Math.max(...samples, 1);
    const points = samples.map((value, index) => `${(index / Math.max(samples.length - 1, 1)) * 92 + 2},${28 - (value / max) * 22}`).join(" ");
    return `<svg class="ops-spark ${tone}" viewBox="0 0 96 32" aria-hidden="true"><polyline points="${points}"></polyline></svg>`;
  }

  function renderOpsStatusChart(runs: DashboardRunStatus[]): string {
    const completed = runs.filter((run) => run.status === "completed").length;
    const failed = runs.filter((run) => run.status === "failed").length;
    const active = Math.max(0, runs.length - completed - failed);
    const total = Math.max(runs.length, 1);
    const completedStop = Math.round((completed / total) * 100);
    const failedStop = completedStop + Math.round((failed / total) * 100);
    return `<div class="ops-donut-layout"><div class="ops-donut" style="--completed:${completedStop}%;--failed:${failedStop}%"><span><strong>${runs.length}</strong><small>runs</small></span></div><div class="ops-donut-key"><div><i class="completed"></i><span>Completed</span><strong>${completed}</strong></div><div><i class="failed"></i><span>Failed</span><strong>${failed}</strong></div><div><i class="active"></i><span>Active</span><strong>${active}</strong></div></div></div>`;
  }

  function renderOpsThroughputChart(buckets: WorkflowThroughputBucket[]): string {
    const max = Math.max(...buckets.map((bucket) => bucket.completed + bucket.failed + bucket.active), 1);
    const bars = buckets.map((bucket) => {
      const total = bucket.completed + bucket.failed + bucket.active;
      const label = new Date(`${bucket.key}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" });
      return `<div class="ops-throughput-column" title="${escapeHtml(label)}: ${total} run(s)"><div class="ops-stacked-bar" style="--bar-height:${Math.max(8, Math.round((total / max) * 100))}%"><i class="completed" style="--share:${total ? bucket.completed / total : 0}"></i><i class="failed" style="--share:${total ? bucket.failed / total : 0}"></i><i class="active" style="--share:${total ? bucket.active / total : 0}"></i></div><span>${escapeHtml(label)}</span></div>`;
    }).join("");
    return `<div class="ops-chart-frame"><div class="ops-y-labels"><span>${max}</span><span>${Math.ceil(max / 2)}</span><span>0</span></div><div class="ops-throughput-bars">${bars || '<div class="ops-empty">No run data</div>'}</div></div><div class="ops-legend"><span><i class="completed"></i>Completed</span><span><i class="failed"></i>Failed</span><span><i class="active"></i>Active</span></div>`;
  }

  function renderPostMergeEvidencePanel(evidence: StorageMergeEvidenceListing): string {
    const statusClass = evidence.safePrimaryStatePlane ? "completed" : "queued";
    const manifest = evidence.latestManifest;
    const importResult = evidence.latestImport;
    const backup = evidence.latestBackup;
    const objectProof = evidence.latestObjectProof;
    const projectDecisions = evidence.latestProjectDecisions;
    const projectMappingByRoot = new Map((manifest?.projectMappings ?? []).map((mapping) => [mapping.rootUri, mapping]));
    const backupFiles = backup?.files.map((file) => `<li><code>${escapeHtml(file.name)}</code> ${escapeHtml(formatBytes(file.sizeBytes))}</li>`).join("") ?? "";
    const warningRows = evidence.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    const proofRows = evidence.switchOverProof.checks.map((check) => `<tr><td>${escapeHtml(check.label)}</td><td><span class="status ${check.status === "pass" ? "completed" : check.status === "fail" ? "failed" : "queued"}">${escapeHtml(check.status)}</span></td><td>${escapeHtml(check.detail)}</td></tr>`).join("");
    const conflictRows = evidence.conflictClassification.rows.map((row) => {
      const decisionForms = row.class === "canonical-project-conflict" && row.conflictRows > 0
        ? row.sampleConflictKeys.slice(0, 5).map((rootUri) => {
            const mapping = projectMappingByRoot.get(rootUri);
            return `<form method="post" action="/api/storage-project-decision" class="inline-form compact-form">
              ${dashboardReturnInput("/server-readiness", new URLSearchParams())}
              <input type="hidden" name="rootUri" value="${escapeHtml(rootUri)}">
              <input type="hidden" name="sourceProjectId" value="${escapeHtml(mapping?.sourceProjectId ?? "")}">
              <input type="hidden" name="targetProjectId" value="${escapeHtml(mapping?.targetProjectId ?? "")}">
              <input type="hidden" name="action" value="preserve-target-project">
              <input type="hidden" name="out" value="${escapeHtml(evidence.directory)}">
              <input name="note" value="Reviewed source/target metadata; shared target is canonical." aria-label="Decision note for ${escapeHtml(rootUri)}">
              <button type="submit">Preserve Target</button>
            </form>`;
          }).join("")
        : "";
      return `<tr>
      <td>${escapeHtml(row.table)}<br><span class="muted">${escapeHtml(row.class)}</span></td>
      <td><span class="status ${row.severity === "critical" ? "failed" : row.severity === "warning" ? "queued" : "completed"}">${escapeHtml(row.severity)}</span></td>
      <td>${formatNumber(row.conflictRows)}</td>
      <td>${row.sampleConflictKeys.slice(0, 3).map((sample) => `<code>${escapeHtml(truncateText(sample, 92))}</code>`).join("<br>") || "<span class=\"muted\">No sampled conflict keys.</span>"}</td>
      <td>${escapeHtml(row.resolution)}${row.reviewedDecision ? `<br><span class="muted">${escapeHtml(row.reviewedDecision)}</span>` : ""}${decisionForms}</td>
    </tr>`;
    }).join("");
    const sampleRows = (manifest?.tables ?? [])
      .filter((table) => ["workflow_runs", "artifacts", "action_approvals", "action_receipts", "memory_items", "project_files", "project_index_state", "projects"].includes(table.table))
      .map((table) => {
        const samples = table.sampleConflictKeys.length
          ? table.sampleConflictKeys
          : table.sampleExistingKeys.length
            ? table.sampleExistingKeys
            : table.sampleSourceKeys;
        return `<tr>
          <td>${escapeHtml(table.table)}</td>
          <td>${formatNumber(table.sourceRows)}</td>
          <td>${formatNumber(table.insertRows)} / ${formatNumber(table.conflictRows)}</td>
          <td>${samples.slice(0, 3).map((sample) => `<code>${escapeHtml(truncateText(sample, 92))}</code>`).join("<br>") || "<span class=\"muted\">Regenerate the merge manifest to capture row samples.</span>"}</td>
        </tr>`;
      }).join("");
    const commandRows = evidence.switchOverProof.recommendedCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>Post-Merge Evidence</h2><span class="muted">Local operator proof for using shared storage as the primary state plane.</span></div>
        <a class="button secondary" href="/api/storage-merge-evidence?dir=${encodeURIComponent(evidence.directory)}">JSON</a>
      </div>
      <div class="metric-grid">
        ${metricCard("Primary State", evidence.safePrimaryStatePlane ? "proven" : "needs proof", evidence.safePrimaryStatePlane ? "shared storage is safe for normal use" : "review the missing evidence below")}
        ${metricCard("Source-Only Rows", manifest ? manifest.sourceOnlyRows : "unknown", "remaining rows from last manifest")}
        ${metricCard("Last Import", importResult ? importResult.status : "none", importResult ? `${importResult.mode}, ${formatNumber(importResult.affectedRows)} affected` : "no persisted import result")}
        ${metricCard("Backup", backup ? "present" : "missing", backup ? `${backup.files.length} file(s)` : "source and target backups not found")}
        ${metricCard("Object Proof", objectProof ? objectProof.status : "missing", objectProof ? `${objectProof.bucketParityStatus ?? "bucket not checked"}, ${formatNumber(objectProof.missingObjects)} missing refs` : "run object-artifact-proof --write")}
        ${metricCard("Project Decisions", projectDecisions ? projectDecisions.decisions.length : 0, projectDecisions ? `latest ${formatDashboardDateTimeText(projectDecisions.generatedAt)}` : "none recorded")}
      </div>
      <div class="table-wrap"><table><thead><tr><th>Switch-Over Check</th><th>Status</th><th>Detail</th></tr></thead><tbody>${proofRows}</tbody></table></div>
      <details class="governance-details" open><summary>Conflict Classification</summary>
        <div class="meta-grid compact">
          <div><strong>Critical</strong>${formatNumber(evidence.conflictClassification.criticalRows)}<br><span class="muted">must resolve before primary proof</span></div>
          <div><strong>Refreshable</strong>${formatNumber(evidence.conflictClassification.derivedRows)}<br><span class="muted">derived project index/cache rows</span></div>
          <div><strong>Reviewed</strong>${formatNumber(projectDecisions?.decisions.length ?? 0)}<br><span class="muted">local project decisions</span></div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Table</th><th>Severity</th><th>Rows</th><th>Samples</th><th>Resolution</th></tr></thead><tbody>${conflictRows || "<tr><td colspan=\"5\">No conflicts remain in the latest manifest.</td></tr>"}</tbody></table></div>
      </details>
      <details class="governance-details" open><summary>Sampled Historical Evidence</summary><div class="table-wrap"><table><thead><tr><th>Table</th><th>Source Rows</th><th>Insert / Conflict</th><th>Representative Keys</th></tr></thead><tbody>${sampleRows || "<tr><td colspan=\"4\">No manifest table samples found.</td></tr>"}</tbody></table></div></details>
      <div class="meta-grid compact">
        <div><strong>Manifest</strong>${manifest ? `${renderDashboardDateTime(manifest.generatedAt)}<br><code>${escapeHtml(manifest.jsonPath)}</code>` : "none"}</div>
        <div><strong>Conflicts</strong>${manifest ? `${formatNumber(manifest.conflictRows)}<br><span class="muted">${formatNumber(manifest.projectIdRewriteRows)} project-id rewrites, ${formatNumber(manifest.legacyReadabilityWarnings)} legacy warnings</span>` : "unknown"}</div>
        <div><strong>Import Result</strong>${importResult ? `${renderDashboardDateTime(importResult.generatedAt)}<br><code>${escapeHtml(importResult.jsonPath)}</code>` : "none"}</div>
        <div><strong>Backup Path</strong>${backup ? `${renderDashboardDateTime(backup.generatedAt)}<br><code>${escapeHtml(backup.path)}</code>` : "none"}</div>
        <div><strong>Object Proof</strong>${objectProof ? `${renderDashboardDateTime(objectProof.generatedAt)}<br><code>${escapeHtml(objectProof.jsonPath)}</code>` : "none"}</div>
        <div><strong>Project Decisions</strong>${projectDecisions ? `${renderDashboardDateTime(projectDecisions.generatedAt)}<br><code>${escapeHtml(projectDecisions.jsonPath)}</code>` : "none"}</div>
      </div>
      <details class="governance-details"><summary>Recommended Commands</summary><ul>${commandRows}</ul></details>
      ${backupFiles ? `<details class="governance-details"><summary>Backup Files</summary><ul>${backupFiles}</ul></details>` : ""}
      ${warningRows ? `<details class="governance-details" open><summary>Evidence Notes</summary><ul>${warningRows}</ul></details>` : ""}
      <p class="muted">Current state: <span class="status ${statusClass}">${evidence.safePrimaryStatePlane ? "ready" : "attention"}</span>.</p>
    </section>`;
  }

  function renderPrimaryStatePlaneOperatorPanel(
    mergeEvidence: StorageMergeEvidenceListing,
    offlineFallback: OfflineFallbackReport,
    runtimeMonitor: RuntimeMonitorReport
  ): string {
    const primaryReady = mergeEvidence.safePrimaryStatePlane && offlineFallback.currentServicesReachable;
    const statusClass = primaryReady ? "completed" : "queued";
    const sharedHost = runtimeMonitor.storageHost ?? runtimeMonitor.sharedHost.host ?? "not configured";
    const pendingOfflineItems = offlineFallback.queue.items.filter((item) => item.status === "pending").length;
    const warningChecks = mergeEvidence.switchOverProof.checks.filter((check) => check.status === "warn");
    const warningRows = warningChecks.map((check) => `<li><strong>${escapeHtml(check.label)}</strong>: ${escapeHtml(check.detail)}</li>`).join("");
    const commandRows = [
      "docker compose -f infra/docker-compose.yml stop postgres redis minio",
      "npm run doctor",
      "npm run storage-merge-evidence",
      "npm run offline-fallback"
    ].map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const summary = primaryReady
      ? "shared host/shared storage is the primary state plane. Local Docker storage should stay stopped unless shared storage is unavailable."
      : "Shared storage is not fully proven as the primary state plane yet; review the checks below before switching clients.";
    return `<section class="panel">
      <div class="section-heading">
        <div>
          <h2>Primary State Plane</h2>
          <span class="muted">Operator note for which storage plane Agent Workflow should use day to day.</span>
        </div>
        <span class="status ${statusClass}">${primaryReady ? "shared primary" : "needs review"}</span>
      </div>
      <div class="metric-grid">
        ${metricCard("Primary", primaryReady ? "shared host" : "not proven", summary)}
        ${metricCard("Shared Host", sharedHost, offlineFallback.currentServicesReachable ? "reachable" : "not reachable")}
        ${metricCard("Local Storage", offlineFallback.localServicesReachable ? "running" : "stopped", primaryReady ? "fallback-only while shared host is online" : "fallback may be needed")}
        ${metricCard("Offline Queue", pendingOfflineItems, "pending local fallback items")}
        ${metricCard("Proof", mergeEvidence.switchOverProof.status, `${mergeEvidence.conflictClassification.criticalRows} critical conflict row(s)`)}
        ${metricCard("Warnings", warningChecks.length, "visible audit/refresh items")}
      </div>
      <p>${escapeHtml(summary)}</p>
      ${warningRows ? `<details class="governance-details" open><summary>Visible Non-Blocking Warnings</summary><ul>${warningRows}</ul></details>` : '<p class="muted">No non-blocking switch-over warnings are currently reported.</p>'}
      <details class="governance-details"><summary>Operator Commands</summary><ul>${commandRows}</ul></details>
    </section>`;
  }

  function renderProjectDetailHtml(detail: DashboardProjectDetail, params: URLSearchParams = new URLSearchParams()): string {
    const project = detail.project;
    const contextRows = detail.contextFiles.map((file) => `
      <details class="artifact" ${file.exists ? "" : ""}>
        <summary>${escapeHtml(file.label)} <span class="muted">${escapeHtml(file.relativePath)} - ${file.exists ? "found" : "missing"}</span></summary>
        ${file.exists ? `<pre>${escapeHtml(file.preview)}</pre>` : "<p class=\"muted\">File not found in this project.</p>"}
      </details>
    `).join("");
    const runRows = detail.runs.map((run) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.id)}">${escapeHtml(run.id.slice(0, 8))}</a></td>
        <td><span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span></td>
        <td>${escapeHtml(run.workflowId)}</td>
        <td>${escapeHtml(run.task)}</td>
        <td>${renderDashboardDateTime(run.startedAt)}</td>
      </tr>
    `).join("");
    const fileRows = detail.files.map((file) => `
      <tr>
        <td>${escapeHtml(file.sourceUri)}</td>
        <td>${formatNumber(file.tokenEstimate)}</td>
        <td>${renderDashboardDateTime(file.updatedAt)}</td>
        <td>${escapeHtml(file.summary)}</td>
      </tr>
    `).join("");
    const memoryRows = detail.memory.map((item) => `
      <tr>
        <td>${escapeHtml(item.sourceUri)}</td>
        <td>${renderDashboardDateTime(item.updatedAt)}</td>
        <td>${escapeHtml(item.summary)}</td>
      </tr>
    `).join("");

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(project.name)} - Agent Workflow</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("projects")}
    <main>
      <div class="topbar">
        <div>
          <a href="/projects">Projects</a>
          <h1>${escapeHtml(project.name)}</h1>
          <p class="muted">${escapeHtml(project.rootUri)}</p>
        </div>
        <a class="button secondary" href="/api/preferences?project=${encodeURIComponent(project.rootUri)}">Preference JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <div class="meta-grid">
          <div><strong>Initialized</strong>${detail.initialized ? "yes" : "no"}</div>
          <div><strong>Profile</strong>${escapeHtml(project.profile)}</div>
          <div><strong>Write Policy</strong>${detail.allowWrites ? "configured" : "read-only or missing"}</div>
          <div><strong>Indexed Files</strong>${formatNumber(project.indexedFiles)}</div>
          <div><strong>Indexed Tokens</strong>${formatNumber(project.indexedTokens)}</div>
          <div><strong>Memory Items</strong>${formatNumber(project.memoryItems)}</div>
          <div><strong>Runs</strong>${formatNumber(project.runCount)}</div>
          <div><strong>Last Indexed</strong>${renderDashboardDateTime(project.lastIndexedAt, "not indexed")}</div>
        </div>
      </section>
      <section class="panel">
        <h2>Project Actions</h2>
        <div class="actions">
          ${projectIndexForm(project.rootUri, dashboardPagePath("/project", params))}
          ${projectActionForm(project.rootUri, "mira-ux-pass", "UX Pass")}
          ${projectActionForm(project.rootUri, "pr-review", "Review")}
          ${projectActionForm(project.rootUri, "production-readiness", "Production Readiness")}
          ${projectActionForm(project.rootUri, "maintain-context", "Maintain Context")}
        </div>
      </section>
      <section class="panel">
        <h2>Context Files</h2>
        ${contextRows}
      </section>
      <section class="panel">
        <h2>Recent Runs</h2>
        <table><thead><tr><th>Run</th><th>Status</th><th>Workflow</th><th>Task</th><th>Started</th></tr></thead><tbody>${runRows || "<tr><td colspan=\"5\">No runs.</td></tr>"}</tbody></table>
      </section>
      <section class="panel">
        <h2>Indexed Files</h2>
        <table><thead><tr><th>File</th><th>Tokens</th><th>Indexed</th><th>Summary</th></tr></thead><tbody>${fileRows || "<tr><td colspan=\"4\">No indexed files.</td></tr>"}</tbody></table>
      </section>
      <section class="panel">
        <h2>Memory</h2>
        <table><thead><tr><th>Source</th><th>Updated</th><th>Summary</th></tr></thead><tbody>${memoryRows || "<tr><td colspan=\"3\">No memory items.</td></tr>"}</tbody></table>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderProjectsHtml(projects: DashboardProjectSummary[], identities: DashboardProjectIdentityGroup[], aliasMergePlan: DashboardProjectAliasMergePlan): string {
    const identityRows = identities.map((identity) => `
      <tr>
        <td><a href="/project?root=${encodeURIComponent(identity.primaryRootUri)}">${escapeHtml(identity.canonicalName)}</a><br><span class="muted">${escapeHtml(identity.canonicalRootUri)}</span></td>
        <td><span class="status ${identity.localPathExists ? "completed" : "queued"}">${identity.localPathExists ? "local" : "remote only"}</span><br><span class="muted">${escapeHtml(identity.source)}</span></td>
        <td>${formatNumber(identity.projects.length)}<br><span class="muted">${identity.aliases.map((alias) => escapeHtml(alias.rootUri)).join("<br>")}</span></td>
        <td>${formatNumber(identity.totalRuns)}<br><span class="muted">${formatNumber(identity.activeRuns)} active / ${formatNumber(identity.failedRuns)} failed</span></td>
        <td>${formatNumber(identity.totalIndexedFiles)}</td>
        <td>${formatNumber(identity.totalMemoryItems)}</td>
        <td>${renderDashboardDateTime(identity.lastRunAt, "none")}</td>
      </tr>
    `).join("");
    const rows = projects.map((project) => `
      <tr>
        <td><a href="/project?root=${encodeURIComponent(project.rootUri)}">${escapeHtml(project.name)}</a><br><span class="muted">${escapeHtml(project.rootUri)}</span></td>
        <td>${escapeHtml(project.profile)}</td>
        <td>${formatNumber(project.indexedFiles)}<br><span class="muted">${formatNumber(project.indexedTokens)} tokens</span></td>
        <td>${formatNumber(project.memoryItems)}</td>
        <td>${formatNumber(project.runCount)}<br><span class="muted">${project.completedRuns} ok / ${project.failedRuns} failed / ${project.queuedRuns + project.runningRuns} active</span></td>
        <td>${project.lastRunId ? `<a href="/run?id=${encodeURIComponent(project.lastRunId)}">${escapeHtml(project.lastRunId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(project.lastWorkflowId ?? "unknown")} ${escapeHtml(project.lastRunStatus ?? "")}</span>` : "none"}</td>
        <td>${renderDashboardDateTime(project.lastIndexedAt, "not indexed")}</td>
      </tr>
    `).join("");
    const aliasMergeRows = aliasMergePlan.groups.slice(0, 12).map((group) => `
      <tr>
        <td><strong>${escapeHtml(group.target.name)}</strong><br><span class="muted">${escapeHtml(group.canonicalRootUri)}</span></td>
        <td><span class="flag ${group.risk === "high" ? "bad" : group.risk === "medium" ? "warn" : "good"}">${escapeHtml(group.risk)}</span></td>
        <td>${escapeHtml(group.target.rootUri)}<br><code>${escapeHtml(group.target.id)}</code></td>
        <td>${group.sources.map((source) => `${escapeHtml(source.rootUri)}<br><code>${escapeHtml(source.id)}</code>`).join("<br>")}</td>
        <td>${formatNumber(group.impactedRows.workflowRuns)} runs<br><span class="muted">${formatNumber(group.impactedRows.projectFiles)} files / ${formatNumber(group.impactedRows.memoryItems)} memory / ${formatNumber(group.impactedRows.activeRuns)} active</span></td>
        <td>${group.conflictWarnings.map((warning) => `<span class="muted">${escapeHtml(warning)}</span>`).join("<br>") || '<span class="muted">No conflicts predicted from summary data.</span>'}</td>
      </tr>
    `).join("");
    const aliasMergeSummary = aliasMergePlan.summary.map((item) => `<li>${escapeHtml(item)}</li>`).join("");

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Projects</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("projects")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Projects</h1>
        </div>
        <div class="button-row">
          <a class="button secondary" href="/api/project-alias-merge-plan">Alias Merge JSON</a>
          <a class="button secondary" href="/api/project-identities">Identity JSON</a>
          <a class="button secondary" href="/api/projects">Projects JSON</a>
        </div>
      </div>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Project Identities</h2>
            <span class="muted">Canonical local identity groups for shared storage paths, mounted paths, and host-specific aliases.</span>
          </div>
        </div>
        <div class="metric-grid">
          ${metricCard("Identities", identities.length, "logical projects")}
          ${metricCard("Registered Paths", projects.length, "stored project roots")}
          ${metricCard("Aliased", identities.filter((identity) => identity.projects.length > 1).length, "multi-path identities")}
          ${metricCard("Remote Only", identities.filter((identity) => !identity.localPathExists).length, "not mounted here")}
        </div>
        <table>
          <thead><tr><th>Identity</th><th>Local</th><th>Aliases</th><th>Runs</th><th>Indexed</th><th>Memory</th><th>Last Run</th></tr></thead>
          <tbody>${identityRows || "<tr><td colspan=\"7\">No project identities found.</td></tr>"}</tbody>
        </table>
      </section>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Alias Merge Plan</h2>
            <span class="muted">Dry-run consolidation plan for duplicate project rows created by host path aliases.</span>
          </div>
          <a class="button secondary" href="/api/project-alias-merge-plan">JSON</a>
        </div>
        <div class="metric-grid">
          ${metricCard("Candidates", aliasMergePlan.candidateCount, "identity groups")}
          ${metricCard("Source Rows", aliasMergePlan.sourceProjectCount, "would move into canonical targets")}
          ${metricCard("Dry Run", aliasMergePlan.dryRun ? "yes" : "no", "no database writes")}
          ${metricCard("High Risk", aliasMergePlan.groups.filter((group) => group.risk === "high").length, "must resolve before execution")}
        </div>
        <ul>${aliasMergeSummary}</ul>
        <div class="table-wrap"><table>
          <thead><tr><th>Identity</th><th>Risk</th><th>Target</th><th>Source Aliases</th><th>Impact</th><th>Warnings</th></tr></thead>
          <tbody>${aliasMergeRows || '<tr><td colspan="6">No alias merge candidates found.</td></tr>'}</tbody>
        </table></div>
        ${aliasMergePlan.groups.length > 12 ? `<p class="muted">${formatNumber(aliasMergePlan.groups.length - 12)} additional merge candidate(s) are available in JSON.</p>` : ""}
        <p class="muted">Execution remains intentionally separate: first create a backup, run storage verification, clear active source runs, and generate an auditable mapping receipt.</p>
      </section>
      <section class="panel">
        <h2>Registered Project Rows</h2>
        <table>
          <thead><tr><th>Project</th><th>Profile</th><th>Indexed</th><th>Memory</th><th>Runs</th><th>Last Run</th><th>Last Indexed</th></tr></thead>
          <tbody>${rows || "<tr><td colspan=\"7\">No projects found. Run onboarding or index a project first.</td></tr>"}</tbody>
        </table>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderProvidersHtml(info: DashboardInfo, params: URLSearchParams = new URLSearchParams()): string {
    const providerRows = [
      ["Selected", info.provider.selected],
      ["Adapter", info.provider.adapter],
      ["Model", info.provider.model ?? "not set"],
      ["Model env", info.provider.modelEnv ?? "not used"],
      ["Base URL", info.provider.baseUrl ?? "not used"],
      ["API key", typeof info.provider.apiKeyConfigured === "boolean" ? info.provider.apiKeyConfigured ? "configured" : "not configured" : "not used"],
      ["Authentication", info.provider.authStatus ?? "provider-specific"],
      ["AWS profile", info.provider.awsProfile ?? "not used"]
    ].map(([label, value]) => `<div><strong>${escapeHtml(label)}</strong>${escapeHtml(value)}</div>`).join("");
    const modelOptions = info.provider.availableModels.map((model) => {
      const selected = model === info.provider.model ? " selected" : "";
      return `<option value="${escapeHtml(model)}"${selected}>${escapeHtml(model)}</option>`;
    }).join("");
    const modelControl = info.provider.availableModels.length
      ? `<select name="model">${modelOptions}</select>`
      : `<input name="model" value="${escapeHtml(info.provider.model ?? "")}" placeholder="Model name">`;
    const modelSelector = info.provider.canSelectModel ? `
        <form class="inline-form" method="post" action="/api/model">
          ${dashboardReturnInput("/providers", params)}
          <input type="hidden" name="provider" value="${escapeHtml(info.provider.selected)}">
          ${modelControl}
          <button type="submit">Use Model</button>
        </form>
        <p class="muted">${info.provider.availableModels.length ? `${info.provider.availableModels.length} models listed from the active provider.` : "No models were listed; enter a model name manually."} Secrets are never displayed.</p>
        ${info.provider.availableModelsError ? `<p class="warn-box">${escapeHtml(info.provider.availableModelsError)}</p>` : ""}`
      : info.provider.selected === "auto"
        ? `<p class="muted">Auto mode selects provider/model by stage tier. Use routing controls to tune it.</p>`
        : `<p class="muted">This provider has no selectable live model list.</p>`;
    const providerIds = ["auto", "local", "byo", "bedrock", "gemini", "codex-cli", "openai", "anthropic", "muse", "openai-compatible", "kiro", "mock"];
    const executionProviderIds = ["auto", "local", "byo", "bedrock", "gemini", "codex-cli", "openai", "anthropic", "muse", "openai-compatible", "kiro", "mock"];
    const fallbackProviderIds = ["", "codex-cli", "openai", "anthropic", "gemini", "muse", "bedrock", "local", "byo", "openai-compatible", "kiro", "mock"];
    const modelPolicyIds = ["best-coding", "balanced", "lowest-cost", "maximum-reasoning"];
    const optionList = (values: string[], selectedValue: string, blankLabel = "none") => values.map((value) => {
      const selected = value === selectedValue ? " selected" : "";
      return `<option value="${escapeHtml(value)}"${selected}>${escapeHtml(value || blankLabel)}</option>`;
    }).join("");
    const autoRouteRows = info.provider.autoRoutes?.map((route) => `
      <tr><td>${escapeHtml(route.tier)}</td><td>${escapeHtml(route.providerId)}</td><td>${escapeHtml(route.estimatedCostTier)}</td><td>${escapeHtml(route.reason)}</td></tr>
    `).join("") ?? "";
    const providerStatusRows = info.provider.providerStatuses?.map((provider) => `
      <tr>
        <td>${escapeHtml(provider.label)}<br><span class="muted">${escapeHtml(provider.providerId)}</span></td>
        <td><span class="status ${provider.status === "ready" ? "completed" : provider.status === "missing" ? "failed" : "queued"}">${escapeHtml(provider.status)}</span></td>
        <td>${provider.configured ? "yes" : "no"}</td>
        <td>${escapeHtml(provider.model ?? "not set")}${provider.tierModels?.length ? `<br><span class="muted">${escapeHtml(formatTierModelPreview(provider.tierModels))}</span>` : ""}</td>
        <td>${escapeHtml(provider.baseUrl ?? "not used")}</td>
        <td>${escapeHtml(provider.apiKeyStatus ?? "not used")}</td>
        <td>${escapeHtml([provider.awsProfile ? `profile: ${provider.awsProfile}` : "", provider.awsRegion ? `region: ${provider.awsRegion}` : ""].filter(Boolean).join(", ") || "not used")}</td>
        <td>${escapeHtml(provider.details.join(" "))}</td>
      </tr>
    `).join("") ?? "";
    const providerStatuses = info.provider.providerStatuses ?? [];
    const providerStatusChecked = providerStatuses.length > 0;
    const readyProviders = providerStatuses.filter((provider) => provider.status === "ready");
    const configuredProviders = providerStatuses.filter((provider) => provider.configured);
    const missingProviders = providerStatuses.filter((provider) => provider.status === "missing");
    const awsStatus = providerStatuses.find((provider) => provider.providerId === "bedrock");
    const selectedStatus = providerStatuses.find((provider) => provider.providerId === info.provider.selected);
    const setupCards = [
      {
        title: "OpenAI",
        detail: "Best hosted path for high-quality development runs. Use OPENAI_MODEL=auto to refresh from the live catalog.",
        command: "OPENAI_API_KEY + OPENAI_MODEL=auto"
      },
      {
        title: "Muse",
        detail: "Meta's Muse Spark models through the Meta Model API. Create a key at dev.meta.ai.",
        command: "MUSE_API_KEY + MUSE_MODEL=auto"
      },
      {
        title: "Codex CLI / ChatGPT",
        detail: "Uses your authenticated Codex entitlement and becomes the primary path after the command succeeds.",
        command: "npm run agentflow -- provider-use codex-cli --login --check"
      },
      {
        title: "Local Runtime",
        detail: "Best opt-in path for Ollama, LM Studio, or llama.cpp-compatible localhost models.",
        command: "DEFAULT_MODEL_PROVIDER=local"
      },
      {
        title: "BYO Gateway",
        detail: "Best path for vLLM, LiteLLM, internal routers, or remote OpenAI-compatible gateways.",
        command: "BYO_MODEL_BASE_URL + BYO_MODEL_NAME"
      },
      {
        title: "AWS Bedrock",
        detail: "Best enterprise cloud option when AWS credentials are already available locally.",
        command: "AWS_PROFILE + AWS_REGION + BEDROCK_MODEL"
      },
      {
        title: "Auto",
        detail: "Routes by tier across ready providers, with fallback and quality threshold controls.",
        command: "DEFAULT_MODEL_PROVIDER=auto"
      }
    ].map((card) => `<div class="provider-setup-card"><strong>${escapeHtml(card.title)}</strong><span>${escapeHtml(card.detail)}</span><code>${escapeHtml(card.command)}</code></div>`).join("");
    const tierModelRows = info.provider.tierModels?.map((item) => `
      <tr><td>${escapeHtml(item.tier)}</td><td>${escapeHtml(item.model)}</td><td>${escapeHtml(item.source)}</td></tr>
    `).join("") ?? "";
    const codexSetup = info.provider.selected === "codex-cli" ? `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Codex CLI Authentication</h2>
            <span class="muted">${escapeHtml(info.provider.authStatus ?? "Run the readiness check to verify authentication.")}</span>
          </div>
          <span class="status ${selectedStatus?.status === "ready" ? "completed" : "failed"}">${escapeHtml(selectedStatus?.status ?? "unchecked")}</span>
        </div>
        <p>Authenticate with ChatGPT, save <code>codex-cli</code> as the primary provider, and verify it with one command:</p>
        <pre><code>npm run agentflow -- provider-use codex-cli --login --check</code></pre>
        <p class="muted">Headless node: add <code>--device-auth</code>. New processes use the saved provider immediately; restart an already-running dashboard, worker, or learning daemon after changing providers.</p>
      </section>` : "";

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Providers</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("providers")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Providers & Models</h1>
          <p class="muted">Choose how Agent Workflow spends tokens: hosted models, local/BYO gateways, AWS Bedrock, or automatic routing by task tier.</p>
        </div>
        <a class="button secondary" href="/api/settings">Settings JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel provider-hero">
        <div class="provider-current">
          <strong>${escapeHtml(info.provider.selected)}</strong>
          <span>${escapeHtml(info.provider.adapter)}${info.provider.model ? ` / ${escapeHtml(info.provider.model)}` : ""}</span>
          <small>${selectedStatus ? escapeHtml(selectedStatus.details.join(" ")) : "Selected provider is routed dynamically or not listed in the status table."}</small>
        </div>
        <div class="provider-readiness">
          <div><strong>${providerStatusChecked ? formatNumber(readyProviders.length) : "unchecked"}</strong><span>ready providers</span></div>
          <div><strong>${providerStatusChecked ? formatNumber(configuredProviders.length) : "unchecked"}</strong><span>configured</span></div>
          <div><strong>${providerStatusChecked ? formatNumber(missingProviders.length) : "unchecked"}</strong><span>need attention</span></div>
          <div><strong>${escapeHtml(awsStatus?.status ?? "unknown")}</strong><span>AWS Bedrock</span></div>
        </div>
      </section>
      ${codexSetup}
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Selected Provider</h2>
            <span class="muted">Secrets are never displayed. New tasks use saved provider values; already-running workers may need a restart.</span>
          </div>
          <div class="actions">
            <a class="button secondary" href="/model-catalog">Explain Catalog</a>
            <a class="button secondary" href="/settings">Runtime Settings</a>
          </div>
        </div>
        <div class="meta-grid">${providerRows}</div>
        ${modelSelector}
        ${info.provider.catalogHint ? `<p class="muted">${escapeHtml(info.provider.catalogHint)}</p>` : ""}
        ${tierModelRows ? `<h3>Tier Model Preview</h3><table><thead><tr><th>Tier</th><th>Model</th><th>Source</th></tr></thead><tbody>${tierModelRows}</tbody></table>` : ""}
      </section>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Setup Paths</h2>
            <span class="muted">Pick one path, then use Routing Controls to make it active or include it in auto mode.</span>
          </div>
        </div>
        <div class="provider-setup-grid">${setupCards}</div>
      </section>
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Routing Controls</h2>
            <span class="muted">Auto mode prioritizes the providers below, then uses tier-specific choices and fallback when quality drops.</span>
          </div>
        </div>
        <form class="routing-form" method="post" action="/api/routing">
          ${dashboardReturnInput("/providers", params)}
          <label>Provider mode
            <select name="provider">${optionList(providerIds, info.provider.routingConfig.provider)}</select>
          </label>
          <label>Auto priority
            <input name="autoProviders" value="${escapeHtml(info.provider.routingConfig.autoProviders)}" placeholder="byo,bedrock,gemini,openai">
          </label>
          <label>Fast tier
            <select name="fastProvider">${optionList(executionProviderIds, info.provider.routingConfig.fastProvider)}</select>
          </label>
          <label>Standard tier
            <select name="standardProvider">${optionList(executionProviderIds, info.provider.routingConfig.standardProvider)}</select>
          </label>
          <label>Reasoning tier
            <select name="reasoningProvider">${optionList(executionProviderIds, info.provider.routingConfig.reasoningProvider)}</select>
          </label>
          <label>Fallback provider
            <select name="fallbackProvider">${optionList(fallbackProviderIds, info.provider.routingConfig.fallbackProvider)}</select>
          </label>
          <label>Quality threshold
            <input name="qualityThreshold" value="${escapeHtml(info.provider.routingConfig.qualityThreshold)}" inputmode="decimal">
          </label>
          <label>Model policy
            <select name="modelPolicy">${optionList(modelPolicyIds, info.provider.routingConfig.modelPolicy)}</select>
          </label>
          <div class="form-actions"><button type="submit">Save Routing</button></div>
        </form>
        <p class="muted">Model policy affects catalog-backed auto model selection: best-coding favors code-specialized models, balanced favors capable mid-cost models, lowest-cost favors efficient models, and maximum-reasoning favors the strongest available models.</p>
      </section>
      ${autoRouteRows ? `<section class="panel"><h2>Auto Routing Preview</h2><table><thead><tr><th>Tier</th><th>Provider</th><th>Cost</th><th>Reason</th></tr></thead><tbody>${autoRouteRows}</tbody></table></section>` : ""}
      ${providerStatusRows ? `<section class="panel"><div class="section-heading"><div><h2>Available Provider Status</h2><span class="muted">Use this table to see which model paths have keys, local endpoints, CLI login, or AWS credentials available.</span></div></div><table><thead><tr><th>Provider</th><th>Status</th><th>Configured</th><th>Model</th><th>Base URL</th><th>API Key / Auth</th><th>AWS</th><th>Details</th></tr></thead><tbody>${providerStatusRows}</tbody></table><p class="muted">Secrets are never displayed.</p></section>` : ""}
    </main>
  </body>
  </html>`;
  }

  function renderQueueHtml(queue: DashboardQueueItem[], params: URLSearchParams, historicalRuns: DashboardRunStatus[]): string {
    const projectFilter = params.get("project")?.trim() || "";
    const active = queue.filter((item) => item.runStatus === "queued" || item.runStatus === "running");
    const recoveryActiveStatuses = new Set(["queued", "leased", "running"]);
    const recovering = queue.filter((item) =>
      (item.runStatus === "failed" || item.runStatus === "blocked")
      && Boolean(item.recoveryRunId)
      && recoveryActiveStatuses.has(item.recoveryRunStatus ?? "")
    );
    const recoveringRunIds = new Set(recovering.map((item) => item.runId));
    const failed = queue.filter((item) => item.runStatus === "failed" && !recoveringRunIds.has(item.runId));
    const expiredLeaseRows = queue.filter((item) => hasExpiredLease(item));
    const cards = queue.filter((item) => !recoveringRunIds.has(item.runId)).map((item) => {
      const presentation = dashboardRunPresentation(item);
      const eta = estimateQueueItemEta(item, historicalRuns);
      const taskSummary = `${item.completedTasks}/${item.totalTasks} done, ${item.queuedTasks} queued, ${item.runningTasks} worker-leased, ${item.failedTasks} failed`;
      const currentStage = item.runningStageId
        ? `${item.runningStageId} (${item.runningAgentId ?? "unknown"})`
        : item.nextStageId
          ? `${item.nextStageId} (${item.nextAgentId ?? "unknown"})`
          : "none";
      const leaseDetail = item.runningWorkerId
        ? `execution unconfirmed; worker lease: ${item.runningWorkerId}${item.runningLeaseExpiresAt ? `; expires ${renderDashboardDateTime(item.runningLeaseExpiresAt)}` : ""}`
        : item.runningTasks > 0
          ? "execution unconfirmed; worker lease owner unknown"
          : "worker: none";
      const activeLabel = item.runningStageId
        ? `Running ${item.runningStageId}`
        : item.nextStageId
          ? `Up next: ${item.nextStageId}`
          : item.runStatus === "failed"
            ? "Needs review"
            : item.runStatus === "blocked"
              ? "Blocked"
            : "Waiting to start";
      const activeAgent = item.runningAgentId ?? item.nextAgentId;
      const stageDots = Array.from({ length: Math.max(item.totalTasks, 1) }, (_, index) => {
        const step = index + 1;
        const state = index < item.completedTasks
          ? "completed"
          : item.failedTasks > 0 && index === item.completedTasks
            ? "failed"
            : item.runStatus === "blocked" && index === item.completedTasks
              ? "blocked"
            : item.runningTasks > 0 && index === item.completedTasks
              ? "running"
              : "pending";
        return `<span class="queue-stage-dot ${state}" title="Stage ${step}: ${state}"><span>${step}</span></span>`;
      }).join("");
      const attention = item.runStatus === "blocked"
        ? `<div class="queue-card-callout warn">${dashboardIcon("warning")}<span><strong>Blocked</strong><small>${escapeHtml(item.blockedReason ?? "This run needs a decision or resolved dependency before it can continue.")}</small></span></div>`
        : item.failedTasks > 0 || item.runStatus === "failed"
        ? `<div class="queue-card-callout bad">${dashboardIcon("warning")}<span><strong>Failed</strong><small>${escapeHtml(item.failedReason?.trim() || `${formatNumber(item.failedTasks || 1)} stage${(item.failedTasks || 1) === 1 ? "" : "s"} failed without a recorded reason.`)}</small></span></div>`
        : hasExpiredLease(item)
          ? `<div class="queue-card-callout warn">${dashboardIcon("warning")}<span><strong>Worker lease expired</strong><small>Recovery is available without losing completed stages.</small></span></div>`
          : "";
      return `
        <article class="queue-card queue-status-${escapeHtml(item.runStatus)}">
          <div class="queue-card-header">
            <div class="queue-card-title">
              <div class="queue-card-eyebrow"><span class="status ${escapeHtml(item.runStatus)}">${escapeHtml(item.runStatus)}</span><span>${escapeHtml(item.projectName)}</span><span>${escapeHtml(item.workflowId)}</span></div>
              <h2><a href="/run?id=${encodeURIComponent(item.runId)}">${escapeHtml(presentation.title)}</a></h2>
              <p>${escapeHtml(presentation.description)}</p>
              <p class="muted">Run ${escapeHtml(item.runId.slice(0, 8))} · started ${renderDashboardDateTime(item.startedAt)}</p>
            </div>
            <div class="actions"><a class="button secondary" href="/runs?runSet=${encodeURIComponent(item.runSetId)}">${iconLabel("layers", "Open set")}</a><a class="button secondary" href="/run?id=${encodeURIComponent(item.runId)}">${iconLabel("activity", "Open run")}</a></div>
          </div>
          ${attention}
          <div class="queue-stage-summary">
            <div class="queue-stage-heading"><span><strong>${formatNumber(item.completedTasks)} of ${formatNumber(item.totalTasks)} stages complete</strong><small>${escapeHtml(activeLabel)}${activeAgent ? ` · ${escapeHtml(activeAgent)}` : ""}</small></span><span class="queue-stage-count">${Math.round((item.completedTasks / Math.max(item.totalTasks, 1)) * 100)}%</span></div>
            <div class="queue-stage-rail" role="img" aria-label="${escapeHtml(`${item.completedTasks} of ${item.totalTasks} stages complete; ${activeLabel}`)}">${stageDots}</div>
          </div>
          <div class="queue-card-facts">
            <div><strong>Current work</strong><span>${escapeHtml(currentStage)}</span></div>
            <div><strong>ETA</strong><span title="${escapeHtml(eta.reason)}">${escapeHtml(formatRunEta(eta))}</span></div>
            <div><strong>Queue</strong><span>${formatNumber(item.runningTasks)} running · ${formatNumber(item.queuedTasks)} waiting</span></div>
            <div><strong>Worker</strong><span>${escapeHtml(item.runningWorkerId ?? "Not leased")}</span></div>
            <div><strong>Oldest active</strong><span>${renderDashboardDateTime(item.oldestRunningAt ?? item.oldestQueuedAt ?? item.startedAt)}</span></div>
            <div><strong>History</strong><span><a href="/runs?runSet=${encodeURIComponent(item.runSetId)}">${formatNumber(item.runSetSize)} related run${item.runSetSize === 1 ? "" : "s"}</a></span></div>
          </div>
          <div class="queue-card-footer">
            <div class="queue-primary-actions">${queueItemPrimaryForms(item)}</div>
            <details class="queue-more-actions"><summary>More actions</summary><div class="actions">${queueItemSecondaryForms(item)}${renderRunInfoDialog({
            runId: item.runId,
            workflowId: item.workflowId,
            status: item.runStatus,
            projectName: item.projectName,
            projectRootUri: item.projectRootUri,
            task: item.task,
            startedAt: item.startedAt,
            blockedReason: item.blockedReason,
            failedReason: item.failedReason,
            summary: [taskSummary, `current: ${currentStage}`, leaseDetail]
          })}</div></details>
          </div>
        </article>
      `;
    }).join("");

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Queue</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("queue")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Queue</h1>
          <span id="queue-watch-status" class="muted">Queue watcher starting…</span>
        </div>
        <a class="button secondary" href="/api/queue">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <div class="meta-grid">
          <div><strong>Active Runs</strong>${formatNumber(active.length)}</div>
          <div><strong>Recovering</strong>${formatNumber(recovering.length)}</div>
          <div><strong>Failed Runs</strong>${formatNumber(failed.length)}</div>
          <div><strong>Queued Tasks</strong>${formatNumber(queue.reduce((sum, item) => sum + item.queuedTasks, 0))}</div>
          <div><strong>Running Tasks</strong>${formatNumber(queue.reduce((sum, item) => sum + item.runningTasks, 0))}</div>
        </div>
        <div class="actions">
          ${queueProcessForm(projectFilter)}
          ${expiredLeaseRows.length ? queueRecoverExpiredLeasesForm() : ""}
        </div>
        <form class="workflow-form" method="get" action="/queue">
          <label class="wide">Project filter<input name="project" value="${escapeHtml(projectFilter)}" placeholder="/path/to/project or blank for all"></label>
          <div class="form-actions"><button type="submit">Filter Queue</button></div>
        </form>
      </section>
      ${failed.length ? `<section class="panel warn-panel">
        <h2>Clear Failed Queue Items</h2>
        <p class="muted">Dismissal removes failed runs from this queue without deleting their history, artifacts, or receipts.</p>
        ${queueDismissAllForm()}
      </section>` : ""}
      ${recovering.length ? `<section class="panel">
        <div class="section-heading"><div><h2>Recovery in Progress</h2><span class="muted">Source failures remain immutable history. Current work is counted once through the active recovery run.</span></div></div>
        <div class="table-wrap"><table>
          <thead><tr><th>Source run</th><th>Derived status</th><th>Current recovery</th><th>Project</th><th>Started</th></tr></thead>
          <tbody>${recovering.map((item) => `<tr>
            <td><a href="/run?id=${encodeURIComponent(item.runId)}">${escapeHtml(item.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(item.runStatus)} · ${escapeHtml(item.workflowId)}</span></td>
            <td><span class="status running">${item.runStatus === "blocked" ? "continuation running" : "recovery running"}</span></td>
            <td><a href="/run?id=${encodeURIComponent(item.recoveryRunId ?? "")}">${escapeHtml(item.recoveryRunId?.slice(0, 8) ?? "unknown")}</a><br><span class="muted">${escapeHtml(item.recoveryRunStatus ?? "unknown")} · ${escapeHtml(item.recoveryRelation ?? "recovery")}</span></td>
            <td>${escapeHtml(item.projectName)}</td>
            <td>${renderDashboardDateTime(item.recoveryStartedAt ?? item.startedAt)}</td>
          </tr>`).join("")}</tbody>
        </table></div>
      </section>` : ""}
      <section class="queue-section" aria-labelledby="queue-runs-heading">
        <div class="section-heading"><div><h2 id="queue-runs-heading">Work in the queue</h2><span class="muted">Follow progress, understand blockers, and act without losing run history.</span></div></div>
        <div class="queue-card-list">${cards || '<div class="panel human-empty"><strong>The queue is clear</strong><span>New and active work will appear here.</span></div>'}</div>
      </section>
    </main>
    <script>
      (() => {
        const status = document.getElementById("queue-watch-status");
        if (!("Worker" in window)) {
          status.textContent = "Live queue updates unavailable; refresh manually.";
          return;
        }
        const watcher = new Worker("/assets/queue-watcher.js");
        watcher.onmessage = (event) => {
          if (event.data.type === "error") {
            status.textContent = "Queue watcher reconnecting…";
            return;
          }
          status.textContent = event.data.active > 0
            ? "Watching " + event.data.active + " active run" + (event.data.active === 1 ? "" : "s") + " · updated " + new Date(event.data.checkedAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })
            : "Queue watcher idle · checked " + new Date(event.data.checkedAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" });
          if (event.data.changed) window.location.reload();
        };
        watcher.postMessage({ type: "start", signature: ${serializeInlineScriptJson(queueSnapshotSignature(queue))} });
        window.addEventListener("pagehide", () => watcher.postMessage({ type: "stop" }), { once: true });
      })();
    </script>
  </body>
  </html>`;
  }

  function renderReadinessGroup(id: string, title: string, summary: string, content: string): string { return `<details class="readiness-group" id="${escapeHtml(id)}"><summary><span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(summary)}</small></span><span class="readiness-group-action">View details</span></summary><div class="readiness-group-content">${content}</div></details>`; }

  function renderRecentGraphExportsHtml(exports: DashboardGraphExportSummary[], project: string): string {
    const projectDir = path.resolve(process.cwd(), project);
    const rows = exports.map((item) => `
      <tr>
        <td>${renderDashboardDateTime(item.generatedAt)}</td>
        <td><strong>${escapeHtml(item.workflowId)}</strong><br><span class="muted">${escapeHtml(item.workflowName)}</span></td>
        <td>${escapeHtml(item.focusedStageId ?? "all stages")}</td>
        <td>${formatNumber(item.runCount)}</td>
        <td>${formatNumber(item.stageHealthCount)}</td>
        <td><a class="button secondary" href="${escapeHtml(item.graphPath)}">Open Graph</a></td>
        <td>${item.markdownPath ? `<a href="${escapeHtml(graphHandoffViewerHref(item.projectPath, item.fileName))}">View</a><br><code>${escapeHtml(item.markdownPath)}</code>` : "<code>missing</code>"}</td>
        <td><code>${escapeHtml(item.jsonPath)}</code></td>
      </tr>
    `).join("") || '<tr><td colspan="8">No graph handoff exports yet. Use Export Handoff to save the current graph state beside project reports.</td></tr>';
    return `<section class="panel capture-hide">
      <div class="section-heading">
        <div>
          <h2>Recent Graph Handoffs</h2>
          <span class="muted">Project-local graph exports that can be reopened, shared, or attached to a review.</span>
        </div>
      </div>
      <div class="table-wrap"><table><thead><tr><th>Generated</th><th>Workflow</th><th>Stage</th><th>Runs</th><th>Health Rows</th><th>Graph</th><th>Markdown</th><th>JSON</th></tr></thead><tbody>${rows}</tbody></table></div>
      ${renderGraphExportLifecycleHtml(projectDir, exports.length)}
    </section>`;
  }

  function renderRecentRoleAuditExportsHtml(exports: DashboardRoleAuditExportSummary[], projectRootUri: string | null): string {
    const rows = exports.map((item) => `
      <tr>
        <td>${renderDashboardDateTime(item.generatedAt)}</td>
        <td>${escapeHtml(item.projectPath ?? projectRootUri ?? "all registered projects")}</td>
        <td>${escapeHtml(item.role ?? "all")} / ${escapeHtml(item.status)} / ${escapeHtml(item.actionType ?? "all")}</td>
        <td>${formatNumber(item.approvalCount)}</td>
        <td>${formatNumber(item.projectCount)}</td>
        <td>${item.markdownPath ? `<a href="${escapeHtml(roleAuditViewerHref(item.projectPath ?? projectRootUri, item.fileName))}">View</a><br><code>${escapeHtml(item.markdownPath)}</code>` : "<code>missing</code>"}</td>
        <td><code>${escapeHtml(item.jsonPath)}</code></td>
      </tr>
    `).join("") || '<tr><td colspan="7">No role audit snapshots yet. Use Export Snapshot to save the current filters locally.</td></tr>';
    return `<section class="panel">
      <div class="section-heading">
        <div>
          <h2>Recent Role Audit Snapshots</h2>
          <span class="muted">Local Markdown and JSON snapshots created from the active role filters.</span>
        </div>
      </div>
      <div class="table-wrap"><table><thead><tr><th>Generated</th><th>Project</th><th>Filters</th><th>Approvals</th><th>Projects</th><th>Markdown</th><th>JSON</th></tr></thead><tbody>${rows}</tbody></table></div>
    </section>`;
  }

  function renderRoadmapCaptureForm(report: RoadmapDashboardReport, params: URLSearchParams): string {
    const milestoneOptions = report.milestones.map((milestone) => `<option value="${milestone.number}">${milestone.number}. ${escapeHtml(milestone.title)}</option>`).join("");
    const priorityOptions = roadmapPriorityOrder().map((priority) => `<option value="${priority}"${priority === "medium" ? " selected" : ""}>${escapeHtml(titleCase(priority))}</option>`).join("");
    return `<section class="panel">
      <div class="section-heading"><div><h2>Record Task Or Bug</h2><span class="muted">Append a milestone-linked item to the roadmap register. This writes only <code>docs/roadmap.md</code>.</span></div></div>
      <form class="workflow-form" method="post" action="/api/roadmap-item">
        ${dashboardReturnInput("/roadmap", params)}
        <label>Type<select name="kind"><option value="task">Task</option><option value="bug">Bug</option></select></label>
        <label>Milestone<select name="milestone">${milestoneOptions}</select></label>
        <label>Priority<select name="priority">${priorityOptions}</select></label>
        <label class="wide">Title<input name="title" maxlength="180" placeholder="Add the smallest useful description"></label>
        <label class="wide">Note<input name="note" maxlength="240" placeholder="Optional context, evidence, or acceptance hint"></label>
        <div class="form-actions"><button type="submit">${iconLabel("plus", "Add To Roadmap")}</button></div>
      </form>
    </section>`;
  }

  function renderRoadmapDashboardHtml(report: RoadmapDashboardReport, params: URLSearchParams): string {
    const view = params.get("view") === "gantt" ? "gantt" : "list";
    const milestoneFilter = params.get("milestone") ?? "all";
    const statusFilter = params.get("status") ?? "open";
    const priorityFilter = params.get("priority") ?? "all";
    const visibleTasks = report.tasks.filter((task) => {
      const milestoneOk = milestoneFilter === "all" || String(task.milestoneNumber ?? "none") === milestoneFilter;
      const statusOk = statusFilter === "all" || task.status === statusFilter || (statusFilter === "open" && task.status === "next");
      const priorityOk = priorityFilter === "all" || task.priority === priorityFilter;
      return milestoneOk && statusOk && priorityOk;
    }).sort(compareRoadmapTasks);
    const milestoneOptions = [
      `<option value="all"${milestoneFilter === "all" ? " selected" : ""}>All milestones</option>`,
      `<option value="none"${milestoneFilter === "none" ? " selected" : ""}>Unlinked</option>`,
      ...report.milestones.map((milestone) => `<option value="${milestone.number}"${milestoneFilter === String(milestone.number) ? " selected" : ""}>${milestone.number}. ${escapeHtml(milestone.title)}</option>`)
    ].join("");
    const statusOptions = ["open", "next", "done", "all"].map((status) => `<option value="${status}"${statusFilter === status ? " selected" : ""}>${escapeHtml(titleCase(status))}</option>`).join("");
    const priorityOptions = [
      `<option value="all"${priorityFilter === "all" ? " selected" : ""}>All priorities</option>`,
      ...roadmapPriorityOrder().map((priority) => `<option value="${priority}"${priorityFilter === priority ? " selected" : ""}>${escapeHtml(titleCase(priority))}</option>`)
    ].join("");
    const viewParams = new URLSearchParams(params);
    viewParams.set("view", view === "gantt" ? "list" : "gantt");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Roadmap</title>
    <style>${dashboardCss()}${roadmapDashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("roadmap")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Roadmap</h1>
          <p class="muted">Live milestone, task, and bug view generated from <code>docs/roadmap.md</code>.</p>
        </div>
        <div class="actions">
          <a class="button secondary" href="/api/roadmap">JSON</a>
          <a class="button secondary" href="/roadmap?${escapeHtml(viewParams.toString())}">${view === "gantt" ? "List View" : "Gantt View"}</a>
        </div>
      </div>
      ${renderDashboardActionHistory()}
      <section class="panel">
        <form class="workflow-form" method="get" action="/roadmap">
          <input type="hidden" name="view" value="${escapeHtml(view)}">
          <label>Milestone<select name="milestone">${milestoneOptions}</select></label>
          <label>Status<select name="status">${statusOptions}</select></label>
          <label>Priority<select name="priority">${priorityOptions}</select></label>
          <div class="form-actions"><button type="submit">${iconLabel("search", "Filter")}</button><a class="button secondary" href="/roadmap?view=${escapeHtml(view)}">Reset</a></div>
        </form>
      </section>
      ${renderRoadmapCaptureForm(report, params)}
      <section class="panel">
        <div class="metric-grid">
          ${metricCard("Milestones", report.summary.milestoneCount, "goal lanes", "clipboard")}
          ${metricCard("Open", report.summary.openCount + report.summary.nextCount, "active tasks", "activity")}
          ${metricCard("Done", report.summary.doneCount, "completed items", "check")}
          ${metricCard("Bugs", report.summary.bugCount, "tracked defects", "warning")}
          ${metricCard("High Priority", report.summary.priorityCounts.critical + report.summary.priorityCounts.high, "critical/high", "warning")}
          ${metricCard("Unlinked", report.summary.unlinkedCount, "missing milestone", report.summary.unlinkedCount ? "warning" : "check")}
        </div>
        <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Tasks link to milestones by explicit <code>Milestone:</code> notes when present, otherwise by roadmap keyword inference.</p>
      </section>
      ${renderRoadmapIntegrityPanel(report)}
      ${renderRoadmapMcpRecoveryPanel(report, params)}
      ${renderRoadmapMilestoneIndex(report)}
      ${view === "gantt" ? renderRoadmapGantt(visibleTasks, report.milestones) : renderRoadmapTaskList(visibleTasks, params)}
    </main>
  </body>
  </html>`;
  }

  function renderRoadmapGantt(tasks: RoadmapTask[], milestones: RoadmapMilestone[]): string {
    const orderedMilestones = milestones.filter((milestone) => tasks.some((task) => task.milestoneNumber === milestone.number));
    const unlinkedTasks = tasks.filter((task) => !task.milestoneNumber);
    const rows = [
      ...orderedMilestones.map((milestone) => renderRoadmapGanttLane(`${milestone.number}. ${milestone.title}`, tasks.filter((task) => task.milestoneNumber === milestone.number), milestone.number)),
      ...(unlinkedTasks.length ? [renderRoadmapGanttLane("Unlinked", unlinkedTasks, 12)] : [])
    ].join("");
    return `<section class="panel"><h2>Gantt View</h2><p class="muted">Relative roadmap timeline by milestone. No calendar dates are invented; bar placement follows task order and status.</p><div class="roadmap-gantt"><div class="roadmap-gantt-head"><span>Milestone</span><span>Now</span><span>Next</span><span>Later</span><span>Future</span></div>${rows || "<p class=\"muted\">No matching roadmap tasks found.</p>"}</div></section>`;
  }

  function renderRoadmapGanttLane(label: string, tasks: RoadmapTask[], seed: number): string {
    const bars = tasks.map((task, index) => {
      const column = task.status === "done" ? 1 : task.status === "next" ? 2 : Math.min(4, 2 + ((index + seed) % 3));
      const width = Math.min(3, Math.max(1, 1 + Math.floor(task.details.length / 4)));
      return `<a class="roadmap-bar ${task.kind} ${task.status} priority-${task.priority}" style="grid-column:${column} / span ${width}" title="${escapeHtml(`${task.priority}: ${task.title}`)}" href="/roadmap?milestone=${encodeURIComponent(String(task.milestoneNumber ?? "none"))}&status=all"><small>${escapeHtml(task.priority)}</small><span>${escapeHtml(truncateMiddle(task.title, 72))}</span></a>`;
    }).join("");
    return `<div class="roadmap-gantt-row"><strong>${escapeHtml(label)}</strong><div class="roadmap-bars">${bars}</div></div>`;
  }

  function renderRoadmapIntegrityPanel(report: RoadmapDashboardReport): string {
    const unlinkedRows = report.tasks
      .filter((task) => task.milestoneSource === "missing")
      .slice(0, 12)
      .map((task) => `<li><code>docs/roadmap.md:${task.sourceLine}</code> ${escapeHtml(task.title)}</li>`)
      .join("");
    const inferredRows = report.tasks
      .filter((task) => task.milestoneSource === "inferred")
      .slice(0, 8)
      .map((task) => `<li><code>docs/roadmap.md:${task.sourceLine}</code> milestone ${escapeHtml(String(task.milestoneNumber ?? "none"))}: ${escapeHtml(task.title)}</li>`)
      .join("");
    const statusClass = report.summary.unlinkedCount ? "failed" : "completed";
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>Milestone Integrity</h2><span class="muted">Keeps roadmap tasks tied to the larger goal instead of drifting into loose notes.</span></div>
        <a class="button secondary" href="/roadmap?milestone=none&status=all">Unlinked</a>
      </div>
      <div class="metric-grid">
        ${metricCard("Explicit", report.summary.explicitMilestoneCount, "Milestone lines", "check")}
        ${metricCard("Inferred", report.summary.inferredMilestoneCount, "keyword fallback", "activity")}
        ${metricCard("Missing", report.summary.unlinkedCount, "needs link", report.summary.unlinkedCount ? "warning" : "check")}
      </div>
      <div class="callout ${statusClass}">
        <strong>${report.summary.unlinkedCount ? "Milestone links need attention" : "Milestone audit is clean"}</strong>
        <p>${report.summary.unlinkedCount ? "Add an explicit Milestone line to each unlinked checklist row before treating the roadmap as ready." : "Every checklist row is milestone-linked explicitly or by dashboard inference. New dashboard-created items require explicit milestone selection."}</p>
      </div>
      ${unlinkedRows ? `<h3>Unlinked Items</h3><ul>${unlinkedRows}</ul>` : ""}
      ${inferredRows ? `<details class="governance-details"><summary>Inferred Links To Review</summary><ul>${inferredRows}</ul></details>` : ""}
    </section>`;
  }

  function renderRoadmapMcpRecoveryPanel(report: RoadmapDashboardReport, params: URLSearchParams): string {
    const transportBug = report.bugs.find((bug) => bug.status !== "done" && /mcp transport closes|transport closed|stdio/iu.test(`${bug.title} ${bug.details.join(" ")}`));
    if (!transportBug) return "";
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>MCP Recovery</h2><span class="muted">High-priority ecosystem bug: Codex or another IDE can close its private stdio pipe while Agent Workflow services stay healthy.</span></div>
        <div class="actions"><a class="button secondary" href="/server-readiness">Runtime Monitor</a><a class="button secondary" href="/api/runtime-monitor?checkMcp=1">JSON</a></div>
      </div>
      <div class="metric-grid">
        ${metricCard("Roadmap Bug", transportBug.priority, `docs/roadmap.md:${transportBug.sourceLine}`, "warning")}
        ${metricCard("Milestone", transportBug.milestoneNumber ?? "none", transportBug.milestoneTitle ?? "unlinked", "route")}
        ${metricCard("Status", transportBug.status, "tracked recovery", "activity")}
      </div>
      <div class="callout queued">
        <strong>Recovery command</strong>
        <p><code>npm run runtime-monitor -- --check-mcp --write-mcp-recovery</code></p>
        <p class="muted">If launcher smoke passes but a specific Codex task still reports <code>Transport closed</code>, reload that task or the IDE client so it creates a fresh stdio subprocess.</p>
      </div>
      <form class="inline-form compact-form" method="post" action="/api/runtime-monitor-action">
        ${dashboardReturnInput("/roadmap", params)}
        <input type="hidden" name="action" value="write-mcp-recovery">
        <button type="submit">${iconLabel("shield", "Write Recovery Package")}</button>
        <a class="button secondary" href="/roadmap?milestone=12&status=all&priority=high">View Ecosystem Bug</a>
      </form>
    </section>`;
  }

  function renderRoadmapMilestoneIndex(report: RoadmapDashboardReport): string {
    const rows = report.milestones.map((milestone) => {
      const linked = report.tasks.filter((task) => task.milestoneNumber === milestone.number);
      const open = linked.filter((task) => task.status !== "done").length;
      return `<tr>
        <td><strong>${milestone.number}. ${escapeHtml(milestone.title)}</strong><br><span class="muted">${escapeHtml(milestone.status || "No status text recorded.")}</span></td>
        <td>${formatNumber(linked.length)}<br><span class="muted">${formatNumber(open)} open</span></td>
        <td>${milestone.workstreams.slice(0, 8).map((item) => `<span class="tag">${escapeHtml(item)}</span>`).join(" ")}</td>
        <td><a href="/roadmap?milestone=${milestone.number}&status=all">Open</a></td>
      </tr>`;
    }).join("");
    return `<section class="panel"><h2>Milestone Index</h2><div class="table-wrap"><table><thead><tr><th>Milestone</th><th>Tasks</th><th>Workstreams</th><th>View</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
  }

  function renderRoadmapPriorityControls(task: RoadmapTask, params: URLSearchParams): string {
    if (task.status === "next") return "";
    const options = roadmapPriorityOrder().map((priority) => `<option value="${priority}"${priority === task.priority ? " selected" : ""}>${escapeHtml(titleCase(priority))}</option>`).join("");
    return `<form class="inline-form compact-form" method="post" action="/api/roadmap-priority">
      ${dashboardReturnInput("/roadmap", params)}
      <input type="hidden" name="line" value="${escapeHtml(String(task.sourceLine))}">
      <select name="priority" aria-label="Priority for ${escapeHtml(task.title)}">${options}</select>
      <button class="secondary" type="submit">Set Priority</button>
    </form>`;
  }

  function renderRoadmapRowActions(task: RoadmapTask, params: URLSearchParams): string {
    if (task.status === "next") return renderRoadmapStatusControls(task, params);
    return `<div class="roadmap-row-actions">${renderRoadmapStatusControls(task, params)}${renderRoadmapPriorityControls(task, params)}</div>`;
  }

  function renderRoadmapStatusControls(task: RoadmapTask, params: URLSearchParams): string {
    if (task.status === "next") return "<span class=\"muted\">Derived next action</span>";
    const nextStatus = task.status === "done" ? "open" : "done";
    return `<form class="inline-form compact-form" method="post" action="/api/roadmap-status">
      ${dashboardReturnInput("/roadmap", params)}
      <input type="hidden" name="line" value="${escapeHtml(String(task.sourceLine))}">
      <input type="hidden" name="status" value="${escapeHtml(nextStatus)}">
      <button class="${nextStatus === "done" ? "" : "secondary"}" type="submit">${nextStatus === "done" ? "Mark Done" : "Reopen"}</button>
    </form>`;
  }

  function renderRoadmapTaskList(tasks: RoadmapTask[], params: URLSearchParams): string {
    const rows = tasks.map((task) => `
      <tr class="roadmap-${task.kind}">
        <td><span class="status ${task.status === "done" ? "completed" : task.status === "next" ? "running" : "queued"}">${escapeHtml(task.status)}</span><br><span class="priority priority-${escapeHtml(task.priority)}">${escapeHtml(task.priority)}</span><br><span class="muted">${escapeHtml(task.kind)}</span></td>
        <td>${task.milestoneNumber ? `<strong>${task.milestoneNumber}. ${escapeHtml(task.milestoneTitle ?? "Milestone")}</strong>` : "<span class=\"muted\">Unlinked</span>"}<br><span class="tag">${escapeHtml(task.milestoneSource)}</span><br><span class="muted">${escapeHtml(task.phase)}</span></td>
        <td><strong>${escapeHtml(task.title)}</strong>${task.details.length ? `<br><span class="muted">${escapeHtml(task.details.slice(0, 2).join(" "))}</span>` : ""}</td>
        <td><code>docs/roadmap.md:${task.sourceLine}</code></td>
        <td>${renderRoadmapRowActions(task, params)}</td>
      </tr>
    `).join("");
    return `<section class="panel"><h2>Task And Bug List</h2><div class="table-wrap"><table><thead><tr><th>Status</th><th>Milestone</th><th>Task</th><th>Source</th><th>Actions</th></tr></thead><tbody>${rows || "<tr><td colspan=\"5\">No matching roadmap tasks found.</td></tr>"}</tbody></table></div></section>`;
  }

  function renderRolesHtml(report: DashboardRoleGovernanceReport, projects: DashboardProjectSummary[], params: URLSearchParams): string {
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${report.projectRootUri === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const roleOptions = uniqueSorted([
      ...report.projects.flatMap((project) => project.roles.map((role) => role.id)),
      "pending",
      "unrecorded"
    ]).map((role) => `<option value="${escapeHtml(role)}"${report.filters.role === role ? " selected" : ""}>${escapeHtml(role)}</option>`).join("");
    const statusOptions = uniqueSorted(["all", "pending", "approved", "rejected", "executed", "failed", ...Object.keys(report.statusCounts)])
      .map((status) => `<option value="${escapeHtml(status)}"${report.filters.status === status ? " selected" : ""}>${escapeHtml(status)}</option>`)
      .join("");
    const actionOptions = uniqueSorted([
      "local_command",
      "file_write",
      "artifact_archive",
      "artifact_restore",
      "artifact_prune",
      "object_mirror",
      "deployment",
      "autonomy",
      ...Object.keys(report.actionCounts)
    ])
      .map((action) => `<option value="${escapeHtml(action)}"${report.filters.actionType === action ? " selected" : ""}>${escapeHtml(action)}</option>`)
      .join("");
    const roleRows = report.projects.flatMap((project) => project.roles.map((role) => `
      <tr>
        <td><strong>${escapeHtml(role.id)}</strong>${project.defaultActorRole === role.id ? ' <span class="flag good">default</span>' : ""}<br><span class="muted">${escapeHtml(role.description || "No description")}</span></td>
        <td>${escapeHtml(project.name)}<br><span class="muted">${escapeHtml(project.rootUri)}</span></td>
        <td><span class="flag ${project.enforcement === "enforce" ? "warn" : "good"}">${project.enforcement}</span><br><span class="muted">separation: ${project.separationOfDuties}<br>config: ${project.configStatus}</span></td>
        <td><div class="chip-row">${role.capabilities.map((capability) => `<span class="chip">${escapeHtml(capability)}</span>`).join("") || '<span class="muted">No capabilities configured.</span>'}</div></td>
      </tr>`)).join("");
    const decisionRows = report.decisionsByRole.map((role) => `
      <tr>
        <td><strong>${escapeHtml(role.role)}</strong></td>
        <td>${role.total}</td>
        <td>${role.pending}</td>
        <td>${role.approved}</td>
        <td>${role.rejected}</td>
        <td>${role.executed}</td>
        <td>${role.failed}</td>
      </tr>`).join("");
    const approvalRows = report.recentApprovals.map((approval) => `
      <tr>
        <td><span class="status ${escapeHtml(approval.status)}">${escapeHtml(approval.status)}</span></td>
        <td><strong>${escapeHtml(approval.actionType)}</strong><br><span class="muted">${escapeHtml(approval.target)}</span></td>
        <td>${escapeHtml(approval.decidedRole ?? (approval.status === "pending" ? "pending" : "unrecorded"))}<br><span class="muted">${escapeHtml(approval.decidedBy ?? "not decided")}</span></td>
        <td>${escapeHtml(approval.executedRole ?? "not executed")}<br><span class="muted">${escapeHtml(approval.executedBy ?? "not executed")}</span></td>
        <td>${escapeHtml(approval.projectName)}<br><span class="muted">${escapeHtml(approval.workflowId)} / ${escapeHtml(approval.stageId)}</span></td>
        <td>${renderDashboardDateTime(approval.updatedAt)}</td>
      </tr>`).join("");
    const filters = `<form method="get" class="form-grid">
      <label>Project<select name="project"><option value="">all registered projects</option>${projectOptions}</select></label>
      <label>Role<select name="role"><option value="">all roles</option>${roleOptions}</select></label>
      <label>Status<select name="status">${statusOptions}</select></label>
      <label>Action<select name="action"><option value="">all actions</option>${actionOptions}</select></label>
      <label>Recent approvals<input name="limit" inputmode="numeric" value="${escapeHtml(String(report.limit))}"></label>
      <div class="form-actions"><button type="submit">Filter</button></div>
    </form>`;
    const exportForm = `<form method="post" action="/api/role-audit-export" class="inline-form">
      ${dashboardReturnInput("/roles", params)}
      <input type="hidden" name="project" value="${escapeHtml(report.projectRootUri ?? "")}">
      <input type="hidden" name="role" value="${escapeHtml(report.filters.role ?? "")}">
      <input type="hidden" name="status" value="${escapeHtml(report.filters.status)}">
      <input type="hidden" name="action" value="${escapeHtml(report.filters.actionType ?? "")}">
      <input type="hidden" name="limit" value="${escapeHtml(String(report.limit))}">
      <button type="submit">Export Snapshot</button>
    </form>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Roles</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("roles")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Roles & Decisions</h1><p class="muted">Read-only team role configuration and recent approval decisions by recorded actor role.</p></div><div class="actions"><a class="button secondary" href="/api/roles?${escapeHtml(params.toString())}">JSON</a>${exportForm}</div></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <section class="panel">${filters}<div class="meta-grid"><div><strong>Projects</strong>${report.projects.length}</div><div><strong>Recent approvals</strong>${report.recentApprovals.length}</div><div><strong>Recorded roles</strong>${report.decisionsByRole.length}</div><div><strong>Pending approvals</strong>${report.statusCounts.pending ?? 0}</div></div></section>
    ${renderRecentRoleAuditExportsHtml(report.recentRoleAuditExports, report.projectRootUri)}
    <section class="panel"><div class="section-heading"><div><h2>Configured Roles</h2><span class="muted">Project-local roles from .agent-workflow/project.yaml, falling back to stored config when the path is unavailable.</span></div></div><div class="table-wrap"><table><thead><tr><th>Role</th><th>Project</th><th>Mode</th><th>Capabilities</th></tr></thead><tbody>${roleRows || '<tr><td colspan="4">No project roles found.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><div class="section-heading"><div><h2>Recent Decisions By Role</h2><span class="muted">Pending and older unrecorded decisions are separated so migration gaps stay visible.</span></div></div><div class="table-wrap"><table><thead><tr><th>Role</th><th>Total</th><th>Pending</th><th>Approved</th><th>Rejected</th><th>Executed</th><th>Failed</th></tr></thead><tbody>${decisionRows || '<tr><td colspan="7">No recent approvals found.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><div class="section-heading"><div><h2>Recent Approval Activity</h2><span class="muted">Latest approval rows used by the role summary.</span></div></div><div class="table-wrap"><table><thead><tr><th>Status</th><th>Action</th><th>Decision Role</th><th>Execution Role</th><th>Project</th><th>Updated</th></tr></thead><tbody>${approvalRows || '<tr><td colspan="6">No recent approval activity found.</td></tr>'}</tbody></table></div></section></main></body></html>`;
  }

  function renderRouteReceiptTrendsHtml(report: DashboardRouteReceiptTrendReport): string {
    const rows = report.topGroups.map((group) => `
      <tr>
        <td>${escapeHtml(group.workflowId)}<br><span class="muted">${escapeHtml(group.stageId)} / ${escapeHtml(group.agentId)}</span></td>
        <td><span class="flag ${group.classification === "local-selected" ? "good" : group.classification === "local-skipped" || group.classification === "hosted-fallback" ? "warn" : "queued"}">${escapeHtml(group.classification.replace(/-/g, " "))}</span></td>
        <td>${escapeHtml(group.providerId)} / ${escapeHtml(group.modelTier)}</td>
        <td>${formatNumber(group.runs)}</td>
        <td>${formatNumber(group.fallbackCount)}</td>
        <td>${group.averageQuality ?? "n/a"}</td>
        <td>${group.averageLatencyMs === null ? "n/a" : `${formatNumber(group.averageLatencyMs)}ms`}</td>
        <td>${escapeHtml(truncateText(group.latestReason || "no route reason recorded", 180))}</td>
      </tr>
    `).join("");
    return `
      <section class="panel">
        <div class="section-heading">
          <div>
            <h2>Route Receipt Trends</h2>
            <span class="muted">Recent model_route receipts grouped by local selection, skipped local preference, and fallback behavior.</span>
          </div>
          <span class="flag ${report.totalReceipts ? "good" : "warn"}">${formatNumber(report.totalReceipts)} receipts</span>
        </div>
        <div class="metric-grid">
          ${metricCard("Reports", report.reportsAnalyzed, "recent runs with quality data")}
          ${metricCard("Local Selected", report.localSelected, "approved local holdout route")}
          ${metricCard("Local Skipped", report.localSkipped, "local preference present but unavailable")}
          ${metricCard("Hosted Fallback", report.hostedFallback, "provider retry receipts")}
          ${metricCard("Hosted Selected", report.hostedSelected, "normal hosted or default route")}
          ${metricCard("Selection Rate", report.localSelectionRate === null ? "n/a" : report.localSelectionRate, "local-selected / all receipts")}
          ${metricCard("Fallback Rate", report.fallbackRate === null ? "n/a" : report.fallbackRate, "fallbacks / all receipts")}
        </div>
        <div class="table-wrap"><table><thead><tr><th>Workflow</th><th>Class</th><th>Provider/Tier</th><th>Runs</th><th>Fallbacks</th><th>Quality</th><th>Latency</th><th>Latest Reason</th></tr></thead><tbody>${rows || "<tr><td colspan=\"8\">No route receipts found in the inspected run window.</td></tr>"}</tbody></table></div>
      </section>
    `;
  }

  function renderRunApprovalLevelControl(
    run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>,
    ceiling: string
  ): string {
    const currentRank = runApprovalLevelRank(run.autonomy);
    const ceilingRank = runApprovalLevelRank(ceiling);
    const immutableActive = run.status === "leased" || run.status === "running";
    const superseded = Boolean(run.replacementRunId) || Boolean(run.superseded);
    const options = RUN_APPROVAL_LEVELS.filter((level) => runApprovalLevelRank(level) <= ceilingRank).map((level) =>
      `<option value="${escapeHtml(level)}"${level === run.autonomy ? " selected" : ""}>Level ${escapeHtml(level)} · ${escapeHtml(runApprovalLevelLabel(level))}</option>`
    ).join("");
    const behavior = run.status === "queued"
      ? "This updates the queued run before any worker claims it."
      : immutableActive
        ? "A worker already owns this policy snapshot, so its authority cannot change mid-stage."
        : "Changing this immutable run creates a checkpoint continuation with the selected level.";
    return `<section class="run-approval-level" aria-labelledby="run-approval-level-title">
      <div>
        <p class="eyebrow">Approval level</p>
        <h3 id="run-approval-level-title">Level ${escapeHtml(run.autonomy)} · ${escapeHtml(runApprovalLevelLabel(run.autonomy))}</h3>
        <p>${escapeHtml(behavior)} Project/profile ceiling: <strong>Level ${escapeHtml(ceiling)}</strong>. Higher levels permit more autonomous action; project policy and explicit high-risk gates still apply.</p>
      </div>
      ${superseded ? `<a class="button" href="/run?id=${encodeURIComponent(run.replacementRunId!)}">Change current continuation →</a>` : immutableActive ? `<span class="status running">Locked while ${escapeHtml(run.status)}</span>` : `<form class="run-approval-level-form" method="post" action="/api/run-approval-level">
        <input type="hidden" name="runId" value="${escapeHtml(run.id)}">
        <input type="hidden" name="returnTo" value="/run?id=${encodeURIComponent(run.id)}">
        <label><span>New level</span><select name="level" aria-label="Run approval level">${options}</select></label>
        <label><span>Reason</span><input name="reason" required maxlength="500" value="Operator changed the run approval level from ${escapeHtml(run.autonomy)}." aria-label="Reason for approval level change"></label>
        <button type="submit"${currentRank > ceilingRank ? " disabled" : ""}>Apply level</button>
      </form>`}
    </section>`;
  }

  function renderRunBlockerGuide(
    run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>,
    tasks: Awaited<ReturnType<typeof getWorkflowRunDetails>>["tasks"]
  ): string {
    const blockedStages = tasks.filter((task) => task.status === "blocked" || task.status === "failed").map((task) => task.stageId);
    return `<div class="run-blocker-guide">
      <div>
        <p class="eyebrow">Not sure what to choose?</p>
        <h3>How to move this run forward</h3>
        <ul>
          <li><strong>Retry After Fix</strong> when you have already corrected the issue or supplied the missing input.</li>
          <li><strong>Diagnose as New Run</strong> when you want Agent Workflow to investigate and attempt a governed repair.</li>
          <li><strong>Skip blocked stage</strong> when this stage is optional and you accept that its checks or output will be missing.</li>
        </ul>
      </div>
      <form class="run-skip-blocker-form" method="post" action="/api/queue-action">
        <input type="hidden" name="runId" value="${escapeHtml(run.id)}">
        <input type="hidden" name="action" value="skip-blocker">
        <label>Why is it safe to skip ${escapeHtml(blockedStages.join(", ") || "this stage")}?<input name="reason" required placeholder="Example: optional verification is unavailable; I accept the risk"></label>
        <label class="check-row"><input type="checkbox" name="confirmed" required> I understand this stage’s evidence or output will be missing.</label>
        <button class="warning" type="submit">Skip blocked stage &amp; continue →</button>
      </form>
    </div>`;
  }

  function renderRunCommandCenterBody(
    run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>,
    tasks: Awaited<ReturnType<typeof getWorkflowRunDetails>>["tasks"],
    approvals: Awaited<ReturnType<typeof listActionApprovals>>
  ): string {
    const openApprovals = approvals.filter((approval) => isOpenApproval(approval) && (approval.status !== "failed" || run.status === "blocked" || run.status === "failed"));
    const completed = tasks.filter((task) => task.status === "completed" && !task.skipped).length;
    const skipped = tasks.filter((task) => task.skipped).length;
    const failed = tasks.filter((task) => task.status === "failed" || task.status === "blocked").length;
    const active = tasks.filter((task) => task.status === "queued" || task.status === "leased" || task.status === "running").length;
    const blocked = run.status === "blocked";
    const failedRun = run.status === "failed";
    const failureResolution = failedRunResolution(run.failedReason);
    const superseded = Boolean(run.replacementRunId) || Boolean(run.superseded);
    const attention = !superseded && (openApprovals.length > 0 || blocked || failedRun);
    const headline = superseded
      ? "This run is read-only history"
      : openApprovals.length
      ? `${openApprovals.length} approval${openApprovals.length === 1 ? "" : "s"} need attention`
      : blocked
        ? "Workflow is blocked"
        : failedRun
          ? failureResolution.headline
          : run.status === "completed"
            ? skipped > 0 ? "Workflow completed with exceptions" : "Workflow completed"
            : "Workflow is progressing";
    const guidance = superseded
      ? `Do not act on blockers here. Work continued in replacement run ${escapeHtml(run.replacementRunId?.slice(0, 8) ?? "")}.`
      : openApprovals.length
      ? "Review each requested side effect below. Approve and run, approve only, reject, or create an exact recurring rule. The workflow resumes automatically after its final required action is resolved."
      : blocked
        ? escapeHtml(run.blockedReason?.trim() || "No open approval remains. Resolve the blocker, resume from a checkpoint, or start a focused diagnosis.")
        : failedRun
          ? escapeHtml(`${run.failedReason?.trim() || "No specific failure reason was recorded."} ${failureResolution.summary}`)
          : run.status === "completed"
            ? skipped > 0
              ? `${skipped} stage${skipped === 1 ? " was" : "s were"} explicitly skipped. Review the missing evidence before treating this run as a fully verified delivery.`
              : "Review the outcome, summarize it, or replay the run with current project state."
            : "No operator decision is required right now. Keep this page open to watch progress, or run the worker until completion.";
    const runPath = `/run?id=${encodeURIComponent(run.id)}`;
    const primaryActions = superseded
      ? `<a class="button" href="/run?id=${encodeURIComponent(run.replacementRunId ?? run.id)}">Open current continuation →</a>`
      : blocked
      ? `${queueRunActionForm(run.id, "resolve-blocker", "Retry After Fix")}${queueRunActionForm(run.id, "repair-blocked", "Diagnose as New Run")}${queueRunActionForm(run.id, "resume-checkpoint", "Resume Checkpoint")}${queueRunActionForm(run.id, "replay-run", "Replay Run")}`
      : failedRun
        ? `${queueRunActionForm(run.id, "retry-failed", "Retry Failed Stages")}${queueRunActionForm(run.id, "repair-blocked", "Diagnose as New Run")}${queueRunActionForm(run.id, "replay-run", "Replay Run")}`
        : run.status === "completed"
          ? `${queueRunActionForm(run.id, "replay-run", "Replay Run")}${runActionForm(run.id, "summarize", "Summarize Run")}`
          : `${workerActionForm(run.id, "batch", "Process Next Batch")}${workerActionForm(run.id, "watch", "Run Until Complete")}${queueRunActionForm(run.id, "cancel", "Cancel Run")}`;
    const approvalCards = openApprovals.map((approval) => renderMobileApprovalCard(approval)).join("");
    const approvalHistory = approvals.filter((approval) => !isOpenApproval(approval)).slice(0, 5).map((approval) => `
      <tr><td>${escapeHtml(approval.actionType)}</td><td><span class="status ${escapeHtml(approval.status)}">${escapeHtml(approval.status)}</span></td><td>${escapeHtml(truncateMiddle(approval.target, 92))}</td><td>${renderDashboardDateTime(approval.updatedAt)}</td></tr>
    `).join("");
    return `
      <div class="section-heading run-command-heading">
        <div><p class="eyebrow">Command Center</p><h2>${escapeHtml(headline)}</h2><span class="muted">${guidance}</span></div>
        <span class="status ${attention ? "blocked" : escapeHtml(run.status)}">${attention ? "attention" : escapeHtml(run.status)}</span>
      </div>
      <div class="run-command-metrics">
        <div><strong>${formatNumber(completed)}/${formatNumber(tasks.length)}</strong><span>stages complete${skipped ? ` · ${formatNumber(skipped)} skipped` : ""}</span></div>
        <div><strong>${formatNumber(active)}</strong><span>active or queued</span></div>
        <div><strong>${formatNumber(failed)}</strong><span>blocked or failed</span></div>
        <div class="${openApprovals.length ? "needs-attention" : ""}"><strong>${formatNumber(openApprovals.length)}</strong><span>open approvals</span></div>
      </div>
      <div class="actions run-command-actions">${primaryActions}<a class="button secondary" href="/approvals?status=open&run=${encodeURIComponent(run.id)}">All Run Approvals</a></div>
      ${blocked && !superseded ? renderRunBlockerGuide(run, tasks) : ""}
      ${openApprovals.length && !superseded ? `<div class="run-approval-section"><div class="section-heading"><div><h3>Decisions Required</h3><span class="muted">These controls use the same project role gates, execution claims, receipts, and policy checks as the Approvals page.</span></div></div><div class="run-approval-grid">${approvalCards}</div></div>` : ""}
      ${approvalHistory ? `<details class="governance-details"><summary>Recent approval history</summary><div class="table-wrap"><table><thead><tr><th>Action</th><th>Status</th><th>Target</th><th>Updated</th></tr></thead><tbody>${approvalHistory}</tbody></table></div></details>` : ""}
      <input type="hidden" data-run-return-path value="${escapeHtml(runPath)}">
    `;
  }

  function renderRunContinuationBanner(
    run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>
  ): string {
    const sourceRunId = typeof run.evaluationMetadata?.replayOfRunId === "string"
      ? run.evaluationMetadata.replayOfRunId.trim()
      : typeof run.evaluationMetadata?.sourceRunId === "string"
        ? run.evaluationMetadata.sourceRunId.trim()
        : "";
    if (run.replacementRunId) {
      const replacementActive = run.replacementRunStatus === "queued" || run.replacementRunStatus === "leased" || run.replacementRunStatus === "running";
      const replacementCompleted = run.replacementRunStatus === "completed";
      const recoveryHeadline = replacementActive
        ? "This run has active follow-up work"
        : replacementCompleted
          ? "This run was recovered by follow-up work"
          : "The latest follow-up needs attention";
      const recoveryDetail = replacementActive
        ? `Current work is happening in run <strong>${escapeHtml(run.replacementRunId.slice(0, 8))}</strong>${run.replacementRunStartedAt ? `, started ${renderDashboardDateTime(run.replacementRunStartedAt)}` : ""}.`
        : replacementCompleted
          ? `Recovery run <strong>${escapeHtml(run.replacementRunId.slice(0, 8))}</strong> completed successfully.`
          : `Latest follow-up run <strong>${escapeHtml(run.replacementRunId.slice(0, 8))}</strong> is ${escapeHtml(run.replacementRunStatus ?? "unavailable")}; review that run before taking further action.`;
      return `<section class="run-continuation-banner source-run" aria-labelledby="run-continuation-title">
        <div class="run-continuation-icon" aria-hidden="true">→</div>
        <div class="run-continuation-copy">
          <p class="eyebrow">Recovery chain</p>
          <h2 id="run-continuation-title">${recoveryHeadline}</h2>
          <p>The original ${escapeHtml(run.status)} result remains immutable history. ${recoveryDetail}</p>
        </div>
        <div class="run-continuation-action">
          ${run.replacementRunStatus ? `<span class="status ${escapeHtml(run.replacementRunStatus)}">${escapeHtml(run.replacementRunStatus)}</span>` : ""}
          <a class="button" href="/run?id=${encodeURIComponent(run.replacementRunId)}">Open continuation run →</a>
        </div>
      </section>`;
    }
    if (sourceRunId) {
      return `<section class="run-continuation-banner replacement-run" aria-labelledby="run-continuation-title">
        <div class="run-continuation-icon" aria-hidden="true">✓</div>
        <div class="run-continuation-copy">
          <p class="eyebrow">Recovery active</p>
          <h2 id="run-continuation-title">Follow-up run in progress</h2>
          <p>This run continues or repairs source run <strong>${escapeHtml(sourceRunId.slice(0, 8))}</strong>. The source history and evidence remain available.</p>
        </div>
        <div class="run-continuation-action">
          <span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span>
          <a class="button secondary" href="/run?id=${encodeURIComponent(sourceRunId)}">View source run</a>
        </div>
      </section>`;
    }
    return "";
  }

  function renderRunDecisionExplanationsHtml(explanations: RunDecisionExplanation[]): string {
    const cards = explanations.map((item) => `
      <article class="decision-card ${item.status}">
        <strong>${escapeHtml(item.title)}</strong>
        <p>${escapeHtml(item.detail)}</p>
        <ul>${item.evidence.map((evidence) => `<li>${escapeHtml(evidence)}</li>`).join("")}</ul>
      </article>
    `).join("");
    return `<section class="panel">
      <div class="section-heading">
        <div>
          <h2>Why This Ran This Way</h2>
          <span class="muted">Evidence-backed explanations for workflow choice, model tier, provider routing, and fallback behavior.</span>
        </div>
      </div>
      <div class="decision-grid">${cards}</div>
    </section>`;
  }

  function renderRunDetailHtml(input: {
    run: NonNullable<Awaited<ReturnType<typeof getWorkflowRunDetails>>["run"]>;
    tasks: Awaited<ReturnType<typeof getWorkflowRunDetails>>["tasks"];
    receipts: Awaited<ReturnType<typeof getWorkflowRunDetails>>["receipts"];
    artifacts: Awaited<ReturnType<typeof listArtifacts>>;
    approvals: Awaited<ReturnType<typeof listActionApprovals>>;
    params: URLSearchParams;
    summary: RunSummary | null;
    qualityReport: CostQualityReport | null;
    observabilityReport: ObservabilityReport | null;
    usageEstimate: RunUsageEstimate | null;
    eta: RunEta;
    preferenceScorecard: PreferenceScorecard | null;
    tuningProposals: TuningProposalSet | null;
    approvalCeiling: string;
  }): string {
    const completedTasks = input.tasks.filter((task) => task.status === "completed" && !task.skipped).length;
    const failedTasks = input.tasks.filter((task) => task.status === "failed").length;
    const activeTasks = input.tasks.filter((task) => task.status === "running" || task.status === "leased" || task.status === "queued").length;
    const shouldRefresh = input.run.status === "queued" || input.run.status === "leased" || input.run.status === "running";
    const summaryBlock = input.summary
      ? `<pre>${escapeHtml(formatRunSummary(input.summary))}</pre>`
      : "<p>No summary available.</p>";
    const taskRows = input.tasks.map((task) => `
      <tr><td>${escapeHtml(task.stageId)}</td><td>${escapeHtml(task.agentId)}</td><td>${escapeHtml(task.status)}</td><td>${task.attempts}</td><td>${task.executorSnapshot ? escapeHtml(`${task.executorSnapshot.executorId}/${task.executorSnapshot.operation}@${task.executorSnapshot.requestedHost}`) : "local model"}</td></tr>
    `).join("");
    const receiptRows = input.receipts.map((receipt) => `
      <tr><td>${escapeHtml(receipt.actionType)}</td><td>${escapeHtml(receipt.agentId)}</td><td>${escapeHtml(receipt.summary)}</td></tr>
    `).join("");
    const artifactBlocks = input.artifacts.map((artifact) => `
      <details class="artifact">
        <summary>${escapeHtml(artifact.kind)} ${escapeHtml(artifact.uri)}</summary>
        <pre>${escapeHtml(JSON.stringify(artifact.content, null, 2))}</pre>
      </details>
    `).join("");
    const decisionExplanations = buildRunDecisionExplanations(input.run, input.qualityReport, input.summary);
    const governedReusePlan = readGovernedReusePlan(input.artifacts);

    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Run ${escapeHtml(input.run.id.slice(0, 8))}</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("runs")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Run ${escapeHtml(input.run.id)}</h1>
        </div>
        <a class="button secondary" href="/api/run?id=${encodeURIComponent(input.run.id)}">JSON</a>
        <a class="button secondary" href="/api/quality?id=${encodeURIComponent(input.run.id)}">Quality JSON</a>
        <a class="button secondary" href="/api/observability?id=${encodeURIComponent(input.run.id)}">OTEL JSON</a>
        <a class="button secondary" href="/api/preferences?project=${encodeURIComponent(input.run.projectRootUri)}">Preference JSON</a>
        <a class="button secondary" href="/api/tuning?project=${encodeURIComponent(input.run.projectRootUri)}">Tuning JSON</a>
      </div>
      ${renderDashboardFlash(input.params)}
      ${renderDashboardActionHistory()}
      ${(input.run.runSetSize ?? 1) > 1 && input.run.runSetId ? `<section class="panel"><strong>Run history</strong><p class="muted">This run belongs to set ${escapeHtml(input.run.runSetId)} with ${formatNumber(input.run.runSetSize ?? 1)} immutable attempts.</p><a href="/runs?runSet=${encodeURIComponent(input.run.runSetId)}">View related runs →</a></section>` : ""}
      <div id="run-continuation">${renderRunContinuationBanner(input.run)}</div>
      <section id="run-stage-timeline" class="panel run-stage-timeline-panel">
        ${renderRunStageTimeline(input.tasks)}
      </section>
      <section id="run-command-center" class="panel run-command-center">
        ${renderRunCommandCenterBody(input.run, input.tasks, input.approvals)}
      </section>
      ${governedReusePlan ? renderGovernedReusePanel(governedReusePlan) : ""}
      <section class="panel run-live-panel" data-run-active="${shouldRefresh ? "true" : "false"}">
        <div class="section-heading">
          <div>
            <h2>Live Progress</h2>
            <span id="run-live-connection" class="muted" aria-live="polite">${shouldRefresh ? "Connecting to run activity…" : "Loading recorded activity…"}</span>
          </div>
          <div class="actions">
            <span id="run-live-indicator" class="run-live-indicator ${shouldRefresh ? "active" : ""}" aria-hidden="true"></span>
            <button id="run-live-verbose" class="secondary compact-button" type="button" aria-pressed="false">Verbose</button>
            <button id="run-live-toggle" class="secondary compact-button" type="button">Pause updates</button>
          </div>
        </div>
        <div id="run-live-scope" class="run-live-scope" hidden></div>
        <ol id="run-live-log" class="run-live-log" aria-label="Run progress log">
          <li class="run-live-empty">Waiting for activity…</li>
        </ol>
      </section>
      <section class="panel">
        <div class="meta-grid">
          <div><strong>Status</strong><span id="run-live-status" class="status ${escapeHtml(input.run.status)}">${escapeHtml(input.run.status)}</span></div>
          <div><strong>Workflow</strong>${escapeHtml(workflowDisplayName(input.run.workflowId))}<br><span class="muted">${escapeHtml(input.run.workflowId)}</span></div>
          <div><strong>Project</strong>${escapeHtml(input.run.projectName)}</div>
          <div><strong>Started</strong>${renderDashboardDateTime(input.run.startedAt)}</div>
          <div><strong>ETA</strong><span id="run-live-eta" title="${escapeHtml(input.eta.reason)}">${escapeHtml(formatRunEta(input.eta))}</span></div>
          <div><strong>Tasks</strong><span id="run-live-completed">${completedTasks}/${input.tasks.length} completed</span></div>
          <div><strong>Failed</strong><span id="run-live-failed">${failedTasks}</span></div>
          <div><strong>Active</strong><span id="run-live-active">${activeTasks}</span></div>
          <div><strong>Receipts</strong>${input.receipts.length}</div>
        </div>
        ${renderRunApprovalLevelControl(input.run, input.approvalCeiling)}
        <p>${escapeHtml(input.run.task)}</p>
        ${input.run.status === "blocked" ? `<h3>Reason Blocked</h3><p class="warn-box">${escapeHtml(input.run.blockedReason?.trim() || "No specific blocker reason was recorded. This is a workflow defect; inspect the stage artifacts below.")}</p>` : ""}
        ${input.run.status === "failed" ? renderFailedRunResolutionPanel(input.run) : ""}
        <details class="governance-details"><summary>Follow-up workflows</summary><div class="actions quick-actions">
          ${runActionForm(input.run.id, "summarize", "Summarize Run")}
          ${runActionForm(input.run.id, "debug-failure", "Diagnose & Fix")}
          ${runActionForm(input.run.id, "investigate-issue", "Investigate Issue")}
          ${runActionForm(input.run.id, "mira-ux-pass", "Ask Mira")}
          ${runActionForm(input.run.id, "frontend-pass", "Frontend Pass")}
          ${runActionForm(input.run.id, "maintain-context", "Maintain Context")}
        </div></details>
      </section>
      <section class="panel">
        <h2>Feedback</h2>
        ${input.qualityReport ? renderFeedbackHtml(input.run.id, input.qualityReport) : "<p>No feedback available.</p>"}
      </section>
      <section class="panel">
        <h2>Summary</h2>
        ${summaryBlock}
      </section>
      ${renderRunDecisionExplanationsHtml(decisionExplanations)}
      <section class="panel">
        <h2>Cost & Quality</h2>
        ${input.qualityReport ? renderCostQualityHtml(input.qualityReport) : "<p>No routing data available.</p>"}
      </section>
      <section class="panel">
        <h2>Observability</h2>
        ${input.observabilityReport ? renderObservabilityHtml(input.observabilityReport) : "<p>No observability data available.</p>"}
      </section>
      <section class="panel">
        <h2>Token Savings Estimate</h2>
        ${input.usageEstimate ? renderRunUsageEstimateHtml(input.usageEstimate) : "<p>No token estimate available.</p>"}
      </section>
      <section class="panel">
        <h2>Preference Scorecard</h2>
        ${input.preferenceScorecard ? renderPreferenceScorecardHtml(input.preferenceScorecard) : "<p>No preference scorecard available.</p>"}
      </section>
      <section class="panel">
        <h2>Tuning Proposals</h2>
        ${input.tuningProposals ? renderTuningProposalsHtml(input.tuningProposals) : "<p>No tuning proposals available.</p>"}
      </section>
      <section class="panel">
        <h2>Stages</h2>
        <table><thead><tr><th>Stage</th><th>Agent</th><th>Status</th><th>Attempts</th><th>Executor</th></tr></thead><tbody id="run-live-stages">${taskRows}</tbody></table>
      </section>
      <section class="panel">
        <h2>Receipts</h2>
        <table><thead><tr><th>Action</th><th>Agent</th><th>Summary</th></tr></thead><tbody>${receiptRows || "<tr><td colspan=\"3\">No receipts.</td></tr>"}</tbody></table>
      </section>
      <section class="panel">
        <h2>Artifacts</h2>
        ${artifactBlocks || "<p>No artifacts.</p>"}
      </section>
    </main>
    <script>${renderRunLiveProgressScript(input.run.id, shouldRefresh)}</script>
  </body>
  </html>`;
  }

  function renderRunInfoDialog(input: {
    idSuffix?: string;
    runId: string;
    workflowId?: string;
    status?: string;
    projectName?: string;
    projectRootUri?: string;
    task?: string;
    startedAt?: string | null;
    blockedReason?: string | null;
    failedReason?: string | null;
    summary?: string[];
  }): string {
    const dialogId = `run-info-${[input.runId, input.idSuffix].filter(Boolean).join("-").replace(/[^a-zA-Z0-9_-]/g, "-")}`;
    const rows = [
      ["Run", input.runId],
      ["Status", input.status],
      ["Workflow", input.workflowId],
      ["Project", input.projectName],
      ["Project path", input.projectRootUri],
      ["Started", input.startedAt ? formatDashboardDateTimeText(input.startedAt) : undefined]
    ].filter(([, value]) => Boolean(value)).map(([label, value]) => `
      <div><strong>${escapeHtml(label ?? "")}</strong><span>${escapeHtml(String(value))}</span></div>
    `).join("");
    const summary = input.summary?.filter(Boolean).length
      ? `<ul>${input.summary.filter(Boolean).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
      : "<p class=\"muted\">No compact run summary is available for this row yet.</p>";
    return `<button type="button" class="secondary compact-button" onclick="document.getElementById('${escapeHtml(dialogId)}').showModal()">${iconLabel("info", "Info")}</button>
      <dialog class="run-info-dialog" id="${escapeHtml(dialogId)}">
        <div>
          <div class="section-heading">
            <div>
              <h2>Run Info</h2>
              <span class="muted">${escapeHtml(input.workflowId ?? "workflow")} · ${escapeHtml(input.runId.slice(0, 8))}</span>
            </div>
            <form method="dialog"><button class="secondary" type="submit">${iconLabel("x", "Close")}</button></form>
          </div>
          <div class="meta-grid compact">${rows}</div>
          ${input.status === "blocked" ? `<h3>Reason Blocked</h3><p class="warn-box">${escapeHtml(input.blockedReason?.trim() || "No specific blocker reason was recorded. This is a workflow defect; open the full run for stage evidence.")}</p>` : ""}
          ${input.status === "failed" ? `<h3>Reason Failed</h3><p class="warn-box">${escapeHtml(input.failedReason?.trim() || "No specific failure reason was recorded. Open the full run for stage evidence.")}</p><h3>How to resolve</h3><ol>${failedRunResolution(input.failedReason).instructions.map((instruction) => `<li>${escapeHtml(instruction)}</li>`).join("")}</ol>` : ""}
          ${input.task ? `<h3>Task</h3><p>${escapeHtml(input.task)}</p>` : ""}
          <h3>Summary</h3>
          ${summary}
          <div class="dialog-actions">
            <a class="button" href="/run?id=${encodeURIComponent(input.runId)}">${iconLabel("activity", "Open Full Run")}</a>
            <form method="dialog"><button class="secondary" type="submit">${iconLabel("check", "Stay Here")}</button></form>
          </div>
        </div>
      </dialog>`;
  }

  function renderRunLiveProgressScript(runId: string, initiallyActive: boolean): string {
    return `(() => {
      const runId = ${serializeInlineScriptJson(runId)};
      const terminal = new Set(['completed', 'failed', 'blocked', 'cancelled', 'dismissed']);
      const log = document.getElementById('run-live-log');
      const connection = document.getElementById('run-live-connection');
      const indicator = document.getElementById('run-live-indicator');
      const toggle = document.getElementById('run-live-toggle');
      const verboseToggle = document.getElementById('run-live-verbose');
      const livePanel = log.closest('.run-live-panel');
      const liveScope = document.getElementById('run-live-scope');
      const stages = document.getElementById('run-live-stages');
      const continuation = document.getElementById('run-continuation');
      const stageTimeline = document.getElementById('run-stage-timeline');
      const commandCenter = document.getElementById('run-command-center');
      const eta = document.getElementById('run-live-eta');
      let selectedStage = '';
      let stageTimer = 0;
      let verbose = false;
      let paused = false;
      let stopped = ${initiallyActive ? "false" : "true"};
      let loaded = false;
      let failures = 0;
      let lastSummaryEvents = [];
      let lastVerboseEvents = [];

      const text = (tag, value, className) => {
        const node = document.createElement(tag);
        node.textContent = value == null ? '' : String(value);
        if (className) node.className = className;
        return node;
      };
      const formatTime = (value) => {
        const date = new Date(value);
        return Number.isNaN(date.getTime()) ? String(value || '') : date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      };
      const formatDuration = (value) => {
        if (!Number.isFinite(value)) return '';
        if (value < 60000) return Math.max(1, Math.round(value / 1000)) + 's';
        const minutes = Math.floor(value / 60000);
        const seconds = Math.round((value % 60000) / 1000);
        return minutes + 'm ' + seconds + 's';
      };
      const statusClass = (value) => ['queued', 'leased', 'running', 'completed', 'failed', 'blocked', 'cancelled'].includes(value) ? value : 'queued';

      function eventKey(event) {
        return String(event.id || [event.occurredAt, event.eventType, event.title, event.detail, event.status].join('|'));
      }

      function renderEvents(events, forceReset = false) {
        const followTail = !loaded || log.scrollHeight - log.scrollTop - log.clientHeight < 64;
        if (forceReset) {
          log.replaceChildren();
          loaded = false;
        }
        const empty = log.querySelector('.run-live-empty');
        if (events.length && empty) empty.remove();
        const existing = new Set(Array.from(log.querySelectorAll('[data-event-key]')).map((node) => node.getAttribute('data-event-key')));
        if (!events.length && !log.children.length) log.append(text('li', verbose ? 'Waiting for verbose activity…' : 'No run activity has been recorded yet.', 'run-live-empty'));
        for (const event of events) {
          const key = eventKey(event);
          if (existing.has(key)) continue;
          const item = document.createElement('li');
          item.className = 'run-live-entry ' + (event.severity || 'info');
          item.dataset.eventKey = key;
          const time = text('time', formatTime(event.occurredAt), 'run-live-time');
          time.dateTime = event.occurredAt || '';
          const body = document.createElement('div');
          body.append(text('strong', event.title || event.eventType || 'Activity'));
          if (event.detail) body.append(text('span', event.detail));
          const badge = text('span', event.status || event.category || 'info', 'status ' + statusClass(event.status));
          item.append(time, body, badge);
          log.append(item);
        }
        if (followTail) log.scrollTop = log.scrollHeight;
        loaded = true;
      }

      function renderStages(tasks) {
        stages.replaceChildren();
        for (const task of tasks) {
          const row = document.createElement('tr');
          for (const value of [task.stageId, task.agentId]) row.append(text('td', value));
          const statusCell = document.createElement('td');
          statusCell.append(text('span', task.skipped ? 'skipped' : task.status, 'status ' + (task.skipped ? 'skipped' : statusClass(task.status))));
          row.append(statusCell, text('td', task.attempts), text('td', task.executor));
          stages.append(row);
        }
      }

      function verboseRunEntries(payload) {
        const entries = [...(Array.isArray(payload.events) ? payload.events : [])];
        for (const task of (Array.isArray(payload.tasks) ? payload.tasks : [])) entries.push({ id: 'task:' + task.stageId + ':' + task.status + ':' + task.attempts, occurredAt: payload.generatedAt, title: 'Stage snapshot · ' + task.stageId, detail: task.agentId + ' · attempt ' + task.attempts + ' · ' + task.executor, status: task.skipped ? 'skipped' : task.status, category: 'stage' });
        for (const receipt of (Array.isArray(payload.receipts) ? payload.receipts : [])) entries.push({ id: 'receipt:' + receipt.id, occurredAt: receipt.createdAt, title: 'Action · ' + receipt.actionType, detail: receipt.summary, status: 'completed', category: 'receipt' });
        for (const approval of (Array.isArray(payload.approvals) ? payload.approvals : [])) entries.push({ id: 'approval:' + approval.id, occurredAt: approval.createdAt, title: 'Approval · ' + approval.actionType, detail: approval.target, status: approval.status, category: 'approval' });
        for (const artifact of (Array.isArray(payload.artifacts) ? payload.artifacts : [])) entries.push({ id: 'artifact:' + artifact.id, occurredAt: artifact.createdAt, title: 'Artifact · ' + artifact.kind, detail: artifact.uri, status: 'recorded', category: 'artifact' });
        return entries.sort((left, right) => String(left.occurredAt || '').localeCompare(String(right.occurredAt || '')));
      }

      function setVerbose(next, stageId = '') {
        verbose = next;
        selectedStage = next ? stageId : '';
        verboseToggle.textContent = verbose ? 'Summary' : 'Verbose';
        verboseToggle.setAttribute('aria-pressed', String(verbose));
        livePanel.classList.toggle('verbose', verbose);
        liveScope.hidden = !verbose;
        liveScope.textContent = selectedStage
          ? 'Streaming full activity for stage “' + selectedStage + '”. Choose Summary to return to the run feed.'
          : 'Streaming all recorded run activity as it arrives. Choose a stage number to focus this stream.';
        log.setAttribute('aria-label', selectedStage ? 'Verbose stage activity stream' : (verbose ? 'Verbose run activity stream' : 'Run progress log'));
        renderEvents([], true);
        if (!selectedStage) renderEvents(verbose ? lastVerboseEvents : lastSummaryEvents);
        window.clearTimeout(stageTimer);
        if (verbose && selectedStage) refreshStage();
      }

      async function refreshStage() {
        if (!verbose || !selectedStage) return;
        try {
          const response = await fetch('/api/run-stage?id=' + encodeURIComponent(runId) + '&stage=' + encodeURIComponent(selectedStage), { cache: 'no-store', headers: { accept: 'application/json' } });
          if (!response.ok) throw new Error('HTTP ' + response.status);
          const payload = await response.json();
          const entries = [{
            id: 'stage-snapshot:' + payload.task.stageId + ':' + payload.task.status + ':' + payload.task.attempts,
            occurredAt: payload.task.finishedAt || payload.task.startedAt || payload.generatedAt,
            title: payload.task.stageId + ' · ' + payload.task.agentId,
            detail: 'Status ' + payload.task.status + ' · attempt ' + payload.task.attempts + ' · ' + payload.task.executor,
            status: payload.task.status,
            category: 'stage'
          }];
          for (const event of (Array.isArray(payload.events) ? payload.events : [])) entries.push(event);
          for (const receipt of payload.receipts) entries.push({ id: 'receipt:' + receipt.actionType + ':' + receipt.createdAt, occurredAt: receipt.createdAt, title: 'Action · ' + receipt.actionType, detail: receipt.summary, status: 'completed', category: 'receipt' });
          for (const approval of payload.approvals) entries.push({ id: 'approval:' + approval.actionType + ':' + approval.createdAt, occurredAt: approval.createdAt, title: 'Approval · ' + approval.actionType, detail: approval.target, status: approval.status, category: 'approval' });
          for (const artifact of payload.artifacts) entries.push({ id: 'artifact:' + artifact.uri + ':' + artifact.createdAt, occurredAt: artifact.createdAt, title: 'Artifact · ' + artifact.kind, detail: artifact.uri, status: 'recorded', category: 'artifact' });
          entries.sort((left, right) => String(left.occurredAt || '').localeCompare(String(right.occurredAt || '')));
          renderEvents(entries);
          connection.textContent = 'Verbose stage stream · updated ' + formatTime(payload.generatedAt) + (terminal.has(payload.task.status) ? '' : ' · next update in 2s');
          window.clearTimeout(stageTimer);
          if (!terminal.has(payload.task.status) && !terminal.has(payload.runStatus)) stageTimer = window.setTimeout(refreshStage, document.hidden ? 5000 : 2000);
        } catch (error) {
          connection.textContent = 'Verbose stage stream unavailable (' + (error instanceof Error ? error.message : 'request failed') + ') · retrying';
          window.clearTimeout(stageTimer);
          stageTimer = window.setTimeout(refreshStage, 5000);
        }
      }

      document.addEventListener('click', (event) => {
        const trigger = event.target instanceof Element ? event.target.closest('[data-stage-watch]') : null;
        if (!trigger) return;
        selectedStage = trigger.getAttribute('data-stage-watch') || '';
        setVerbose(true, selectedStage);
        livePanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
      verboseToggle.addEventListener('click', () => {
        setVerbose(!verbose);
        if (verbose) refresh();
      });

      async function refresh() {
        if (paused) return schedule();
        try {
          const response = await fetch('/api/run-progress?id=' + encodeURIComponent(runId), { cache: 'no-store', headers: { accept: 'application/json' } });
          if (!response.ok) throw new Error('HTTP ' + response.status);
          const payload = await response.json();
          failures = 0;
          lastSummaryEvents = Array.isArray(payload.events) ? payload.events : [];
          lastVerboseEvents = verboseRunEntries(payload);
          if (!selectedStage) renderEvents(verbose ? lastVerboseEvents : lastSummaryEvents);
          renderStages(Array.isArray(payload.tasks) ? payload.tasks : []);
          if (typeof payload.continuationHtml === 'string' && continuation.innerHTML !== payload.continuationHtml) {
            continuation.innerHTML = payload.continuationHtml;
          }
          if (typeof payload.stageTimelineHtml === 'string' && stageTimeline.innerHTML !== payload.stageTimelineHtml) {
            stageTimeline.innerHTML = payload.stageTimelineHtml;
          }
          if (typeof payload.commandCenterHtml === 'string' && commandCenter.innerHTML !== payload.commandCenterHtml) {
            commandCenter.innerHTML = payload.commandCenterHtml;
          }
          const tasks = Array.isArray(payload.tasks) ? payload.tasks : [];
          const completed = tasks.filter((task) => task.status === 'completed' && !task.skipped).length;
          const failed = tasks.filter((task) => task.status === 'failed').length;
          const active = tasks.filter((task) => ['queued', 'leased', 'running'].includes(task.status)).length;
          document.getElementById('run-live-completed').textContent = completed + '/' + tasks.length + ' completed';
          document.getElementById('run-live-failed').textContent = String(failed);
          document.getElementById('run-live-active').textContent = String(active);
          if (eta && payload.eta) {
            eta.textContent = payload.eta.state === 'complete'
              ? 'Complete'
              : payload.eta.state === 'paused'
                ? 'Paused'
                : payload.eta.state === 'estimated' && Number.isFinite(payload.eta.remainingMs)
                  ? '~' + formatDuration(payload.eta.remainingMs) + ' remaining · ' + new Date(payload.eta.estimatedCompletionAt).toLocaleString([], { hour: 'numeric', minute: '2-digit' }) + ' · ' + payload.eta.confidence + ' confidence'
                  : 'Estimating…';
            eta.title = payload.eta.reason || '';
          }
          const status = document.getElementById('run-live-status');
          status.textContent = payload.run.status;
          status.className = 'status ' + statusClass(payload.run.status);
          stopped = terminal.has(payload.run.status);
          indicator.classList.toggle('active', !stopped);
          connection.textContent = stopped
            ? 'Run ' + payload.run.status + ' · final activity loaded ' + formatTime(payload.generatedAt)
            : 'Live · updated ' + formatTime(payload.generatedAt) + ' · next update in 2s';
          toggle.hidden = stopped;
          if (stopped && ${initiallyActive ? "true" : "false"}) window.setTimeout(() => window.location.reload(), 1200);
        } catch (error) {
          failures += 1;
          connection.textContent = 'Live update unavailable (' + (error instanceof Error ? error.message : 'request failed') + ') · retrying';
          indicator.classList.remove('active');
        }
        schedule();
      }

      function schedule() {
        if (!stopped) window.setTimeout(refresh, failures ? Math.min(15000, 2000 * failures) : (document.hidden ? 5000 : 2000));
      }
      toggle.addEventListener('click', () => {
        paused = !paused;
        toggle.textContent = paused ? 'Resume updates' : 'Pause updates';
        indicator.classList.toggle('active', !paused && !stopped);
        connection.textContent = paused ? 'Live updates paused' : 'Resuming live updates…';
        if (!paused) refresh();
      });
      refresh();
    })();`;
  }

  function renderRunStageTimeline(tasks: Awaited<ReturnType<typeof getWorkflowRunDetails>>["tasks"]): string {
    const steps = tasks.map((task, index) => {
      const state = task.skipped
        ? "skipped"
        : task.status === "completed"
        ? "completed"
        : task.status === "running" || task.status === "leased"
          ? "active"
          : task.status === "failed" || task.status === "blocked"
            ? "failed"
            : task.status === "cancelled"
              ? "cancelled"
              : "pending";
      const stateLabel = state === "active" ? "in progress" : state;
      return `<li class="run-stage-step ${state}" aria-label="Stage ${index + 1}: ${escapeHtml(task.stageId)}, ${escapeHtml(stateLabel)}">
        <div class="run-stage-track"><button type="button" class="run-stage-circle" data-stage-watch="${escapeHtml(task.stageId)}" aria-label="Watch stage ${escapeHtml(task.stageId)}" title="Focus verbose stream on this stage">${index + 1}</button></div>
        <strong>${escapeHtml(task.stageId)}</strong>
        <span class="run-stage-agent">${escapeHtml(task.agentId)}</span>
        <small>${escapeHtml(stateLabel)}</small>
      </li>`;
    }).join("");
    const completed = tasks.filter((task) => task.status === "completed" && !task.skipped).length;
    const skipped = tasks.filter((task) => task.skipped).length;
    return `<div class="section-heading"><div><p class="eyebrow">Stage Timeline</p><h2>${formatNumber(completed)} of ${formatNumber(tasks.length)} complete${skipped ? ` · ${formatNumber(skipped)} skipped` : ""}</h2></div><span class="muted">Updates live</span></div>
      <div class="run-stage-timeline-scroll"><ol class="run-stage-timeline" aria-label="Workflow stage progress">${steps || '<li class="run-stage-empty">No stages were created for this run.</li>'}</ol></div>`;
  }

  function renderRunUsageEstimateHtml(estimate: RunUsageEstimate): string {
    return `
      <div class="metric-grid">
        ${metricCard("Est. Prompt Tokens", formatNumber(estimate.estimatedPromptTokens), `${estimate.routedStages} routed stages`)}
        ${metricCard("Est. Tokens Saved", formatNumber(estimate.estimatedTokensSaved), `${estimate.tokenReductionPercent ?? "n/a"}% reduction`)}
        ${metricCard("Indexed Context", formatNumber(estimate.indexedProjectTokens), "project baseline")}
        ${metricCard("Compiled Brief", formatNumber(estimate.compiledBriefTokens), "per-stage compact context")}
        ${metricCard("Selected Sources", formatNumber(estimate.selectedSourceTokens), "source summary budget")}
        ${metricCard("Run Duration", estimate.runDurationMs === null ? "n/a" : formatDuration(estimate.runDurationMs), "wall-clock")}
      </div>
      <p class="muted">Estimate compares the indexed project context baseline with the compact compiled brief that each model-routed stage received.</p>
    `;
  }

  function renderRunsHtml(runs: DashboardRunStatus[], params: URLSearchParams = new URLSearchParams()): string {
    const selectedRunSet = params.get("runSet")?.trim(), visibleRuns = selectedRunSet ? runs.filter((run) => run.runSetId === selectedRunSet) : runs;
    const rows = visibleRuns.map((run) => {
      const presentation = dashboardRunPresentation(run);
      const eta = estimateRunEta({ run, tasks: [{ status: run.status }], historicalRuns: runs });
      return `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.id)}">${escapeHtml(run.id.slice(0, 8))}</a><br><span class="muted">${escapeHtml(run.id)}</span><div class="row-tools">${renderRunInfoDialog({
          runId: run.id,
          workflowId: run.workflowId,
          status: run.status,
          projectName: run.projectName,
          projectRootUri: run.projectRootUri,
          task: run.task,
          startedAt: run.startedAt,
          blockedReason: run.blockedReason,
          summary: [
            run.finishedAt ? `finished: ${formatDashboardDateTimeText(run.finishedAt)}` : "not finished yet",
            run.providerOverride ? `provider: ${run.providerOverride}` : "provider: default route",
            run.modelTierOverride ? `model tier: ${run.modelTierOverride}` : "model tier: workflow default"
          ]
        })}</div></td>
        <td><span class="status ${escapeHtml(run.status)}">${escapeHtml(run.status)}</span></td>
        <td><strong>${escapeHtml(workflowDisplayName(run.workflowId))}</strong><br><span class="muted">${escapeHtml(run.workflowId)}</span></td>
        <td>${escapeHtml(run.projectName)}<br><span class="muted">${escapeHtml(run.projectRootUri)}</span></td>
        <td class="run-task-cell"><strong>${escapeHtml(presentation.title)}</strong><br><span>${escapeHtml(presentation.description)}</span><details class="run-task-details"><summary>Original request</summary><div>${escapeHtml(run.task)}</div></details></td>
        <td>${renderDashboardDateTime(run.startedAt)}</td>
        <td title="${escapeHtml(eta.reason)}">${escapeHtml(formatRunEta(eta))}</td>
      </tr>
    `;
    }).join("");
    return `<!doctype html>
  <html>
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Agent Workflow Runs</title>
    <style>${dashboardCss()}</style>
  </head>
  <body>
    ${dashboardNav("runs")}
    <main>
      <div class="topbar">
        <div>
          <a href="/">Dashboard</a>
          <h1>Runs</h1>
        </div>
        <a class="button secondary" href="/api/runs">JSON</a>
      </div>
      ${renderDashboardFlash(params)}
      ${selectedRunSet ? `<section class="panel"><strong>Related run history</strong><p class="muted">Run set ${escapeHtml(selectedRunSet)} · ${formatNumber(visibleRuns.length)} run${visibleRuns.length === 1 ? "" : "s"}</p><a href="/runs">Show all runs</a></section>` : ""}
      ${renderDashboardActionHistory()}
      <section class="panel">
        <h2>Recent Runs</h2>
        <table>
          <thead><tr><th>Run</th><th>Status</th><th>Workflow</th><th>Project</th><th>Task</th><th>Started</th><th>ETA</th></tr></thead>
          <tbody>${rows || "<tr><td colspan=\"7\">No runs found.</td></tr>"}</tbody>
        </table>
      </section>
    </main>
  </body>
  </html>`;
  }

  function renderRuntimeMonitorPanel(report: RuntimeMonitorReport, params: URLSearchParams = new URLSearchParams()): string {
    const sharedHostRows = report.sharedHost.services.map((service) => `
      <tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>
    `).join("");
    const localRows = report.localServices.map((service) => `
      <tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>
    `).join("");
    const portRows = report.ports.map((port) => `
      <tr><td>${escapeHtml(port.label)}<br><span class="muted">:${port.port}</span></td><td><span class="status ${port.status === "listening" ? "completed" : "queued"}">${escapeHtml(port.status)}</span></td><td>${port.pid ? `pid ${port.pid}` : "none"}</td><td>${escapeHtml(port.command || "")}</td></tr>
    `).join("");
    const processRows = report.processes.map((processGroup) => `
      <tr><td>${escapeHtml(processGroup.role)}</td><td><span class="status ${processGroup.status === "ok" ? "completed" : "queued"}">${escapeHtml(processGroup.status)}</span></td><td>${formatNumber(processGroup.count)}</td><td>${processGroup.pids.map((pid) => `<code>${pid}</code>`).join(" ") || "none"}</td><td>${escapeHtml(processGroup.detail)}</td></tr>
    `).join("");
    const cleanupRows = report.mcpCleanup.candidates.map((candidate) => `
      <label class="bulk-approval-row">
        <input type="checkbox" name="pid" value="${candidate.pid}" checked>
        <span><strong>PID ${candidate.pid}</strong> parent ${candidate.parentPid ?? "n/a"} · <span class="flag ${candidate.autoCleanable ? "good" : "queued"}">${candidate.autoCleanable ? "auto-cleanable" : candidate.risk}</span><br><span class="muted">age ${candidate.ageMs === null ? "n/a" : escapeHtml(formatDuration(candidate.ageMs))} · session ${escapeHtml(candidate.sessionKey)}</span><br><span class="muted">${escapeHtml(candidate.reason)}</span><br><code>${escapeHtml(compactDashboardText(candidate.command, 220))}</code></span>
      </label>
    `).join("");
    const staleRunRows = report.staleRuns.candidates.map((run) => `
      <tr>
        <td><a href="/run?id=${encodeURIComponent(run.runId)}">${escapeHtml(run.runId.slice(0, 8))}</a><br><span class="muted">${escapeHtml(run.workflowId)}</span></td>
        <td><span class="status queued">${escapeHtml(run.runStatus)}</span> -> <span class="status completed">${escapeHtml(run.recommendedStatus)}</span></td>
        <td>${formatNumber(run.completedTasks)}/${formatNumber(run.totalTasks)} completed<br><span class="muted">${formatNumber(run.cancelledTasks)} cancelled</span></td>
        <td>${renderDashboardDateTime(run.startedAt, "n/a")}</td>
        <td>${escapeHtml(compactDashboardText(run.task, 160))}<br><span class="muted">${escapeHtml(run.projectRootUri)}</span></td>
      </tr>
    `).join("");
    const containerRows = report.docker.containers.map((container) => `
      <tr><td>${escapeHtml(container.name)}</td><td>${escapeHtml(container.image)}</td><td>${escapeHtml(container.ports)}</td></tr>
    `).join("");
    const mcpStdioRows = report.mcpPipeline.lastStdioEvents.slice(-6).reverse().map((event) => `
      <tr><td>${escapeHtml(String(event.ts ?? ""))}</td><td>${escapeHtml(String(event.event ?? ""))}</td><td><code>${escapeHtml(JSON.stringify(event))}</code></td></tr>
    `).join("");
    const mcpLauncherRows = report.mcpPipeline.lastLauncherEvents.slice(-6).reverse().map((event) => `
      <tr><td>${escapeHtml(String(event.ts ?? ""))}</td><td>${escapeHtml(String(event.event ?? ""))}</td><td><code>${escapeHtml(JSON.stringify(event))}</code></td></tr>
    `).join("");
    const mcpApprovalRows = report.mcpPipeline.approvalDiagnostics.recentEvents.slice(-6).reverse().map((event) => `
      <tr><td>${escapeHtml(String(event.ts ?? ""))}</td><td>${escapeHtml(String(event.event ?? ""))}</td><td><code>${escapeHtml(JSON.stringify(event))}</code></td></tr>
    `).join("");
    const mcpCommandRows = report.mcpPipeline.commandDiagnostics.recentEvents.slice(-6).reverse().map((event) => `
      <tr><td>${escapeHtml(String(event.ts ?? ""))}</td><td>${escapeHtml(String(event.event ?? ""))}</td><td>${escapeHtml(String(event.operation ?? "unknown"))}</td><td>${escapeHtml(String(event.exitCode ?? event.timedOut ?? ""))}</td><td><code>${escapeHtml(JSON.stringify(event))}</code></td></tr>
    `).join("");
    const mcpReloadSteps = report.mcpPipeline.clientReload.steps.map((step) => `<li>${escapeHtml(step)}</li>`).join("");
    const mcpReloadClass = report.mcpPipeline.clientReload.suspectedStalePipe ? "failed" : report.mcpPipeline.smoke.status === "passed" ? "completed" : "queued";
    const recommendations = report.recommendations.map((note) => `<li>${escapeHtml(note)}</li>`).join("");
    return `<section class="panel">
      <div class="section-heading">
        <div><h2>Runtime Monitor</h2><span class="muted">Local process inventory plus shared host/shared storage and localhost fallback health.</span></div>
        <a class="button secondary" href="/api/runtime-monitor">JSON</a>
      </div>
      <div class="metric-grid">
        ${metricCard("shared host", report.sharedHost.reachable ? "online" : "attention", report.sharedHost.host ?? "not configured")}
        ${metricCard("Local Fallback", report.localServices.every((service) => service.reachable) ? "ready" : "stopped", "localhost storage services")}
        ${metricCard("Docker", report.docker.status, report.docker.message)}
        ${metricCard("Local Model", report.localModelRuntime.endpointHealthy ? "online" : "attention", `${report.localModelRuntime.serviceStatus} · ${report.localModelRuntime.modelCount} models`)}
        ${metricCard("MCP Processes", report.processes.find((item) => item.role === "mcp")?.count ?? 0, "active local MCP server processes")}
        ${metricCard("MCP Pipeline", report.mcpPipeline.status, report.mcpPipeline.smoke.status === "passed" ? `${report.mcpPipeline.smoke.toolCount ?? 0} tools verified` : report.mcpPipeline.smoke.message)}
        ${metricCard("Stale Runs", report.staleRuns.candidateCount, report.staleRuns.autoReconcile.enabled ? "daemon auto-reconcile on" : "manual reconcile")}
      </div>
      <details class="governance-details"${!report.localModelRuntime.endpointHealthy ? " open" : ""}>
        <summary>Durable Local Model Runtime (${escapeHtml(report.localModelRuntime.serviceStatus)})</summary>
        <p class="muted">A dedicated LaunchAgent owns local inference so model failures do not restart the dashboard, workers, or learning daemon. Its wrapper resolves the current Homebrew Ollama symlink on every start, avoiding version-pinned executable paths after upgrades.</p>
        <div class="meta-grid compact">
          <div><strong>Runtime</strong>${escapeHtml(report.localModelRuntime.runtime)}</div>
          <div><strong>Executable</strong><code>${escapeHtml(report.localModelRuntime.executable ?? "not installed")}</code></div>
          <div><strong>Service</strong>${escapeHtml(report.localModelRuntime.serviceStatus)}${report.localModelRuntime.pid ? ` · pid ${report.localModelRuntime.pid}` : ""}</div>
          <div><strong>Endpoint</strong>${report.localModelRuntime.endpointHealthy ? "healthy" : "unavailable"} · <code>${escapeHtml(report.localModelRuntime.endpoint)}</code></div>
          <div><strong>Models</strong>${formatNumber(report.localModelRuntime.modelCount)}</div>
          <div><strong>Selected Model</strong>${escapeHtml(report.localModelRuntime.selectedModel)}</div>
          <div><strong>Plist</strong><code>${escapeHtml(report.localModelRuntime.plistPath)}</code></div>
          <div><strong>Logs</strong><code>${escapeHtml(report.localModelRuntime.stdoutPath)}</code><br><code>${escapeHtml(report.localModelRuntime.stderrPath)}</code></div>
        </div>
        <div class="callout ${report.localModelRuntime.endpointHealthy ? "completed" : "queued"}"><strong>Next action</strong><p>${escapeHtml(report.localModelRuntime.guidance)}</p></div>
        <p><code>${escapeHtml(report.localModelRuntime.installCommand)}</code></p>
        <p><code>${escapeHtml(report.localModelRuntime.restartCommand)}</code></p>
      </details>
      <div class="meta-grid compact">
        <div><strong>Generated</strong>${renderDashboardDateTime(report.generatedAt)}</div>
        <div><strong>Shared Host Source</strong>${escapeHtml(report.sharedHost.source)}</div>
        <div><strong>Storage Host</strong>${escapeHtml(report.storageHost ?? "not configured")}</div>
        <div><strong>Docker Detail</strong>${escapeHtml(report.docker.message)}</div>
      </div>
      <div class="split-grid">
        <div><h3>shared host / Shared Storage</h3><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${sharedHostRows || '<tr><td colspan="3">No shared storage host configured.</td></tr>'}</tbody></table></div></div>
        <div><h3>Local Fallback Storage</h3><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${localRows}</tbody></table></div></div>
      </div>
      <h3>Local Ports</h3>
      <div class="table-wrap"><table><thead><tr><th>Port</th><th>Status</th><th>PID</th><th>Command</th></tr></thead><tbody>${portRows}</tbody></table></div>
      <h3>Agent Workflow Processes</h3>
      <div class="table-wrap"><table><thead><tr><th>Role</th><th>Status</th><th>Count</th><th>PIDs</th><th>Detail</th></tr></thead><tbody>${processRows}</tbody></table></div>
      <details class="governance-details"${report.staleRuns.candidateCount ? " open" : ""}>
        <summary>Reconcile Stale Terminal Runs (${formatNumber(report.staleRuns.candidateCount)} candidate${report.staleRuns.candidateCount === 1 ? "" : "s"})</summary>
        <p class="muted">Repairs parent workflow runs that still show queued/running even though every child task is already terminal. The daemon can do this automatically because it only updates Agent Workflow run bookkeeping and writes a receipt.</p>
        <div class="meta-grid compact">
          <div><strong>Daemon Auto Reconcile</strong>${report.staleRuns.autoReconcile.enabled ? "on" : "off"}</div>
          <div><strong>Limit</strong>${formatNumber(report.staleRuns.autoReconcile.limit)}</div>
          <div><strong>Preview CLI</strong><code>${escapeHtml(report.staleRuns.previewCommand)}</code></div>
          <div><strong>Execute CLI</strong><code>${escapeHtml(report.staleRuns.executeCommand)}</code></div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Run</th><th>Status</th><th>Tasks</th><th>Started</th><th>Task</th></tr></thead><tbody>${staleRunRows || '<tr><td colspan="5">No stale terminal workflow runs found.</td></tr>'}</tbody></table></div>
        ${report.staleRuns.candidateCount ? `<form method="post" action="/api/runtime-monitor-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="action" value="reconcile-stale-runs">
          <button type="submit">Reconcile Stale Runs</button>
        </form>` : ""}
      </details>
      <details class="governance-details"${report.mcpPipeline.status !== "ok" || report.mcpPipeline.smoke.status !== "not-run" ? " open" : ""}>
        <summary>MCP Pipeline (${escapeHtml(report.mcpPipeline.status)})</summary>
        <p class="muted">Codex starts Agent Workflow MCP on demand over stdio, so zero active MCP processes can be normal between tool calls. This section checks the plugin launcher path instead.</p>
        <div class="meta-grid compact">
          <div><strong>Plugin</strong>${report.mcpPipeline.pluginEnabled ? "enabled" : "disabled"}</div>
          <div><strong>Launcher</strong>${report.mcpPipeline.launcherExists ? "found" : "missing"}${report.mcpPipeline.launcherExecutable ? " / executable" : ""}</div>
          <div><strong>Repo</strong>${escapeHtml(report.mcpPipeline.resolvedRepo ?? "not resolved")}</div>
          <div><strong>Built Server</strong>${report.mcpPipeline.serverBuilt ? "yes" : "no"}</div>
          <div><strong>Last Spawn</strong>${renderDashboardDateTime(report.mcpPipeline.lastSpawnAt)}</div>
          <div><strong>Last Exit</strong>${renderDashboardDateTime(report.mcpPipeline.lastExitAt)}${report.mcpPipeline.lastExitCode === null ? "" : ` code ${report.mcpPipeline.lastExitCode}`}</div>
          <div><strong>Smoke</strong>${escapeHtml(report.mcpPipeline.smoke.status)} · ${escapeHtml(report.mcpPipeline.smoke.message)}</div>
          <div><strong>Smoke CLI</strong><code>${escapeHtml(report.mcpPipeline.smoke.command)}</code></div>
          <div><strong>Launcher Log</strong><code>${escapeHtml(report.mcpPipeline.launcherLogPath)}</code></div>
          <div><strong>Stdio Log</strong><code>${escapeHtml(report.mcpPipeline.stdioLogPath)}</code></div>
        </div>
        <div class="callout ${mcpReloadClass}">
          <strong>Codex / IDE Reload Guidance</strong>
          <p>${escapeHtml(report.mcpPipeline.clientReload.summary)}</p>
          <ul>${mcpReloadSteps}</ul>
        </div>
        <div class="callout queued">
          <strong>MCP Approval-Call Diagnostics</strong>
          <p>${escapeHtml(report.mcpPipeline.approvalDiagnostics.summary)}</p>
          <p><code>${escapeHtml(report.mcpPipeline.approvalDiagnostics.fallbackCommand)}</code></p>
        </div>
        <div class="callout queued">
          <strong>MCP Command Spans</strong>
          <p>${escapeHtml(report.mcpPipeline.commandDiagnostics.summary)}</p>
        </div>
        <div class="callout ${report.mcpPipeline.recovery.status === "available" ? "completed" : "queued"}">
          <strong>MCP Recovery Package</strong>
          <p>${escapeHtml(report.mcpPipeline.recovery.recommendedAction)}</p>
          <div class="meta-grid compact">
            <div><strong>Status</strong>${escapeHtml(report.mcpPipeline.recovery.status)}</div>
            <div><strong>Last Written</strong>${renderDashboardDateTime(report.mcpPipeline.recovery.lastWrittenAt)}</div>
            <div><strong>Can Restart Client Pipe</strong>${report.mcpPipeline.recovery.canRestartClientPipe ? "yes" : "no"}</div>
            <div><strong>Reason</strong>${escapeHtml(report.mcpPipeline.recovery.reason)}</div>
            <div><strong>Runbook</strong><code>${escapeHtml(report.mcpPipeline.recovery.markdownPath)}</code></div>
            <div><strong>Script</strong><code>${escapeHtml(report.mcpPipeline.recovery.scriptPath)}</code></div>
          </div>
        </div>
        <div class="button-row">
          <form method="post" action="/api/runtime-monitor-action">
            ${dashboardReturnInput("/server-readiness", params)}
            <input type="hidden" name="action" value="check-mcp">
            <button type="submit">Run MCP Smoke</button>
          </form>
          <form method="post" action="/api/runtime-monitor-action">
            ${dashboardReturnInput("/server-readiness", params)}
            <input type="hidden" name="action" value="write-mcp-recovery">
            <button type="submit">Write Recovery Package</button>
          </form>
        </div>
        <div class="split-grid">
          <div><h3>Launcher Events</h3><div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Detail</th></tr></thead><tbody>${mcpLauncherRows || '<tr><td colspan="3">No launcher events recorded.</td></tr>'}</tbody></table></div></div>
          <div><h3>Stdio Events</h3><div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Detail</th></tr></thead><tbody>${mcpStdioRows || '<tr><td colspan="3">No stdio events recorded.</td></tr>'}</tbody></table></div></div>
        </div>
        <h3>Approval Call Events</h3>
        <div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Detail</th></tr></thead><tbody>${mcpApprovalRows || '<tr><td colspan="3">No MCP approval calls recorded in the recent log window.</td></tr>'}</tbody></table></div>
        <h3>Command Span Events</h3>
        <div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Operation</th><th>Exit/Timeout</th><th>Detail</th></tr></thead><tbody>${mcpCommandRows || '<tr><td colspan="5">No MCP command spans recorded in the recent log window.</td></tr>'}</tbody></table></div>
      </details>
      <details class="governance-details"${report.mcpCleanup.candidateCount ? " open" : ""}>
        <summary>Cleanup Stale MCP Sessions (${formatNumber(report.mcpCleanup.candidateCount)} candidate${report.mcpCleanup.candidateCount === 1 ? "" : "s"})</summary>
        <p class="muted">Preview-only by default. These candidates are limited to Agent Workflow MCP commands from this checkout.</p>
        <div class="meta-grid compact">
          <div><strong>Daemon Auto Cleanup</strong>${report.mcpCleanup.autoCleanup.enabled ? escapeHtml(report.mcpCleanup.autoCleanup.mode) : "off"}</div>
          <div><strong>Stale Threshold</strong>${formatNumber(report.mcpCleanup.autoCleanup.staleMinutes)} min</div>
          <div><strong>Auto-cleanable</strong>${formatNumber(report.mcpCleanup.candidates.filter((candidate) => candidate.autoCleanable).length)}</div>
          <div><strong>Preview CLI</strong><code>${escapeHtml(report.mcpCleanup.previewCommand)}</code></div>
          <div><strong>Execute CLI</strong><code>${escapeHtml(report.mcpCleanup.executeCommand)}</code></div>
          <div><strong>Auto Low Risk CLI</strong><code>${escapeHtml(`${report.mcpCleanup.executeCommand} --auto-low-risk`)}</code></div>
        </div>
        ${cleanupRows ? `<form class="bulk-approval-form" method="post" action="/api/runtime-monitor-action">
          ${dashboardReturnInput("/server-readiness", params)}
          <input type="hidden" name="action" value="cleanup-mcp">
          <div class="bulk-approval-list">${cleanupRows}</div>
          <label class="checkbox-row"><input type="checkbox" name="confirmed" required> Confirm terminating the selected Agent Workflow MCP candidate processes</label>
          <button class="danger" type="submit">Terminate Selected MCP Candidates</button>
        </form>` : `<p>No Agent Workflow MCP cleanup candidates found.</p>`}
      </details>
      ${containerRows ? `<details class="governance-details"><summary>Docker Containers</summary><div class="table-wrap"><table><thead><tr><th>Name</th><th>Image</th><th>Ports</th></tr></thead><tbody>${containerRows}</tbody></table></div></details>` : ""}
      <ul>${recommendations}</ul>
    </section>`;
  }

  function renderServerApprovalActionPlanPanel(report: ServerApprovalActionPlanReport, testAdapter: ServerApprovalActionTestAdapterReport): string {
    const statusClass = report.status === "ready" ? "completed" : report.status === "blocked" ? "failed" : "queued";
    const testStatusClass = testAdapter.status === "pass" ? "completed" : "failed";
    const decisionRows = report.decisions.map((decision) => {
      const rowStatusClass = decision.status === "ready" ? "completed" : "failed";
      const receipts = decision.requiredReceiptKinds.map((receipt) => `<code>${escapeHtml(receipt)}</code>`).join(" ");
      const missing = decision.missingControls.length
        ? decision.missingControls.map((control) => `<code>${escapeHtml(control)}</code>`).join(" ")
        : '<span class="muted">none</span>';
      return `
      <tr>
        <td><strong>${escapeHtml(decision.decision)}</strong><br><span class="muted">${decision.executesSideEffect ? "executes side effect" : "approval state only"}</span></td>
        <td><span class="status ${rowStatusClass}">${escapeHtml(decision.status)}</span><br><span class="muted">${decision.mutatesApprovalState ? "mutates approval state" : "read-only"}</span></td>
        <td>${receipts}</td>
        <td><code>${escapeHtml(decision.idempotencyReuseKey)}</code><br><span class="muted">${escapeHtml(decision.replayBehavior)}</span></td>
        <td>${decision.rollbackEvidence.map((item) => escapeHtml(item)).join("<br>")}</td>
        <td>${missing}</td>
      </tr>`;
    }).join("");
    const phaseRows = report.implementationPhases.map((phase) => `<li><strong>${escapeHtml(phase.phase)}</strong> <span class="status ${phase.status === "done" ? "completed" : phase.status === "next" ? "queued" : "pending"}">${escapeHtml(phase.status)}</span> ${escapeHtml(phase.detail)}</li>`).join("");
    return `<section class="panel"><div class="section-heading"><div><h2>Approval Action Plan</h2><span class="muted">Per-decision receipt, replay, and rollback checklist before remote approval mutations can be enabled.</span></div><div class="actions"><a class="button secondary" href="/api/server-approval-action-plan">Plan JSON</a><a class="button secondary" href="/api/server-approval-action-test-adapter">Test JSON</a></div></div>
    <div class="metric-grid">
      ${metricCard("Plan", report.status, "remote approval mutation")}
      ${metricCard("Decisions", report.summary.decisions, "approval actions")}
      ${metricCard("Ready", report.summary.ready, "decision paths")}
      ${metricCard("Blocked", report.summary.blocked, "decision paths")}
      ${metricCard("Test Adapter", testAdapter.status, `${testAdapter.summary.passed}/${testAdapter.summary.decisions} decisions`)}
      ${metricCard("Replay Proof", testAdapter.summary.replayed, "idempotent fixture paths")}
      ${metricCard("Receipts", report.summary.receiptPlanReady ? "ready" : "blocked", "per-action")}
      ${metricCard("Idempotency", report.summary.idempotencyReuseReady ? "ready" : "blocked", "replay")}
    </div>
    <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Current status: <span class="status ${statusClass}">${escapeHtml(report.status)}</span>. Enablement: ${report.canEnableApprovalActions ? "allowed" : "blocked"}. Test adapter: <span class="status ${testStatusClass}">${escapeHtml(testAdapter.status)}</span>, ${formatNumber(testAdapter.summary.simulatedSideEffects)} simulated side effect(s), no live effects.</p>
    <div class="table-wrap"><table><thead><tr><th>Decision</th><th>Status</th><th>Receipts</th><th>Idempotency Replay</th><th>Rollback Evidence</th><th>Missing Controls</th></tr></thead><tbody>${decisionRows}</tbody></table></div>
    ${phaseRows ? `<details class="governance-details" open><summary>Implementation Phases</summary><ul>${phaseRows}</ul></details>` : ""}
    </section>`;
  }

  function renderServerAuthHardeningPanel(report: ServerAuthHardeningReport): string {
    const statusClass = report.status === "ready" || report.status === "local-only" ? "completed" : report.status === "blocked" ? "failed" : "queued";
    const checkRows = report.checks.map((check) => `
      <tr>
        <td>${escapeHtml(check.label)}</td>
        <td><span class="status ${check.status === "pass" ? "completed" : check.status === "fail" ? "failed" : "queued"}">${escapeHtml(check.status)}</span></td>
        <td>${escapeHtml(check.detail)}</td>
      </tr>
    `).join("");
    const actionRows = report.recommendedActions.map((action) => `<li>${escapeHtml(action)}</li>`).join("");
    return `<section class="panel"><div class="section-heading"><div><h2>Auth Hardening</h2><span class="muted">Operator checklist before Agent Workflow is exposed as a shared server surface.</span></div><span class="status ${statusClass}">${escapeHtml(report.status)}</span></div>
    <div class="metric-grid">
      ${metricCard("Ready", report.readyControls, "controls passing")}
      ${metricCard("Warnings", report.warningControls, "review before shared use")}
      ${metricCard("Blocked", report.failingControls, "must fix first")}
      ${metricCard("Posture", report.status, "server auth")}
    </div>
    <p class="muted">${escapeHtml(report.summary)}</p>
    <div class="table-wrap"><table><thead><tr><th>Control</th><th>Status</th><th>Detail</th></tr></thead><tbody>${checkRows}</tbody></table></div>
    ${actionRows ? `<details class="governance-details" open><summary>Recommended Actions</summary><ul>${actionRows}</ul></details>` : ""}
    </section>`;
  }

  function renderServerMutationControlsPanel(report: ServerMutationControlReport): string {
    const statusClass = report.status === "ready" ? "completed" : report.status === "blocked" ? "failed" : "queued";
    const endpointRows = report.endpoints.map((endpoint) => {
      const endpointStatusClass = endpoint.status === "ready" ? "completed" : endpoint.status === "blocked" ? "failed" : "queued";
      const missingControls = endpoint.missingControls.length
        ? endpoint.missingControls.map((control) => `<code>${escapeHtml(control)}</code>`).join(" ")
        : '<span class="muted">none</span>';
      return `
      <tr>
        <td>${escapeHtml(endpoint.name)}<br><code>${escapeHtml(`${endpoint.method} ${endpoint.path}`)}</code></td>
        <td><span class="status ${endpointStatusClass}">${escapeHtml(endpoint.status)}</span><br><span class="muted">${escapeHtml(endpoint.exposure)}</span></td>
        <td>${endpoint.remoteEligible ? "yes" : "local-only"}<br><span class="muted">${endpoint.dryRunDefault ? "dry-run default" : "executes when submitted"}</span></td>
        <td>${escapeHtml(endpoint.executionGate)}</td>
        <td>${endpoint.roleCapability ? `<code>${escapeHtml(endpoint.roleCapability)}</code>` : '<span class="muted">n/a</span>'}</td>
        <td>${endpoint.receipt ? `<code>${escapeHtml(endpoint.receipt)}</code>` : '<span class="muted">n/a</span>'}</td>
        <td>${missingControls}</td>
      </tr>`;
    }).join("");
    const actionRows = report.recommendedActions.map((action) => `<li>${escapeHtml(action)}</li>`).join("");
    return `<section class="panel"><div class="section-heading"><div><h2>Mutation Controls</h2><span class="muted">Read-only audit of server-mode and local operator mutation surfaces.</span></div><a class="button secondary" href="/api/server-mutation-controls">JSON</a></div>
    <div class="metric-grid">
      ${metricCard("Controls", report.status, "remote mutation posture")}
      ${metricCard("Remote Mutations", report.summary.remoteMutationEndpoints, `${report.summary.readyRemoteMutations} ready`)}
      ${metricCard("Blocked", report.summary.blockedRemoteMutations, "remote mutations gated")}
      ${metricCard("Local Actions", report.summary.localOnlyMutations, "dashboard/operator only")}
      ${metricCard("Approval Gate", report.mode.approvalActionExecutionEnabled ? "on" : "off", "server approval actions")}
      ${metricCard("Body Limit", `${report.mode.requestBodyMaxBytes} bytes`, "remote JSON mutation")}
      ${metricCard("Rate Limit", report.mode.rateLimitPerMinute <= 0 ? "off" : `${report.mode.rateLimitPerMinute}/min`, "per actor/IP")}
    </div>
    <p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Current status: <span class="status ${statusClass}">${escapeHtml(report.status)}</span>.</p>
    <div class="table-wrap"><table><thead><tr><th>Endpoint</th><th>Status</th><th>Exposure</th><th>Execution Gate</th><th>Role</th><th>Receipt</th><th>Missing Controls</th></tr></thead><tbody>${endpointRows}</tbody></table></div>
    ${actionRows ? `<details class="governance-details"><summary>Recommended Actions</summary><ul>${actionRows}</ul></details>` : ""}
    </section>`;
  }

  function renderServerReadinessHtml(report: ServerReadinessReport, registry: ServerProjectRegistryReport, storageVerification: StorageVerificationReport, migrationPlans: StorageMigrationPlanListing, mergeEvidence: StorageMergeEvidenceListing, offlineFallback: OfflineFallbackReport, objectProof: ObjectArtifactProofReport, runtimeMonitor: RuntimeMonitorReport, statePlaneProof: SharedStatePlaneProof, mutationControls: ServerMutationControlReport, approvalActionPlan: ServerApprovalActionPlanReport, approvalActionTestAdapter: ServerApprovalActionTestAdapterReport, requestAudit: ServerRequestAuditReport, projects: DashboardProjectSummary[], params: URLSearchParams): string {
    const projectOptions = projects.map((project) => `<option value="${escapeHtml(project.rootUri)}"${report.projectRootUri === project.rootUri ? " selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
    const statusClass = report.status === "ready" || report.status === "local-only" ? "completed" : report.status === "blocked" ? "failed" : "queued";
    const checkRows = report.checks.map((check) => `
      <tr><td>${escapeHtml(check.label)}</td><td><span class="status ${check.status === "pass" ? "completed" : check.status === "fail" ? "failed" : "queued"}">${escapeHtml(check.status)}</span></td><td>${escapeHtml(check.detail)}</td></tr>
    `).join("");
    const endpointRows = report.endpointClasses.map((endpoint) => `
      <tr><td>${escapeHtml(endpoint.name)}<br><span class="muted">${escapeHtml(endpoint.exposure)}</span></td><td><span class="status ${endpoint.implemented ? "completed" : "queued"}">${endpoint.implemented ? "implemented" : "not implemented"}</span></td><td><span class="status ${endpoint.ready ? "completed" : "queued"}">${endpoint.ready ? "ready" : "not ready"}</span></td><td>${endpoint.requiredControls.map((control) => `<code>${escapeHtml(control)}</code>`).join(" ")}</td></tr>
    `).join("");
    const projectRows = report.projects.map((project) => `
      <tr><td>${escapeHtml(project.name)}<br><code>${escapeHtml(project.id)}</code></td><td><code>${escapeHtml(project.rootUri)}</code></td><td><span class="status ${project.configStatus === "valid" ? "completed" : project.configStatus === "invalid" ? "failed" : "queued"}">${escapeHtml(project.configStatus)}</span></td><td>${escapeHtml(project.roleEnforcement)}</td><td>${project.roles.map((role) => `<code>${escapeHtml(role)}</code>`).join(" ") || "none"}</td></tr>
    `).join("");
    const registryRows = registry.projects.map((project) => `
      <tr><td>${escapeHtml(project.name)}<br><code>${escapeHtml(project.projectId)}</code><br><a href="/api/server-project?projectId=${encodeURIComponent(project.projectId)}">Resolve JSON</a></td><td>${project.rootUri ? `<code>${escapeHtml(project.rootUri)}</code>` : `<span class="muted">hidden</span><br><code>${escapeHtml(project.rootHash.slice(0, 12))}</code>`}</td><td>${project.defaultWorkflows.map((workflow) => `<code>${escapeHtml(workflow)}</code>`).join(" ") || "none"}</td><td><code>${escapeHtml(JSON.stringify(project.requestExample))}</code></td></tr>
    `).join("");
    const serviceRows = report.services.map((service) => `
      <tr><td>${escapeHtml(service.endpoint.name)}</td><td><span class="status ${service.reachable ? "completed" : "failed"}">${service.reachable ? "OK" : "MISSING"}</span></td><td>${escapeHtml(service.message)}</td></tr>
    `).join("");
    const storageStatusClass = storageVerification.status === "match" ? "completed" : storageVerification.status === "blocked" || storageVerification.status === "mismatch" ? "failed" : "queued";
    const storageMatches = storageVerification.diffs.filter((diff) => diff.status === "match").length;
    const storageMismatches = storageVerification.diffs.filter((diff) => diff.status === "mismatch").length;
    const storageMissing = storageVerification.diffs.filter((diff) => diff.status === "missing").length;
    const storageDiffRows = storageVerification.diffs.map((diff) => `
      <tr><td>${escapeHtml(diff.table)}</td><td><span class="status ${diff.status === "match" ? "completed" : "failed"}">${escapeHtml(diff.status)}</span></td><td>${escapeHtml(String(diff.sourceCount ?? "missing"))}</td><td>${escapeHtml(String(diff.targetCount ?? "missing"))}</td></tr>
    `).join("");
    const storageWarningRows = storageVerification.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    const migrationPlanRows = migrationPlans.plans.map((plan) => {
      const planStatusClass = plan.status === "ready" ? "completed" : plan.status === "blocked" ? "failed" : "queued";
      return `
      <tr>
        <td>${renderDashboardDateTime(plan.generatedAt)}<br><code>${escapeHtml(path.basename(plan.jsonPath))}</code></td>
        <td><span class="status ${planStatusClass}">${escapeHtml(plan.status)}</span><br><span class="muted">${escapeHtml(plan.mode)}</span></td>
        <td><code>${escapeHtml(plan.sourceDatabaseUrl)}</code></td>
        <td><code>${escapeHtml(plan.targetDatabaseUrl)}</code><br><span class="muted">${escapeHtml(plan.targetObjectStorageEndpoint)} / ${escapeHtml(plan.targetObjectStorageBucket)}</span></td>
        <td>${formatNumber(plan.warningCount)}<br><span class="muted">${formatNumber(plan.stepCount)} steps</span></td>
        <td>${plan.markdownPath ? `<code>${escapeHtml(plan.markdownPath)}</code>` : '<span class="muted">none</span>'}</td>
        <td>${plan.scriptPath ? `<code>${escapeHtml(plan.scriptPath)}</code>` : '<span class="muted">none</span>'}</td>
      </tr>`;
    }).join("");
    const migrationWarningRows = migrationPlans.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("");
    const storageHost = params.get("storageHost") ?? process.env.AGENTFLOW_SHARED_STORAGE_HOST ?? "";
    const migrationDir = params.get("migrationDir") ?? ".agent-workflow/migrations";
    const commandRows = report.recommendedCommands.map((command) => `<li><code>${escapeHtml(command)}</code></li>`).join("");
    const noteRows = report.notes.map((note) => `<li>${escapeHtml(note)}</li>`).join("");
    const jsonParams = new URLSearchParams();
    if (report.projectRootUri) jsonParams.set("project", report.projectRootUri);
    jsonParams.set("limit", String(report.limit));
    const storageParams = new URLSearchParams();
    if (storageHost) storageParams.set("storageHost", storageHost);
    const migrationParams = new URLSearchParams();
    migrationParams.set("dir", migrationPlans.directory);
    const registryParams = new URLSearchParams(jsonParams);
    if (registry.includeRoots) registryParams.set("includeRoots", "true");
    const serverControlDetails = `
      <section class="panel"><h2>Readiness Checks</h2><div class="table-wrap"><table><thead><tr><th>Check</th><th>Status</th><th>Detail</th></tr></thead><tbody>${checkRows}</tbody></table></div></section>
      <section class="panel"><h2>Endpoint Classes</h2><div class="table-wrap"><table><thead><tr><th>Class</th><th>Implementation</th><th>Ready</th><th>Required Controls</th></tr></thead><tbody>${endpointRows}</tbody></table></div></section>
      ${renderServerAuthHardeningPanel(report.authHardening)}
      ${renderServerMutationControlsPanel(mutationControls)}
      ${renderServerApprovalActionPlanPanel(approvalActionPlan, approvalActionTestAdapter)}`;
    const projectAndAuditDetails = `
      ${renderServerRequestAuditPanel(requestAudit)}
      <section class="panel"><div class="section-heading"><div><h2>Server Project IDs</h2><span class="muted">Client-facing preview. Future server-mode requests should use projectId instead of raw filesystem paths.</span></div><a class="button secondary" href="/api/server-projects?${escapeHtml(registryParams.toString())}">JSON</a></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Root</th><th>Default Workflows</th><th>Request Example</th></tr></thead><tbody>${registryRows || '<tr><td colspan="4">No registered projects found.</td></tr>'}</tbody></table></div></section>
      <section class="panel"><h2>Registered Projects</h2><div class="table-wrap"><table><thead><tr><th>Project</th><th>Root</th><th>Config</th><th>Roles</th><th>Role IDs</th></tr></thead><tbody>${projectRows || '<tr><td colspan="5">No registered projects found.</td></tr>'}</tbody></table></div></section>`;
    const runtimeDetails = `
      <section class="panel"><h2>Services</h2><div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th>Detail</th></tr></thead><tbody>${serviceRows || '<tr><td colspan="3">No service checks were recorded.</td></tr>'}</tbody></table></div></section>
      ${renderRuntimeMonitorPanel(runtimeMonitor, params)}`;
    const storageDetails = `
      <section class="panel"><div class="section-heading"><div><h2>Shared Storage Verification</h2><span class="muted">Read-only migration proof. This does not copy, restore, delete, or mutate storage.</span></div><a class="button secondary" href="/api/storage-verify?${escapeHtml(storageParams.toString())}">JSON</a></div>
      <div class="metric-grid">${metricCard("Storage", storageVerification.status, "durable state comparison")}${metricCard("Matched", storageMatches, `${storageVerification.diffs.length} durable tables`)}${metricCard("Mismatched", storageMismatches, "count or fingerprint differs")}${metricCard("Missing", storageMissing, "table absent on one side")}</div>
      <div class="meta-grid compact"><div><strong>Source DB</strong>${escapeHtml(storageVerification.source.endpoint.databaseUrl)}</div><div><strong>Target DB</strong>${escapeHtml(storageVerification.target.endpoint.databaseUrl)}</div><div><strong>Source Objects</strong>${escapeHtml(storageVerification.source.endpoint.objectStorageEndpoint)}</div><div><strong>Target Objects</strong>${escapeHtml(storageVerification.target.endpoint.objectStorageEndpoint)}</div></div>
      <p class="muted">Generated ${renderDashboardDateTime(storageVerification.generatedAt)}. Current status: <span class="status ${storageStatusClass}">${escapeHtml(storageVerification.status)}</span>.</p>
      ${storageVerification.warnings.length ? `<details class="governance-details" open><summary>Storage Warnings</summary><ul>${storageWarningRows}</ul></details>` : ""}
      <div class="table-wrap"><table><thead><tr><th>Table</th><th>Status</th><th>Source Rows</th><th>Target Rows</th></tr></thead><tbody>${storageDiffRows}</tbody></table></div></section>
      ${renderPostMergeEvidencePanel(mergeEvidence)}
      ${renderOfflineFallbackPanel(offlineFallback, params)}
      ${renderObjectArtifactProofPanel(objectProof, params)}
      <section class="panel"><div class="section-heading"><div><h2>Storage Migration Plans</h2><span class="muted">Generated dry-run operator packages from <code>storage-migrate --write-plan</code>. This page only reads plan artifacts.</span></div><a class="button secondary" href="/api/storage-migrations?${escapeHtml(migrationParams.toString())}">JSON</a></div>
      <div class="metric-grid">${metricCard("Plans", migrationPlans.plans.length, "generated migration packages")}${metricCard("Ready", migrationPlans.plans.filter((plan) => plan.status === "ready").length, "safe to review for execution")}${metricCard("Blocked", migrationPlans.plans.filter((plan) => plan.status === "blocked").length, "requires config changes first")}${metricCard("Warnings", migrationPlans.plans.reduce((total, plan) => total + plan.warningCount, 0), "across listed plans")}</div>
      <div class="meta-grid compact"><div><strong>Directory</strong><code>${escapeHtml(migrationPlans.directory)}</code></div><div><strong>Generated</strong>${renderDashboardDateTime(migrationPlans.generatedAt)}</div></div>
      ${migrationPlans.warnings.length ? `<details class="governance-details" open><summary>Migration Plan Warnings</summary><ul>${migrationWarningRows}</ul></details>` : ""}
      <div class="table-wrap"><table><thead><tr><th>Generated</th><th>Status</th><th>Source DB</th><th>Target Storage</th><th>Warnings / Steps</th><th>Markdown Report</th><th>Guarded Script</th></tr></thead><tbody>${migrationPlanRows || '<tr><td colspan="7">No generated storage migration plans found. Run <code>npm run storage-migrate -- --write-plan</code> to create a reviewed dry-run package.</td></tr>'}</tbody></table></div></section>`;
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agent Workflow Server Readiness</title><style>${dashboardCss()}</style></head><body>
    ${dashboardNav("server-readiness")}
    <main><div class="topbar"><div><a href="/">Dashboard</a><h1>Server Readiness</h1><p class="muted">Read-only governed server-mode readiness. This page does not enable remote execution or change network binding.</p></div><a class="button secondary" href="/api/server-readiness?${escapeHtml(jsonParams.toString())}">JSON</a></div>
    ${renderDashboardFlash(params)}
    ${renderDashboardActionHistory()}
    <details class="readiness-filter"><summary>Inspection scope and advanced filters</summary><section class="panel"><form method="get" class="workflow-form"><label>Project<select name="project"><option value="">all registered projects</option>${projectOptions}</select></label><label>Limit<input name="limit" value="${escapeHtml(params.get("limit") ?? String(report.limit))}" inputmode="numeric"></label><label>Storage host<input name="storageHost" value="${escapeHtml(storageHost)}" placeholder="192.0.2.10"></label><label>Migration dir<input name="migrationDir" value="${escapeHtml(migrationDir)}" placeholder=".agent-workflow/migrations"></label><label class="checkbox-row"><input type="checkbox" name="includeRoots" value="true"${registry.includeRoots ? " checked" : ""}> include local roots</label><div class="form-actions"><button type="submit">Inspect</button></div></form></section></details>
    ${renderPrimaryStatePlaneOperatorPanel(mergeEvidence, offlineFallback, runtimeMonitor)}
    ${renderSharedStatePlaneProofPanel(statePlaneProof)}
    <section class="panel"><div class="metric-grid">
      ${metricCard("Status", report.status, "server-mode readiness")}
      ${metricCard("Mode", report.mode.enabled ? "enabled" : "local-only", report.mode.networkExposed ? "network-exposed bind" : "loopback bind")}
      ${metricCard("Bind", `${report.mode.bind}:${report.mode.port}`, report.mode.networkExposed ? "shared network candidate" : "local developer default")}
      ${metricCard("Auth", report.mode.authMode, report.mode.tokenConfigured ? "token configured" : "no token configured")}
      ${metricCard("Projects", report.projects.length, "registered project ids inspected")}
      ${metricCard("Origins", report.mode.allowedOrigins.length, "allowed browser origins")}
    </div><p class="muted">Generated ${renderDashboardDateTime(report.generatedAt)}. Current status: <span class="status ${statusClass}">${escapeHtml(report.status)}</span>.</p></section>
    <nav class="readiness-jump-nav" aria-label="Readiness detail groups"><a href="#server-controls">Server controls</a><a href="#runtime-services">Runtime &amp; services</a><a href="#projects-audit">Projects &amp; audit</a><a href="#storage-recovery">Storage &amp; recovery</a></nav>
    ${renderReadinessGroup("server-controls", "Server controls", `${report.authHardening.warningControls + report.authHardening.failingControls} controls need review`, serverControlDetails)}
    ${renderReadinessGroup("runtime-services", "Runtime & services", `${runtimeMonitor.processes.reduce((total, process) => total + process.count, 0)} managed processes inspected`, runtimeDetails)}
    ${renderReadinessGroup("projects-audit", "Projects & audit", `${report.projects.length} projects and ${requestAudit.totalRead} request events`, projectAndAuditDetails)}
    ${renderReadinessGroup("storage-recovery", "Storage & recovery", `${storageMatches}/${storageVerification.diffs.length} tables match; ${migrationPlans.plans.length} migration plans`, storageDetails)}
    <details class="readiness-group"><summary><span><strong>Operator reference</strong><small>Commands and local-first operating notes</small></span><span class="readiness-group-action">View details</span></summary><div class="readiness-group-content"><section class="panel"><h2>Recommended Commands</h2><ul>${commandRows}</ul></section><section class="panel"><h2>Notes</h2><ul>${noteRows || '<li>No server-mode notes found.</li>'}</ul></section></div></details></main></body></html>`;
  }

  function renderServerRequestAuditPanel(report: ServerRequestAuditReport): string {
    const rows = report.events.slice(0, 25).map((event) => `
      <tr>
        <td>${renderDashboardDateTime(event.generatedAt)}<br><code>${escapeHtml(event.requestId ?? "n/a")}</code></td>
        <td><span class="status ${event.status === "queued" || event.status === "ready" ? "completed" : event.status === "blocked" || event.status === "rejected" ? "failed" : "queued"}">${escapeHtml(event.status)}</span><br><span class="muted">${event.dryRun ? "dry-run" : "executed"}</span></td>
        <td><code>${escapeHtml(event.method)} ${escapeHtml(event.path)}</code><br><span class="muted">${event.projectId ? `project ${escapeHtml(event.projectId)}` : "project n/a"}</span></td>
        <td>${escapeHtml(event.workflowId ?? "n/a")}<br><span class="muted">task ${escapeHtml(event.taskHash ?? "n/a")} (${event.taskBytes} bytes)</span></td>
        <td>${escapeHtml(event.auth.method)}<br><span class="status ${event.auth.accepted ? "completed" : "failed"}">${event.auth.accepted ? "accepted" : escapeHtml(event.auth.errorCode ?? "rejected")}</span></td>
        <td>${event.rateLimit.accepted === null ? "n/a" : `<span class="status ${event.rateLimit.accepted ? "completed" : "failed"}">${event.rateLimit.accepted ? "accepted" : "limited"}</span>`}<br><span class="muted">${event.rateLimit.remaining === null ? "" : `${event.rateLimit.remaining} remaining`}</span></td>
        <td>${event.queuedRunId ? `<a href="/run?id=${encodeURIComponent(event.queuedRunId)}">${escapeHtml(event.queuedRunId.slice(0, 8))}</a>` : "none"}<br><span class="muted">${event.reusedRun === null ? "" : event.reusedRun ? "reused" : "new"}</span></td>
      </tr>
    `).join("");
    return `<section class="panel"><div class="section-heading"><div><h2>Remote Request Audit</h2><span class="muted">Redacted JSONL evidence for governed server queue requests. No task text, tokens, credentials, local roots, actor names, IPs, origins, or user agents are stored raw.</span></div><a class="button secondary" href="/api/server-request-log">JSON</a></div>
    <div class="metric-grid">
      ${metricCard("Events", report.totalRead, "redacted request records")}
      ${metricCard("Queued", report.queued, "workflow requests")}
      ${metricCard("Blocked", report.blocked, "blocked or rejected")}
      ${metricCard("Dry Runs", report.dryRuns, "preview-only requests")}
      ${metricCard("Rate Limited", report.rateLimited, "request decisions")}
      ${metricCard("Invalid Lines", report.invalidLines, "skipped while reading")}
    </div>
    <div class="meta-grid compact"><div><strong>Log Path</strong><code>${escapeHtml(report.logPath)}</code></div><div><strong>Latest</strong>${report.latestAt ? renderDashboardDateTime(report.latestAt) : "none"}</div><div><strong>Status Counts</strong>${escapeHtml(formatInlineCounts(report.statusCounts) || "none")}</div><div><strong>Auth Counts</strong>${escapeHtml(formatInlineCounts(report.authCounts) || "none")}</div></div>
    <div class="table-wrap"><table><thead><tr><th>Time</th><th>Status</th><th>Endpoint</th><th>Workflow</th><th>Auth</th><th>Rate Limit</th><th>Run</th></tr></thead><tbody>${rows || '<tr><td colspan="7">No governed server request audit events found.</td></tr>'}</tbody></table></div></section>`;
  }

  function renderSharedStatePlaneProofPanel(proof: SharedStatePlaneProof): string {
    const statusClass = proof.status === "ready" ? "completed" : proof.status === "blocked" ? "failed" : "queued";
    const checkRows = proof.checks.map((check) => `
      <tr>
        <td>${escapeHtml(check.label)}</td>
        <td><span class="status ${check.status === "pass" ? "completed" : check.status === "fail" ? "failed" : "queued"}">${escapeHtml(check.status)}</span></td>
        <td>${escapeHtml(check.detail)}</td>
      </tr>
    `).join("");
    const actions = proof.recommendedActions.map((action) => `<li>${escapeHtml(action)}</li>`).join("");
    return `<section class="panel">
      <div class="section-heading">
        <div>
          <h2>Shared State Plane</h2>
          <span class="muted">One verdict for shared host/shared storage, post-merge proof, offline fallback, object parity, and server controls.</span>
        </div>
        <span class="status ${statusClass}">${escapeHtml(proof.status)}</span>
      </div>
      <div class="metric-grid">
        ${metricCard("State Plane", proof.status, proof.summary)}
        ${metricCard("Shared Host", proof.sharedHost ?? "not configured", "configured durable storage target")}
        ${metricCard("Local Fallback", proof.localFallbackCanStayStopped ? "can stay stopped" : "keep available", "based on shared health and sync queue")}
        ${metricCard("Open Items", proof.recommendedActions.length, "operator follow-up")}
      </div>
      <p class="muted">Generated ${renderDashboardDateTime(proof.generatedAt)}. ${escapeHtml(proof.summary)}</p>
      <div class="table-wrap"><table><thead><tr><th>Proof</th><th>Status</th><th>Detail</th></tr></thead><tbody>${checkRows}</tbody></table></div>
      ${actions ? `<details class="governance-details" open><summary>Recommended Actions</summary><ul>${actions}</ul></details>` : `<p class="muted">No state-plane follow-up actions are currently recommended.</p>`}
    </section>`;
  }

  function renderStageHealthRing(radius: number, health: DashboardWorkflowStageHealth): string {
    if (health.totalTasks <= 0) return "";
    const ringRadius = radius + 7;
    const circumference = Math.PI * 2 * ringRadius;
    const segments = [
      { className: "completed", value: health.completedTasks },
      { className: "failed", value: health.failedTasks },
      { className: "active", value: health.queuedTasks + health.runningTasks },
      { className: "cancelled", value: health.cancelledTasks }
    ].filter((segment) => segment.value > 0);
    let offset = 0;
    const gap = segments.length > 1 ? 2.2 : 0;
    return segments.map((segment) => {
      const length = Math.max(0, (segment.value / health.totalTasks) * circumference - gap);
      const svg = `<circle class="network-health-ring ${segment.className}" r="${formatSvgNumber(ringRadius)}" fill="none" stroke-dasharray="${formatSvgNumber(length)} ${formatSvgNumber(circumference - length)}" stroke-dashoffset="${formatSvgNumber(-offset)}"></circle>`;
      offset += length + gap;
      return svg;
    }).join("");
  }

